INSERT OR IGNORE INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-d283a9225d6ece09', 'com-ca-hoi-donburi', 160, 'Cơm cá hồi ướp tương Donburi kiểu Nhật', 'Những lát cá hồi tươi béo mềm ướp sốt tương mirin dầu mè đậm đà, xếp trên lớp hành tây giòn ngọt và cơm gạo Nhật ấm nóng', 'Cơm cá hồi Zuke Donburi là món cơm tô nổi tiếng của Nhật với phi lê cá hồi tươi chuẩn sashimi thái lát mỏng, ướp thấm đẫm nước sốt xì dầu mirin thơm dầu mè, đặt lên lớp đệm hành tây thái mỏng trên nền cơm ấm.', 'Xới cơm Nhật vừa ấm ra hai tô lớn, phủ kín hành tây và cá hồi ướp sốt lên trên, rắc hành lá, rong biển nori vụn, hạt mè rang và ăn kèm wasabi.', 'Món cá hồi sống ướp sốt ngon nhất khi ăn ngay sau khi hoàn thành; không nên hâm nóng hoặc để qua ngày để đảm bảo độ tươi ngon và an toàn thực phẩm.', 'japanese', 'mon_nhanh_sang', NULL, 'easy', 15, 15, 2, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Donburi","Cá hồi","Bữa trưa","Thanh mát"]', '["lunch","dinner"]', '["toss_mix","assemble"]', '["fish","salmon","sesame","soybean","wheat"]', 654, 654.1, 2736, 36.7, 25.4, 5.3, 64.2, 2.1, 8.4, 1549, 3.88, '["MEXT Hon-Mirin 16031","USDA FDC 168456","USDA FDC 168878","USDA FDC 169231","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 174277","USDA FDC 175167"]', '0ab09124e614508d233b9b83cd56783f8159e6fb58030d782ab4ca910bf281b5', '3519921a36a5a08f7c729abb40fa1c7d5735419d8265be5589118216b2f17f41', 4),
('imp-7ed24282981e96f6', 'thit-ba-chi-shogayaki-gung', 161, 'Thịt ba chỉ áp chảo sốt gừng Shogayaki', 'Thịt ba chỉ heo thái mỏng áp chảo xém cạnh quyện sốt gừng tươi xì dầu mirin thơm nồng, ăn kèm bắp cải thái sợi thanh mát', 'Shogayaki là món thịt heo xào gừng quốc dân trong thực đơn teishoku Nhật Bản, nổi bật với từng lát thịt ba chỉ mềm thơm phủ sốt gừng tươi mài nhuyễn hòa quyện vị mặn ngọt từ nước tương, rượu sake và mirin.', 'Bày thịt ba chỉ sốt gừng nóng hổi cạnh ụ bắp cải thái sợi mịn trên đĩa lớn, rưới phần sốt sánh còn lại trong chảo lên mặt thịt và ăn cùng cơm trắng nóng.', 'Phần thịt thừa bảo quản hộp kín ngăn mát tối đa 2 ngày; hâm nóng lại trên chảo lửa nhỏ hoặc lò vi sóng 1–2 phút, phần bắp cải nên ăn tươi trong ngày.', 'japanese', 'mon_xao', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Shogayaki","Thịt ba chỉ","Cơm trưa","Nhanh gọn"]', '["lunch","dinner"]', '["pan_fry"]', '["pork","soybean","wheat"]', 681, 680.6, 2848, 13.1, 58.2, 20.6, 21.2, 3.4, 14.2, 1032, 2.58, '["MEXT Hon-Mirin 16031","MEXT Sake 16021","USDA FDC 167820","USDA FDC 169231","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 171413","USDA FDC 174277"]', '81ea24d173972ec1b47292157e8ca404e0ecacc115f0ea7f7a00f92e15759c48', '1c477a09e1b43625b53f46a3bdeb09a770134ace41fe341f28f587bc2c590f66', 4),
('imp-c6e706b483805e44', 'ba-chi-ham-kakuni', 162, 'Thịt ba chỉ hầm Kakuni kiểu Nhật', 'Thịt ba chỉ heo hầm hai giai đoạn mềm tan như tan trong miệng, quyện nước sốt dashi xì dầu đường ngọt dịu và trứng lòng đào ngấm vị', 'Buta no Kakuni là món thịt ba chỉ hầm trứ danh vùng Nagasaki Nhật Bản. Thịt được áp chảo rút mỡ, ninh mềm trong nước gừng hành rồi mới om chậm cùng nước dùng dashi, rượu sake, mirin, đường và xì dầu cho đến khi từng thớ thịt mềm rục bóng mượt.', 'Xếp từng khối thịt ba chỉ hầm bóng mượt ra bát sâu lòng cùng nửa quả trứng ngâm sốt và rau đậu hoặc cải thìa chần, rưới nước kho sánh ngọt và đặt hành trắng thái sợi lên trên.', 'Món Kakuni càng để qua đêm trong tủ lạnh càng thấm đậm; hớt bỏ lớp mỡ đông trên mặt nước kho, bảo quản tối đa 3–4 ngày và hâm lại lửa nhỏ khoảng 5–7 phút trước khi ăn.', 'japanese', 'mon_kho', NULL, 'hard', 25, 150, 5, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Kakuni","Thịt kho","Bữa tiệc","Hầm mềm"]', '["lunch","dinner"]', '["braise","pan_fry","boil"]', '["egg","fish","pork","soybean","wheat"]', 802, 802.2, 3356, 19.6, 65, 23.3, 25.5, 1.1, 19.1, 1559, 3.9, '["MEXT Hon-Mirin 16031","MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA FDC 167820","USDA FDC 169231","USDA FDC 169655","USDA FDC 169961","USDA FDC 170005","USDA FDC 170106","USDA FDC 171287","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277"]', 'e991055e26963a5baf30bbe9ed07b36c104c49177b9a7fd3835be13e94afd5cd', '84e4c6a5e09e67c60a009f77ecc4cc4c5dbfd0d4d7bd4f2cc53ea887daddf232', 4),
('imp-324e0ea2e2f068bf', 'canh-miso-dau-phu-nam', 163, 'Canh Miso đậu phụ non và nấm', 'Bát canh Miso ấm nóng nấu từ nước dùng dashi tảo bẹ thanh ngọt, đậu phụ non mềm mịn, nấm tươi giòn và rong biển wakame', 'Canh Miso là món canh truyền thống không thể thiếu trong bữa cơm Nhật Bản. Nước dùng thanh ngọt từ tảo bẹ kombu hòa cùng tương miso thơm dịu, đậu phụ non cắt khối và nấm tươi tạo nên vị umami nhẹ nhàng ấm bụng.', 'Múc canh nóng ra từng chén sứ nhỏ có nắp, rắc hành lá thái khoanh lên trên và dùng nóng ngay trước hoặc trong bữa cơm cùng cá nướng và cơm trắng.', 'Canh miso ngon nhất khi dùng ngay lúc mới nấu; nếu bảo quản tủ mát tối đa 1 ngày, chỉ hâm nóng tới khoảng 75–80°C trên lửa nhỏ, tuyệt đối không đun sôi bùng để tránh mất mùi thơm của tương miso.', 'japanese', 'mon_canh', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Món canh","Canh Miso","Thanh đạm","Bữa sáng"]', '["breakfast","lunch","dinner"]', '["simmer"]', '["soybean"]', 90, 90.2, 377, 6.7, 3.2, 0.5, 9.7, 2.1, 2.6, 789, 1.97, '["USDA FDC 168457","USDA FDC 169251","USDA FDC 170005","USDA FDC 170496","USDA FDC 172446","USDA FDC 172476","USDA FDC 173647"]', '80f1b740c56e069805b0b9f9831f9b03ed4993cd2f80e7f7dfc92af1bb9f5815', 'e8d7e15b85a402aa4f336e48838f63e4108f9459b879680f4582b5597069a2c2', 4),
('imp-5507103398040565', 'mi-xao-yakisoba-rau-cu', 164, 'Mì xào Yakisoba thịt ba chỉ rau củ', 'Sợi mì lúa mì Yakisoba xào lửa lớn giòn thơm cùng thịt ba chỉ, bắp cải, cà rốt, giá đỗ và nước sốt chua ngọt đậm đà kiểu đường phố Nhật', 'Yakisoba là món mì xào lễ hội nổi tiếng của Nhật Bản, kết hợp sợi mì lúa mì dai giòn, thịt ba chỉ áp chảo thơm béo cùng các loại rau củ tươi giòn và sốt yakisoba tự pha từ sốt Worcestershire, dầu hào, tương cà và xì dầu.', 'Bày mì Yakisoba nóng hổi ra đĩa lớn, rắc rong biển vụn hoặc cá bào Katsuobushi lên trên và dùng kèm gừng hồng muối nếu thích.', 'Mì xào ngon nhất khi ăn nóng ngay; phần thừa cất hộp kín bảo quản tủ lạnh tối đa 2 ngày, khi ăn xào lại trên chảo lửa vừa với 1 muỗng canh nước cho sợi mì tơi mềm.', 'japanese', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Yakisoba","Mì xào","Rau củ","Bữa trưa"]', '["lunch","dinner"]', '["stir_fry"]', '["egg","molluscs","pork","soybean","wheat"]', 696, 696.2, 2913, 18.3, 35.2, 11.3, 78, 6.7, 14.9, 1083, 2.71, '["USDA / MEXT Wheat Noodle Ref","USDA FDC 167820","USDA FDC 168456","USDA FDC 169076","USDA FDC 169251","USDA FDC 169655","USDA FDC 169963","USDA FDC 169975","USDA FDC 170000","USDA FDC 170005","USDA FDC 170108","USDA FDC 170393","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172227","USDA FDC 174277"]', '1f7ac3d8a09a40ed8e13a6dcaf75402e8a8921de7f0c94891a80a18f628fabc1', '41e538533fe5ae45355bc83c858005d7670edb76368d904a958bebd5497ec8be', 4),
('imp-710fd476f2dddd56', 'com-trung-boc-omurice', 165, 'Cơm gà sốt cà chua bọc trứng Omurice', 'Cơm chiên thịt gà sốt cà chua đậm đà thơm mùi bơ lạt và hành tây, được bọc khéo léo trong lớp trứng chiên vàng mịn mượt chuẩn vị Yoshoku Nhật Bản', 'Omurice là món cơm bọc trứng nổi tiếng thuộc phong cách ẩm thực Yoshoku Nhật Bản. Hạt cơm tơi ráo xào thấm đều sốt cà chua ketchup, thịt đùi gà mềm ngọt và đậu xanh, bọc ngoài bằng lớp trứng rây mịn mềm ẩm tan chảy.', 'Úp ngược từng phần Omurice ra đĩa bầu dục cho phần mép gấp nằm gọn bên dưới, rưới hình zíc zắc chút tương cà lên mặt trứng vàng mịn và dọn ăn nóng.', 'Phần cơm gà chiên có thể bảo quản tủ lạnh 2 ngày hoặc đông lạnh 1 tháng; khi dùng chiên nóng lại cơm rồi mới tráng lớp trứng tươi bọc ngoài để giữ độ mềm ngon nhất.', 'japanese', 'mon_nhanh_sang', NULL, 'medium', 15, 20, 2, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Omurice","Trẻ em","Cơm chiên","Trứng gà"]', '["breakfast","lunch","dinner"]', '["stir_fry","pan_fry","assemble"]', '["chicken","egg","milk"]', 615, 614.8, 2572, 28.2, 28.7, 13.2, 59.5, 1.8, 11.7, 986, 2.47, '["USDA FDC 168878","USDA FDC 169076","USDA FDC 169961","USDA FDC 170000","USDA FDC 170931","USDA FDC 171287","USDA FDC 172227","USDA FDC 172385","USDA FDC 173430","USDA FDC 173468"]', '4cc3a30db55b7b54af699b819dc0011a47a8ef05b028178f583db8a142cb6233', 'cff17e56b24663e5169818f0ab2d357033e3922934e6799de6b0499f59eac1fd', 4),
('imp-14c8ef999fe47b8f', 'trung-cuon-tamagoyaki', 166, 'Trứng cuộn Nhật Bản Tamagoyaki', 'Khối trứng cuộn nhiều lớp vàng ươm vuông vức, ruột mềm ẩm béo nhẹ vị sữa tươi và hành lá, món trứng chuẩn hộp cơm bento Nhật', 'Tamagoyaki là món trứng cuộn nhiều lớp kinh điển của bữa sáng và hộp cơm bento Nhật Bản. Hỗn hợp trứng gà, chút sữa tươi, xì dầu, rượu mirin và hành lá được tráng thành từng lớp mỏng rồi cuộn chồng khéo léo tạo nên khối trứng mềm ẩm thơm dịu.', 'Thái khối trứng Tamagoyaki thành 6–8 khoanh dày khoảng 2 cm, xếp gọn ra đĩa dùng nóng với cơm trắng hoặc cho vào hộp cơm bento.', 'Có thể bảo quản hộp kín trong ngăn mát tủ lạnh tối đa 2 ngày; khi ăn dùng ở nhiệt độ phòng kiểu bento hoặc quay lò vi sóng nhẹ 20 giây cho ấm mềm.', 'japanese', 'mon_nhanh_sang', NULL, 'medium', 10, 10, 2, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Tamagoyaki","Trứng cuộn","Bữa sáng","Hộp cơm"]', '["breakfast","lunch"]', '["pan_fry"]', '["egg","milk","soybean","wheat"]', 192, 192.1, 804, 12, 12, 3.4, 7.6, 0.3, 6.3, 650, 1.62, '["MEXT Hon-Mirin 16031","USDA FDC 169655","USDA FDC 170005","USDA FDC 171265","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277"]', '65a83094ac9b0049e0086dfa0581f2f4acdbb862349b136f8dbe992818678c59', '6538b3c7c9f54057148be93d16a3aa4f6d2a30e5f179532d0b333c3e381eed73', 4),
('imp-0841a517e823e3b6', 'ga-nuong-teriyaki-bong', 167, 'Đùi gà áp chảo sốt Teriyaki kiểu Nhật', 'Đùi gà lọc xương áp chảo da vàng giòn, thịt mềm mọng thấm đẫm nước sốt Teriyaki nâu bóng hương gừng tỏi đậm đà đưa cơm', 'Gà Teriyaki là món mặn trứ danh của ẩm thực Nhật Bản. Thịt đùi gà có da được khía nhẹ dàn đều độ dày rồi áp chảo giòn da, sau đó rưới sốt Teriyaki tự pha từ nước tương Nhật, rượu mirin, sake, đường cùng gừng tỏi cô sánh bóng đẹp.', 'Thái miếng đùi gà vừa ăn theo thớ ngang, xếp lên đĩa hoặc tô cơm nóng, rưới thêm vài muỗng sốt Teriyaki sóng sánh và dùng kèm bắp cải bào sợi hoặc bông cải xanh luộc.', 'Bảo quản thịt gà đã nguội cùng nước sốt trong hộp kín tủ mát tối đa 3 ngày; khi dùng hâm nóng lại trên chảo lửa nhỏ có thêm 1 muỗng canh nước để giữ độ mềm mọng.', 'japanese', 'mon_chien', NULL, 'easy', 15, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Teriyaki","Thịt gà","Áp chảo","Cơm nhà"]', '["lunch","dinner"]', '["pan_fry","braise"]', '["chicken","soybean","wheat"]', 488, 487.9, 2042, 40.5, 25.1, 6.4, 17.3, 0.4, 12.9, 1334, 3.34, '["MEXT Hon-Mirin 16031","MEXT Sake 16021","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170931","USDA FDC 171413","USDA FDC 172385","USDA FDC 173468","USDA FDC 174277"]', '9d58135b5ab116d5a1773801bb98e470fd5e6cf41d3c41e826398333dec7f385', '2845103596af3fb745831797a2e9e8aea88a0ba411b785ae46d2013f9c341c05', 4),
('imp-6ae7feae7ec0d517', 'ga-xien-yakitori-hanh', 168, 'Gà xiên nướng hành lá Yakitori', 'Xiên đùi gà xen kẽ hành lá nướng xém cạnh thơm lừng, quét nhiều lớp nước sốt tare đậm đà sánh bóng kiểu quán nướng Nhật Bản', 'Negima Yakitori là món gà xiên nướng trứ danh trong các quán izakaya Nhật Bản, kết hợp thịt đùi gà mềm mọng xen kẽ khúc hành lá ngọt thơm, được quét liên tục nước sốt tare cô đặc từ xì dầu, mirin, sake và đường nâu.', 'Dọn nóng từng xiên gà Yakitori vừa nướng xong ra đĩa dài, rắc thêm chút bột ớt 7 vị Shichimi Togarashi và dùng kèm nước chấm sốt tare chừa riêng.', 'Phần xiên thừa bảo quản hộp kín tủ mát tối đa 3 ngày; khi dùng làm nóng lại bằng lò nướng hoặc nồi chiên không dầu ở 180°C khoảng 6–7 phút và quét thêm chút sốt tare.', 'japanese', 'mon_lau_tiec', NULL, 'medium', 20, 35, 3, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Yakitori","Đồ nướng","Thịt gà","Món nhậu"]', '["dinner"]', '["grill_roast","simmer"]', '["chicken","sesame","soybean","wheat"]', 367, 367.1, 1537, 31.3, 17.5, 4.6, 14.5, 0.9, 10.6, 1298, 3.24, '["MEXT Hon-Mirin 16031","MEXT Sake 16021","MEXT Spice Ref","USDA FDC 168833","USDA FDC 170005","USDA FDC 171413","USDA FDC 172385","USDA FDC 173647","USDA FDC 174277"]', 'a47a22106838b7010d8fd321c0a962196f23352a4dc3bac3a1eefab823cd41d5', '7ea1502a4332f34d647777f6c3a31cedbc91837e644e103626946b38996e58b3', 4),
('imp-7facaaeafc40dac2', 'ca-hoi-nuong-muoi-chanh', 169, 'Cá hồi nướng muối chanh Shioyaki', 'Phi lê cá hồi ướp rượu sake và muối hạt kiểu Shioyaki truyền thống, nướng da giòn thịt mềm béo, dùng kèm củ cải trắng mài và chanh tươi', 'Shioyaki là phương pháp nướng cá với muối mộc mạc nhưng tinh tế của Nhật Bản. Cá hồi được xoa rượu sake và ướp muối hạt trong tủ lạnh để khử tanh, rút bớt nước thừa giúp thịt cá săn ngọt và phần da nướng giòn thơm.', 'Xếp cá hồi nướng nóng ra đĩa cùng ụ củ cải trắng mài nhuyễn vắt nhẹ nước, múi chanh tươi và hành lá thái nhỏ; dọn kèm cơm trắng nóng và canh miso.', 'Bảo quản cá nướng thừa trong hộp kín ngăn mát tối đa 2 ngày; khi ăn làm nóng lại bằng lò nướng hoặc nồi chiên không dầu ở 180°C trong 3–4 phút cho da giòn trở lại.', 'japanese', 'mon_chien', NULL, 'easy', 15, 10, 2, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Shioyaki","Cá hồi","Đồ nướng","Nhẹ bụng"]', '["lunch","dinner"]', '["grill_roast"]', '["fish","salmon"]', 391, 391, 1635, 35.2, 25.2, 5.5, 3.5, 1.1, 1.3, 458, 1.15, '["MEXT Sake 16021","USDA FDC 168155","USDA FDC 168452","USDA FDC 170005","USDA FDC 171413","USDA FDC 173468","USDA FDC 175167"]', '5d758ce57af3d9bdf4d303bd2ab7a45be485b119e055089ee72588aa5d7a5d75', 'a2b8ae89724ede5f472c575ba75ff00e2ae22dc5a10bb8fda25f82cebf27951e', 4),
('imp-70379b3f30b48438', 'goi-dua-leo-tom-nhat', 170, 'Gỏi dưa leo tôm giấm Nhật Sunomono', 'Dưa leo thái lát mỏng bóp muối giòn sần sật trộn cùng tôm luộc ngọt thịt, rưới nước giấm gạo chua ngọt dịu và mè rang thơm bùi', 'Ebi Sunomono là món gỏi trộn giấm khai vị truyền thống thanh nhẹ của Nhật Bản. Dưa leo được ướp muối vắt ráo để giữ độ giòn lâu, kết hợp cùng tôm tươi luộc chín ngọt thịt và nước sốt giấm gạo pha xì dầu, đường và dầu mè thơm dịu.', 'Múc gỏi dưa leo tôm ra các chén thủy tinh nhỏ, rắc hạt mè trắng rang và hành lá lên trên, dùng lạnh làm món khai vị hoặc ăn kèm cá nướng, cơm chiên để chống ngấy.', 'Món ăn dùng lạnh, bảo quản hộp kín trong ngăn mát tủ lạnh tối đa 1–2 ngày; không để lâu hơn vì dưa leo sẽ tiết nước làm nhạt vị sốt giấm.', 'japanese', 'mon_cuon_nom', NULL, 'easy', 15, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Sunomono","Món gỏi","Khai vị","Thanh mát"]', '["lunch","dinner"]', '["toss_mix","boil"]', '["crustaceans","sesame","shrimp","soybean","wheat"]', 115, 115.3, 483, 13.2, 3.3, 0.5, 9, 1.1, 5.8, 563, 1.41, '["USDA FDC 168409","USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 171319","USDA FDC 172238","USDA FDC 173468","USDA FDC 174277","USDA FDC 175179"]', 'e97b0fcaee04dac6112648d5c65a030c6c6aa1e8fb72739cef679dbb9f0a1291', '94c9a1ef627b6711f2ca9183a51996dca248ff1d933ae8792fa7a451b3fa7013', 4),
('imp-49262ac40836045a', 'trung-hap-chawanmushi-ga', 171, 'Trứng hấp Chawanmushi thịt gà và nấm', 'Trứng hấp Chawanmushi trong chén sứ mềm mịn mượt mà như pudding mặn, nhân ức gà ướp sake, nấm đùi gà giòn ngọt và chả cá Nhật', 'Khác với phiên bản hải sản, Chawanmushi thịt gà và nấm tập trung vào vị ngọt thanh của nước dùng dashi kết hợp cùng ức gà mềm thơm ướp rượu sake, nấm đùi gà thái mỏng và lớp trứng đánh rây mịn màng không bọt khí.', 'Dọn nóng từng chén sứ Chawanmushi có nắp lên bàn ăn, rắc thêm hành lá thái nhỏ lên trên mặt trứng vàng mịn và thưởng thức bằng thìa nhỏ.', 'Nên ăn nóng ngay sau khi hấp; phần dư đậy kín nắp chén cất tủ mát tối đa 2 ngày và hấp cách thủy lửa nhỏ 3–4 phút cho nóng lại.', 'japanese', 'mon_hap_luoc', NULL, 'medium', 15, 25, 3, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Chawanmushi","Món hấp","Thịt gà","Thanh đạm"]', '["breakfast","lunch","dinner"]', '["steam"]', '["chicken","egg","fish","soybean","wheat"]', 148, 148, 619, 16.6, 5.5, 1.6, 5.6, 0.6, 2.5, 1030, 2.57, '["MEXT Hon-Mirin 16031","MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA / MEXT Fish Cake Ref","USDA FDC 169251","USDA FDC 170005","USDA FDC 171287","USDA FDC 171477","USDA FDC 173468","USDA FDC 174277"]', 'd2327976ce200739134df084c8009ca06909879a1aaca10bc7c98bb270109cb0', '5bb4a59497b9af8b027bd3b268454bfaa168ca3d7a19a571095c6e635b6cd6f7', 4),
('imp-e26d04bf95bcede8', 'mi-ramen-heo-trung', 172, 'Mì Ramen thịt xá xíu Chashu và trứng lòng đào', 'Tô mì Shoyu Ramen chuẩn vị Nhật với nước dùng hầm xương heo đậm ngọt, sợi mì dai ngon, thịt ba chỉ cuộn Chashu mềm tan và trứng ngâm tương Ajitama', 'Shoyu Ramen là món mì nước biểu tượng của Nhật Bản với nước dùng trong ngọt từ xương ống heo và rau củ thơm, kết hợp cùng nước sốt shoyu tare cô từ nước om thịt ba chỉ cuộn Chashu mềm béo và trứng lòng đào ngâm tương Ajitama.', 'Chan nước dùng nóng hổi vào tô đã lót sẵn shoyu tare, xếp gọn mì ramen trụng dai vừa, vài lát thịt Chashu béo mềm, nửa quả trứng lòng đào, hành lá thái nhỏ và lá rong biển Nori.', 'Nước dùng, thịt Chashu cuộn và nước sốt tare nguội có thể trữ hộp kín ngăn mát 3–4 ngày; khi ăn thái lát Chashu lạnh rồi thả vào tô nước dùng đang sôi nóng và luộc mì ramen mới ngay trước lúc dọn.', 'japanese', 'mon_bun_pho', NULL, 'hard', 30, 180, 4, '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Mì Ramen","Chashu","Trứng lòng đào","Bữa tối"]', '["lunch","dinner"]', '["simmer","braise","boil"]', '["egg","pork","soybean","wheat"]', 837, 836.7, 3501, 27.6, 51.6, 18.5, 61.5, 2.6, 5, 1478, 3.69, '["MEXT Hon-Mirin 16031","MEXT Sake 16021","Pork Bone Stock Extraction Ref","USDA / MEXT Wheat Noodle Ref","USDA FDC 167820","USDA FDC 168456","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 171287","USDA FDC 171401","USDA FDC 173647","USDA FDC 174277"]', 'dab2229616c9f004379a9b49cbf3d06d482bbe38f477853a55ac8cf704d31896', '4029f97b221fa950e52521203eab8bd16e75ef1fbf2100cd07da885f8a2fe42c', 4),
('imp-b808fb03d1e8ede6', 'com-ca-ri-ga-nhat', 173, 'Cơm cà ri gà Nhật', 'Sốt cà ri Nhật sánh mịn, ngọt dịu từ hành tây xào vàng ôm lấy thịt gà mềm, khoai tây và cà rốt ăn kèm cơm nóng', 'Cơm cà ri gà kiểu Nhật (Kare Raisu) có phần sốt sánh mịn, thơm nồng gia vị cà ri hòa quyện vị ngọt tự nhiên từ hành tây xào chín vàng, đùi gà mềm mọng cùng khoai tây và cà rốt bùi bở, chan cạnh cơm trắng dẻo nóng.', 'Xới cơm trắng dẻo ra một bên đĩa sâu lòng, múc cà ri gà nóng hổi sang nửa đĩa còn lại, rắc hành lá thái xéo và dọn kèm củ cải muối Fukujinzuke giòn chua ngọt.', 'Để cà ri nguội hoàn toàn rồi bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 3 ngày; khi ăn đun nóng lại trên lửa nhỏ, thêm chút nước dùng nếu sốt quá đặc.', 'japanese', 'mon_kho', NULL, 'easy', 20, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Cà ri Nhật","Ẩm thực Nhật","Đùi gà","Cơm nhà","Bữa tối"]', '["lunch","dinner"]', '["stir_fry","simmer"]', '["chicken","soybean","wheat"]', 757, 757.2, 3169, 32.6, 25.6, 8.4, 96.8, 6.2, 8.8, 1818, 4.54, '["MEXT Curry Roux Ref","MEXT Takuan Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169756","USDA FDC 170000","USDA FDC 170005","USDA FDC 170026","USDA FDC 170393","USDA FDC 171413","USDA FDC 172227","USDA FDC 172385","USDA FDC 172883","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'ba7a5dc007cc688d4063a0d09dc13cd77241bf36ad658129f23649d3f3ce74b2', 'e2814039ae0669ad52efa307d6a76eead5bdbb5670e218aebd29392ed0563e9c', 4),
('imp-46c2a1c4cc7a8bb5', 'mi-udon-bo-hanh', 174, 'Mì Udon bò hành', 'Sợi mì Udon trắng dày dai mướt trong nước dùng Dashi thanh ngọt, phủ thịt bò xào hành tây đậm vị kiểu Nhật', 'Mì Udon bò hành (Niku Udon) kết hợp sợi Udon mềm dai cùng nước dùng Dashi trong thanh, ngọt dịu từ xì dầu và Mirin, điểm xuyết thịt bò thái lát mỏng xào nhanh với hành tây và gừng thơm nồng ấm bụng.', 'Chia mì Udon ra tô sâu lòng, chan ngập nước dùng Dashi nóng hổi, xếp thịt bò xào hành tây lên trên và rắc hành lá thái xéo cùng chút bột ớt 7 vị Shichimi.', 'Bảo quản riêng phần nước dùng, thịt bò xào và mì Udon chưa trụng trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn đun sôi lại nước dùng và thịt bò trước rồi mới trụng mì.', 'japanese', 'mon_bun_pho', NULL, 'easy', 15, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Mì Udon","Ẩm thực Nhật","Thịt bò","Mì nước","Bữa trưa"]', '["lunch","dinner"]', '["boil","pan_fry","assemble"]', '["beef","fish","sesame","soybean","wheat"]', 540, 539.7, 2258, 29.6, 14.5, 4.7, 64.6, 3.6, 15.1, 1858, 4.65, '["MEXT Boiled/Fresh Udon","MEXT Hon-Mirin 16031","MEXT Ichiban Dashi Ref","MEXT Sake 16021","MEXT Spice Ref","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170187","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277"]', '90965f2cfa23deb65a626b4225d438607927280eb0bb57fe58ff888bdcb30471', 'ba027095e1e55e6f7352dcf61d557bfe4e5db9828f0684152d22818166c1586d', 4),
('imp-38fb8569664d1f3b', 'ca-hoi-ap-chao-bo-chanh', 175, 'Cá hồi áp chảo bơ chanh', 'Phi lê cá hồi da giòn rụm, thịt mềm mọng quyện sốt bơ lạt sủi bọt thơm tỏi, chanh tươi và xì dầu Nhật', 'Cá hồi áp chảo bơ chanh kiểu Meunière Nhật kết hợp lớp áo bột gạo thật mỏng giúp da cá giòn rụm, bên trong vẫn mềm hồng béo ngậy, rưới sốt bơ tan chảy hòa quyện nước cốt chanh tươi, tỏi phi và xì dầu thanh nhẹ.', 'Đặt miếng cá hồi mặt da hướng lên trên đĩa ấm, rưới đều phần sốt bơ chanh tỏi phi, rắc hành lá thái nhỏ và dùng nóng cùng cơm trắng hoặc măng tây áp chảo.', 'Món cá hồi áp chảo ngon nhất khi ăn ngay lúc da còn giòn; nếu dư, bọc kín bảo quản ngăn mát tối đa 2 ngày và làm nóng lại bằng nồi chiên không dầu ở 160°C trong 3 phút.', 'japanese', 'mon_chien', NULL, 'easy', 15, 15, 2, '/frigo/illustrations/delicious-meal.png', '["Cá hồi","Áp chảo","Sốt bơ chanh","Ẩm thực Nhật","Nhanh gọn"]', '["lunch","dinner"]', '["pan_fry"]', '["fish","milk","salmon","soybean","wheat"]', 425, 424.7, 1777, 29.4, 31.1, 10, 5.3, 0.5, 1.4, 635, 1.59, '["MEXT Hon-Mirin 16031","USDA FDC 168155","USDA FDC 169230","USDA FDC 169714","USDA FDC 170005","USDA FDC 170931","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468","USDA FDC 174277","USDA FDC 175167"]', '750644319c464acf8e22200f3200bfdb3d4bf049abd9cffbddcdaa1b24af8616', 'da34e39aa1b07a4b6451f83e255f0b56b96f3f9e3d47623d7a9f45745d5223e2', 4),
('imp-eae128801c2c7f96', 'rau-bina-tron-me-nhat', 176, 'Rau bina trộn mè Nhật', 'Rau bina chần xanh mướt, vắt ráo nước trộn cùng mè trắng rang giã thơm với xì dầu, Mirin và dầu mè thanh dịu', 'Rau bina trộn mè Nhật (Horenso Goma-ae) là món rau phụ thanh mát quen thuộc trong mâm cơm Nhật, giữ trọn màu xanh ngọc mướt của cải bó xôi hòa quyện vị béo bùi của hạt mè trắng rang giã dập và sốt xì dầu ngọt dịu.', 'Bày rau bina trộn mè thành từng ụ nhỏ gọn đẹp mắt ra đĩa sứ nhỏ, rắc thêm chút hạt mè rang nguyên hạt lên trên và dùng mát hoặc ở nhiệt độ phòng kèm cơm nóng.', 'Cho rau bina trộn mè vào hộp đậy kín, bảo quản trong ngăn mát tủ lạnh tối đa 2 ngày; món ăn ngon khi dùng nguội mát, không nên hâm nóng lại.', 'japanese', 'mon_chay', NULL, 'easy', 10, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Rau bina","Mè rang","Món chay","Ẩm thực Nhật","Thanh mát"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["sesame","soybean","wheat"]', 135, 134.9, 564, 5.4, 8.7, 1.2, 11.5, 3.6, 5.2, 566, 1.42, '["MEXT Hon-Mirin 16031","USDA FDC 168462","USDA FDC 169655","USDA FDC 170150","USDA FDC 171028","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'bd3bdefa0cb87a9047432ba2b3ef597cff34c78233181890dc22fbcaa9e10ff6', 'ecdbc6a772a0fe966b6333837ad69614c6deb6b27724807d651a08e967472fac', 4),
('imp-56ec9eae817af509', 'bap-cai-tron-me-lanh', 177, 'Bắp cải trộn mè lạnh', 'Bắp cải và cà rốt thái sợi hấp nhanh giữ độ giòn ngọt, làm lạnh trộn cùng sốt mè rang giã thơm thanh mát', 'Bắp cải trộn mè lạnh kiểu Nhật kết hợp bắp cải xanh và cà rốt thái sợi hấp nhẹ chỉ với một ít nước nên giữ trọn vị ngọt giòn tự nhiên, trộn đều cùng sốt mè trắng rang giã dập, xì dầu, giấm gạo và dầu mè thơm bùi.', 'Múc bắp cải trộn mè đã làm lạnh ra đĩa sâu lòng hoặc bát nhỏ, rắc thêm hành lá thái nhỏ và một nhúm hạt mè rang nguyên hạt lên trên để dùng kèm các món mặn.', 'Đậy kín trong hộp bảo quản ở ngăn mát tủ lạnh dùng ngon trong 2–3 ngày; không hâm nóng để giữ độ giòn mát của rau.', 'japanese', 'mon_cuon_nom', NULL, 'easy', 15, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Bắp cải","Mè rang","Món trộn","Ẩm thực Nhật","Thanh mát"]', '["lunch","dinner"]', '["steam","toss_mix"]', '["sesame","soybean","wheat"]', 158, 157.8, 661, 4.7, 9.1, 1.3, 17.3, 5.5, 9.5, 429, 1.07, '["USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170150","USDA FDC 170393","USDA FDC 171028","USDA FDC 172238","USDA FDC 173647","USDA FDC 174277"]', 'af73b90f3bc99882c6bbb5f999734a75086d60ed66f61ad7a0f0514c746ad228', '0b80f38998999b896cbfc4a227174fc0fced6ce32cd6827e1f3a894ac05aa796', 4),
('imp-44b1338a7a49098d', 'canh-kimchi-dau-phu-han', 178, 'Canh kim chi đậu phụ kiểu Hàn', 'Nước canh hầm nóng hổi đậm vị kim chi ủ chua, thịt ba chỉ mềm thơm và đậu phụ trắng thanh mát trong nền nước dùng cá cơm tảo bẹ', 'Canh kim chi đậu phụ kiểu Hàn mang hương vị truyền thống với phần kim chi được xào kỹ cùng thịt ba chỉ cho dậy mùi thơm, hầm liu riu trong nước dùng cá cơm tảo bẹ ngọt thanh cùng hành tây, ớt bột Gochugaru và đậu phụ mềm mịn.', 'Múc canh nóng ra tô sâu lòng hoặc nồi đất, rắc hành lá thái vát lên mặt và dùng kèm cơm trắng dẻo nóng.', 'Canh nguội hẳn cho vào hộp kín bảo quản ngăn mát tối đa 3 ngày; khi ăn lại đun sôi trên lửa vừa 4–5 phút để hương vị hài hòa trở lại.', 'korean', 'mon_canh', NULL, 'easy', 15, 30, 3, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món canh","Kim chi","Đậu phụ","Cơm nhà"]', '["lunch","dinner"]', '["simmer","stir_fry"]', '["fish","pork","sesame","soybean","wheat"]', 567, 567.2, 2373, 17.4, 48.9, 15.6, 16.9, 4.5, 7.9, 1781, 4.45, '["Korean Anchovy Kelp Stock Ref","Korean Chili Flake Ref","USDA / Korean Gochujang Ref","USDA FDC 167820","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170497","USDA FDC 171028","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468"]', '8e5d265493068fb0942e1f08c0a76df0fcec3af548fb2d5ac4b1f57be46c9eed', 'f30ff93b8748843604a1a2b1fd7a0224e7ff4b4eb62c2d48c5b2156052d9a288', 4),
('imp-a24a701c584d3ef3', 'com-tron-bibimbap-han', 179, 'Cơm trộn Bibimbap Hàn Quốc', 'Tô cơm trộn đủ sắc vị với thịt bò ướp xào mềm, giá đỗ, rau chân vịt, cà rốt, bí ngòi, nấm đùi gà, dưa leo, trứng ốp la và sốt Gochujang', 'Cơm trộn Bibimbap Hàn Quốc là bức tranh ẩm thực hài hòa năm sắc màu với cơm trắng dẻo nóng làm nền, xếp bên trên các loại rau củ sơ chế riêng giữ trọn độ giòn tươi, thịt bò thăn xào đậm vị, trứng gà ốp la và sốt tương ớt Gochujang cay ngọt.', 'Dọn mỗi tô cơm trộn nóng hổi kèm một phần sốt Gochujang riêng và chén canh rong biển hoặc kim chi; khi ăn trộn đều tất cả nguyên liệu với lòng đỏ trứng.', 'Có thể chuẩn bị sẵn các phần rau xào và thịt bò đựng hộp riêng trong ngăn mát tối đa 2 ngày; khi ăn chỉ cần làm nóng cơm và thịt bò rồi xếp lên tô, chiên trứng mới.', 'korean', 'mon_cuon_nom', NULL, 'medium', 25, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Cơm trộn","Bibimbap","Đầy đủ dinh dưỡng","Thịt bò"]', '["lunch","dinner"]', '["boil","stir_fry","pan_fry","toss_mix"]', '["beef","egg","sesame","soybean","wheat"]', 672, 671.6, 2810, 30.6, 26, 6.2, 79.7, 6.2, 15.2, 1928, 4.82, '["MEXT Hon-Mirin 16031","USDA / Korean Gochujang Ref","USDA FDC 168409","USDA FDC 168462","USDA FDC 168580","USDA FDC 168878","USDA FDC 169230","USDA FDC 169291","USDA FDC 169655","USDA FDC 169963","USDA FDC 170005","USDA FDC 170150","USDA FDC 170187","USDA FDC 170393","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'eb15297647f4c6c2f6e9ed58514e1955ac5f3538a7439cd62b429aac045b0a63', '93cd09a34d76d75a293dc7fdb772956ac39ac7fd8fe1f1d8ab6850821876ffff', 4),
('imp-52b5963c6cecfb96', 'bo-nuong-bulgogi-ngot', 180, 'Bò nướng Bulgogi kiểu Hàn', 'Thịt bò thăn ngoại thái lát mỏng ướp xì dầu, mật ong, đường nâu và tỏi gừng nướng áp chảo xém cạnh thơm lừng', 'Bò nướng Bulgogi kiểu Hàn nổi bật với từng lát thịt bò thăn ngoại mềm ngọt, thấm sâu nước sốt ướp mặn ngọt dịu từ nước tương, mật ong, đường nâu và rượu ngọt Mirin, khi nướng áp chảo lửa lớn tạo lớp cạnh xém thơm quyến rũ.', 'Bày thịt bò nướng Bulgogi nóng ra đĩa, rắc hạt mè trắng rang và hành lá thái nhỏ; ăn kèm cơm trắng hoặc cuốn xà lách cùng kim chi.', 'Thịt bò ướp sống có thể để ngăn mát tối đa 24 giờ; thịt đã nướng chín bảo quản hộp kín trong tủ lạnh tối đa 2 ngày và hâm nhanh trên chảo nóng 2 phút.', 'korean', 'mon_lau_tiec', NULL, 'easy', 20, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món nướng","Bulgogi","Thịt bò","Tiệc nướng"]', '["lunch","dinner"]', '["grill_roast","pan_fry"]', '["beef","sesame","soybean","wheat"]', 367, 366.7, 1535, 27, 20.1, 6, 18.9, 1.5, 14, 891, 2.23, '["MEXT Hon-Mirin 16031","USDA FDC 168833","USDA FDC 169230","USDA FDC 169231","USDA FDC 169640","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 174277"]', '8730c296336bdc47bb20a3c9094b2aa57894fce500c49d9aa00c54371399dd98', 'df3ab1eaf3d9a4c50a69d686194fa741ea582782e441361304bf90a86b0ebbbf', 4),
('imp-51b6559bf09bc980', 'canh-tom-nau-bi-do', 181, 'Canh tôm nấu bí đỏ dẻo ngọt', 'Bí đỏ hầm bở dẻo hòa quyện vị tôm sú xào thơm tỏi và gừng sợi ấm bụng, tạo nên tô canh vàng sánh ngọt lành cho bữa cơm nhà', 'Khác với kiểu nấu nhanh giữ miếng, bí đỏ được ninh bở dẻo trên lửa nhỏ cùng nước dùng ngọt thanh từ tôm tươi xào tỏi gừng thơm nức, mang đến tô canh ấm áp sánh vàng dịu nhẹ.', 'Múc canh nóng ra tô lớn, rắc hành lá, ngò rí và tiêu xay; dùng kèm cơm trắng nóng rất thích hợp cho bữa tối gia đình quây quần.', 'Để nguội rồi bảo quản hộp kín trong tủ mát tối đa 24 giờ; khi hâm lại nên khuấy đều nhẹ tay trên lửa nhỏ để phần bí bở dẻo không bén đáy nồi.', 'vietnamese', 'mon_canh', 'nam', 'easy', 15, 22, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Nam Bộ","Bí đỏ","Bổ dưỡng","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 123, 123, 515, 13.4, 3.8, 0.6, 10.5, 0.9, 4.5, 1220, 3.05, '["USDA FDC 168448","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '2041006f1a05862ce58acbf14f87b75f3b06353f4187bbbd5d357b4580f57bda', '99fa6a307e0f3fa51bc9b4106c556b0468be4884cfb3828783be0704facdd8e9', 4),
('imp-81a203668e5e4c1a', 'canh-trung-nam-kim-cham', 182, 'Canh trứng nấm kim châm cà chua', 'Nấm kim châm giòn ngọt nấu cùng cà chua chua dịu và vân trứng gà đánh tơi vàng óng, món canh thanh nhẹ nấu nhanh 15 phút', 'Tô canh thanh nhẹ giàu chất xơ với nấm kim châm giòn sần sật ngọt nước, hòa quyện sắc đỏ dịu của cà chua chín và những sợi vân trứng gà mềm béo đẹp mắt.', 'Dọn canh nóng vào tô lớn ngay sau khi tắt bếp, rắc hành lá và tiêu xay lên trên; dùng kèm cơm trắng hoặc ăn nhẹ buổi tối đều rất ngon.', 'Món canh nấm trứng nên dùng hết ngay trong bữa để giữ độ giòn của nấm kim châm và vị béo mịn của trứng; hạn chế đun lại nhiều lần.', 'vietnamese', 'mon_canh', 'toan_quoc', 'easy', 10, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món canh","Nấm","Dưới 20 phút","Dễ nấu","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["egg","fish"]', 155, 155.4, 650, 8.7, 9, 2.1, 11.6, 3, 3.4, 1291, 3.23, '["USDA FDC 169230","USDA FDC 169253","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'a05dcd7ea953254e47a300d35e8f568a5e5bfaaad13abf2799055d5e50fd6ec3', 'aba3ea8c57d8b2d1a8cdc037a980773e1b3be5f2e36e6d0165c9af80a9ec2b9d', 4),
('imp-6c20dba60d77bdfd', 'canh-suon-su-su-non', 183, 'Canh sườn hầm su su non', 'Sườn non heo ninh mềm róc xương cho nước dùng trong ngọt đậm đà, kết hợp su su non giòn mát và cà rốt cho bữa cơm ấm áp cả nhà', 'Nồi canh ấm nóng quen thuộc với phần nước hầm sườn non trong veo, thịt sườn mềm ngọt róc xương quyện cùng su su non giòn mát và sắc cam dịu của cà rốt.', 'Múc canh nóng ra tô lớn, rắc hành lá, ngò rí và chút tiêu xay lên mặt; dọn kèm cơm trắng và đĩa rau xào hoặc thịt kho đều rất tròn vị.', 'Bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 24 giờ sau khi canh nguội hẳn; đun sôi lại ở lửa vừa vừa đủ nóng để su su không bị nhũn.', 'vietnamese', 'mon_canh', 'bac', 'easy', 15, 45, 5, '/frigo/illustrations/delicious-meal.png', '["Món canh","Miền Bắc","Sườn","Bổ dưỡng","Cơm nhà"]', '["lunch","dinner"]', '["boil","simmer"]', '["fish","pork"]', 217, 217.4, 909, 11.8, 15.4, 5.7, 8.4, 2.7, 3.2, 955, 2.39, '["USDA FDC 167861","USDA FDC 169990","USDA FDC 169997","USDA FDC 170005","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '63937bff019916ca3a26ac40fca38f3dc842e06ddab00ceab14eb4d6c1214fd5', '487849306d18ba65862c23c5e539cf677983581b7255c2482f662c51a992a8ec', 4),
('imp-734cc9acf8620c69', 'canh-dau-phu-ca-chua-trung', 184, 'Canh đậu phụ cà chua trứng', 'Món canh thanh nhẹ với đậu phụ non mềm mịn, cà chua chín đỏ au và vân trứng gà tơ vàng ươm đẹp mắt', 'Canh đậu phụ cà chua trứng có nước dùng đỏ cam tự nhiên, vị chua dịu hài hòa từ cà chua chín, miếng đậu phụ non béo mềm tan nhẹ cùng những sợi vân trứng gà vàng mịn thơm lừng.', 'Múc canh ra tô lớn khi còn nóng hổi, rắc thêm hành lá, ngò rí và chút tiêu xay; dùng kèm cơm trắng và các món mặn như cá kho hay thịt rang cháy cạnh.', 'Canh ngon nhất khi ăn nóng ngay sau khi nấu; nếu còn dư, đậy kín bảo quản ngăn mát tối đa 24 giờ và hâm lại trên lửa vừa, tránh khuấy mạnh làm nát đậu phụ.', 'vietnamese', 'mon_canh', 'toan_quoc', 'easy', 10, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Đậu phụ","Thanh đạm","Nấu nhanh","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["egg","fish","soybean"]', 126, 125.7, 526, 7.5, 7.6, 1.5, 7.5, 1.3, 3.8, 914, 2.28, '["USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 172476","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '404ca5dfff64e388c6f15c91ed6b3a6f6000a30026a85fe2ec53de241654398b', '5b8312c83eef8c43ec0141f56e70e627883821f908fc5ab6dbd22f99c8b0c21f', 4),
('imp-095cff5e61d32fd9', 'canh-bo-ca-chua-ngot', 185, 'Canh bò cà chua ngọt', 'Nước canh đỏ cam ngọt thanh chua dịu hòa quyện cùng thịt bò thăn thái mỏng mềm ngọt và hương rau răm đặc trưng Nam Bộ', 'Canh bò cà chua ngọt là món canh cơm nhà giản dị nhưng đậm đà hương vị miền Nam. Thịt bò thăn thái mỏng ướp gia vị thấm mềm, nấu nhanh trong nước dùng cà chua đỏ au chua ngọt nhẹ, dậy mùi rau răm và hành lá.', 'Dọn canh nóng ngay khi thịt bò vừa chín tới, ăn kèm cơm trắng nóng dẻo hoặc chan cùng bún tươi và chén nước mắm ớt cắt lát.', 'Nên ăn hết trong bữa để thịt bò giữ được độ mềm ngọt; nếu bảo quản tủ mát tối đa 24 giờ, nên vớt riêng phần thịt bò, đun sôi nước canh trước rồi mới thả bò vào làm nóng nhanh 30 giây.', 'vietnamese', 'mon_canh', 'nam', 'easy', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Thịt bò","Cà chua","Nam Bộ","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["beef","molluscs","soybean","wheat"]', 228, 227.7, 953, 19.8, 12.9, 4.1, 8.4, 2.1, 5.1, 872, 2.18, '["USDA FDC 169655","USDA FDC 170005","USDA FDC 170187","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","VN Culinary Herb Ref","VN Rau Ram Ref","VN/Asian Seasoning Powder Avg"]', '452c7247d0b39e6d665b86c44d791244f6e1dc1934d1369f65c9e066338343bd', '07b8bd99f7781a6698e96a5e935439890315ed53448241539a561e613643415e', 4),
('imp-a4822c0a1187e4d7', 'suon-nuong-muoi-ot', 186, 'Sườn nướng muối ớt', 'Sườn non ướp muối hạt, ớt hiểm, tỏi và nước mắm ngon nướng vàng xém cạnh, chấm muối ớt chanh chua cay thơm lừng', 'Những khúc sườn non nhiều thịt mềm ngọt được ướp đậm đà vị mặn mà của muối hạt, cay nồng từ ớt hiểm tươi và tỏi băm, nướng chín vàng xém cạnh ăn kèm nước chấm chanh ớt.', 'Bày sườn nướng ra đĩa lớn, dọn nóng cùng cơm trắng, dưa leo, rau sống và chén nước mắm chanh ớt tiêu cay thơm.', 'Bảo quản sườn đã nướng trong hộp kín ở ngăn mát tối đa 2 ngày; khi dùng làm nóng lại bằng lò nướng hoặc nồi chiên không dầu ở 180°C khoảng 5 phút.', 'vietnamese', 'mon_kho', 'toan_quoc', 'medium', 20, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Sườn nướng","Muối ớt","Cuối tuần","Món mặn","Đưa cơm"]', '["lunch","dinner"]', '["grill_roast","boil"]', '["fish","pork"]', 456, 456.2, 1909, 21.2, 35.5, 11.9, 12.4, 0.6, 9.9, 1185, 2.96, '["USDA FDC 167861","USDA FDC 168155","USDA FDC 169230","USDA FDC 169655","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647"]', 'b97eed0b515685b9f9d19cbda6470dde8cadc3c88f46f4d3aa97ba7c2f512690', 'c3ce6641b40e010029458ae894dcd6e3917fcb51f630cef85dc2ab93667ead2d', 4),
('imp-04514fa34052d242', 'ga-kho-nam-dam', 187, 'Gà kho nấm đùi gà đậm vị', 'Đùi gà áp chảo vàng thơm kho cùng nấm đùi gà dai giòn và nấm hương khô trong nước sốt xì dầu, dầu mè đen và đường phèn sóng sánh', 'Thịt đùi gà áp chảo săn chắc kho quyện hương thơm đặc trưng của dầu mè, nấm hương khô ngâm nở và nấm đùi gà dai ngọt tự nhiên, nước kho sánh nâu đậm vị.', 'Múc gà kho nấm ra đĩa sâu lòng, rắc hành lá và cần tây lên trên, dùng nóng cùng cơm trắng dẻo và rau luộc.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn hâm nóng lại trên lửa nhỏ, thêm 1 muỗng nước lọc để sốt sánh mượt trở lại.', 'vietnamese', 'mon_kho', 'toan_quoc', 'easy', 20, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món kho","Thịt gà","Nấm đùi gà","Đưa cơm","Cơm nhà"]', '["lunch","dinner"]', '["braise","pan_fry"]', '["celery","chicken","fish","molluscs","sesame","soybean","wheat"]', 393, 392.9, 1644, 31.7, 22.8, 5.3, 16.1, 2.5, 5.3, 1250, 3.13, '["Dark Soy Sauce Label Ref","USDA FDC 168436","USDA FDC 168580","USDA FDC 169230","USDA FDC 169231","USDA FDC 169988","USDA FDC 170005","USDA FDC 170106","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173647","USDA FDC 174277","USDA FDC Sucrose Ref"]', '91f0a4b48bd00a6551b8369fb231d9040def327f4d9a149bde98ae0ae89e3056', '793dba71a342f0cdade36aaf3f3b37167f65606157a9492993c3a95920e89d74', 4),
('imp-695f59248dbf4895', 'ca-kho-gung-sa', 188, 'Cá kho gừng sả miền Trung', 'Cá lóc cắt khoanh chiên sơ kho liu riu cùng sả băm, gừng giã nhuyễn và ớt cay nồng, thấm vị mặn ngọt đậm đà chuẩn cơm nhà miền Trung', 'Khúc cá lóc chiên săn chắc thịt kho thấm vị nước mắm ngon, thơm nồng mùi sả băm, gừng giã dập phi vàng và vị cay ấm đặc trưng từ ớt bột cùng ớt tươi miền Trung.', 'Gắp cá ra đĩa sâu lòng, rưới phần nước kho sánh thơm sả gừng và rắc hành lá thái nhỏ; dùng nóng với cơm trắng dẻo.', 'Bảo quản hộp kín trong ngăn mát tối đa 3 ngày; khi dùng hâm nóng lại trên lửa nhỏ cùng 1–2 muỗng canh nước sôi.', 'vietnamese', 'mon_kho', 'trung', 'medium', 20, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Cá kho","Miền Trung","Gừng sả","Món kho","Đưa cơm"]', '["lunch","dinner"]', '["braise","pan_fry"]', '["fish"]', 273, 272.6, 1140, 30, 10.7, 2, 13.6, 0.8, 7.8, 1440, 3.6, '["USDA FDC 168573","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 171319","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175176"]', '9d3d29042fcbf059eb01e3d54b56bc787082b58290a45f50ab157e52927abbb0', '4a455f9e48c34219624378b5c79b8f202077af5185a0e556a504cb4826e43ea5', 4),
('imp-208386f834b8da43', 'trung-kho-tuong-keo', 189, 'Trứng gà kho nước tương sánh keo', 'Trứng gà luộc lòng chín tới chiên xém nhẹ rồi kho liu riu trong sốt nước tương, hắc xì dầu và ngũ vị hương sánh bóng đậm đà', 'Những quả trứng gà thấm đẫm nước sốt nước tương và xì dầu đặc sánh kẹo màu nâu bóng đẹp mắt, phảng phất mùi thơm dịu của ngũ vị hương, hành tỏi phi và tương ớt cay nhẹ.', 'Cắt đôi hoặc để nguyên quả trứng bày ra đĩa sâu lòng, rưới phần sốt keo bóng cùng hành lá, ngò rí và tiêu xay; ăn nóng với cơm trắng.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 3 ngày; khi ăn hâm lại trên lửa nhỏ cùng 1 muỗng nước ấm để sốt sánh nóng đều.', 'vietnamese', 'mon_kho', 'toan_quoc', 'easy', 15, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Trứng kho","Nước tương","Nhanh gọn","Đưa cơm","Cơm nhà"]', '["lunch","dinner"]', '["braise","boil","pan_fry"]', '["egg","soybean","wheat"]', 278, 278.4, 1165, 17.7, 18, 4.7, 11.4, 1.2, 6.8, 1739, 4.35, '["Dark Soy Sauce Label Ref","Five Spice USDA Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277","USDA FDC Sriracha Ref"]', '633ef7c2e0d459d46761a5256c050b97805bf74c3dd453a4fbc0b31c5fad6d81', '6f6e5e3801a551e2dc7fcbc2024acde4f7559596b1eb0acd6cb28fb0860dbecf', 4),
('imp-d1f8ab89051a6336', 'bong-cai-xao-tom-tuoi', 190, 'Bông cải xào tôm tươi', 'Bông cải xanh và cà rốt giòn ngọt xào lửa lớn cùng tôm tươi cong hồng, áo sốt sánh nhẹ thơm mè trắng rang', 'Đĩa bông cải xào tôm tươi hài hòa giữa sắc xanh mướt của súp lơ, cam tươi của cà rốt và vị ngọt săn chắc từ tôm tươi, được bao bọc bởi lớp sốt bột bắp sánh bóng thơm dịu dầu mè và mè trắng rang.', 'Trình bày bông cải xào tôm tươi ra đĩa rộng, rắc mè trắng rang và tiêu đen xay; dùng nóng cùng cơm trắng và nước tương ớt.', 'Món xào ngon nhất khi ăn ngay lúc vừa hoàn thành; nếu bảo quản hộp kín trong ngăn mát tối đa 24 giờ, đảo nóng nhanh trên chảo lửa lớn trong 1 phút trước khi dùng.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Hải sản","Rau xanh","Giàu chất xơ","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry","boil"]', '["crustaceans","fish","sesame","shrimp"]', 196, 195.7, 819, 16.7, 9.3, 1.4, 13.7, 3.4, 3.5, 1077, 2.69, '["USDA FDC 169230","USDA FDC 169698","USDA FDC 170000","USDA FDC 170150","USDA FDC 170379","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', 'e79164017f41fe11823c366609946912a3c75c4a2deee68d71e1527d08570143', '444f7401efc8c125f35e4aa74cdbc538e2e4d61ff064a1b84660aa6ae28b597f', 4),
('imp-03c5e6e31e01088d', 'dau-phu-xao-sa-ot', 191, 'Đậu phụ xào sả ớt', 'Đậu phụ chiên vàng giòn cạnh xào thấm sốt sả ớt cay thơm đậm vị nước tương và tương ớt, món chay mặn đều ngon', 'Đậu phụ xào sả ớt kiểu Nam Bộ hấp dẫn với lớp vỏ đậu vàng giòn bên ngoài nhưng bên trong vẫn béo mềm, quyện đẫm phần sốt sả băm thơm lừng, vị cay nồng của ớt và mặn ngọt sánh nhẹ từ nước tương, dầu hào chay và tương ớt.', 'Xếp đậu phụ xào sả ớt ra đĩa, rắc thêm chút tiêu đen xay và vài lát ớt sừng; ăn nóng với cơm trắng hoặc bún tươi đều rất bắt vị.', 'Bảo quản trong hộp kín ngăn mát tối đa 2 ngày; khi dùng làm nóng lại trên chảo chống dính ở lửa vừa khoảng 2–3 phút để đậu nóng đều.', 'vietnamese', 'mon_xao', 'nam', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Món chay","Đậu phụ","Sả ớt","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry","pan_fry"]', '["soybean","wheat"]', 264, 264.4, 1106, 17.4, 18.3, 2.7, 12.7, 1.8, 4, 601, 1.5, '["USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 173647","USDA FDC 174277","USDA FDC Sriracha Ref","Vegan Mushroom Sauce Ref"]', '84cb2d06f15fbe550b3b52420cbedba20dfc94ac2e3c040504ec1af553e45f1c', '8f8ec8d7b59df4044a4c252afae195f6ceed7eec0e8ad986ed57ba648fced937', 4),
('imp-2862e7aa0ae0d8fe', 'bo-xao-dua-chua-ngot', 192, 'Bò xào dứa chua ngọt', 'Thịt thăn bò mềm mọng quyện vị chua ngọt thanh dịu từ dứa chín tươi và hành tây giòn thơm kiểu Nam Bộ', 'Bò xào dứa chua ngọt là món ăn cực kỳ bắt cơm với thịt thăn bò mềm tan nhờ enzyme tự nhiên từ dứa tươi, kết hợp cùng hành tây giòn ngọt và nước sốt dầu hào nước mắm đậm đà hương vị Nam Bộ.', 'Múc bò xào dứa ra đĩa rộng khi còn bốc khói, rắc tiêu đen xay lên mặt; ăn nóng kèm cơm trắng và nước tương ớt.', 'Món xào ngon nhất khi ăn ngay lúc vừa nấu xong vì dứa tiết nước theo thời gian; nếu bảo quản tủ mát trong ngày, hâm nóng nhanh trên chảo lửa lớn khoảng 1 phút.', 'vietnamese', 'mon_xao', 'nam', 'easy', 18, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Chua ngọt","Nam Bộ","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","fish","molluscs","soybean","wheat"]', 347, 347, 1452, 22.6, 19.1, 5.4, 22, 2.3, 14.2, 1518, 3.8, '["USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170187","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","VN/Asian Seasoning Powder Avg"]', 'ab41d359bac6f6e05c8e07d2099c9d1aa66b4b06bfb1953127882b4f28c08c23', '95f88171ea5f667701fd53ddee30d00456b478dcb1ccf1883a8f71305b99335e', 4),
('imp-aa94e2f8bdf3985f', 'tom-hap-sa-chanh', 193, 'Tôm hấp sả lá chanh thơm nồng', 'Tôm sú tươi hấp nhanh cùng sả cây, lá chanh, gừng và rượu trắng rồi rưới tỏi phi vàng thơm lừng chấm muối chanh ớt', 'Tôm sú tươi giữ nguyên vị ngọt giòn tự nhiên khi hấp nhanh cùng sả đập dập, lá chanh thơm mát, gừng lát và chút rượu trắng khử tanh, phủ thêm lớp tỏi phi vàng giòn dậy mùi hấp dẫn.', 'Xếp tôm đỏ au ra đĩa lớn, rưới đều tỏi phi thơm lừng lên thân tôm và dọn nóng chấm kèm muối tiêu chanh ớt.', 'Món tôm hấp ngon nhất khi thưởng thức nóng ngay. Nếu còn dư, bóc vỏ bảo quản ngăn mát tối đa 24 giờ và làm nóng nhanh 2 phút trong chảo hoặc xửng hấp.', 'vietnamese', 'mon_hap_luoc', 'nam', 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Tôm","Sả","Mát lành","Dưới 20 phút"]', '["lunch","dinner"]', '["steam"]', '["crustaceans","shrimp","sulphites"]', 173, 172.6, 723, 26.9, 4.9, 0.8, 5.5, 0.7, 0.5, 1042, 2.61, '["Citrus Leaf Culinary Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169231","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 173190","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '531bbb31623f716fc61b5a5866635514f54845c55df2d304ff262879ced5133b', '0acf80870c6058c1cbc2a425942ea08b8fa410da196a410d299fceff90973d88', 4),
('imp-b55451e6e46a4c13', 'bap-cai-cuon-hap-thit', 194, 'Bắp cải cuộn thịt hấp thanh ngọt', 'Lá bắp cải chần mềm cuộn nhân thịt heo xay, mộc nhĩ và cà rốt hấp chín tới ngọt thanh đẹp mắt chuẩn vị Bắc Bộ', 'Những cuộn bắp cải xanh mướt căng tròn ôm lấy phần nhân thịt heo xay quyện mộc nhĩ giòn sần sật và cà rốt ngọt dịu, buộc cố định bằng cọng hành lá chần mềm; hấp cách thủy giữ trọn vị ngọt tự nhiên.', 'Xếp các cuộn bắp cải hấp nóng hổi ra đĩa sâu lòng, rưới ít nước ngọt tiết ra khi hấp cùng tiêu xay; ăn kèm cơm nóng và chấm nước tương ớt hoặc nước mắm tỏi ớt.', 'Có thể bảo quản cuộn bắp cải đã hấp chín trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn hấp lại 6–8 phút đến khi phần nhân thịt nóng đều.', 'vietnamese', 'mon_hap_luoc', 'bac', 'medium', 25, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Bắp cải","Khéo tay","Món Bắc","Thanh đạm"]', '["lunch","dinner"]', '["steam","boil"]', '["fish","pork"]', 246, 246.1, 1030, 14.9, 16.1, 6, 11.3, 5.5, 3.8, 665, 1.66, '["USDA FDC 167902","USDA FDC 168437","USDA FDC 169230","USDA FDC 169975","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '59821506f7edc893591174184c94561c8664ef657df563707620d80a1cdb5ea2', 'b5cc87c231c52e0bb60b2639514978ee14bd932f3c0c419bffeca00442d344de', 4),
('imp-500644420438efd3', 'dau-phu-hap-sa', 195, 'Đậu phụ hấp sả xì dầu thanh đạm', 'Đậu phụ trắng mềm mịn hấp cùng sả băm xào thơm và xì dầu đậm đà, điểm hành lá dầu mè nhẹ bụng cho bữa tối', 'Đậu phụ non mịn hấp cách thủy cùng nước sốt xì dầu đậm dịu và sả xào vàng thơm lừng, giữ trọn vị béo bùi tự nhiên của đậu nành, ít dầu mỡ và rất dễ tiêu hóa.', 'Dọn nóng nguyên đĩa đậu phụ hấp sả ra bàn, rưới thêm chút xì dầu pha ớt nếu thích đậm vị, ăn kèm cơm trắng nóng.', 'Món đậu phụ hấp ngon nhất khi dùng nóng ngay trong bữa để đậu mềm mọng không bị xốp rỗ; nếu còn dư, bảo quản ngăn mát tối đa 24 giờ rồi hấp lại 4 phút.', 'vietnamese', 'mon_hap_luoc', 'toan_quoc', 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Đậu phụ","Thanh đạm","Dễ nấu","Món chay"]', '["lunch","dinner"]', '["steam"]', '["sesame","soybean","wheat"]', 179, 178.8, 748, 13.3, 12.4, 1.8, 7.2, 1.5, 2.1, 856, 2.14, '["USDA FDC 168573","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 171028","USDA FDC 171413","USDA FDC 172475","USDA FDC 173647","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', 'c65c15a06decc2ab7f448d9daca352fcf5f5dfa58a23741b7709fe2e9e645941', 'b791bcdf2b9a34e5a54b2300d4e171e02d11665f245d578d5234ad7acc1b4a69', 4),
('imp-47cbfe72125b811d', 'goi-bo-dua-leo-chanh', 196, 'Gỏi bò dưa leo chanh', 'Thịt bò thăn xào lửa lớn mềm mọng quyện dưa leo bỏ ruột giòn mát, cà rốt, hành tây trong nước trộn mắm chanh tỏi ớt chua cay cuốn hút', 'Gỏi bò dưa leo chanh kết hợp tinh tế giữa thịt bò thăn xào tỏi thơm mềm mọng, từng sợi dưa leo và cà rốt giòn ngọt, hành tây thanh dịu và nước trộn mắm chanh ớt hiểm đậm đà, điểm xuyết đậu phộng rang bùi béo và rau thơm.', 'Bày gỏi bò ra đĩa, rắc phần đậu phộng rang giã dập còn lại và ớt thái lát lên mặt; dọn ăn ngay kèm bánh phồng tôm.', 'Thịt bò xào nên trộn và dùng ngay khi còn tươi giòn; nếu chuẩn bị trước, để riêng phần rau củ vắt ráo và nước trộn trong ngăn mát tủ lạnh, chỉ xào bò và trộn gỏi ngay trước bữa ăn.', 'vietnamese', 'mon_cuon_nom', 'nam', 'medium', 25, 10, 4, '/frigo/illustrations/delicious-meal.png', '["Gỏi bò","Dưa leo","Chua cay","Khai vị","Đãi tiệc"]', '["lunch","dinner"]', '["stir_fry","toss_mix"]', '["beef","fish","peanut"]', 396, 396.4, 1659, 26.9, 23.5, 5.9, 21.9, 4, 12.6, 1308, 3.27, '["USDA FDC 168155","USDA FDC 168409","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172430","USDA FDC 173468","USDA FDC 173474","VN/Asian Seasoning Powder Avg"]', '4f86934f4a69d3c316cab17b266fd72d3de2647e88c25e4bf063057535a7bf9c', '98b349cae6bf53d394c293a4c0b50eed9d340dd60fb3cf12bcf6cfed58ec40f2', 4),
('imp-403a1693ea9b3cf8', 'bun-tom-rau-muong-chua-cay', 197, 'Bún tôm rau muống chua cay', 'Nước dùng xương heo nấu me, dứa, cà chua và sa tế chua cay bắt vị, ăn kèm tôm tươi giòn ngọt, bún tươi và rau muống chẻ thanh mát', 'Bún tôm rau muống chua cay mang đậm hương vị Nam Bộ dễ ăn với nước dùng ngọt xương hòa vị chua dịu từ me vắt, thơm dịu từ dứa và cà chua, thêm chút sa tế cay nồng ăn cùng tôm tươi và rau muống chẻ giòn.', 'Trụng bún và xếp tôm chín lên tô cùng rau muống chẻ, chan nước dùng chua cay nóng hổi, rắc hành phi, hành lá, ngò rí, tiêu xay rồi vắt thêm chanh và ớt tươi tùy thích.', 'Bảo quản nước dùng riêng trong ngăn mát tối đa 24 giờ; khi ăn đun sôi nước dùng, thả tôm và rau muống chẻ vào trụng nóng rồi chan lên bún mới.', 'vietnamese', 'mon_bun_pho', 'nam', 'easy', 25, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Bún tôm","Chua cay","Rau muống","Nam Bộ"]', '["breakfast","lunch","dinner"]', '["simmer","stir_fry","boil","assemble"]', '["crustaceans","fish","pork","shrimp"]', 593, 592.5, 2478, 28, 16, 3, 89, 7, 24.5, 2309, 5.77, '["Annatto Infused Oil Ref","Chili Oil / Satay Ref","NIN VN Fresh Bun Ref","Pork Bone Stock Extraction Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169124","USDA FDC 169230","USDA FDC 169378","USDA FDC 169655","USDA FDC 169918","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', 'e9de5b0409df62333527716d2d92fb447f86979c841d3a3abd446cb34a4dd146', '16430058b635bd4a35dd83d399987897a4f649f4a2b3cd4a0e902df45f6fb939', 4),
('imp-c039dac37b31acdb', 'mi-quang-ga-ta', 198, 'Mì Quảng gà ta', 'Sợi mì Quảng dẻo thơm quyện nước nhân gà ta kho nghệ sánh vàng óng, ăn kèm đậu phộng rang giòn, bánh đa nướng và đĩa rau sống miền Trung', 'Mì Quảng gà ta chuẩn vị Quảng Nam với phần nước nhân nấu vừa xâm xấp đậm đà hương nghệ, hành tím và sả phi dầu, thịt gà ta săn mềm thấm vị, ăn cùng rau sống chín tầng, đậu phộng rang và bánh đa bẻ giòn.', 'Lót xà lách, giá đỗ, húng lủi và bắp chuối bào dưới đáy tô, xếp mì Quảng và thịt gà lên trên, chan nước nhân vừa xâm xấp mặt mì, rắc đậu phộng rang, hành lá và ăn kèm bánh đa nướng cùng nước mắm tỏi ớt.', 'Phần thịt gà và nước nhân bảo quản ngăn mát tối đa 2 ngày; khi ăn đun sôi lại nồi nước nhân và trụng mới mì Quảng để sợi mì không bị bở.', 'vietnamese', 'mon_bun_pho', 'trung', 'medium', 30, 55, 4, '/frigo/illustrations/delicious-meal.png', '["Mì Quảng","Gà ta","Ẩm thực miền Trung","Đặc sản"]', '["breakfast","lunch","dinner"]', '["braise","simmer","assemble"]', '["chicken","fish","peanut"]', 817, 817.1, 3420, 40.5, 38.7, 8.9, 78.5, 7.4, 9.3, 2019, 5.05, '["Annatto Infused Oil Ref","NIN VN Fresh Pho Noodle Ref","SE Asian Banana Blossom Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169247","USDA FDC 169655","USDA FDC 169963","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171077","USDA FDC 171319","USDA FDC 171413","USDA FDC 172185","USDA FDC 172231","USDA FDC 172430","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","VN Banh Da Ref","VN/Asian Seasoning Powder Avg"]', '9f17cf267d185684b3c494bdf44f7fdbaa9442a870a9d084fcee1fdf19b74f49', '9eb26db39154ec9eee7fc2616aac82b571b0401950ff3d36bf1d30bfd1261eac', 4);
INSERT OR IGNORE INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-875e99916a13d031', 'pho-chay-nam-dau', 199, 'Phở chay nấm đậu', 'Nước dùng rau củ hầm củ cải trắng, cà rốt và hành gừng nướng thơm thoang thoảng quế hồi thảo quả, ăn cùng đậu phụ chiên vàng và nấm đùi gà xào đậm đà', 'Phở chay nấm đậu thanh tịnh nhưng vẫn đậm đà tròn vị nhờ nước dùng hầm củ cải trắng, cà rốt, hành tây nướng và gia vị phở truyền thống, kết hợp đậu phụ chiên vàng giòn và nấm đùi gà xào ngũ vị hương thơm lừng.', 'Xếp bánh phở, giá đỗ trụng và nấm đậu xào lên tô, chan ngập nước dùng chay sôi nóng, rắc hành lá, ngò gai và thưởng thức cùng húng quế, chanh tươi và tương đen.', 'Nước dùng rau củ bảo quản ngăn mát 2–3 ngày; đậu phụ và nấm nên xào nóng lại trên chảo trước khi chan nước dùng sôi lên bánh phở mới.', 'vietnamese', 'mon_bun_pho', 'toan_quoc', 'medium', 25, 50, 4, '/frigo/illustrations/delicious-meal.png', '["Phở chay","Thanh đạm","Nấm đậu","Món nước"]', '["breakfast","lunch","dinner"]', '["simmer","pan_fry","stir_fry","assemble"]', '["sesame","soybean","wheat"]', 448, 447.9, 1875, 18.2, 12, 1.8, 71.9, 6.8, 12.4, 1930, 4.83, '["Five Spice USDA Ref","NIN VN Fresh Pho Noodle Ref","USDA FDC 168155","USDA FDC 168452","USDA FDC 168580","USDA FDC 169231","USDA FDC 169963","USDA FDC 170000","USDA FDC 170005","USDA FDC 170393","USDA FDC 170919","USDA FDC 170931","USDA FDC 171316","USDA FDC 171320","USDA FDC 171370","USDA FDC 171413","USDA FDC 172232","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC Sucrose Ref","VN Culinary Herb Ref","Vegetarian Seasoning Powder Ref"]', '467f53dad9f593c5b95b73083cd57d71bb42c3aef34d62b4ae192d87cf4e82c4', '74a2d85da074e50d87e28c13276b779ccaf37313d9c08196b97a4ec534b1d0e2', 4),
('imp-389f525ea854b373', 'canh-chua-chay-dua-dau', 200, 'Canh chua chay dứa đậu phụ Nam Bộ', 'Nồi canh chua thanh mát chuẩn vị Nam Bộ với nước cốt me, dứa chín, cà chua, đậu bắp, bạc hà và đậu phụ mềm béo', 'Bát canh chua chay Nam Bộ thanh tao đậm đà với sự hòa quyện cân bằng giữa vị chua dịu từ me chín, ngọt thơm của dứa chín, sắc đỏ của cà chua cùng đậu phụ béo mềm, đậu bắp, dọc mùng và giá đỗ giòn tươi.', 'Múc canh nóng ra tô lớn, rắc rau ngổ, ngò gai thái nhỏ lên trên; dùng kèm cơm trắng nóng hoặc bún tươi đều rất hợp vị.', 'Canh ngon nhất khi dùng hết trong ngày để giữ độ giòn của đậu bắp, dọc mùng và giá đỗ; nếu để sang ngày hôm sau nên vớt riêng rau và đun sôi lại phần nước canh trước khi ăn.', 'vietnamese', 'mon_chay', 'nam', 'easy', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món chay","Canh chua","Nam Bộ","Thanh nhiệt","Đậu phụ"]', '["lunch","dinner"]', '["simmer"]', '["soybean"]', 204, 204, 853, 12, 8.4, 1.2, 25.1, 4.8, 15.4, 717, 1.79, '["NIN VN Doc Mung Ref","USDA FDC 169124","USDA FDC 169246","USDA FDC 169260","USDA FDC 169655","USDA FDC 169918","USDA FDC 169963","USDA FDC 170457","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","VN Culinary Herb Ref","VN Herb Ref","Vegetarian Seasoning Powder Ref"]', '12b4dcea26bcfa995936dce6b4f2fbef435d9466ddc044ca2a54229108eb576a', 'f0092dac3c2e4aec79902132e4cd0f6c53955fd92379e6d0d014aa6ca115c91f', 4),
('imp-8301ed8c884fb619', 'cai-bap-xao-nam-chay', 201, 'Bắp cải xào nấm đùi gà chay', 'Bắp cải giòn ngọt xào nhanh lửa lớn cùng nấm đùi gà thái lát, lá hẹ xanh thơm và xì dầu đậm vị', 'Món xào chay thanh đạm mà đưa cơm với lá bắp cải trắng giòn ngọt tự nhiên kết hợp nấm đùi gà dai sần sật, thấm nhẹ nước tương, hương tỏi phi và mùi thơm đặc trưng của lá hẹ xanh tươi.', 'Trút bắp cải xào nấm ra đĩa rộng khi còn nóng hổi, rắc tiêu xay lên mặt và dùng kèm cơm trắng nóng hoặc chấm thêm chén nước tương ớt.', 'Món rau xào nên dùng hết trong bữa để giữ trọn độ giòn của bắp cải; nếu còn dư bảo quản ngăn mát tối đa 24 giờ và đảo nhanh lại trên chảo nóng.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Món xào","Bắp cải","Nấm đùi gà","Nhanh gọn"]', '["lunch","dinner"]', '["boil","stir_fry"]', '["soybean","wheat"]', 145, 144.6, 606, 5.2, 7.9, 1.2, 15.8, 5.1, 6.7, 1106, 2.77, '["MEXT Sake 16021","USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 169975","USDA FDC 169994","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', 'baac2cf3d31ec51e23e709b1cf7561f5278a1d47a5cdb261e3b395aec9dfc949', '7d8b42b23f606da4fe5747f357c9954b23c2f4374b27165a659bb64fc95e3d1f', 4),
('imp-327ffa644fbe1a7d', 'chao-tom-nam-nong', 202, 'Cháo tôm nấm đùi gà nóng', 'Cháo gạo rang sánh mịn ngọt tự nhiên từ tôm tươi và nấm đùi gà xào thơm, điểm gừng sợi và hành lá ấm bụng', 'Tô cháo tôm nấm nóng hổi sánh mượt với gạo tẻ kết hợp chút gạo nếp rang thơm, thịt tôm tươi săn ngọt đậm đà cùng nấm đùi gà giòn sần sật, gừng tươi thái chỉ và hành lá thơm dịu.', 'Múc cháo nóng ra tô, xếp phần tôm và nấm đùi gà xào lên mặt cùng hành lá, ngò rí, gừng thái sợi và tiêu đen xay rồi dùng ngay.', 'Nên thưởng thức ngay khi còn nóng. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ; khi hâm lại trên lửa nhỏ cần thêm chút nước sôi và khuấy đều tránh cháy đáy.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 15, 28, 4, '/frigo/illustrations/delicious-meal.png', '["Cháo tôm","Nấm đùi gà","Ăn sáng","Thanh ngọt","Ấm bụng"]', '["breakfast","dinner"]', '["boil","simmer","stir_fry"]', '["crustaceans","fish","shrimp"]', 245, 245.2, 1026, 13.1, 3.8, 0.6, 39.3, 1.8, 1.7, 908, 2.27, '["USDA FDC 168881","USDA FDC 169231","USDA FDC 169251","USDA FDC 169756","USDA FDC 169997","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '488d7220d7809772762d5ca6740c06e91451c4229bfdd573b4c31ce5c0dc034d', 'd4d55596ad7651e07cef5a3ea0cb1d93f74be009008ece862ed455e110c1edc4', 4),
('imp-9aed26098f07c061', 'trung-duc-thit-bam', 203, 'Trứng đúc thịt bằm', 'Trứng gà đánh bông chiên lửa nhỏ cùng thịt heo xay, hành tím và hành lá chín vàng xốp mềm đậm đà', 'Món trứng đúc thịt bằm dân dã quen thuộc trong mọi mâm cơm Việt với lớp vỏ ngoài vàng ươm thơm phức, phần nhân bên trong bông mềm ẩm mượt quyện thịt heo nạc vai xay, hành tím phi và hành lá xanh tươi.', 'Cắt trứng đúc thịt thành từng miếng tam giác hoặc miếng vuông vừa ăn, bày lên đĩa nóng cùng rau sống dưa leo và thưởng thức với cơm trắng nóng chấm tương ớt.', 'Ngon nhất khi ăn nóng ngay sau khi chiên. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 2 ngày và hâm nóng lại bằng chảo đậy nắp 3 phút trên lửa nhỏ hoặc lò vi sóng.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 10, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Trứng đúc thịt","Cơm nhà","Nhanh gọn","Giàu đạm","Bé thích"]', '["breakfast","lunch","dinner"]', '["pan_fry"]', '["egg","fish","pork"]', 280, 280.1, 1172, 17.4, 21.8, 6.7, 2.8, 0.5, 1.1, 836, 2.09, '["USDA FDC 167902","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","VN/Asian Seasoning Powder Avg"]', 'a10da70bc157094694b8aca694528fb66ef3fd150c707af96c73160dd6f4e095', '3af9544b49dfab4c3f221abbc0f1d8dddc52d02a7f87baa8c09a1d3a837aa652', 4),
('imp-24e75cbb2ba569f4', 'banh-trang-tron-rau-cu', 204, 'Bánh tráng trộn rau củ', 'Bánh tráng gạo cắt sợi dai mềm trộn bắp cải, cà rốt bào giòn cùng sốt nước tương chanh ớt chua cay mặn ngọt', 'Món bánh tráng trộn rau củ chuẩn vị Sài Gòn phiên bản thanh mát với sợi bánh tráng dẻo dai vừa độ, bắp cải và cà rốt bào giòn, rau răm thơm nồng quyện mỡ hành béo nhẹ, đậu phộng rang giòn bùi và sốt nước tương chanh ớt.', 'Cho bánh tráng trộn rau củ ra đĩa ngay khi vừa trộn xong, rắc thêm đậu phộng rang và rau răm lên trên rồi thưởng thức liền để bánh không bị nhũn.', 'Chỉ trộn ngay trước lúc ăn để bánh tráng giữ độ dẻo dai và rau củ còn giòn. Có thể chuẩn bị riêng bánh tráng cắt sợi, rau củ bào và hũ nước sốt trong ngăn mát tối đa 1 ngày.', 'vietnamese', 'mon_nhanh_sang', 'nam', 'easy', 10, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Bánh tráng trộn","Nam Bộ","Ăn vặt","Thanh nhẹ","Dưới 20 phút"]', '["breakfast","lunch"]', '["toss_mix"]', '["peanut","soybean","wheat"]', 262, 262.3, 1098, 5.8, 10.2, 1.4, 39.7, 4.1, 7.6, 604, 1.51, '["USDA FDC 168155","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 171413","USDA FDC 172430","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC Rice Paper Ref","VN Rau Ram Ref"]', '60944fc7510ffc897fa0a30283a1334471528201dadfc50600711adf3bd39afb', '89b46d22c25a5ea4c1a1322638b2960a3d7908a631f1bd8d08f522e10553b3aa', 4),
('imp-0bd4954058454e92', 'lau-ga-nam-am', 205, 'Lẩu gà nấm ấm bụng', 'Thịt đùi gà ta hầm thơm gừng sả và nấm hương tươi, nước dùng vàng óng thanh ngọt nhúng cùng nấm đùi gà, bắp cải và rau muống', 'Lẩu gà nấm ấm bụng mang hương vị dịu nhẹ chuẩn cơm tiệc gia đình miền Bắc. Đùi gà ta xào săn cùng gừng tươi và sả cây rồi hầm mềm ngọt nước, kết hợp nấm hương tươi thơm nức, nấm đùi gà giòn ngọt cùng bắp cải và rau muống xanh mát.', 'Dọn nồi lẩu sôi lăn tăn trên bàn tiệc ngày se lạnh, nhúng nấm đùi gà, bắp cải và rau muống; ăn nóng cùng bún tươi và chén muối tiêu chanh ớt chấm thịt gà.', 'Nếu còn dư nước dùng và thịt gà, để nguội hoàn toàn rồi bảo quản ngăn mát tối đa 24 giờ; khi dùng lại đun sôi 5 phút trước khi nhúng thêm rau.', 'vietnamese', 'mon_lau_tiec', 'bac', 'medium', 20, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Món lẩu","Gà nấm","Bắc Bộ","Ấm bụng","Gia đình"]', '["lunch","dinner"]', '["simmer","boil"]', '["chicken","fish"]', 554, 554.4, 2320, 40.5, 21.5, 5.4, 51.5, 6.9, 8, 1460, 3.65, '["NIN VN Fresh Bun Ref","USDA FDC 168573","USDA FDC 168580","USDA FDC 169230","USDA FDC 169231","USDA FDC 169251","USDA FDC 169378","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'd2559e40cca13fbbe6e732c5dd28ff7ab68482294487078ef2c9ae773f222b3c', 'edbca77cb531dbec35df9365460b15ab109da66afb836af0bce1be156affe0f1', 4),
('imp-7fa36d5f0187a86e', 'com-chien-ba-chi-hanh', 206, 'Cơm chiên ba chỉ hành', 'Thịt ba chỉ cắt hạt lựu rang cháy cạnh béo thơm cùng tỏi phi, cơm nguội săn tơi đậm xì dầu và nhiều hành lá', 'Món cơm chiên ba chỉ hành thơm nức mũi với những miếng thịt ba chỉ cắt hạt lự chiên giòn cạnh tiết mỡ béo ngậy, hạt cơm rang săn rời áo hương tỏi phi, xì dầu dậy mùi khói chảo cùng thật nhiều hành lá tươi xanh.', 'Múc cơm chiên ba chỉ hành ra đĩa nóng, rắc tiêu đen xay và hành lá, thưởng thức cùng dưa leo thái lát và chén nước tương ớt xắt.', 'Ngon nhất khi ăn nóng để phần ba chỉ cháy cạnh giữ độ giòn. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và rang lại trên chảo nóng không dầu 3 phút.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Ba chỉ","Béo thơm","Nhanh gọn","Cơm nhà"]', '["breakfast","lunch","dinner"]', '["pan_fry","stir_fry"]', '["pork","soybean","wheat"]', 595, 594.7, 2488, 11.9, 35.1, 12.2, 56.2, 1.4, 1.6, 935, 2.34, '["USDA FDC 167820","USDA FDC 168878","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', 'f7ca9be077b285f8d58a29ffd23ad81d3647c25e570f860d45c5c994cb5141b6', 'b236b420adf65df735ee7c013aa837d0a1e2e0e92d4ddc392193e6318a367e10', 4),
('imp-fcf23c737f51ef13', 'com-chien-ca-chua-trung', 207, 'Cơm chiên cà chua trứng', 'Hạt cơm tơi săn áo sốt cà chua tương cà đỏ óng hòa cùng trứng bác bông mềm và hương dầu mè thơm nức', 'Món cơm chiên cà chua trứng kiểu Trung Hoa giản dị nhưng cuốn hút với từng hạt cơm nguội tơi ráo quyện đều nước sốt cà chua chua ngọt, dầu hào đậm đà và những mảng trứng gà chiên mềm thơm.', 'Múc cơm chiên ra tô hoặc đĩa sâu lòng, rắc hành lá thái nhỏ lên trên; dùng nóng ngay cùng dưa leo thái lát hoặc canh rong biển thanh mát.', 'Ngon nhất khi ăn ngay lúc vừa chiên xong; nếu bảo quản ngăn mát trong hộp kín tối đa 2 ngày, khi hâm lại đảo trên chảo chống dính lửa vừa 3–4 phút cho hạt cơm nóng tơi trở lại.', 'chinese', 'mon_nhanh_sang', NULL, 'easy', 10, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Cơm chiên","Cà chua","Trứng gà","Trung Hoa","Món nhanh"]', '["breakfast","lunch","dinner"]', '["stir_fry"]', '["egg","molluscs","sesame","soybean","wheat"]', 625, 624.7, 2613, 19.4, 24.7, 5.2, 79.7, 2.3, 9.1, 1361, 3.4, '["Dark Soy Sauce Label Ref","USDA FDC 168878","USDA FDC 169076","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170457","USDA FDC 170933","USDA FDC 171028","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468"]', '425b0f70cad55799855b64e58d584c55c6646dda18fe540f2e72b9002176ab26', '7e985363a21ae73ce4001ba679331fb581d2f53cd63cadb6e4b5a69df4835778', 4),
('imp-a5148e527a9ce9cf', 'ga-xao-gung-hanh-trung', 208, 'Gà xào gừng hành kiểu Trung', 'Thịt đùi gà mềm mọng xào lửa lớn thấm sốt gừng non nạo, hành tây ngọt và hành lá thơm nồng đưa cơm', 'Món gà xào gừng hành kiểu Trung Hoa chế biến nhanh gọn nhưng đậm đà nhờ phần nước sốt pha gừng non nạo nhuyễn kết hợp xì dầu, dầu hào và hành lá cắt khúc thơm nồng.', 'Dọn nóng ra đĩa sâu lòng cùng phần nước sốt sánh bóng chan cơm trắng; ăn kèm rau cải luộc hoặc dưa leo tươi.', 'Bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; khi dùng, đun nóng trên chảo lửa vừa 3–4 phút cùng 1–2 muỗng canh nước lọc để sốt sánh mượt trở lại.', 'chinese', 'mon_xao', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt gà","Gừng hành","Trung Hoa","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["chicken","molluscs","soybean","wheat"]', 300, 299.8, 1255, 24.7, 16.8, 4.1, 11, 1.3, 4.1, 1090, 2.73, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170000","USDA FDC 170005","USDA FDC 170933","USDA FDC 171369","USDA FDC 171413","USDA FDC 172385","USDA FDC 173647","USDA FDC 174277"]', 'a5647acfc4e226d23b478b897eb26d422d2725ff1d1b6125bc7f47f45dc385a1', '00af15f5958ceeb63b7bb893fd9774f82b8c9bff3743f68d0870d46f8716863e', 4),
('imp-b3d9ecb751b0a043', 'bo-xao-hanh-tay-ot', 209, 'Bò xào hành tây ớt kiểu Trung', 'Thịt bò thăn thái mỏng thấm xì dầu, dầu hào xào lửa lớn cùng hành tây giòn ngọt và ớt hiểm cay nồng', 'Món bò xào hành tây ớt kiểu Trung Hoa hấp dẫn bởi từng lát thịt bò thăn mềm ngọt quyện sốt xì dầu dầu hào bóng mịn, kết hợp cùng hành tây giòn ngọt và chút cay nồng của ớt hiểm.', 'Dọn nóng ngay ra đĩa, rắc thêm chút tiêu đen xay lên trên; thưởng thức cùng cơm trắng nóng hoặc bánh mì.', 'Ngon nhất khi ăn ngay lúc vừa xào xong để bò mềm và hành tây còn độ giòn; nếu còn dư, bảo quản ngăn mát tối đa 24 giờ và đảo nhanh trên chảo nóng 1 phút khi hâm lại.', 'chinese', 'mon_xao', NULL, 'easy', 20, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Hành tây","Trung Hoa","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","molluscs","soybean","wheat"]', 295, 295.1, 1235, 22.1, 19.1, 5.4, 8.4, 1, 3.4, 925, 2.31, '["USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170106","USDA FDC 170187","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', 'c617e98bd2da57ce1532d8e2040441041b97c323163ed9e0142534106a2f05d9', '73adbeacc0d9ce3b67062660871d81d1a0d23f91e2bfa3175a835dc3869cae1c', 4),
('imp-835a527c81a79e9c', 'sup-bap-cai-thit-bam', 210, 'Súp cải thảo thịt bằm kiểu Trung', 'Nước dùng gà trong ngọt nấu cùng cải thảo mềm thanh, thịt heo bằm xào thơm và gừng ấm bụng', 'Món canh súp cải thảo thịt bằm kiểu Trung Hoa có nước dùng trong veo ngọt dịu từ gà và rau củ, thịt heo bằm ướp mềm đậm vị kết hợp cùng cọng cải thảo chín tới ấm lòng cho bữa cơm tối.', 'Múc canh ra tô sứ lớn, nhỏ vài giọt dầu mè thơm và rắc hành lá thái nhỏ lên mặt; ăn nóng cùng cơm trắng.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn đun sôi lại trên lửa vừa 3–4 phút.', 'chinese', 'mon_canh', NULL, 'easy', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Cải thảo","Thịt bằm","Trung Hoa","Thanh đạm"]', '["lunch","dinner"]', '["stir_fry","simmer"]', '["pork","sesame","soybean","wheat"]', 254, 254.1, 1063, 14.3, 18.7, 5.8, 7, 2, 2.9, 1260, 3.15, '["Shaoxing Wine Ref","USDA FDC 167902","USDA FDC 169231","USDA FDC 169698","USDA FDC 169977","USDA FDC 170005","USDA FDC 170393","USDA FDC 170933","USDA FDC 171028","USDA FDC 171413","USDA FDC 172883","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '48b2cc76fc304e9b77943b86b25cafb865295aacd4f57738ddcbe0b64dedb821', 'aed14aa421063f7fc2323b437e1234ea8a99b7f5ac13b5fcffa92b91443ef66f', 4),
('imp-1dc0835c31b06d5e', 'tom-xao-bong-cai-trung', 211, 'Tôm xào bông cải xanh kiểu Trung', 'Tôm tươi săn giòn đỏ hồng xào cùng bông cải xanh mướt thấm sốt dầu hào Hoisin bóng nhẹ chuẩn Quảng Đông', 'Món tôm xào bông cải xanh kiểu Trung Hoa cân bằng dinh dưỡng với từng con tôm tươi săn ngọt kết hợp bông cải xanh chín tới giòn mướt nhờ kỹ thuật ủ hơi nước, phủ lớp sốt dầu hào bóng nhẹ.', 'Trút ra đĩa lớn, dọn nóng ngay để giữ độ giòn của bông cải xanh và vị ngọt săn của tôm; dùng kèm cơm trắng rất hợp.', 'Ngon nhất khi thưởng thức ngay lúc nóng; nếu còn dư, đậy kín bảo quản ngăn mát tối đa 24 giờ và đảo nhanh trên chảo lửa vừa 1–2 phút khi hâm lại.', 'chinese', 'mon_xao', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Tôm tươi","Bông cải xanh","Quảng Đông","Thanh ngọt"]', '["lunch","dinner"]', '["stir_fry","steam"]', '["crustaceans","molluscs","sesame","shrimp","soybean","wheat"]', 346, 345.8, 1447, 35.6, 15.5, 2.3, 19.5, 4.2, 6, 1453, 3.63, '["Dark Soy Sauce Label Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170106","USDA FDC 170379","USDA FDC 170931","USDA FDC 171319","USDA FDC 171369","USDA FDC 171370","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', 'ea85c6268421c353b95f49e83c76f1ed5f3061d560a12e7a865cd9f40827b4ff', 'e884ec0cdc5fc16fbd6da9697d4821191fa073bdad5e4daad458e0d368aa88aa', 4),
('imp-57b4406be05661c7', 'ba-chi-xao-tuong-dau', 212, 'Thịt ba chỉ xào tương đậu', 'Lát ba chỉ áp chảo cháy cạnh giòn béo xào quyện tương ớt đậu bản Doubanjiang, đậu đen muối và ớt chuông giòn ngọt', 'Món thịt ba chỉ xào tương đậu đậm chất cơm nhà Trung Hoa với từng miếng ba chỉ áp chảo xém cạnh thơm béo, quyện trong mùi thơm nồng đặc trưng của tương ớt đậu bản Doubanjiang và đậu tương đen lên men Douchi.', 'Dọn nóng ngay ra đĩa, dùng kèm cơm trắng nóng để cân bằng vị mặn béo đậm đà; có thể ăn kèm rau cải luộc.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn đảo nhanh trên chảo lửa vừa 2–3 phút cho thịt nóng giòn trở lại.', 'chinese', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt ba chỉ","Tương đậu","Trung Hoa","Đưa cơm"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["pork","soybean","wheat"]', 737, 736.7, 3082, 15.1, 67.5, 23.8, 16.6, 3.4, 7.5, 1276, 3.19, '["Dark Soy Sauce Label Ref","Douchi Reference","Pixian Doubanjiang Ref","Shaoxing Wine Ref","USDA FDC 167820","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170108","USDA FDC 170933","USDA FDC 171413","USDA FDC 174277"]', 'b61931828870200eb549ca9b31feded8a3791d07f5111f4c563159cc91215d0a', 'c587cad384601ce68d34943e2118cc0c54c5cf9e13970cb24e57a9b45814b4ef', 4),
('imp-3774a1f0fda5cce1', 'ga-sot-chua-ngot-trung', 213, 'Gà chiên sốt chua ngọt kiểu Trung', 'Miếng ức gà tẩm bột chiên giòn rụm hai lần phủ sốt chua ngọt dứa chín, tương cà và ớt chuông bóng đẹp', 'Món gà chiên sốt chua ngọt kiểu Trung Hoa hấp dẫn với lớp vỏ bột mỏng nhẹ giòn rụm nhờ kỹ thuật chiên hai lần, quyện trong nước sốt chua ngọt sóng sánh cùng dứa chín, ớt chuông và hành tây tím.', 'Dọn nóng ngay ra đĩa khi lớp vỏ gà vẫn còn giòn tan, ăn kèm cơm trắng hoặc mì xào rau củ.', 'Ngon nhất khi ăn ngay sau khi trộn sốt; nếu cần chuẩn bị trước, nên giữ riêng phần gà đã chiên lần một và chỉ chiên giòn lần hai rồi áo sốt ngay trước bữa ăn.', 'chinese', 'mon_chien', NULL, 'medium', 20, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Chua ngọt","Thịt gà","Trung Hoa","Món tiệc"]', '["lunch","dinner"]', '["deep_fry","stir_fry"]', '["chicken","sesame","wheat"]', 503, 502.5, 2102, 32, 19.3, 3, 49.1, 2.6, 18, 747, 1.87, '["USDA FDC 169076","USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 169698","USDA FDC 169761","USDA FDC 170000","USDA FDC 170108","USDA FDC 170933","USDA FDC 171028","USDA FDC 171325","USDA FDC 171413","USDA FDC 171477","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC 175039"]', '5618cb6677557a414aa2316b467b263b355ce7154ca23270a115a5b8c83f0082', '1cf96e7d06f10449ba7a544fbbe707e8f992e83bc742f633a3fcb569792629e0', 4),
('imp-49ca1819d60ffec8', 'mi-hanh-dau', 214, 'Mì trộn dầu hành kiểu Quảng Đông', 'Sợi mì dai mượt trộn quyện dầu hành phi vàng thơm nức và sốt xì dầu hai vị mặn ngọt bóng bẩy', 'Món mì trộn dầu hành nổi tiếng với hương thơm quyến rũ từ hành lá phi chậm trong dầu nguội hòa quyện cùng xì dầu nhạt, xì dầu đặc và đường cát tạo nên lớp sốt nâu bóng áo đều từng sợi mì dai ngon.', 'Chia mì ra tô sâu lòng, rắc hành lá phi giòn và hạt mè rang lên mặt; có thể ăn kèm trứng ốp la hoặc cải thìa chần.', 'Mì ngon nhất khi trộn và ăn ngay lúc nóng; riêng phần sốt dầu hành có thể làm sẵn để hũ thủy tinh kín trong ngăn mát dùng dần trong 2 tuần.', 'chinese', 'mon_bun_pho', NULL, 'easy', 5, 12, 2, '/frigo/illustrations/delicious-meal.png', '["Mì trộn","Dầu hành","Quảng Đông","Món nhanh","Giản dị"]', '["breakfast","lunch","dinner"]', '["boil","pan_fry","toss_mix"]', '["egg","sesame","soybean","wheat"]', 520, 520.4, 2178, 14.6, 18, 2.9, 75.6, 3.9, 5.1, 1498, 3.74, '["Dark Soy Sauce Label Ref","USDA / MEXT Wheat Noodle Ref","USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '16283652a9c8fca1ecee7dc8010224e2120bd491035e7de7c9bb3b1a9f3cf5d8', '61378ba5b3d5cc4ba73423db15bbf86a834014778fee75789684dcfde5d16007', 4),
('imp-2b5b79ba1b622db1', 'canh-cai-thao-tom', 215, 'Canh cải thảo nấu tôm', 'Canh cải thảo mềm ngọt nấu cùng tôm khô đậm đà, nước dùng gà thanh trong và gừng hành ấm áp', 'Món canh cải thảo nấu tôm mang vị ngọt thanh tự nhiên từ tôm khô ninh kỹ hòa quyện cùng nước dùng gà trong veo, lá cải thảo mềm mọng và hương thơm ấm áp của gừng tươi.', 'Múc canh nóng hổi ra tô lớn, nhỏ vài giọt dầu mè thơm và rắc hành lá thái nhỏ; dùng kèm cơm trắng trong bữa ăn hằng ngày.', 'Ngon nhất khi dùng hết trong ngày; nếu bảo quản ngăn mát tối đa 24 giờ, đun sôi nhẹ lại 2–3 phút trên lửa vừa trước khi ăn.', 'chinese', 'mon_canh', NULL, 'easy', 10, 18, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Cải thảo","Tôm khô","Trung Hoa","Thanh ngọt"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","sesame","shrimp"]', 101, 100.8, 422, 10.3, 4.7, 0.8, 5.2, 1.9, 2.5, 941, 2.35, '["USDA / Asian Dried Shrimp Ref","USDA FDC 169231","USDA FDC 169977","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171413","USDA FDC 172883","USDA FDC 173468","USDA FDC 173647"]', 'e795e4571c666ebca4c9e249a54173f37f36d90fb1913467061421c26c663e21', '08e0a3d965682e68c00c2b527fca229cfed88451a62427450f7f71a289c77f3e', 4),
('imp-ee5bc076d722f397', 'ga-hap-nam-dong', 216, 'Gà hấp nấm đông cô', 'Thịt đùi gà ướp mềm đậm vị hấp cách thủy cùng nấm hương khô và gừng sợi giữ trọn nước ngọt thanh', 'Món gà hấp nấm đông cô kiểu gia đình Trung Hoa giữ nguyên độ mọng nước ngọt tự nhiên của thịt đùi gà ướp bột bắp kết hợp hương thơm umami đậm đà từ nấm hương khô ngâm nở.', 'Đặt nguyên đĩa gà hấp nóng hổi lên bàn ăn, rắc hành lá thái nhỏ; dùng kèm cơm trắng và chan phần nước thịt ngọt tiết ra trong đĩa.', 'Bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; khi ăn hấp lại trong xửng khoảng 5–7 phút cho thịt và nấm nóng đều.', 'chinese', 'mon_hap_luoc', NULL, 'easy', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Thịt gà","Nấm hương","Trung Hoa","Gia đình"]', '["lunch","dinner"]', '["steam"]', '["chicken","molluscs","sesame","soybean","wheat"]', 266, 265.6, 1112, 25.3, 13.8, 3.7, 9.5, 1.2, 1.5, 302, 0.76, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA FDC 168436","USDA FDC 169231","USDA FDC 169698","USDA FDC 170005","USDA FDC 170106","USDA FDC 170933","USDA FDC 171028","USDA FDC 171369","USDA FDC 172385","USDA FDC 174277","USDA FDC Jujube Ref"]', 'e2e6c4755b62d64c1308b7abee87ae137f34875a6bd737a662715a9b3713acde', '5d2518c217726f864fafd8608d670f4ede43186f18517bdf773a48ffa741129b', 4),
('imp-aac2c265c3845ec4', 'tom-hap-gung-hanh', 217, 'Tôm hấp gừng hành kiểu Quảng Đông', 'Tôm sú tươi còn vỏ hấp chín hồng mọng nước cùng gừng sợi, rưới sốt xì dầu pha thơm nhẹ tinh tế', 'Món tôm hấp gừng hành kiểu Quảng Đông tôn vinh trọn vẹn độ ngọt giòn tự nhiên của tôm sú tươi hấp chín vừa tới trong vòng 5–6 phút, phủ lớp gừng sợi, hành lá xanh mướt và nước sốt xì dầu dịu nhẹ.', 'Dọn nóng nguyên đĩa tôm hấp ngay khi vừa rưới sốt, dùng kèm cơm trắng và chấm thêm nước sốt xì dầu đọng dưới đáy đĩa.', 'Tôm hấp ngon nhất khi thưởng thức ngay lúc nóng để thịt giòn ngọt; nếu còn dư, bóc vỏ bảo quản ngăn mát tối đa 24 giờ và hấp nhanh 2 phút khi dùng lại.', 'chinese', 'mon_hap_luoc', NULL, 'easy', 10, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Tôm sú","Gừng hành","Quảng Đông","Thanh đạm"]', '["lunch","dinner"]', '["steam"]', '["crustaceans","sesame","shrimp","soybean","wheat"]', 158, 157.9, 661, 24.7, 4.4, 0.7, 4.6, 0.6, 1.9, 703, 1.76, '["Shaoxing Wine Ref","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '75f53e45e000423781fed7ad80e35ca630e10b7794c5c5ccdbde25259e127d3a', 'a67b088b6d267853ff5fbadb7f73ca584408ad977930a83397c006538c8e7e57', 4),
('imp-55201e4225342ca3', 'ca-sot-chua-ngot-trung', 218, 'Cá phi lê sốt chua ngọt kiểu Trung', 'Phi lê cá thịt trắng chiên vàng giòn rụm áo sốt chua ngọt cà chua, dứa chín và ớt chuông bóng loáng', 'Món cá phi lê sốt chua ngọt kiểu Quảng Đông nổi bật với từng miếng phi lê cá lọc xương áo lòng trắng trứng và bột bắp chiên vàng giòn rụm, hòa quyện trong phần sốt tương cà, giấm gạo, dứa chín và rau củ giòn tươi.', 'Dọn nóng ngay ra đĩa bầu dục khi cá vừa phủ sốt, dùng kèm cơm trắng nóng để cảm nhận trọn vẹn độ giòn bên ngoài và thịt cá mềm ngọt bên trong.', 'Ngon nhất khi ăn ngay lúc vừa chế biến; nếu cần chuẩn bị trước, giữ riêng cá chiên và sốt trong hộp kín ngăn mát tối đa 24 giờ, khi ăn chiên giòn lại cá rồi mới đảo nhanh với sốt nóng.', 'chinese', 'mon_chien', NULL, 'medium', 20, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Chua ngọt","Phi lê cá","Quảng Đông","Món tiệc"]', '["lunch","dinner"]', '["deep_fry","stir_fry"]', '["egg","fish","soybean","wheat"]', 443, 442.6, 1853, 38.7, 17.7, 3.2, 31.5, 1.9, 16.2, 1037, 2.59, '["USDA FDC 169076","USDA FDC 169124","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170000","USDA FDC 170005","USDA FDC 170108","USDA FDC 170457","USDA FDC 170933","USDA FDC 171287","USDA FDC 171413","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175148"]', 'e427c5ec180552c80fa0e8c8f5a8dbe3e80389e6dd61d38b8486aa64c81dfd78', 'bac9d9750e554e4257532f2134a826eaadf18b83ee34422e719bd2baf311b4e5', 4),
('imp-6771c725aa163703', 'dau-phu-lanh-hanh', 219, 'Đậu phụ non sốt hành xì dầu lạnh', 'Đậu phụ non mát lạnh mịn mướt chan sốt xì dầu hành lá thơm nồng, pha chút chua nhẹ giấm gạo và vị cay tê của ớt hiểm', 'Món khai vị lạnh chuẩn vị Trung Hoa với từng khối đậu phụ non mềm tan như kem, quyện cùng nước sốt xì dầu nhạt đun thơm hành tỏi, điểm chút giấm gạo thanh dịu, dầu mè béo thơm và ớt hiểm tươi cay nhẹ.', 'Rắc thêm hành lá xanh và mè rang lên mặt đậu, dọn lạnh ngay cùng cơm trắng nóng hoặc dùng làm món khai vị giải nhiệt đầu bữa.', 'Nên thưởng thức ngay sau khi làm mát 15–20 phút để đậu giữ độ tươi mượt; sốt dư bảo quản lọ kín trong ngăn mát tối đa 5 ngày.', 'chinese', 'mon_chay', NULL, 'easy', 10, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món lạnh","Khai vị","Đậu phụ","Thanh mát","Chay"]', '["lunch","dinner"]', '["simmer","assemble"]', '["sesame","soybean","wheat"]', 148, 148.2, 620, 9.4, 7.9, 1.1, 10.5, 1, 4.4, 1067, 2.67, '["USDA FDC 168833","USDA FDC 169230","USDA FDC 170005","USDA FDC 170106","USDA FDC 170150","USDA FDC 171028","USDA FDC 172238","USDA FDC 172476","USDA FDC 174277"]', '7d6bf6fddf250300263aff0e80e5d368019642bffd8dbee86b018f56b3c04f6b', 'a6407dc35899329e9d90ce65ca337134be547fb824eb8d2430a037eac50e9296', 4),
('imp-5eb2769876646aae', 'mi-tron-dau-phu-cay', 220, 'Mì trộn đậu phụ chiên giòn sốt cay', 'Sợi mì dai mượt áo sốt xì dầu đậm vị cùng dầu ớt cay nồng, kết hợp đậu phụ chiên giòn rụm bên ngoài, mềm béo bên trong', 'Bữa trưa nhanh gọn mà đầy đủ năng lượng với sợi mì lúa mì dai ngon trộn đều trong nước sốt xì dầu nhạt, xì dầu đặc, giấm gạo và dầu ớt thơm lừng tỏi phi, ăn kèm những khối đậu phụ áo bột bắp ngũ vị chiên giòn rụm.', 'Chia mì đã trộn sốt ra tô, xếp đậu phụ chiên giòn lên trên cùng (không trộn trước) và rắc hành lá thái nhỏ, dùng ngay để giữ lớp vỏ đậu giòn lâu.', 'Món ngon nhất khi dùng ngay lúc mới trộn; nếu chuẩn bị trước, nên tách riêng mì trộn sốt và đậu phụ chiên, khi ăn chỉ cần làm nóng lại đậu bằng nồi chiên không dầu 3 phút ở 180°C.', 'chinese', 'mon_bun_pho', NULL, 'easy', 25, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Mì trộn","Đậu phụ","Cay nồng","Nhanh gọn","Bữa trưa"]', '["breakfast","lunch","dinner"]', '["boil","pan_fry","toss_mix"]', '["sesame","soybean","wheat"]', 416, 415.6, 1738, 17.5, 19.6, 2.9, 45.6, 3.2, 5.1, 1634, 4.09, '["Chili Oil / Satay Ref","Dark Soy Sauce Label Ref","Five Spice USDA Ref","NIN VN Fresh Rice Noodle Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170106","USDA FDC 171028","USDA FDC 171413","USDA FDC 172238","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '164b5d3140407eb2554b4b03b7b1b674be2857686c134d7cb71fa55d1a6094c9', '2af83bc4c416bc7a85cc18f4f29b782cd33a72015933c0e8556886281218067f', 4),
('imp-87adca15ad4c1369', 'ga-ham-nikujaga-ca-rot', 221, 'Gà hầm Nikujaga cà rốt', 'Đùi gà, khoai tây, cà rốt và hành tây hầm mềm thấm đẫm nước dùng Dashi xì dầu Mirin ngọt mặn đậm cơm nhà Nhật', 'Gà hầm Nikujaga biến tấu thanh nhẹ từ món hầm truyền thống Nhật Bản với thịt đùi gà mềm ngọt thay cho thịt bò, hầm cùng khoai tây bở bùi, cà rốt và hành tây trong nước dùng Dashi hòa quyện xì dầu, rượu Sake và Mirin.', 'Múc gà hầm Nikujaga cùng khoai tây, cà rốt và ít nước hầm nóng ra bát sâu lòng, rắc hành lá thái nhỏ lên trên rồi dùng nóng với cơm trắng.', 'Để nguội hoàn toàn rồi cất trong hộp kín ở ngăn mát tủ lạnh tối đa 3 ngày; hôm sau hâm nóng lại trên lửa nhỏ món hầm càng ngấm vị đậm đà (không nên cấp đông vì khoai tây dễ bị bở).', 'japanese', 'mon_kho', NULL, 'easy', 20, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Nikujaga","Thịt gà hầm","Ẩm thực Nhật","Cơm nhà","Mùa lạnh"]', '["lunch","dinner"]', '["simmer","braise"]', '["chicken","fish","soybean","wheat"]', 319, 319, 1335, 21.8, 11.6, 2.9, 29.1, 3.6, 10.6, 1474, 3.68, '["MEXT Hon-Mirin 16031","MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170026","USDA FDC 170393","USDA FDC 171413","USDA FDC 172385","USDA FDC 174277"]', 'c68561034947f0834ba0ad946c3bd8f06fdca4bf640916219b4733f43e66ff72', '328703ae0476424335d86cb1355de6f7db7826ea7bb93fc531f81957cdda264b', 4),
('imp-62d95da722597187', 'mi-soba-tron-nam-me', 222, 'Mì Soba trộn nấm mè', 'Mì Soba kiều mạch dai bùi trộn nấm đùi gà áp chảo xém cạnh quyện sốt xì dầu giấm gạo, dầu mè và hạt mè rang thơm', 'Mì Soba trộn nấm mè mang hương vị thanh nhã của mì kiều mạch Nhật Bản dai mềm, hòa quyện cùng nấm đùi gà xào vàng giòn sần sật, gừng bào, hành lá và phần sốt mè rang thơm bùi đậm vị xì dầu giấm gạo.', 'Chia mì Soba trộn nấm ra đĩa hoặc bát nông, rắc phần hành lá và hạt mè rang chừa lại lên trên; có thể thưởng thức lúc còn ấm nóng hoặc để mát đều ngon.', 'Ngon nhất khi dùng trong ngày; nếu bảo quản ngăn mát tối đa 24 giờ trong hộp kín, nên để riêng phần sốt trộn và nấm xào để sợi mì Soba không bị trương mềm.', 'japanese', 'mon_bun_pho', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Mì Soba","Nấm đùi gà","Mè rang","Ẩm thực Nhật","Bữa trưa"]', '["lunch","dinner"]', '["boil","stir_fry","toss_mix"]', '["buckwheat","sesame","soybean","wheat"]', 446, 445.7, 1865, 17, 15.9, 2.3, 63.7, 7.2, 5.9, 1811, 4.53, '["MEXT Dry Soba 01097","USDA FDC 168580","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 170499","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172238","USDA FDC 173647","USDA FDC 174277"]', '2b9a7226031f3e72c7f68cfe3eb9129356a21a8476b40c33a478044090f6fcc3', 'd0eedf7f7e5d7b7ef51801aa71ece3a181a9600c37b3fed924a3996f396883b1', 4),
('imp-d2ab8a9e07388289', 'muc-nuong-teriyaki', 223, 'Mực nướng Teriyaki', 'Mực ống tươi chần săn khứa vằn nướng lửa lớn phết sốt Teriyaki sánh bóng, ngọt mặn đậm đà hương gừng tỏi', 'Mực nướng Teriyaki kiểu Nhật (Ika Maruyaki) giữ trọn độ giòn ngọt tự nhiên của mực ống tươi nhờ chần nhanh rồi nướng xém cạnh, phủ lớp sốt Teriyaki nấu từ xì dầu, rượu Sake, Mirin và đường nâu sánh bóng thơm lừng.', 'Cắt thân mực nướng thành từng khoanh tròn dày 1,5 cm, xếp ra đĩa cùng phần râu mực giòn, rưới thêm nước sốt Teriyaki còn lại và rắc hành lá thái nhỏ rồi dùng nóng.', 'Nên dùng hết trong bữa để mực giữ độ giòn ngọt; nếu còn dư, bọc kín bảo quản ngăn mát tối đa 24 giờ và làm nóng nhanh trên chảo cùng phần sốt dư trong 1–2 phút.', 'japanese', 'mon_lau_tiec', NULL, 'easy', 20, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Mực nướng","Teriyaki","Hải sản","Ẩm thực Nhật","Món nướng"]', '["lunch","dinner"]', '["boil","grill_roast"]', '["molluscs","soybean","squid","wheat"]', 301, 300.7, 1258, 30.8, 6.8, 1.3, 21.8, 0.5, 11, 1318, 3.3, '["MEXT Hon-Mirin 16031","MEXT Sake 16021","USDA FDC 168833","USDA FDC 169230","USDA FDC 169231","USDA FDC 169698","USDA FDC 170005","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","USDA FDC 174277"]', 'f890c9afb1298e60e6c9aaf7c5dd119aecb22cd4e73fed863e9444594bb89e01', '355660a2e522ec5fcc9867baa41424bcf99bb7a96dbf66a0c9a283b751056aec', 4),
('imp-81ff926a5557c059', 'ca-hoi-nuong-miso', 224, 'Cá hồi nướng Miso', 'Phi lê cá hồi ướp tương Miso trắng hòa quyện Sake, Mirin và xì dầu nướng vàng xém cạnh, mềm béo đậm đà kiểu Saikyo Yaki', 'Cá hồi nướng Miso (Saikyo Yaki) là món cá nướng tinh tế nổi tiếng của Nhật Bản, dùng tương Miso trắng ngọt dịu kết hợp rượu Sake, Mirin và chút dầu mè ướp thấm nhẹ vào từng thớ cá hồi béo ngậy rồi nướng lửa trên vàng xém thơm lừng.', 'Bày từng miếng cá hồi nướng Miso mặt da úp xuống hoặc ngửa tùy thích ra đĩa, rắc thêm hạt mè rang và hành lá thái xéo lên trên, ăn nóng kèm cơm trắng và củ cải bào.', 'Bảo quản cá hồi nướng Miso trong hộp kín ở ngăn mát tủ lạnh tối đa 3 ngày; khi dùng làm nóng lại bằng lò nướng hoặc nồi chiên không dầu ở 160°C trong 3–4 phút.', 'japanese', 'mon_chien', NULL, 'easy', 20, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Cá hồi","Tương Miso","Món nướng","Ẩm thực Nhật","Cơm tối"]', '["lunch","dinner"]', '["grill_roast"]', '["fish","salmon","sesame","soybean","wheat"]', 440, 440.1, 1841, 37.3, 26.4, 5.7, 8.7, 1.1, 4.2, 998, 2.5, '["MEXT Hon-Mirin 16031","MEXT Sake 16021","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 171413","USDA FDC 172446","USDA FDC 174277","USDA FDC 175167"]', '8a22be9422c20b4556546a10e625a2722251e8d911642f0128bde4a81e44e01d', 'ed329b8e33f4240fd9256b22c0e484b03e0cf25b4ab0ad79efe5d9c9f0032e47', 4),
('imp-8c6abf9194ba8c45', 'ga-xao-gia-itame', 225, 'Gà xào giá Itame', 'Đùi gà áp chảo da vàng giòn trộn thấm sốt xì dầu tỏi, xào nhanh lửa lớn cùng giá đỗ giòn sần sật thanh đạm', 'Gà xào giá Itame (Tori Moyashi Itame) là món xào nhà Nhật nhanh gọn chỉ trong 20 phút, kết hợp thịt đùi gà áp chảo vàng thơm thấm sốt xì dầu tỏi và giá đỗ xào nhanh trên lửa lớn nên vẫn giữ được độ giòn ngọt tươi mát.', 'Múc gà xào giá nóng hổi ra đĩa rộng, rắc hành lá băm nhỏ cùng chút tiêu đen xay lên trên và dùng ngay khi còn nóng kèm cơm trắng.', 'Nên ăn hết ngay sau khi xào để giá đỗ giữ được độ giòn tươi; nếu dư, bảo quản ngăn mát tối đa 24 giờ và đảo nóng nhanh trên lửa lớn 1 phút.', 'japanese', 'mon_xao', NULL, 'easy', 10, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Gà xào","Giá đỗ","Itame","Ẩm thực Nhật","Nhanh gọn"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["chicken","sesame","soybean","wheat"]', 339, 338.5, 1417, 33.5, 19, 4.8, 8.8, 2.2, 4.5, 1236, 3.09, '["USDA FDC 169230","USDA FDC 169963","USDA FDC 170005","USDA FDC 170931","USDA FDC 171028","USDA FDC 172385","USDA FDC 173468","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '52206e2eebae61603d3d999c0e548181f77d437566b26e13bfe5644c909200c4', '70c0441dcd4cfb4c45340c65a3de0a18ec647b92f96fc8c55c9b42ea102bd2ae', 4),
('imp-b33750551f6ea7fe', 'nam-nuong-bo-shoyu', 226, 'Nấm nướng bơ Shoyu', 'Nấm đùi gà thái khoanh dày khía caro áp chảo vàng nâu quyện bơ tan chảy và xì dầu cháy cạnh thơm nức kiểu Izakaya', 'Nấm nướng bơ Shoyu là món nhậu Izakaya kinh điển của Nhật Bản, dùng nấm đùi gà cắt khoanh dày khía caro áp chảo vàng ruộm rồi áo đẫm bơ béo thơm và xì dầu Nhật rưới cháy cạnh, cắn vào giòn sần sật đậm vị umami.', 'Xếp từng khoanh nấm nướng bơ Shoyu lên đĩa ấm, rưới phần bơ xì dầu còn lại trong chảo, rắc hành lá thái nhỏ lên trên rồi thưởng thức ngay khi còn nóng.', 'Ngon nhất khi ăn nóng ngay sau khi áp chảo; nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 2 ngày và làm nóng lại trên chảo khô khoảng 1–2 phút.', 'japanese', 'mon_chien', NULL, 'easy', 10, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Nấm đùi gà","Bơ Shoyu","Izakaya","Ẩm thực Nhật","Nhanh gọn"]', '["lunch","dinner"]', '["pan_fry"]', '["milk","soybean","wheat"]', 116, 115.6, 484, 3.7, 9.4, 4.7, 6.6, 2.5, 1.2, 429, 1.07, '["USDA FDC 168580","USDA FDC 170005","USDA FDC 170931","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468","USDA FDC 174277"]', '663a4b9b85bb5d46e8b09b3fa8976f81cd57a14ac13015440d62dc93ea969976', 'd6d937eb5a0d127ba6b3c340aba53e34f1b471320c9aad7c50f688ae8d07868d', 4),
('imp-e9562581c7d79169', 'com-cua-kanimeshi', 227, 'Cơm cua Kanimeshi', 'Gạo Nhật nấu thấm vị xì dầu Sake hạt nêm gà, trộn thịt cua tươi ngọt thơm, hành lá, dầu mè và trứng gà hấp chín mềm tơi', 'Cơm cua Kanimeshi nấu bằng nồi cơm điện tiện lợi nhưng vẫn đậm đà hương vị biển kiểu Hokkaido, kết hợp cơm gạo Nhật dẻo thơm vị xì dầu và rượu Sake, hòa quyện thịt cua tươi ngọt chắc, dầu mè thơm và lớp trứng đánh hấp tơi béo.', 'Xới cơm cua Kanimeshi ra bát sứ nóng, rắc thêm chút hành lá thái nhỏ và tiêu đen xay lên trên, ăn nóng trực tiếp hoặc kèm súp Miso thanh nhẹ.', 'Để nguội rồi bảo quản hộp kín trong ngăn mát tủ lạnh tối đa 2 ngày; khi ăn rưới thêm một thìa nhỏ nước lọc và hâm nóng lại trong lò vi sóng 1–2 phút cho cơm mềm ẩm.', 'japanese', 'mon_nhanh_sang', NULL, 'medium', 15, 45, 3, '/frigo/illustrations/delicious-meal.png', '["Kanimeshi","Cơm cua","Nồi cơm điện","Ẩm thực Nhật","Hải sản"]', '["lunch","dinner"]', '["boil","steam"]', '["crab","crustaceans","egg","sesame","soybean","wheat"]', 523, 523.2, 2189, 23.1, 9.9, 2.1, 81.2, 1.6, 0.7, 1178, 2.94, '["MEXT Sake 16021","USDA FDC 169756","USDA FDC 170005","USDA FDC 170931","USDA FDC 171009","USDA FDC 171028","USDA FDC 171287","USDA FDC 173468","USDA FDC 173647","USDA FDC 174208","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '9ff61d83a5cea5f490e73dfb955a3848156502d5751a13b1b1a680b492f2f5e3', '3acc6e3cf352eeb5d612addb95a1989535317f9b23b7787cc5afb2eaef7b1928', 4),
('imp-ee7ca138c67f4f24', 'bo-xao-gung-itame', 228, 'Bò xào gừng Itame', 'Thịt bò thái lát áo bột khoai tây mềm mọng, xào nhanh cùng hành tây ngọt giòn và sốt gừng Sake Mirin xì dầu sánh bóng', 'Bò xào gừng Itame kiểu Nhật có miếng thịt bò mềm mọng nhờ bí quyết áo lớp tinh bột khoai tây mỏng, xào nhanh cùng hành tây hấp chín ngọt thanh và gừng tươi hai kiểu vừa thái sợi vừa mài nhuyễn trong nước sốt xì dầu Mirin sánh đậm.', 'Múc bò xào gừng hành tây ra đĩa nông lòng, rắc hành lá thái nhỏ lên trên và dùng nóng ngay cùng cơm trắng dẻo.', 'Nên dùng nóng ngay sau khi xào để thịt bò giữ độ mềm mọng; nếu còn dư, bảo quản hộp kín ngăn mát tối đa 2 ngày và đảo nóng nhanh trên lửa vừa trong 1 phút.', 'japanese', 'mon_xao', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Thịt bò xào","Gừng tươi","Itame","Ẩm thực Nhật","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","sesame","soybean","wheat"]', 272, 272.3, 1139, 19.2, 12, 3.9, 16.9, 1.6, 8.9, 831, 2.08, '["MEXT Hon-Mirin 16031","MEXT Sake 16021","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170187","USDA FDC 170931","USDA FDC 171028","USDA FDC 173468","USDA FDC 174277","USDA FDC Potato Starch"]', 'f0e7d2bc14d03303ab2cb3aec5a82f70f351668d0a931448b2080414ca050ead', '72770dd432f54301313b169f6c342ea320198ae4038e9eaf44762e1059df9f2c', 4),
('imp-57a8ece15d731efb', 'sup-miso-bap-cai', 229, 'Súp Miso bắp cải', 'Nước dùng Dashi thanh ngọt nấu mềm bắp cải xanh, nấm đùi gà giòn ngọt và rong biển Wakame, hòa tương Miso thơm dịu', 'Súp Miso bắp cải là món canh hằng ngày thanh đạm của người Nhật, kết hợp vị ngọt tự nhiên từ bắp cải xanh và nấm đùi gà nấu vừa chín tới trong nước dùng Dashi, hòa tan tương Miso sau khi tắt bếp để giữ trọn hương thơm lên men dịu nhẹ.', 'Múc súp Miso bắp cải nấm nóng ra 3 bát gỗ hoặc bát sứ sâu lòng, rắc hành lá thái xéo mỏng lên trên và thưởng thức nóng đầu bữa cơm.', 'Súp Miso ngon nhất khi dùng nóng ngay sau khi nấu; nếu còn dư, bảo quản ngăn mát tối đa 2 ngày và chỉ hâm nóng lại trên lửa nhỏ đến khi vừa bốc hơi, tuyệt đối không đun sôi bùng.', 'japanese', 'mon_canh', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Súp Miso","Bắp cải","Nấm đùi gà","Ẩm thực Nhật","Món canh"]', '["breakfast","lunch","dinner"]', '["simmer"]', '["fish","sesame","soybean","wheat"]', 95, 94.6, 396, 6.4, 2.9, 0.4, 12.8, 3.8, 3.9, 1528, 3.82, '["MEXT Ichiban Dashi Ref","USDA FDC 168580","USDA FDC 169975","USDA FDC 170005","USDA FDC 170496","USDA FDC 171028","USDA FDC 172446","USDA FDC 174277"]', '40be28752f0d9685725f27634af4b19ac64235e05c3152f64401896d97e998cb', 'c9e0fe0d0dd73be09341851647e5d11815fd19bbc21a3f7b3b2666ba2a5b76ff', 4),
('imp-23a82881883d70fb', 'mi-udon-nam-dau', 230, 'Mì Udon nấm đậu', 'Nước dùng Dashi chay ninh từ tảo bẹ Kombu và nấm hương khô ngọt thanh, ăn cùng mì Udon dai, nấm đùi gà và đậu phụ chiên', 'Mì Udon nấm đậu là tô mì chay thanh tịnh chuẩn vị Nhật Bản, lấy vị ngọt tự nhiên từ tảo bẹ Kombu và nấm hương khô nấu Dashi, kết hợp sợi mì Udon dày dai, đậu phụ chiên vàng mềm béo và nấm đùi gà giòn ngọt.', 'Chia mì Udon ra 3 tô lớn, xếp nấm đùi gà, nấm hương thái lát và đậu phụ chiên lên trên, chan ngập nước dùng Dashi nấm nóng hổi rồi rắc hành lá thái khoanh.', 'Bảo quản riêng phần nước dùng nấm đậu và mì Udon chưa trụng trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn đun sôi lại nước dùng rồi trụng nóng mì sau cùng.', 'japanese', 'mon_bun_pho', NULL, 'easy', 20, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Mì Udon","Đậu phụ","Nấm đùi gà","Món chay","Ẩm thực Nhật"]', '["lunch","dinner"]', '["boil","simmer"]', '["soybean","wheat"]', 412, 411.7, 1722, 16.6, 10, 1.6, 65.3, 6.2, 7.2, 999, 2.5, '["MEXT Boiled/Fresh Udon","MEXT Hon-Mirin 16031","USDA FDC 168436","USDA FDC 168457","USDA FDC 168580","USDA FDC 169655","USDA FDC 170005","USDA FDC 172472","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'f7fa032e5a288b2e3fb25898e2556eefdd50eb94d7b92c6f11dcbfcc4d9c2287', 'f2bac8ed52eeccbd94abf5a0a3bed4d5782a7c7c5631fcef09ea29a90acdb2cd', 4),
('imp-85a3d8b84fc0bc05', 'mi-ramen-pho-mai-kim-chi', 231, 'Mì ramen phô mai kim chi', 'Sợi mì ramen dai ngon thấm nước dùng kim chi cay ấm, quyện lớp phô mai Cheddar tan chảy béo ngậy và trứng gà lòng đào', 'Mì ramen phô mai kim chi kết hợp vị chua cay nồng ấm của kim chi cải thảo xào thơm với nước dùng đậm đà, sợi mì ramen dai giòn, trứng gà lòng đào và lớp phô mai Cheddar tan chảy béo thơm hài hòa.', 'Bưng nguyên nồi nhỏ ra bàn hoặc múc ra tô sâu lòng, rắc hành lá thái nhỏ và thưởng thức ngay khi phô mai còn kéo sợi nóng hổi.', 'Món mì nước ngon nhất khi ăn ngay lúc vừa nấu xong; không nên bảo quản qua đêm vì sợi mì sẽ trương nở và mất độ dai.', 'korean', 'mon_bun_pho', NULL, 'easy', 10, 15, 2, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Mì cay","Phô mai","Kim chi","Món nhanh"]', '["breakfast","lunch","dinner"]', '["boil","simmer"]', '["egg","milk","sesame","wheat"]', 661, 661, 2766, 25.5, 27.1, 8.5, 79.3, 5.1, 5.6, 1545, 3.86, '["Korean Chili Flake Ref","USDA / MEXT Wheat Noodle Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170497","USDA FDC 170499","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 173414","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '2990f477bfc519843cda7f1eb855f95c0117a6023604c139083db60775aee081', '0f2048029bcf0732af4698378ea5894081942771be9c760522bd0b75ce57298a', 4),
('imp-9d28abab0b8e5619', 'ga-ham-kim-chi', 232, 'Gà hầm kim chi (Dak Kimchi Jjim)', 'Đùi gà hầm mềm thấm đẫm vị kim chi cải thảo ủ chua cay nồng, sóng sánh nước sốt đỏ đậm đà kiểu Dak Kimchi Jjim cực đưa cơm', 'Gà hầm kim chi (Dak Kimchi Jjim) kết hợp những miếng đùi gà chặt vừa ăn được om chậm cùng kim chi cải thảo chua lâu năm và sốt Gochujang cay thơm, cho phần thịt gà mềm rục thấm vị và nước sốt sánh đỏ cực kỳ bắt cơm.', 'Bày gà hầm kim chi nóng hổi ra đĩa sâu lòng hoặc nồi đất, rắc hành lá xanh lên mặt và ăn kèm cơm trắng dẻo nóng.', 'Để nguội hoàn toàn rồi bảo quản hộp kín trong ngăn mát tối đa 3 ngày; khi dùng hâm nóng trên lửa vừa 6–8 phút, có thể thêm chút nước nếu sốt quá sánh.', 'korean', 'mon_kho', NULL, 'easy', 15, 40, 4, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món hầm","Thịt gà","Kim chi","Đưa cơm"]', '["lunch","dinner"]', '["braise","simmer"]', '["chicken","fish","sesame","soybean","wheat"]', 370, 369.5, 1547, 33.1, 19.5, 5, 14.6, 3.5, 7.6, 1808, 4.52, '["Korean Chili Flake Ref","MEXT Sake 16021","USDA / Korean Gochujang Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 172185","USDA FDC 172385","USDA FDC 173647","USDA FDC 174277"]', 'bc3cb19bce5a478f8d221f3a31892d681d5a6c969ab726d808bd2eed7d00a6f6', '48f079129023a33b9da3c5f08c87975695ba2cd80afa945f9764b45863939f20', 4),
('imp-2842fe1b767de23d', 'trung-cuon-gyeran-mari', 233, 'Trứng cuộn Hàn Quốc (Gyeran Mari)', 'Cuộn trứng gà vàng ươm mềm ẩm điểm xuyết sắc đỏ cà rốt và xanh hành lá, cắt khoanh gọn đẹp cho bữa sáng hoặc hộp cơm Bento', 'Trứng cuộn Hàn Quốc (Gyeran Mari) có kết cấu mềm mịn, nhiều lớp cuộn chặt tay với nhân cà rốt và hành lá băm nhuyễn đẹp mắt, vị béo nhẹ thanh tao thích hợp dùng kèm cơm nóng hoặc xếp hộp cơm trưa.', 'Để trứng cuộn nguội bớt 3 phút cho định hình rồi cắt lát dày 2 cm, bày ra đĩa chấm kèm nước tương hoặc tương cà tùy thích.', 'Bảo quản hộp kín trong ngăn mát tối đa 2 ngày; món ăn ngon ở cả nhiệt độ phòng hoặc làm ấm nhẹ bằng lò vi sóng 30 giây.', 'korean', 'mon_nhanh_sang', NULL, 'medium', 10, 10, 2, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món trứng","Bữa sáng","Hộp cơm","Món nhanh"]', '["breakfast","lunch","dinner"]', '["pan_fry"]', '["egg","milk","soybean","wheat"]', 180, 180.4, 755, 12.3, 12.9, 3.5, 3.4, 0.7, 1.5, 1012, 2.53, '["USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171265","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277"]', 'b0ff00dd10d8209d3f98f78a5ab7186d3ee45b560ce1396dc25af04e5c6cec6b', 'd968fd759d83778a616a2e0393bbc1e8d7c0ecd3ea3a88aeff03f5cc9047820d', 4),
('imp-412960b58d00d211', 'sundubu-tom-cay', 234, 'Canh đậu phụ non hải sản cay (Sundubu Jjigae)', 'Nồi canh Sundubu Jjigae sôi sùng sục với đậu phụ non mềm tan, tôm tươi ngọt thịt, nấm đùi gà, trứng gà và nước dùng ớt bột Gochugaru cay ấm', 'Canh đậu phụ non hải sản cay (Sundubu Jjigae) là món canh nóng nổi tiếng của Hàn Quốc nhờ dầu ớt Gochugaru tự xào thơm lừng hòa trong nước dùng cá cơm tảo bẹ, ôm trọn từng miếng đậu phụ non béo mịn, tôm tươi săn ngọt và trứng gà lòng đào.', 'Dọn canh trực tiếp trong nồi đất khi nước còn sôi lăn tăn, rắc hành lá và ớt hiểm đỏ thái lát, thưởng thức cùng cơm trắng nóng.', 'Món canh có đậu phụ non và trứng ngon nhất khi ăn ngay trong ngày; nếu cần bảo quản, cất ngăn mát tối đa 24 giờ và hâm sôi nhẹ không khuấy mạnh để tránh vỡ đậu.', 'korean', 'mon_canh', NULL, 'easy', 15, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món canh","Hải sản","Đậu phụ non","Cay ấm"]', '["lunch","dinner"]', '["simmer","stir_fry"]', '["crustaceans","egg","fish","sesame","shrimp","soybean"]', 408, 408.4, 1709, 39.4, 20.2, 3.7, 19.1, 4.3, 4.7, 1748, 4.37, '["Korean Anchovy Kelp Stock Ref","Korean Chili Flake Ref","USDA FDC 168580","USDA FDC 169230","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 172476","USDA FDC 175179"]', '2607daaeacd23f7d74473513968a6883a0a757c228ba9aa03c7382b925a6c13f', 'be5c92bbb65b39c1a1ef82c5db225ae5c6cd61bca849c4077fa75cacbd6b4b09', 4),
('imp-80976e834de46c34', 'japchae-mi-soi-tron', 235, 'Miến trộn Hàn Quốc (Japchae)', 'Sợi miến khoai lang dai bóng thơm dầu mè trộn cùng thịt bò xào mềm, nấm hương, nấm đùi gà, rau chân vịt, cà rốt, ớt chuông và trứng thái sợi', 'Miến trộn Hàn Quốc (Japchae) là món ăn truyền thống không thể thiếu trong các dịp lễ tiệc nhờ sợi miến khoai lang trong suốt dai ngon áo xì dầu và dầu mè rang, hòa quyện cùng thịt bò thăn, hai loại nấm thơm ngọt và rau củ xào riêng rực rỡ.', 'Bày miến trộn ra đĩa lớn, rắc thêm hạt mè trắng rang và sợi trứng tráng vàng lên trên; ngon cả khi ăn ấm lẫn ở nhiệt độ phòng.', 'Bảo quản hộp kín trong ngăn mát tối đa 2 ngày; khi ăn chỉ cần làm ấm lại nhanh trên chảo hoặc lò vi sóng 1–2 phút với chút nước lọc để sợi miến mềm lại.', 'korean', 'mon_xao', NULL, 'medium', 25, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Miến trộn","Japchae","Lễ tiệc","Thịt bò"]', '["lunch","dinner"]', '["boil","stir_fry","toss_mix"]', '["beef","egg","sesame","soybean","wheat"]', 438, 437.5, 1831, 14.5, 19, 4, 54.3, 4.3, 9, 1116, 2.79, '["USDA FDC 168436","USDA FDC 168462","USDA FDC 168580","USDA FDC 168952","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170108","USDA FDC 170150","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '737662300c51bfa9ba939a0a37f2520d94e5221de28caa5e7636ac214ca3bc8c', 'feaa49914f7c267ece5c8f5e65dc6af4e851d17ec49f444009189c5deaec186d', 4),
('imp-8608afb7fee8ebc3', 'ba-chi-nuong-samgyeopsal', 236, 'Ba chỉ nướng Hàn Quốc (Samgyeopsal)', 'Thịt ba chỉ heo cắt dày áp chảo vàng ruộm giòn bì, nướng kèm kim chi và tỏi lát, cuốn lá xà lách tía tô chấm sốt Ssamjang chuẩn tiệc nướng Hàn', 'Ba chỉ nướng Hàn Quốc (Samgyeopsal) hấp dẫn nhờ miếng ba chỉ dày thịt xen mỡ được nướng trên chảo gang đến khi vàng giòn hai mặt, ăn kèm kim chi áp chảo và tỏi nướng thơm lừng, cuốn trong xà lách và lá tía tô cùng tương Ssamjang.', 'Cắt thịt ba chỉ thành miếng vừa ăn trực tiếp trên chảo, cuốn cùng lá xà lách, lá tía tô, kim chi, tỏi nướng, hành lá trộn và chấm sốt Ssamjang hoặc dầu mè muối tiêu.', 'Thịt ba chỉ đã nướng chín bảo quản hộp kín trong ngăn mát tối đa 2 ngày; hâm nóng lại bằng chảo gang không dầu trên lửa vừa 3–4 phút cho bề mặt giòn trở lại.', 'korean', 'mon_lau_tiec', NULL, 'easy', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Tiệc nướng","Thịt ba chỉ","Samgyeopsal","Cuốn rau"]', '["lunch","dinner"]', '["grill_roast","pan_fry"]', '["pork","sesame","soybean","wheat"]', 811, 810.6, 3391, 16.2, 76.6, 26.2, 14.1, 3.2, 5.6, 1293, 3.23, '["Korean Doenjang Ref","MEXT Hon-Mirin 16031","MEXT Shiso Ref","USDA / Korean Gochujang Ref","USDA FDC 167820","USDA FDC 169230","USDA FDC 169247","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170150","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 173468"]', '16fb0b61f83f33f980294554d8aea92a5dde9dbbbe7f8a6cb4f53a303fc84c54', 'a0657c46d6f84bdee8004bd5994c93e402dc532e1ec5a9a1289c22c45c330d9f', 4),
('imp-97ba5787e2d4113b', 'canh-tuong-dau-han', 237, 'Canh tương đậu Hàn Quốc (Doenjang Jjigae)', 'Canh tương đậu lên men Doenjang thơm nồng hòa quyện nước dùng cá cơm tảo bẹ cùng đậu phụ trắng mềm, nấm đùi gà và rau chân vịt thanh ngọt', 'Canh tương đậu Hàn Quốc (Doenjang Jjigae) là món canh quen thuộc trên mâm cơm gia đình xứ Hàn với vị mặn bùi đặc trưng của tương đậu lên men Doenjang hòa cùng nước dùng cá cơm tảo bẹ ngọt thanh, nấm đùi gà giòn ngọt, rau chân vịt xanh mướt và đậu phụ mềm.', 'Dọn canh nóng hổi trong nồi đất hoặc tô lớn, ăn kèm cơm trắng nóng, kim chi và các món panchan.', 'Canh nguội hẳn cho vào hộp kín bảo quản ngăn mát tối đa 2 ngày; khi hâm nóng đun sôi nhẹ trên lửa vừa 3–4 phút rồi mới thêm rau nếu cần.', 'korean', 'mon_canh', NULL, 'easy', 10, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món canh","Tương đậu","Đậu phụ","Thanh đạm"]', '["lunch","dinner"]', '["simmer"]', '["fish","soybean","wheat"]', 135, 134.9, 564, 13.8, 4.4, 0.6, 12.8, 4.1, 2.6, 1206, 3.01, '["Korean Anchovy Kelp Stock Ref","Korean Chili Flake Ref","Korean Doenjang Ref","USDA FDC 168462","USDA FDC 168580","USDA FDC 169230","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 172475"]', 'da8b10144a39c55aa21cb1d61e22a88deb304811fbc7cf4db69df97f355840dd', 'adce81ad663fd62ad6050036f897d5ce43c198bd739706610880da16ed5b244d', 4);
INSERT OR IGNORE INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-96d226a7f4d12156', 'ga-chien-gangjeong-cay', 238, 'Gà chiên giòn sốt cay ngọt (Dakgangjeong)', 'Miếng ức gà áo bột bắp chiên giòn hai lần phủ lớp sốt mật ong Gochujang cay ngọt keo bóng, rắc đậu phộng giã dập và hạt mè rang', 'Gà chiên giòn sốt cay ngọt (Dakgangjeong) nổi bật với kỹ thuật chiên hai lần giúp lớp vỏ bột bắp giòn rụm lâu dài dù đã áo đẫm nước sốt mật ong, đường nâu, giấm gạo và tương ớt Gochujang keo bóng đậm đà.', 'Bày gà chiên phủ sốt ra đĩa lớn, rắc đậu phộng rang giã dập, hạt mè trắng rang và hành lá thái nhỏ; dùng kèm củ cải muối hoặc cơm trắng.', 'Món ngon nhất khi dùng ngay lúc mới xóc sốt để giữ vỏ giòn; nếu còn dư, bảo quản ngăn mát tối đa 2 ngày và làm nóng lại bằng nồi chiên không dầu ở 180°C trong 4–5 phút.', 'korean', 'mon_chien', NULL, 'medium', 20, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Gà chiên","Cay ngọt","Giòn rụm","Dakgangjeong"]', '["lunch","dinner"]', '["deep_fry","simmer","toss_mix"]', '["chicken","peanut","sesame","soybean","wheat"]', 460, 459.5, 1923, 30.8, 18, 2.8, 42, 1.3, 26, 702, 1.76, '["MEXT Hon-Mirin 16031","USDA / Korean Gochujang Ref","USDA FDC 168833","USDA FDC 169230","USDA FDC 169231","USDA FDC 169640","USDA FDC 169698","USDA FDC 170005","USDA FDC 170150","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 171477","USDA FDC 172238","USDA FDC 172430","USDA FDC 173468","USDA FDC 174277"]', '995ef0fc5c85d127c7f32d240328967e103feb5a07ceca458b7e72f6a81fc510', 'aa213359a43f6e618f6bb7918be360e2741554c4e7a41c3f0a89ed3b7d141861', 4),
('imp-ba1871f088d9a522', 'lau-bulgogi-nam', 239, 'Lẩu Bulgogi nấm kiểu Hàn (Bulgogi Jeongol)', 'Nồi lẩu nóng hổi thanh ngọt với thịt bò ướp Bulgogi mềm thơm, nấm đùi gà giòn ngọt, cải thảo, củ cải trắng và miến khoai lang dai mượt', 'Lẩu Bulgogi nấm kiểu Hàn (Bulgogi Jeongol) mang đến trải nghiệm ấm cúng với thịt bò thăn ướp sốt mật ong xì dầu xếp gọn cùng nấm đùi gà, cải thảo, cà rốt và miến khoai lang trong nồi nước dùng cá cơm tảo bẹ ninh củ cải ngọt thanh.', 'Đặt nồi lẩu trên bếp từ hoặc bếp gas mini tại bàn cho sôi lăn tăn, chan dùng nóng kèm cơm trắng hoặc thưởng thức trực tiếp cùng kim chi.', 'Nếu còn dư nước lẩu và thịt bò, vớt riêng phần miến và rau; bảo quản nước lẩu cùng thịt trong ngăn mát tối đa 2 ngày và đun sôi lại 5 phút trước khi dùng.', 'korean', 'mon_lau_tiec', NULL, 'easy', 25, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món lẩu","Thịt bò","Nấm đùi gà","Tiệc gia đình"]', '["lunch","dinner"]', '["simmer","boil"]', '["beef","fish","sesame","soybean","wheat"]', 425, 425.2, 1779, 29.7, 16.1, 5.2, 40.1, 3.3, 12.9, 1597, 3.99, '["Korean Anchovy Kelp Stock Ref","MEXT Hon-Mirin 16031","USDA FDC 168452","USDA FDC 168580","USDA FDC 168952","USDA FDC 169230","USDA FDC 169640","USDA FDC 169655","USDA FDC 169977","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 172185","USDA FDC 173468","USDA FDC 174277"]', 'ac88b0f0c1610f685da5bdef4a1416cca230f33a1fc991129d3a1e54ba8b4804', '3f2fc75109abf5a1abd8fc32d1730a218a2c06c89cf9b440116eeb27ec2d17ea', 4),
('imp-24fc3ac5cd3ff445', 'com-chien-kim-chi-han', 240, 'Cơm chiên kim chi truyền thống (Kimchi Bokkeumbap)', 'Cơm nguội chiên săn tơi thấm đẫm vị kim chi ủ chua kỹ, nước kim chi và tương ớt Gochujang cay đậm, ăn kèm trứng ốp la và rong biển khô', 'Cơm chiên kim chi truyền thống (Kimchi Bokkeumbap) giữ đúng tinh thần tối giản chuẩn vị Hàn với kim chi cải thảo ủ chua kỹ xào săn, hạt cơm nguội rang tơi áo đều nước kim chi và Gochujang cay nồng, phủ trứng ốp la béo thơm.', 'Xới cơm chiên nóng ra 3 đĩa hoặc tô, đặt trứng ốp la lên trên, rắc hạt mè trắng rang, hành lá và rong biển khô xé nhỏ để trộn ăn ngay.', 'Phần cơm còn dư bảo quản hộp kín trong ngăn mát tối đa 24 giờ; khi ăn đảo nóng lại trên chảo lửa vừa 3–4 phút cho hạt cơm tơi ráo.', 'korean', 'mon_chien', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Cơm chiên","Kim chi","Món nhanh","Cay đậm"]', '["breakfast","lunch","dinner"]', '["stir_fry","pan_fry"]', '["egg","sesame","soybean","wheat"]', 401, 401.2, 1679, 12.4, 13.9, 2.8, 55.8, 2.8, 3.8, 1002, 2.51, '["USDA / Korean Gochujang Ref","USDA FDC 168456","USDA FDC 168878","USDA FDC 170005","USDA FDC 170150","USDA FDC 170497","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 174277"]', '1643183b5aa7f5ab46b47d3e5a54206cf37bcc80bfa11f86b06fcef9fc9c99f6', '208e259f02662ca8c689f0495aacddd26b6fe662e3af55c28da0981bb8bdb1f4', 4),
('imp-46962ad0d6f6e63b', 'ga-xao-hung-que-pad-krapao', 241, 'Gà bằm xào húng quế kiểu Thái (Pad Krapow Gai)', 'Thịt ức gà băm xào lửa lớn với tỏi ớt hiểm dậy hương húng quế Thái nồng nàn, sốt dầu hào xì dầu đậm vị ăn kèm cơm trắng và trứng ốp la', 'Phiên bản Pad Krapow thịt gà băm thanh nhẹ hơn thịt heo nhưng vẫn giữ trọn hương vị đường phố Thái Lan: thịt gà tơi ngọt quyện sốt dầu hào, hai loại xì dầu, vị cay tê của ớt hiểm và mùi thơm bừng tỉnh của lá húng quế.', 'Xới cơm trắng nóng ra 3 đĩa, múc gà xào húng quế lên bên cạnh, đặt trứng ốp la lòng đào giòn viền lên trên và dọn kèm vài lát dưa leo tươi.', 'Thịt gà xào giữ được 2 ngày trong hộp kín ngăn mát; hâm nóng lại trên chảo lửa lớn với 1 muỗng cà phê nước và chiên trứng ốp la mới khi dùng.', 'thai', 'mon_xao', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Pad Krapow","Thịt gà","Cay nồng","Cơm đĩa"]', '["lunch","dinner"]', '["stir_fry","pan_fry"]', '["chicken","egg","fish","molluscs","soybean","wheat"]', 571, 570.7, 2388, 45.5, 19.1, 3.9, 51.1, 1.6, 5.2, 1287, 3.22, '["Dark Soy Sauce Label Ref","USDA FDC 168878","USDA FDC 169230","USDA FDC 169655","USDA FDC 169961","USDA FDC 170005","USDA FDC 170106","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 171477","USDA FDC 172185","USDA FDC 172232","USDA FDC 174277"]', 'f38fa81ba0ab2005090625ee9cac5982e9d20f26c26ac37a8597987654ea3678', '75098db7cea55ed73438ecca9f5740c7fd66107c40208aaae544a444e367af93', 4),
('imp-f8fc539b7aa359ac', 'com-chien-dua-thai', 242, 'Cơm chiên dứa hải sản kiểu Thái (Khao Pad Sapparot)', 'Cơm hạt tơi vàng óng hương bột cà ri xào cùng dứa chín mọng, tôm tươi áp chảo, trứng gà và hạt điều rang giòn bùi', 'Khao Pad Sapparot là món cơm chiên nhiệt đới nổi tiếng của Thái Lan với hạt cơm tơi vàng ươm hương cà ri dịu nhẹ, vị chua ngọt thanh mát từ dứa tươi hòa cùng tôm săn ngọt và hạt điều bùi béo.', 'Múc cơm chiên dứa vào lòng quả dứa khoét rỗng hoặc đĩa rộng, xếp tôm lên trên và rắc thêm hành lá; dọn ăn nóng kèm dưa leo thái lát.', 'Ngon nhất khi ăn nóng ngay để hạt điều giòn và cơm không bị ẩm; phần dư bảo quản ngăn mát tối đa 24 giờ và rang lại trên chảo lửa vừa.', 'thai', 'mon_xao', NULL, 'medium', 20, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Cơm chiên","Hải sản","Dứa chín","Chua ngọt"]', '["lunch","dinner"]', '["stir_fry"]', '["cashew","crustaceans","egg","fish","shrimp","soybean","tree_nuts","wheat"]', 672, 671.9, 2811, 32.3, 27.6, 5.2, 76.7, 5.4, 16.2, 1218, 3.05, '["USDA FDC 168878","USDA FDC 169124","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170162","USDA FDC 170457","USDA FDC 170924","USDA FDC 170933","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 174277","USDA FDC 175179"]', '5b1a6e080803aff0baff57cec8a57021788a5673f96d3553e80ee2881702e16f', '9e0cb238e62098d0eeed6f6c57334df06c615a8ff87300027b47e56448f9e0c9', 4),
('imp-e28e249efceacac7', 'larb-heo-chua-cay', 243, 'Gỏi thịt heo bằm chua cay kiểu Thái (Larb Moo)', 'Thịt heo bằm xào chín tơi trộn nước cốt chanh chua sáng, nước mắm, ớt khô cay nồng, thính gạo rang thơm lừng và rau thơm mát', 'Larb Moo là món gỏi thịt bằm đặc sản vùng Isan Thái Lan với vị chua thanh từ chanh tươi, mặn ngọt hài hòa, cay tê của ớt bột và hương thơm bùi đặc trưng từ thính gạo rang cùng húng lủi.', 'Bày gỏi thịt heo bằm ra đĩa sâu lòng, xếp bắp cải tách lá và dưa leo thái lát bên cạnh để cuốn hoặc ăn kèm xôi nếp nóng hay cơm trắng.', 'Nên trộn và ăn ngay trong ngày khi thính gạo còn thơm và rau sống giòn tươi; tránh để qua đêm vì nước chanh làm thịt sẫm màu và rau bị héo.', 'thai', 'mon_cuon_nom', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Gỏi trộn","Chua cay","Thịt heo bằm","Ít dầu mỡ"]', '["lunch","dinner"]', '["stir_fry","toss_mix"]', '["fish","pork"]', 355, 355.1, 1485, 21, 23, 8.5, 16.9, 3.5, 5.5, 1036, 2.59, '["Citrus Leaf Culinary Ref","Toasted Rice Powder Ref","USDA FDC 167902","USDA FDC 168155","USDA FDC 168409","USDA FDC 169655","USDA FDC 169975","USDA FDC 169997","USDA FDC 170005","USDA FDC 170499","USDA FDC 171319","USDA FDC 172185","USDA FDC 173474","USDA FDC 173647"]', '883d9e49ee240c89cf71167a026e8d0ff00f484520b0c408233c02451062b1b0', 'd11819602e1065c4f805f180333092f5e77f1bd61013fa2f111081da3d13b809', 4),
('imp-90fc2e140739a7d7', 'tom-yum-ca-nam', 244, 'Canh chua cay cá nấm Tom Yum kiểu Thái (Tom Yum Pla)', 'Nước canh Tom Yum trong thanh dậy hương sả, riềng, lá chanh Thái nấu cùng cá phi lê trắng ngọt, nấm đùi gà giòn và cà chua bi', 'Tom Yum Pla là biến thể Tom Yum nước trong thanh mát không dùng cốt dừa hay tương ớt béo, nổi bật với vị ngọt tự nhiên của phi lê cá thịt trắng, nấm đùi gà giòn sần sật và hương thảo mộc tươi nồng nàn.', 'Múc canh Tom Yum cá nấm nóng hổi ra tô lớn, rắc ngò rí lên trên và thưởng thức cùng cơm trắng dẻo.', 'Thịt cá dễ nát khi hâm đi hâm lại nên ngon nhất khi ăn hết trong bữa; nếu còn dư có thể bảo quản ngăn mát 24 giờ và hâm nhẹ trên lửa nhỏ không khuấy mạnh.', 'thai', 'mon_canh', NULL, 'easy', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món canh","Tom Yum","Cá tươi","Chua cay"]', '["lunch","dinner"]', '["simmer"]', '["fish"]', 193, 192.9, 807, 28.7, 3.9, 0.9, 11.4, 2.3, 5.6, 1148, 2.87, '["Citrus Leaf Culinary Ref","USDA / SE Asian Galangal Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 168580","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 172185","USDA FDC 173647","USDA FDC 175148","USDA FDC Palm Sugar Ref"]', 'b119bd404383a3ee96781bd335b052feafb18b391ca8a6d2fff1d27f9368b7b1', '9360d9d93e7f31e90169e37f5cd7cac7ce77c258214275b8f2de1ae611613ef5', 4);

