INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-d283a9225d6ece09_v4_step_1', 'imp-d283a9225d6ece09', 1, 'prep', 'Ngâm giòn hành tây thái mỏng và chuẩn bị cơm ấm', 'Xới 360 g cơm gạo Nhật nấu chín ra đĩa rộng khoảng 5 phút cho thoát bớt hơi nóng, giữ cơm ở trạng thái hơi ấm dịu. Thái 1/2 củ hành tây thành lát ngang mỏng 2 mm, ngâm ngay vào bát nước lạnh 15 phút cho hết vị hăng rồi vớt ra vắt thật kiệt nước.', 'Cơm còn quá nóng sẽ làm cá hồi sống bị tái chín mất độ béo mượt; để cơm hơi ấm và lót lớp hành tây ở giữa là bí quyết chuẩn Nhật.', 15),
('imp-d283a9225d6ece09_v4_step_2', 'imp-d283a9225d6ece09', 2, 'prep', 'Thái lát phi lê cá hồi tươi chuẩn sashimi', 'Thấm thật khô 280 g phi lê cá hồi tươi bằng khăn giấy, kiểm tra kỹ và rút sạch xương dăm nếu có. Dùng dao sắc kéo dứt khoát một đường cắt cá thành những lát sashimi dày khoảng 5–7 mm để mặt cắt láng mịn không bị nát thớ.', 'Nên chọn cá hồi tươi đạt chuẩn ăn sống và dùng dao thật sắc kéo một đường dài dứt khoát để không làm dập thớ thịt cá.', NULL),
('imp-d283a9225d6ece09_v4_step_3', 'imp-d283a9225d6ece09', 3, 'sauce', 'Pha nước sốt Zuke và ướp lạnh cá hồi', 'Đun sôi nhanh 30 ml rượu ngọt Mirin trên lửa nhỏ khoảng 30 giây rồi để nguội hẳn. Trộn đều phần Mirin đã nguội với 45 ml nước tương Nhật, 10 ml dầu mè rang và 6 g gừng tươi mài nhuyễn trong tô thủy tinh. Xếp cá hồi vào đảo nhẹ cho phủ đều sốt, bọc kín màng thực phẩm và ướp trong ngăn mát 25–30 phút.', 'Ướp cá đủ thời gian trong ngăn mát giúp lát cá săn nhẹ và thấm đều vị xì dầu dầu mè mà vẫn giữ trọn độ tươi béo.', 25),
('imp-d283a9225d6ece09_v4_step_4', 'imp-d283a9225d6ece09', 4, 'prep', 'Chuẩn bị hành lá và rong biển Nori rắc mặt', 'Trong lúc chờ ướp cá, thái nhỏ 1/2 bó hành lá tươi và dùng kéo cắt 3 g rong biển khô Nori thành sợi mảnh khoảng 3 mm để riêng ra đĩa sạch.', NULL, NULL),
('imp-d283a9225d6ece09_v4_step_5', 'imp-d283a9225d6ece09', 5, 'finish', 'Xếp lớp hành tây, cá hồi lên cơm ấm', 'Chia đều 360 g cơm gạo Nhật hơi ấm vào hai tô donburi, trải kín lớp hành tây đã vắt thật ráo lên mặt cơm. Lần lượt xếp các lát cá hồi đã ướp tương phủ chồng nhẹ lên nhau thành hình cánh hoa đẹp mắt, rưới thêm 1–2 muỗng nước sốt ướp còn lại tùy khẩu vị.', NULL, NULL),
('imp-d283a9225d6ece09_v4_step_6', 'imp-d283a9225d6ece09', 6, 'finish', 'Rắc hành lá, mè rang và thưởng thức ngay', 'Rắc rong biển khô Nori cắt sợi, hành lá thái nhỏ và hạt mè trắng rang lên bề mặt tô cá hồi. Dọn thưởng thức ngay khi cá còn mát lạnh và cơm vẫn ấm dẻo.', NULL, NULL),
('imp-7ed24282981e96f6_v4_step_1', 'imp-7ed24282981e96f6', 1, 'prep', 'Bào sợi bắp cải ngâm giòn và sơ chế nguyên liệu', 'Cắt bỏ phần lõi cứng của 1/2 bắp cải xanh, dùng dao sắc hoặc bàn bào bào thành sợi thật mảnh rồi ngâm nước đá lạnh 5 phút cho giòn, sau đó vẩy thật ráo nước. Cắt 340 g thịt ba chỉ thái mỏng thành miếng vừa ăn và chia làm 2 mẻ; thái lát mỏng 1 bó hành lá tươi và mài nhuyễn 25 g gừng tươi lấy cả nước.', 'Quay hoặc vẩy thật ráo nước bắp cải sợi sẽ giúp đĩa thịt sốt gừng không bị loãng nước khi bày chung.', 5),
('imp-7ed24282981e96f6_v4_step_2', 'imp-7ed24282981e96f6', 2, 'sauce', 'Pha sẵn nước sốt gừng Shogayaki', 'Trộn đều 45 ml nước tương Nhật, 45 ml rượu Sake nấu ăn, 45 ml rượu ngọt Mirin và 10 g đường cát trắng trong bát đến khi đường tan hết. Chia hỗn hợp sốt làm 2 phần đều nhau tương ứng với 2 mẻ chiên thịt.', NULL, NULL),
('imp-7ed24282981e96f6_v4_step_3', 'imp-7ed24282981e96f6', 3, 'cook', 'Áp chảo mẻ thịt ba chỉ thứ nhất với lửa vừa cao', 'Làm nóng chảo rộng trên lửa vừa cao, phết 5 ml dầu ăn thực vật rồi xếp phẳng mẻ thịt ba chỉ thứ nhất thành một lớp không chồng chéo. Áp chảo khoảng 2 phút cho thịt xém vàng nhẹ các mép và tiết bớt mỡ thơm thì trở mặt.', 'Chia thịt chiên thành 2 mẻ vừa vặn mặt chảo giúp thịt áp chảo xém thơm thay vì bị ra nước và hấp mềm.', 2),
('imp-7ed24282981e96f6_v4_step_4', 'imp-7ed24282981e96f6', 4, 'cook', 'Áo sốt gừng và hành lá cho mẻ thịt thứ nhất', 'Đổ 1/2 bát nước sốt đã pha vào chảo cùng một nửa lượng gừng tươi mài nhuyễn và hành lá thái mỏng. Đảo nhanh tay trên lửa vừa khoảng 2 phút đến khi thịt heo chín kỹ hoàn toàn, nước sốt sôi sủi bọt hơi sánh lại bám bóng đều từng lát thịt thì gắp ra đĩa đã lót bắp cải sợi.', 'Cho gừng tươi mài cả nước vào cùng lúc với sốt giúp hương gừng quyện thơm nồng mà không bị cháy đắng.', 2),
('imp-7ed24282981e96f6_v4_step_5', 'imp-7ed24282981e96f6', 5, 'cook', 'Áp chảo và hoàn thiện mẻ thịt ba chỉ thứ hai', 'Lau nhẹ chảo bằng khăn giấy, phết 5 ml dầu ăn thực vật còn lại và lặp lại quy trình áp chảo với mẻ thịt ba chỉ thứ hai cùng phần nước sốt, gừng tươi và hành lá còn lại trong 4 phút đến khi thịt chín đều và sốt keo sánh.', NULL, 4),
('imp-7ed24282981e96f6_v4_step_6', 'imp-7ed24282981e96f6', 6, 'finish', 'Trình bày đĩa Shogayaki nóng hổi và dùng kèm cơm', 'Xếp phần thịt ba chỉ còn lại lên đĩa bên cạnh bắp cải xanh bào sợi, rưới toàn bộ nước sốt gừng sánh thơm trong chảo lên trên mặt thịt và thưởng thức ngay cùng cơm trắng nóng.', NULL, NULL),
('imp-c6e706b483805e44_v4_step_1', 'imp-c6e706b483805e44', 1, 'prep', 'Sơ chế thịt ba chỉ, gừng và hành lá', 'Cắt 750 g thịt ba chỉ heo thành các dải lớn vừa chiều rộng lòng nồi để thịt giữ phom trong quá trình hầm lâu. Thái lát mỏng 50 g gừng tươi và chia làm hai phần bằng nhau; tách 2 bó hành lá riêng phần lá xanh cắt khúc 5 cm và phần thân trắng thái sợi mảnh ngâm nước đá trang trí.', NULL, NULL),
('imp-c6e706b483805e44_v4_step_2', 'imp-c6e706b483805e44', 2, 'cook', 'Áp chảo xém vàng rút bớt mỡ thừa của thịt', 'Làm nóng nồi gang hoặc chảo đáy dày trên lửa vừa cao với 10 ml dầu ăn trung tính. Đặt từng dải thịt ba chỉ mặt mỡ xuống trước, áp chảo vàng đều tất cả các mặt khoảng 8–10 phút để khóa hương thịt và rút bớt phần mỡ béo dư thừa.', NULL, 10),
('imp-c6e706b483805e44_v4_step_3', 'imp-c6e706b483805e44', 3, 'cook', 'Ninh mềm thịt ba chỉ lần một trong nước gừng hành', 'Xếp thịt đã áp chảo thành một lớp vào nồi lớn, đổ 2000 ml nước lọc ngập mặt thịt cùng 75 ml rượu Sake nấu ăn, một nửa lượng gừng thái lát và phần lá xanh hành lá. Đun sôi trên lửa vừa, hớt sạch bọt và váng mỡ, phủ một tờ giấy nến khoét lỗ sát mặt thịt rồi hạ lửa nhỏ nhất ninh liu riu không đậy vung khoảng 90 phút đến khi thịt mềm rục.', 'Ninh mở nắp ở lửa nhỏ liu riu giúp mùi hôi thịt bay hơi hết và thịt mềm tơi từng thớ mà không bị nát vụn.', 90),
('imp-c6e706b483805e44_v4_step_4', 'imp-c6e706b483805e44', 4, 'cook', 'Luộc trứng gà lòng đào và chần đậu xanh ăn kèm', 'Trong lúc ninh thịt, đun sôi một nồi nước khác, nhẹ nhàng thả 5 quả trứng gà lạnh vào luộc đúng 7 phút rồi vớt ngay sang tô nước đá 10 phút và bóc sạch vỏ. Dùng lại nồi nước sôi chần 80 g đậu cô ve trong 2 phút cho chín giòn xanh mướt rồi vớt ra đĩa.', NULL, 7),
('imp-c6e706b483805e44_v4_step_5', 'imp-c6e706b483805e44', 5, 'cook', 'Cắt khối vuông và kho chậm trong nước dùng Dashi', 'Vớt thịt ba chỉ ra thớt, bỏ phần nước ninh cùng xác hành gừng cũ, nhẹ tay cắt thịt thành các khối vuông cạnh 5 cm rồi xếp gọn vào nồi vừa khít. Đổ 750 ml nước dùng Dashi, 75 ml rượu Sake nấu ăn còn lại, 75 ml rượu ngọt Mirin, 55 g đường cát trắng, phần gừng lát còn lại và 1 quả ớt khô nguyên quả vào, đậy nắp giấy kho lửa nhỏ liu riu trong 30 phút.', 'Chưa cho nước tương ngay từ đầu giúp đường và mirin thấm vào làm mềm thịt trước, tránh thịt bị mặn gắt bên ngoài.', 30),
('imp-c6e706b483805e44_v4_step_6', 'imp-c6e706b483805e44', 6, 'cook', 'Nêm nước tương Nhật và om cùng trứng lòng đào', 'Sau 30 phút kho, rót 75 ml nước tương Nhật vào nồi cùng 5 quả trứng gà đã bóc vỏ. Tiếp tục đậy nắp giấy om liu riu lửa nhỏ thêm 30 phút nữa, thỉnh thoảng lắc nhẹ nồi hoặc múc nước kho rưới lên trứng và thịt đến khi nước sốt sánh bóng đậm đà và thịt mềm tan khi xiên đũa qua.', 'Tắt bếp để thịt và trứng nguội tự nhiên trong nồi nước kho vài giờ rồi hâm lại sẽ giúp món Kakuni thấm vị đậm sâu hơn nhiều.', 30),
('imp-c6e706b483805e44_v4_step_7', 'imp-c6e706b483805e44', 7, 'finish', 'Trình bày bát thịt hầm Kakuni và thưởng thức', 'Gắp các khối thịt ba chỉ hầm, trứng lòng đào cắt đôi và đậu cô ve chần ra bát sâu lòng, chan nước kho bóng mượt lên trên. Vẩy ráo phần đầu hành trắng thái sợi ngâm đá đặt lên mặt thịt và thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-324e0ea2e2f068bf_v4_step_1', 'imp-324e0ea2e2f068bf', 1, 'prep', 'Ngâm tảo bẹ Kombu lấy nền nước dùng Dashi', 'Dùng khăn ẩm lau nhẹ lớp phấn trắng tự nhiên trên 8 g tảo bẹ Kombu khô (không rửa trôi vị ngọt), cho vào nồi cùng 750 ml nước lọc lạnh ngâm khoảng 20 phút để tảo tiết hết vị thanh ngọt.', NULL, 20),
('imp-324e0ea2e2f068bf_v4_step_2', 'imp-324e0ea2e2f068bf', 2, 'prep', 'Ngâm nở rong biển Wakame và thái đậu phụ, nấm', 'Ngâm 5 g rong biển Wakame khô trong bát nước mát khoảng 5 phút cho nở mềm hoàn toàn rồi vớt ra vắt nhẹ. Thái lát mỏng 120 g nấm đùi gà tươi; nhẹ tay cắt 200 g đậu phụ non thành khối vuông 2 cm và thái khoanh mỏng 1/2 bó hành lá tươi.', NULL, 5),
('imp-324e0ea2e2f068bf_v4_step_3', 'imp-324e0ea2e2f068bf', 3, 'cook', 'Đun nước dùng Kombu và nấu chín mềm nấm', 'Đặt nồi nước ngâm tảo bẹ lên bếp lửa vừa, khi đáy nồi vừa xuất hiện bọt lăn tăn chuẩn bị sôi thì lập tức vớt bỏ lá tảo bẹ Kombu ra ngoài. Thả toàn bộ nấm thái lát vào nồi nấu khoảng 3–4 phút trên lửa vừa cho nấm chín mềm và ra vị ngọt.', 'Vớt tảo bẹ Kombu ngay trước lúc nước sôi bùng giúp nước canh trong veo, thơm thanh mà không bị đắng chát hay nhớt.', 4),
('imp-324e0ea2e2f068bf_v4_step_4', 'imp-324e0ea2e2f068bf', 4, 'cook', 'Thả đậu phụ non và rong biển Wakame làm nóng', 'Nhẹ nhàng trượt 200 g đậu phụ non cắt khối cùng rong biển Wakame đã vắt ráo vào nồi canh. Đun thêm 1–2 phút trên lửa nhỏ cho đậu phụ nóng đều từ trong ra ngoài, chỉ lắc nhẹ nồi chứ không dùng muôi khuấy mạnh làm vỡ đậu, sau đó tắt bếp hoàn toàn.', 'Chỉ đun lửa nhỏ làm nóng đậu phụ trong 1–2 phút giúp miếng đậu giữ nguyên khối vuông đẹp mắt và không bị rỗ xốp.', 2),
('imp-324e0ea2e2f068bf_v4_step_5', 'imp-324e0ea2e2f068bf', 5, 'sauce', 'Hòa tan tương Miso khi nồi đã tắt bếp', 'Múc một muôi nước canh nóng ra bát nhỏ, cho 60 g tương Miso Nhật vào dùng đũa hoặc phới lồng khuấy tan mịn hoàn toàn rồi từ từ rót trở lại vào nồi canh, khuấy nhẹ cho đồng nhất và tuyệt đối không bật bếp đun sôi lại.', 'Tắt bếp rồi mới hòa tan tương Miso giúp giữ trọn vẹn hương thơm đậu nành lên men tinh tế và bảo toàn lợi khuẩn tự nhiên.', NULL),
('imp-324e0ea2e2f068bf_v4_step_6', 'imp-324e0ea2e2f068bf', 6, 'finish', 'Múc canh ra chén, rắc hành lá và dùng nóng', 'Múc canh Miso chia đều vào 3 chén nhỏ sao cho mỗi chén có đủ đậu phụ non, nấm và rong biển, rắc hành lá thái khoanh lên trên và thưởng thức ngay khi canh còn ấm nóng.', NULL, NULL),
('imp-5507103398040565_v4_step_1', 'imp-5507103398040565', 1, 'sauce', 'Pha nước sốt Yakisoba chua ngọt đậm đà', 'Trộn đều 50 ml sốt Worcestershire Nhật, 20 ml dầu hào, 20 ml tương cà, 10 ml nước tương Nhật và 8 g đường cát trắng trong bát nhỏ đến khi đường tan hoàn toàn. Nếm thử độ chua ngọt để điều chỉnh nếu cần.', NULL, NULL),
('imp-5507103398040565_v4_step_2', 'imp-5507103398040565', 2, 'prep', 'Sơ chế rau củ, thịt ba chỉ và luộc tơi sợi mì', 'Thái lát mỏng 180 g thịt ba chỉ heo; cắt miếng vuông 2,5 cm phần 0,25 bắp cải xanh; thái sợi 1 củ cà rốt và 0,5 quả ớt chuông xanh; thái mỏng 0,5 củ hành tây và 50 g nấm hương tươi; rửa ráo 100 g giá đỗ và cắt khúc 1 bó hành lá tươi. Luộc 240 g mì Yakisoba khô trong nồi nước sôi 2–3 phút cho sợi vừa chín tới còn độ dai nhẹ rồi vớt ra xả nhanh nước mát và vẩy thật ráo.', 'Không luộc mì quá nhừ vì sợi mì sẽ còn đảo trên chảo nóng với nước sốt Yakisoba.', NULL),
('imp-5507103398040565_v4_step_3', 'imp-5507103398040565', 3, 'cook', 'Xào thịt ba chỉ vàng thơm với tiêu đen', 'Làm nóng chảo sâu lòng trên lửa vừa cao với 20 ml dầu ăn thực vật. Cho thịt ba chỉ heo vào xào, rắc 2 g tiêu đen xay và đảo đều khoảng 3–4 phút cho đến khi thịt chuyển vàng xém nhẹ, chín hoàn toàn và tiết mỡ thơm.', 'Xào thịt ba chỉ trước cho săn vàng giúp dầu quyện mùi thơm thịt và rau củ khi cho vào sau sẽ bóng ngon hơn.', 4),
('imp-5507103398040565_v4_step_4', 'imp-5507103398040565', 4, 'cook', 'Xào thơm hành tây, đầu hành lá và rau củ', 'Thả hành tây thái lát cùng phần đầu trắng hành lá vào chảo xào 2 phút đến khi hành trong thơm. Tiếp tục cho bắp cải xanh, cà rốt, nấm hương tươi và ớt chuông xanh vào đảo đều tay trên lửa lớn thêm 3 phút cho rau củ vừa chín mềm mà vẫn giữ độ giòn.', NULL, 5),
('imp-5507103398040565_v4_step_5', 'imp-5507103398040565', 5, 'cook', 'Thêm giá đỗ và xào quyện mì với sốt Yakisoba', 'Cho 100 g giá đỗ tươi vào đảo nhanh 1 phút, sau đó trút mì Yakisoba vào chảo cùng toàn bộ bát nước sốt Yakisoba đã pha. Dùng kẹp hoặc hai chiếc đũa đảo đều tay trên lửa lớn 2–3 phút để sốt phủ bóng và thấm quyện từng sợi mì rồi cho phần lá hành xanh vào đảo tắt bếp.', 'Cho giá đỗ và hành lá xanh vào giai đoạn cuối giúp giữ nguyên độ giòn ngọt và sắc xanh tươi bắt mắt.', 4),
('imp-5507103398040565_v4_step_6', 'imp-5507103398040565', 6, 'finish', 'Bày đĩa Yakisoba và rắc rong biển Nori', 'Gắp mì Yakisoba xào thịt rau củ chia ra ba đĩa nóng, rắc rong biển khô Nori vụn lên mặt mì và thưởng thức ngay khi còn nóng hổi.', NULL, NULL),
('imp-710fd476f2dddd56_v4_step_1', 'imp-710fd476f2dddd56', 1, 'prep', 'Sơ chế thịt gà, hành tây, đậu xanh và làm ráo cơm', 'Trải 300 g cơm gạo Nhật nấu chín ra đĩa rộng cho thoát hơi ẩm. Thái hạt lựu nhỏ 0,5 củ hành tây và 120 g thịt đùi gà lọc xương (cạnh 1,5 cm); chần nhanh 30 g đậu xanh cắt nhỏ trong nước sôi 2 phút rồi vớt ra để ráo.', 'Cơm nguội hoặc cơm mới nấu được quạt ráo hơi nước sẽ giúp từng hạt cơm tơi bóng, không bị vón cục hay nhão bết khi trộn sốt cà chua.', 2),
('imp-710fd476f2dddd56_v4_step_2', 'imp-710fd476f2dddd56', 2, 'cook', 'Xào thơm hành tây và thịt đùi gà với bơ lạt', 'Đun chảy 15 g bơ lạt trong chảo rộng trên lửa vừa, cho hành tây hạt lựu vào xào khoảng 3 phút cho trong thơm. Tiếp tục thả thịt đùi gà vào xào cùng 1 g muối ăn và 1 g tiêu đen xay thêm 4–5 phút đến khi thịt gà săn chắc, chín trắng đều không còn sắc hồng.', NULL, 8),
('imp-710fd476f2dddd56_v4_step_3', 'imp-710fd476f2dddd56', 3, 'cook', 'Cô sánh tương cà và chiên cơm gà đỏ bóng', 'Hạ lửa vừa nhỏ, đổ 60 ml tương cà và 5 ml sốt Worcestershire vào chảo gà hành, đảo đều 2 phút cho nước sốt bay bớt hơi ẩm và dịu vị chua gắt. Trút 300 g cơm vào dùng sạn ép tán nhẹ cho tơi hạt rồi đảo cùng đậu xanh thêm 3 phút cho cơm thấm đều màu đỏ cam, chia ra hai phần bằng nhau.', 'Cô đặc nhẹ tương cà trước khi cho cơm vào giúp loại bỏ nước dư, giữ hạt cơm săn ráo và dậy mùi thơm bơ cà chua nồng nàn.', 5),
('imp-710fd476f2dddd56_v4_step_4', 'imp-710fd476f2dddd56', 4, 'prep', 'Đánh trứng và lọc qua rây cho vỏ trứng mịn lụa', 'Làm từng suất một: đập 2 quả trứng gà vào bát với 0,5 g muối ăn, dùng đũa đánh tan đều theo đường zíc zắc rồi lọc qua rây lưới mịn vào ca nhỏ để loại bỏ dây chằng lòng trắng. Lặp lại tương tự cho 2 quả trứng của suất thứ hai.', NULL, NULL),
('imp-710fd476f2dddd56_v4_step_5', 'imp-710fd476f2dddd56', 5, 'cook', 'Tráng lớp trứng nửa chín mềm mịn trên chảo chống dính', 'Đun chảy 10 g bơ lạt trong chảo chống dính nhỏ đường kính 20 cm trên lửa vừa, xoay tráng đều mặt chảo. Đổ bát trứng thứ nhất vào, vừa dùng đầu đũa khuấy nhanh theo vòng tròn ở giữa chảo vừa lắc nhẹ chảo khoảng 1 phút cho đến khi trứng tạo vân mịn, mặt trên vẫn còn hơi ướt thì tắt bếp và đặt đáy chảo lên khăn ẩm 5 giây.', 'Đặt chảo lên khăn ẩm giúp hạ nhiệt tức thì để lớp trứng không bị khô cháy trong lúc tạo hình bọc cơm.', 1),
('imp-710fd476f2dddd56_v4_step_6', 'imp-710fd476f2dddd56', 6, 'finish', 'Bọc cơm gà, tạo hình oval và rưới tương cà', 'Đặt một phần cơm gà sốt cà chua vào giữa mặt trứng theo chiều thuôn dài, nhẹ tay gấp hai mép trứng phủ ôm lấy cơm rồi kê sát đĩa vào thành chảo úp ngược lại cho mặt láng hướng lên trên. Dùng khăn giấy nắn nhẹ thành khối oval đẹp mắt, làm tương tự suất thứ hai, rưới 15 ml tương cà còn lại thành đường zíc zắc và dùng nóng.', NULL, NULL),
('imp-14c8ef999fe47b8f_v4_step_1', 'imp-14c8ef999fe47b8f', 1, 'prep', 'Đánh nhẹ hỗn hợp trứng sữa gia vị và lọc rây', 'Thái nhỏ mịn 0,5 bó hành lá tươi. Đập 4 quả trứng gà vào bát lớn, thêm 20 ml sữa tươi không đường, 10 ml nước tương Nhật, 10 ml rượu ngọt Mirin, 6 g đường cát trắng và 1 g muối ăn. Dùng đũa khuấy nhẹ tay theo đường zíc zắc để đường tan và trứng quyện đều mà không tạo bọt, lọc qua rây mịn rồi trộn hành lá vào.', 'Khuấy trứng bằng đũa theo đường zíc zắc thay vì đánh bông giúp cắt đứt dây lòng trắng mà không tạo bọt khí gây rỗ mặt cuộn trứng.', NULL),
('imp-14c8ef999fe47b8f_v4_step_2', 'imp-14c8ef999fe47b8f', 2, 'cook', 'Làm nóng chảo và tráng cuộn lớp trứng đầu tiên', 'Đặt chảo chữ nhật chuyên dụng (hoặc chảo chống dính nhỏ 18 cm) lên bếp lửa vừa nhỏ, dùng khăn giấy thấm dầu ăn trung tính thoa một lớp thật mỏng đều mặt chảo. Đổ 1/3 bát trứng vào tráng mỏng khắp chảo, đun khoảng 2 phút đến khi mặt trứng vừa se lại nhưng vẫn còn hơi ẩm ướt thì dùng đũa và xẻng cuộn tròn từ mép xa về sát mép gần rồi đẩy cuộn trứng về góc xa.', NULL, 2),
('imp-14c8ef999fe47b8f_v4_step_3', 'imp-14c8ef999fe47b8f', 3, 'cook', 'Tráng và cuộn nối tiếp lớp trứng thứ hai', 'Thấm thêm một lớp dầu ăn trung tính thật mỏng vào khoảng trống trên mặt chảo, đổ tiếp 1/3 hỗn hợp trứng thứ hai vào, dùng đũa khẽ nhấc cuộn trứng lên cho trứng mới chảy đều xuống dưới đáy cuộn. Chờ khoảng 2 phút cho mặt trứng se chín còn hơi ẩm rồi cuộn ngược chồng tiếp lên lớp cũ và đẩy về mép chảo.', 'Cuộn ngay khi mặt trên trứng vừa se nhưng còn độ ẩm dính nhẹ sẽ giúp các lớp kết nối liền mạch không bị tách rời khi cắt.', 2),
('imp-14c8ef999fe47b8f_v4_step_4', 'imp-14c8ef999fe47b8f', 4, 'cook', 'Hoàn tất lớp trứng thứ ba và ép vuông khối trứng', 'Thoa dầu ăn mỏng lên chảo một lần nữa, rót nốt 1/3 hỗn hợp trứng cuối cùng vào nâng nhẹ cuộn trứng cho chảy đều xuống dưới. Đun thêm 2 phút trên lửa vừa nhỏ cho chín đều, cuộn tròn lại rồi dùng xẻng ép nhẹ các cạnh sát thành chảo khoảng 20 giây để khối trứng định hình vuông vức vàng đều.', NULL, 2),
('imp-14c8ef999fe47b8f_v4_step_5', 'imp-14c8ef999fe47b8f', 5, 'finish', 'Để nghỉ định hình khối trứng cuộn', 'Tắt bếp, nhẹ nhàng gắp cuộn trứng ra thớt hoặc cuộn chặt trong mành tre sạch để nghỉ khoảng 4 phút cho khối trứng nguội bớt, săn chắc và giữ nguyên phom chữ nhật đẹp mắt.', 'Chờ trứng nghỉ vài phút cho se mặt trước khi cắt sẽ giúp khoanh trứng phẳng mịn, không bị chảy xô lệch giữa các lớp.', 4),
('imp-14c8ef999fe47b8f_v4_step_6', 'imp-14c8ef999fe47b8f', 6, 'finish', 'Cắt khoanh Tamagoyaki vừa ăn và trình bày', 'Dùng dao sắc cắt cuộn trứng thành 6–8 khoanh dày khoảng 2 cm lộ rõ từng vòng xoắn vàng ươm xen sắc xanh hành lá, xếp ra đĩa và thưởng thức.', NULL, NULL),
('imp-0841a517e823e3b6_v4_step_1', 'imp-0841a517e823e3b6', 1, 'sauce', 'Pha hỗn hợp sốt Teriyaki hương gừng tỏi', 'Trong bát chịu nhiệt, trộn đều 45 ml nước tương Nhật, 45 ml rượu ngọt Mirin, 45 ml rượu Sake nấu ăn, 18 g đường cát trắng cùng 15 g gừng tươi thái lát (hoặc mài nhuyễn) và 0,5 củ tỏi khô băm nhỏ. Khuấy đều hoặc quay ấm 30 giây cho đường tan hoàn toàn.', NULL, NULL),
('imp-0841a517e823e3b6_v4_step_2', 'imp-0841a517e823e3b6', 2, 'prep', 'Khía thịt đùi gà đều độ dày và ướp muối tiêu', 'Đặt 600 g thịt đùi gà lọc xương còn da lên thớt với mặt thịt hướng lên trên, dùng mũi dao khía nhẹ các đường song song ở phần thịt dày và ấn phẳng cho cả miếng gà có độ dày đồng đều. Châm vài lỗ nhỏ trên mặt da, thấm khô rồi rắc đều 1,5 g muối ăn và 1 g tiêu đen xay lên hai mặt.', 'Khía nhẹ phần thịt dày thay vì dùng búa đập giúp miếng gà chín đều từ trong ra ngoài mà vẫn giữ được thớ thịt mọng nước.', NULL),
('imp-0841a517e823e3b6_v4_step_3', 'imp-0841a517e823e3b6', 3, 'cook', 'Áp chảo mặt da gà vàng giòn', 'Làm nóng chảo rộng trên lửa vừa với 15 ml dầu ăn trung tính, đặt từng miếng đùi gà mặt da úp xuống đáy chảo. Dùng xẻng ấn nhẹ trong 10 giây đầu để mặt da phẳng sát chảo rồi chiên khoảng 5 phút không lật đến khi da gà vàng giòn rụm và chuyển sang màu nâu cánh gián đẹp mắt.', NULL, 5),
('imp-0841a517e823e3b6_v4_step_4', 'imp-0841a517e823e3b6', 4, 'cook', 'Lật mặt và hấp chín đều lõi thịt gà', 'Lật mặt thịt gà xuống dưới, hạ lửa xuống mức nhỏ và đậy kín vung chảo hấp tiếp 3–4 phút cho lõi thịt đùi gà chín trắng hoàn toàn, không còn nước đỏ khi xiên thử. Mở nắp, dùng khăn giấy thấm sạch lượng mỡ gà chảy ra dư thừa trong chảo.', 'Thấm bỏ phần mỡ tiết ra trước khi rưới sốt giúp sốt Teriyaki bám trực tiếp lên thịt và trong bóng đẹp mắt hơn.', 4),
('imp-0841a517e823e3b6_v4_step_5', 'imp-0841a517e823e3b6', 5, 'cook', 'Rưới sốt Teriyaki và rim cô bóng mặt gà', 'Bật lại lửa vừa, đổ toàn bộ bát sốt Teriyaki vào chảo, vớt bỏ xác lát gừng nếu muốn sốt mịn và liên tục nghiêng chảo múc sốt rưới đều lên hai mặt gà khoảng 3 phút cho đến khi cồn bay hơi, sốt sánh keo lại và phủ lớp men nâu bóng đẹp lên từng miếng gà.', 'Không cần pha thêm bột năng; đường và rượu ngọt Mirin trong sốt sẽ tự caramel hóa tạo độ sánh bóng mượt khi cô đặc.', 3),
('imp-0841a517e823e3b6_v4_step_6', 'imp-0841a517e823e3b6', 6, 'finish', 'Thái miếng vừa ăn, rưới sốt và thưởng thức nóng', 'Gắp gà ra thớt nghỉ 2 phút cho ổn định nước thịt rồi thái thành từng lát dày 1,5–2 cm. Xếp ra đĩa hoặc lên bát cơm nóng, rưới phần sốt Teriyaki sánh bóng còn lại trong chảo lên trên và dùng nóng ngay.', NULL, NULL),
('imp-6ae7feae7ec0d517_v4_step_1', 'imp-6ae7feae7ec0d517', 1, 'prep', 'Ngâm que tre và nấu cô đặc nước sốt Tare', 'Ngâm 9 que xiên tre ngập trong khay nước lạnh ít nhất 30 phút để que không cháy sém khi nướng. Cho 90 ml nước tương Nhật, 90 ml rượu ngọt Mirin, 45 ml rượu Sake nấu ăn, 45 ml nước lọc, 10 g đường nâu cùng phần lá xanh của 2 bó hành lá vào nồi nhỏ, đun sôi rồi hạ lửa nhỏ đun mở nắp khoảng 25 phút đến khi sốt còn 1/3 lượng ban đầu và hơi sánh bóng thì vớt bỏ lá hành, để nguội hẳn.', 'Tách riêng 1/3 lượng sốt tare nguội ra chén sạch để chấm hoặc quét sau khi nướng xong, tránh nhiễm chéo từ cọ đã quét thịt sống.', 25),
('imp-6ae7feae7ec0d517_v4_step_2', 'imp-6ae7feae7ec0d517', 2, 'prep', 'Thái gà, hành lá và xiên xen kẽ khít tay', 'Cắt 450 g thịt đùi gà lọc xương thành các miếng vuông cạnh 3 cm và cắt phần thân trắng hành lá thành các khúc dài 3 cm tương ứng. Xiên lần lượt thịt gà xen kẽ hành lá vào 9 que tre (mỗi xiên khoảng 3–4 miếng gà và 2–3 khúc hành), xếp các miếng sát khít nhau che kín phần que gỗ ở giữa.', 'Xiên thịt và hành thật khít nhau đồng thời bọc giấy bạc vào phần đuôi que tre sẽ ngăn que bị cháy gãy trong lò nướng.', NULL),
('imp-6ae7feae7ec0d517_v4_step_3', 'imp-6ae7feae7ec0d517', 3, 'cook', 'Làm nóng lò và nướng xiên gà lần đầu cho se mặt', 'Làm nóng trước lò nướng chế độ lửa trên ở mức cao (hoặc chuẩn bị bếp than hồng) trong 5 phút. Lót giấy bạc dưới khay, đặt vỉ lên trên, quét 10 ml dầu ăn trung tính chống dính rồi xếp các xiên gà lên vỉ, nướng 6 phút cho mặt thịt săn lại và bắt đầu chín tới.', NULL, 6),
('imp-6ae7feae7ec0d517_v4_step_4', 'imp-6ae7feae7ec0d517', 4, 'cook', 'Quét sốt Tare và nướng lật mặt cho xém cạnh', 'Lấy khay xiên ra khỏi lò, dùng cọ quét đều lớp sốt tare sánh lên cả hai mặt thịt gà và hành lá, cho lại vào lò nướng thêm 4 phút đến khi lớp sốt sủi bọt thơm lừng và các cạnh gà hơi xém nâu.', 'Canh sát ở những phút cuối sau khi quét sốt vì lượng đường trong sốt tare dễ bị cháy sém nhanh dưới thanh nhiệt lò.', 4),
('imp-6ae7feae7ec0d517_v4_step_5', 'imp-6ae7feae7ec0d517', 5, 'cook', 'Quét lớp sốt Tare thứ hai tạo màu bóng đẹp', 'Lật mặt đẹp của các xiên gà hướng lên trên, quét thêm một lớp sốt tare mỏng nữa rồi nướng thêm 2 phút cuối đến khi thịt gà chín hoàn toàn bên trong, mặt ngoài bóng mượt xém cạnh thơm nức.', NULL, 2),
('imp-6ae7feae7ec0d517_v4_step_6', 'imp-6ae7feae7ec0d517', 6, 'finish', 'Quét sốt sạch, rắc Shichimi và thưởng thức nóng', 'Gắp các xiên gà Yakitori ra đĩa, dùng cọ sạch quét thêm một lớp mỏng phần sốt tare đã chừa riêng, rắc chút bột ớt 7 vị Nhật Shichimi lên trên và dùng nóng ngay.', NULL, NULL),
('imp-7facaaeafc40dac2_v4_step_1', 'imp-7facaaeafc40dac2', 1, 'prep', 'Làm sạch xương dăm, vảy cá và xoa rượu Sake', 'Miết dọc thớ thịt 340 g phi lê cá hồi còn da để tìm và nhổ hết xương dăm bằng nhíp, cạo sạch phần vảy còn sót trên mặt da. Rưới đều 15 ml rượu Sake nấu ăn lên cả hai mặt cá, để nghỉ 5 phút rồi dùng khăn giấy thấm khô nhẹ.', NULL, 5),
('imp-7facaaeafc40dac2_v4_step_2', 'imp-7facaaeafc40dac2', 2, 'marinate', 'Ướp muối hạt lạnh giúp thịt cá săn ngọt', 'Đặt cá lên vỉ thoáng đặt trên khay, rắc đều 12 g muối hạt phủ khắp hai mặt miếng cá hồi. Đặt khay cá không đậy nắp vào ngăn mát tủ lạnh khoảng 45 phút để muối rút bớt độ ẩm thừa và giúp vị đậm thấm sâu vào thớ cá.', 'Ướp muối rồi để hở trong tủ lạnh giúp bề mặt cá khô ráo, khi nướng thịt cá săn chắc và da rất dễ giòn.', 45),
('imp-7facaaeafc40dac2_v4_step_3', 'imp-7facaaeafc40dac2', 3, 'prep', 'Rửa sạch muối thừa, thấm khô và mài củ cải trắng', 'Lấy cá ra khỏi tủ lạnh, xả nhanh dưới vòi nước lạnh để rửa trôi hoàn toàn lớp muối mặn bên ngoài rồi dùng khăn giấy thấm thật khô cả phần thịt lẫn mặt da. Gọt vỏ 80 g củ cải trắng, mài nhuyễn mịn và vắt nhẹ cho ráo bớt nước; cắt múi cau 1 quả chanh tươi và thái nhỏ 0,5 bó hành lá.', 'Rửa sạch muối thừa sau khi ướp giúp cá thấm vị mặn dịu hài hòa từ bên trong mà không bị mặn gắt trên bề mặt.', NULL),
('imp-7facaaeafc40dac2_v4_step_4', 'imp-7facaaeafc40dac2', 4, 'cook', 'Làm nóng lò nướng hoặc nồi chiên không dầu', 'Làm nóng trước lò nướng chế độ lửa trên ở 220°C trong 5 phút (kê khay cách thanh nhiệt khoảng 10 cm). Lót giấy bạc lên khay nướng, thoa đều 10 ml dầu ăn trung tính chống dính rồi xếp hai miếng cá hồi lên khay.', NULL, 5),
('imp-7facaaeafc40dac2_v4_step_5', 'imp-7facaaeafc40dac2', 5, 'cook', 'Nướng cá hồi xém vàng và giòn mặt da', 'Cho khay cá vào nướng ở 220°C khoảng 6–8 phút (xoay khay một lần giữa chừng nếu cần) đến khi phần da giòn phồng nhẹ, bề mặt thịt cá hơi xém vàng các cạnh và phần thịt bên trong chuyển màu hồng nhạt đục tách thớ nhẹ là vừa chín tới.', 'Nướng ở nhiệt cao trong thời gian ngắn giúp da cá hồi giòn rụm mà phần thịt bên trong vẫn giữ được độ béo ẩm tự nhiên.', 7),
('imp-7facaaeafc40dac2_v4_step_6', 'imp-7facaaeafc40dac2', 6, 'finish', 'Bày cá nướng cùng củ cải mài, chanh tươi và hành lá', 'Chuyển cá hồi nướng Shioyaki ra đĩa, đặt ụ củ cải trắng mài và múi chanh tươi bên cạnh, rắc thêm hành lá thái nhỏ. Vắt nước cốt chanh trực tiếp lên mặt cá và dùng nóng cùng cơm trắng.', NULL, NULL),
('imp-70379b3f30b48438_v4_step_1', 'imp-70379b3f30b48438', 1, 'prep', 'Thái mỏng và ướp muối làm giòn dưa leo', 'Rửa sạch 2 quả dưa leo tươi, cắt bỏ hai đầu, có thể bào vỏ sọc xen kẽ cho đẹp rồi thái thành những lát tròn thật mỏng khoảng 2 mm. Cho dưa leo vào tô, rắc 5 g muối ăn lên bóp nhẹ đều tay rồi để yên 10 phút cho dưa ra hết nước chát.', 'Ướp muối trước khi trộn giúp lát dưa leo giòn sần sật và không tiết thêm nước làm loãng sốt giấm về sau.', 10),
('imp-70379b3f30b48438_v4_step_2', 'imp-70379b3f30b48438', 2, 'cook', 'Sơ chế và luộc chín tới tôm tươi', 'Rửa sạch 220 g tôm tươi, bóc bỏ vỏ, rút sạch chỉ đen trên sống lưng. Đun sôi nồi nước nhỏ trên lửa vừa, thả tôm vào luộc khoảng 3 phút cho đến khi tôm cong tròn, chuyển sang màu hồng cam đục và chín kỹ hoàn toàn thì vớt ngay ra để nguội ráo.', NULL, 3),
('imp-70379b3f30b48438_v4_step_3', 'imp-70379b3f30b48438', 3, 'prep', 'Vắt thật kiệt nước dưa leo đã ướp muối', 'Dùng hai tay nắm từng nắm dưa leo bóp vắt thật kiệt phần nước muối tiết ra (nếu thấy hơi mặn có thể tráng nhanh qua nước lọc lạnh rồi vắt lại), thấm thêm bằng khăn giấy cho dưa khô ráo hoàn toàn.', 'Dưa leo càng được vắt ráo nước thì khi trộn sẽ càng giòn lâu và thấm đều vị nước sốt giấm ngọt.', NULL),
('imp-70379b3f30b48438_v4_step_4', 'imp-70379b3f30b48438', 4, 'sauce', 'Pha nước sốt giấm gạo chua ngọt', 'Trong bát nhỏ, khuấy tan 35 ml giấm gạo Nhật, 12 g đường cát trắng, 15 ml nước tương Nhật, 5 ml dầu mè rang cùng 1 g ớt vảy khô đến khi hạt đường hòa quyện hoàn toàn vào dung dịch giấm.', NULL, NULL),
('imp-70379b3f30b48438_v4_step_5', 'imp-70379b3f30b48438', 5, 'finish', 'Trộn nhẹ gỏi dưa leo tôm và ướp lạnh', 'Cho dưa leo đã vắt ráo, tôm luộc đã nguội (có thể chẻ đôi con lớn) và 0,5 bó hành lá thái nhỏ vào tô sạch. Rưới đều bát nước sốt giấm gạo lên trên, đảo trộn nhẹ tay cho dưa không bị dập, rắc 8 g hạt mè trắng rang vào trộn thêm lần nữa rồi đậy kín để ngăn mát tủ lạnh 15 phút cho thấm vị.', 'Ướp lạnh khoảng 15–20 phút trước khi ăn giúp món gỏi Sunomono mát sâu, giòn ngọt và các hương vị hòa quyện thanh tao nhất.', 15),
('imp-70379b3f30b48438_v4_step_6', 'imp-70379b3f30b48438', 6, 'finish', 'Trình bày gỏi Sunomono ra chén và dùng mát', 'Chia gỏi dưa leo tôm ra ba chén nhỏ gọn đẹp, rưới thêm chút nước sốt dưới đáy tô lên trên và thưởng thức lạnh như món khai vị thanh mát.', NULL, NULL),
('imp-49262ac40836045a_v4_step_1', 'imp-49262ac40836045a', 1, 'marinate', 'Thái nhỏ và ướp thịt ức gà với rượu Sake', 'Thái 100 g thịt ức gà phi lê thành từng miếng vuông nhỏ khoảng 1 cm cho nhanh chín đều. Trộn thịt gà với 15 ml rượu Sake nấu ăn trong bát nhỏ, ướp khoảng 10 phút cho thịt mềm ẩm và hết mùi tanh. Song song, thái lát mỏng 60 g nấm đùi gà tươi, 40 g chả cá Nhật và thái nhỏ 0,5 bó hành lá tươi.', NULL, 10),
('imp-49262ac40836045a_v4_step_2', 'imp-49262ac40836045a', 2, 'sauce', 'Pha hỗn hợp trứng và nước dùng Dashi nguội', 'Đập 3 quả trứng gà vào bát, dùng đũa khuấy nhẹ sát đáy theo đường zíc zắc cho lòng đỏ và lòng trắng hòa quyện mà không nổi bọt. Rót từ từ 360 ml nước dùng Dashi đã nguội hoàn toàn cùng 10 ml rượu ngọt Mirin, 10 ml nước tương Nhật và 2 g muối ăn vào khuấy tan đều.', 'Nước dùng Dashi phải nguội về nhiệt độ phòng; dùng nước dashi nóng sẽ làm trứng bị vón lợn cợn ngay khi pha.', NULL),
('imp-49262ac40836045a_v4_step_3', 'imp-49262ac40836045a', 3, 'prep', 'Lọc rây hỗn hợp trứng và xếp nhân vào ba chén sứ', 'Lọc hỗn hợp trứng dashi qua rây lưới mịn 2 lần vào ca có miệng rót để loại bỏ hoàn toàn dây lòng trắng. Chia đều thịt ức gà đã ướp và nấm đùi gà thái lát xuống đáy ba chén sứ chịu nhiệt, đặt các lát chả cá Nhật lên trên rồi rót từ từ hỗn hợp trứng vào đầy 80% chén, hớt sạch bọt khí mặt trên và đậy kín nắp chén (hoặc bọc màng giấy bạc).', 'Lọc hỗn hợp trứng qua rây mịn và hớt sạch bọt khí trên mặt chén giúp thành phẩm custard mịn mướt không bị rỗ.', NULL),
('imp-49262ac40836045a_v4_step_4', 'imp-49262ac40836045a', 4, 'cook', 'Đun nồi nước hấp và hạ lửa nhỏ nhất', 'Đổ nước vào nồi hấp sâu lòng sao cho mực nước ngập khoảng một nửa chiều cao chén sứ, đun sôi mạnh trên lửa lớn rồi hạ ngay xuống mức lửa nhỏ nhất để mặt nước lắng êm chỉ còn hơi nóng nhẹ ở khoảng 85–90°C.', NULL, NULL),
('imp-49262ac40836045a_v4_step_5', 'imp-49262ac40836045a', 5, 'cook', 'Hấp cách thủy trứng lửa nhỏ trong 22–25 phút', 'Nhẹ nhàng đặt ba chén trứng vào nồi nước nóng (không để nước sôi bùng), đậy nắp nồi hơi hé khe nhỏ thoát bớt áp suất và hấp liu riu ở lửa nhỏ nhất trong 22–25 phút cho đến khi trứng đông đặc mượt mà và thịt gà chín kỹ hoàn toàn bên trong.', 'Hấp ở nhiệt độ ổn định dưới mức sôi và hé nhẹ nắp nồi là bí quyết giúp mặt chén trứng Chawanmushi láng bóng như lụa, không bị rỗ bọt khí.', 23),
('imp-49262ac40836045a_v4_step_6', 'imp-49262ac40836045a', 6, 'finish', 'Kiểm tra độ chín, rắc hành lá và thưởng thức nóng', 'Xiên nhẹ đầu que tre vào chính giữa chén trứng, thấy nước chảy ra trong veo không còn đục là đạt. Rắc hành lá thái nhỏ lên mặt từng chén, đậy nắp ủ thêm 1 phút rồi dọn nóng dùng bằng thìa nhỏ.', NULL, NULL),
('imp-e26d04bf95bcede8_v4_step_1', 'imp-e26d04bf95bcede8', 1, 'cook', 'Hầm nước dùng xương heo và rau củ thơm', 'Cho 400 g xương ống heo, 3500 ml nước lọc, 0,5 củ hành tây, 0,5 củ tỏi khô nguyên vỏ và 25 g gừng tươi thái lát vào nồi cao lớn. Đun sôi trên lửa lớn không đậy nắp, dùng vợt lưới mịn hớt thật sạch toàn bộ bọt và váng bẩn nổi lên rồi buộc chặt 450 g thịt ba chỉ heo bằng dây dù thực phẩm thả vào hầm chung.', 'Hớt bọt thật kỹ trong 20 phút đầu sôi là chìa khóa giúp nước dùng Ramen trong veo, thơm thanh mà không có mùi hôi xương.', 25),
('imp-e26d04bf95bcede8_v4_step_2', 'imp-e26d04bf95bcede8', 2, 'cook', 'Ninh mềm thịt ba chỉ và thêm mỡ béo vào nước dùng', 'Tiếp tục đun sôi lăn tăn mở nắp khoảng 90 phút cho thịt ba chỉ chín mềm. Múc khoảng 240 ml nước dùng nóng sang nồi nhỏ để chuẩn bị om Chashu; đồng thời thả 30 g mỡ heo thắng cùng phần lá xanh của 1,5 bó hành lá tươi vào nồi nước dùng chính tiếp tục ninh lửa vừa nhỏ thêm 60 phút cho ngọt sâu.', NULL, 90),
('imp-e26d04bf95bcede8_v4_step_3', 'imp-e26d04bf95bcede8', 3, 'cook', 'Om thịt ba chỉ Chashu và cô nước sốt Shoyu Tare', 'Pha vào nồi nhỏ chứa 240 ml nước dùng nóng: 155 ml nước tương Nhật, 30 ml rượu Sake nấu ăn và 30 ml rượu ngọt Mirin. Vớt tảng thịt ba chỉ từ nồi xương sang nồi sốt này, phủ giấy nến khoét lỗ sát mặt thịt và om liu riu lửa nhỏ khoảng 60 phút, thỉnh thoảng rưới sốt lên mặt thịt. Sau đó vớt thịt ra để nguội hẳn rồi bọc kín ướp lạnh cho săn chắc để dễ thái lát mỏng 3 mm; phần nước sốt lọc sạch mỡ chính là Shoyu Tare.', 'Làm lạnh thịt Chashu trước khi cắt giúp lát thịt tròn đẹp, mỡ kết dính không bị nát vụn.', 60),
('imp-e26d04bf95bcede8_v4_step_4', 'imp-e26d04bf95bcede8', 4, 'marinate', 'Luộc trứng lòng đào và ngâm tương Ajitama', 'Đun sôi nồi nước nhỏ, thả 4 quả trứng gà lạnh từ tủ mát vào luộc đúng 7 phút rồi vớt ngay sang tô nước đá 15 phút và bóc sạch vỏ. Đun sôi nhẹ 45 ml nước tương Nhật, 45 ml rượu Sake nấu ăn, 30 ml rượu ngọt Mirin và 12 g đường cát trắng trong 1 phút cho tan đường rồi để nguội hẳn, cho trứng vào ngâm kín trong tủ mát ít nhất 2 giờ cho ngấm màu nâu đẹp.', 'Luộc trứng ngay từ lúc lấy ở tủ mát rồi ngâm nước đá lạnh giúp lòng trắng săn mịn, dễ bóc vỏ và lòng đỏ dẻo sánh.', 7),
('imp-e26d04bf95bcede8_v4_step_5', 'imp-e26d04bf95bcede8', 5, 'cook', 'Lọc trong nước dùng và luộc nhanh mì Ramen', 'Lọc bỏ hết xương ống và xác rau củ khỏi nồi nước dùng chính, đun nóng sôi lăn tăn trở lại. Chuẩn bị sẵn thịt ba chỉ Chashu thái lát 3 mm, trứng lòng đào cắt đôi và hành lá thái nhỏ. Đun sôi mạnh một nồi nước lớn khác, thả 320 g mì Ramen khô vào khuấy tơi luộc khoảng 3 phút cho sợi vừa chín dai rồi vớt ra rổ lắc thật ráo nước.', 'Vẩy thật kiệt nước sau khi luộc mì để không làm loãng hương vị đậm đà của tô nước dùng Ramen.', 3),
('imp-e26d04bf95bcede8_v4_step_6', 'imp-e26d04bf95bcede8', 6, 'finish', 'Hoàn thiện tô Shoyu Ramen nóng hổi và thưởng thức', 'Cho vào mỗi tô 1,5 muỗng canh nước sốt Shoyu Tare và chút hành lá thái nhỏ, chan 350 ml nước dùng đang sôi nóng vào, thả mì Ramen vào gắp gọn sang một bên. Xếp vài lát thịt Chashu, hai nửa trứng lòng đào Ajitama, hành lá thái nhỏ và cắm miếng rong biển khô Nori bên thành tô rồi dùng nóng ngay.', NULL, NULL),
('imp-b808fb03d1e8ede6_v4_step_1', 'imp-b808fb03d1e8ede6', 1, 'prep', 'Vo ngâm gạo và nấu cơm trắng Nhật', 'Vo nhẹ 300 g gạo hạt ngắn Nhật 2–3 lần đến khi nước khá trong, cho vào nồi cơm điện cùng 430 ml nước lọc và ngâm 20 phút trước khi bật nấu. Khi cơm chín, để nồi ở chế độ giữ ấm thêm 10 phút rồi mở nắp xới tơi hạt cơm.', 'Ngâm gạo trước khi bật nút nấu giúp hạt gạo ngậm đủ nước, chín dẻo bóng và không bị sượng lõi.', 30),
('imp-b808fb03d1e8ede6_v4_step_2', 'imp-b808fb03d1e8ede6', 2, 'marinate', 'Cắt và ướp thịt đùi gà cùng sơ chế rau củ', 'Cắt 450 g đùi gà lọc xương thành miếng vuông khoảng 2,5 cm rồi ướp đều với 1,5 g muối ăn trong 10 phút. Khoai tây gọt vỏ cắt khối 2 cm và ngâm ngay vào thau nước lạnh 15 phút cho ra bớt tinh bột, sau đó vớt ra để ráo; cà rốt cắt khoanh xéo dày 1,5 cm; hành tây thái múi mỏng; tỏi băm nhuyễn và gừng tươi mài mịn.', 'Ngâm khoai tây vào nước lạnh trước khi nấu giúp mặt khoai săn lại, không bị bở nát làm đục nồi cà ri.', 15),
('imp-b808fb03d1e8ede6_v4_step_3', 'imp-b808fb03d1e8ede6', 3, 'cook', 'Xào hành tây nâu vàng và phi thơm gừng tỏi', 'Làm nóng nồi đáy dày trên lửa vừa với 15 ml dầu ăn thực vật, cho toàn bộ hành tây thái mỏng cùng 0,5 g muối ăn còn lại vào đảo đều khoảng 8 phút đến khi hành mềm rũ, chuyển màu nâu vàng và dậy mùi thơm ngọt. Thêm tỏi băm và gừng tươi mài vào đảo nhanh 30 giây cho dậy hương thơm.', 'Xào hành tây đến khi ngả màu nâu vàng chứ không chỉ chín trong là bí quyết tạo vị ngọt sâu cho sốt cà ri.', 8),
('imp-b808fb03d1e8ede6_v4_step_4', 'imp-b808fb03d1e8ede6', 4, 'cook', 'Xào săn thịt gà và ninh mềm khoai tây, cà rốt', 'Cho phần đùi gà đã ướp vào nồi xào trên lửa vừa khoảng 3 phút cho thịt săn bề mặt và không còn màu hồng bên ngoài. Tiếp tục thả khoai tây và cà rốt vào đảo đều 1 phút, đổ 300 ml nước dùng gà cùng 350 ml nước lọc vào đun sôi trên lửa lớn rồi hạ xuống lửa nhỏ, đậy hờ nắp ninh liu riu 18–20 phút đến khi xiên đũa qua khoai và cà rốt thấy mềm bùi.', 'Luôn giữ lửa nhỏ sôi lăn tăn và vớt bọt nhẹ để nước dùng trong, rau củ chín đều mà không bị vỡ cạnh.', 20),
('imp-b808fb03d1e8ede6_v4_step_5', 'imp-b808fb03d1e8ede6', 5, 'sauce', 'Hòa tan viên cà ri Nhật và nêm sốt sánh mịn', 'Tắt bếp hoặc hạ lửa xuống mức nhỏ nhất, bẻ nhỏ 110 g viên cà ri Nhật thả từ từ vào nồi, dùng muôi gỗ khuấy nhẹ liên tục khoảng 1–2 phút cho viên cà ri tan hoàn toàn, không còn vón cục. Bật lại lửa nhỏ, thêm 10 ml xì dầu Nhật và 5 ml sốt Worcestershire vào khuấy đều, đun liu riu thêm 4 phút cho sốt sánh bóng và thịt gà chín kỹ hoàn toàn.', 'Tắt bếp khi thả viên cà ri giúp bột roux tan đều mượt mà, tránh bị vón cục hoặc bén đáy nồi.', 4),
('imp-b808fb03d1e8ede6_v4_step_6', 'imp-b808fb03d1e8ede6', 6, 'finish', 'Trình bày đĩa cơm cà ri và hoàn thiện món ăn', 'Xới cơm trắng nóng ra một nửa đĩa sâu lòng, múc cà ri gà cùng khoai tây và cà rốt chan vào nửa đĩa còn lại. Rắc hành lá thái xéo lên trên và xếp củ cải muối đỏ Fukujinzuke bên cạnh đĩa rồi thưởng thức ngay khi sốt còn nóng sánh.', NULL, NULL),
('imp-46c2a1c4cc7a8bb5_v4_step_1', 'imp-46c2a1c4cc7a8bb5', 1, 'prep', 'Sơ chế thịt bò, hành tây, gừng và hành lá', 'Thịt bò thái lát mỏng cắt miếng dài 4–5 cm vừa gắp. Hành tây bóc vỏ thái lát mỏng dọc củ, gừng tươi thái sợi mảnh, hành lá rửa sạch thái xéo mỏng để riêng.', 'Thịt bò thái lát mỏng ngang thớ hoặc dùng loại thịt bò nhúng lẩu sẽ giúp thịt mềm ngọt, không bị dai khi nấu nhanh.', NULL),
('imp-46c2a1c4cc7a8bb5_v4_step_2', 'imp-46c2a1c4cc7a8bb5', 2, 'cook', 'Nấu và nêm nồi nước dùng Dashi nóng', 'Đổ 600 ml nước dùng Dashi cùng 300 ml nước lọc vào nồi, đun sôi nhẹ trên lửa vừa rồi nêm 25 ml xì dầu Nhật, 20 ml rượu Mirin và 6 g đường cát trắng. Khuấy tan hoàn toàn, nếm thử vị mặn ngọt thanh vừa miệng rồi tắt bếp, đậy nắp giữ nóng.', 'Pha thêm nước lọc giúp nước dùng Dashi vừa vị thanh tao khi kết hợp cùng xì dầu mà không bị mặn gắt.', 4),
('imp-46c2a1c4cc7a8bb5_v4_step_3', 'imp-46c2a1c4cc7a8bb5', 3, 'cook', 'Áp chảo thịt bò với gừng và hành tây', 'Làm nóng chảo rộng trên lửa vừa với 10 ml dầu ăn thực vật, dàn đều 300 g thịt bò thành một lớp mỏng và đảo nhanh khoảng 1–2 phút đến khi thịt vừa chuyển màu hết đỏ tái. Thêm gừng thái sợi và hành tây vào đảo chung thêm 2 phút cho hành mềm trong và dậy mùi thơm.', 'Dùng chảo rộng để thịt bò áp chảo nhanh thay vì bị ra nước hấp hơi, giữ được độ mềm ngọt tự nhiên.', 4),
('imp-46c2a1c4cc7a8bb5_v4_step_4', 'imp-46c2a1c4cc7a8bb5', 4, 'sauce', 'Rim thịt bò thấm sốt mặn ngọt kiểu Nhật', 'Cho 30 ml xì dầu Nhật còn lại, 30 ml rượu Mirin còn lại, 45 ml rượu Sake nấu ăn, 14 g đường cát trắng còn lại và 45 ml nước lọc vào chảo thịt bò, đảo đều trên lửa vừa khoảng 2–3 phút đến khi nước sốt sôi lăn tăn, hơi sánh lại và bám đều quanh từng lát thịt bò thì tắt bếp.', 'Không nấu thịt bò quá lâu sau khi thịt đã chín tới để tránh làm thịt bị khô xơ.', 3),
('imp-46c2a1c4cc7a8bb5_v4_step_5', 'imp-46c2a1c4cc7a8bb5', 5, 'cook', 'Trụng mì Udon trong nước sôi', 'Đun sôi một nồi nước riêng trên lửa lớn, thả 3 gói mì Udon vào trụng nhanh khoảng 1–2 phút, dùng đũa khuấy nhẹ cho từng sợi mì tơi rời, trong bóng và mềm dai thì vớt ngay ra rổ, xóc thật ráo nước.', 'Trụng mì Udon thật ráo nước giúp tô nước dùng không bị loãng và giữ trọn vị đậm đà của Dashi.', 2),
('imp-46c2a1c4cc7a8bb5_v4_step_6', 'imp-46c2a1c4cc7a8bb5', 6, 'finish', 'Trình bày tô mì Udon bò hành nóng hổi', 'Chia mì Udon đã ráo nước vào 3 tô lớn, đun sôi lại nồi nước dùng Dashi rồi chan ngập mặt mì. Xếp phần thịt bò xào hành tây cùng chút nước sốt lên trên, rắc hành lá thái xéo và thêm bột ớt 7 vị Nhật Shichimi tùy thích rồi dùng ngay khi còn nóng.', NULL, NULL),
('imp-38fb8569664d1f3b_v4_step_1', 'imp-38fb8569664d1f3b', 1, 'marinate', 'Thấm khô, ướp gia vị và áo bột cá hồi', 'Kiểm tra và nhổ sạch xương dăm trên 280 g cá hồi phi lê còn da, dùng khăn giấy thấm thật khô cả mặt thịt và mặt da. Rắc đều 2 g muối ăn và 1 g tiêu đen xay lên hai mặt cá, để thấm 10 phút cho thịt cá săn nhẹ.', 'Thấm thật khô nước trên bề mặt cá hồi là điều kiện quan trọng nhất để da cá áp chảo giòn rụm, không bị bắn dầu.', 10),
('imp-38fb8569664d1f3b_v4_step_2', 'imp-38fb8569664d1f3b', 2, 'prep', 'Áo bột gạo mỏng và chuẩn bị nguyên liệu làm sốt', 'Rây 5 g bột gạo áo thành một lớp thật mỏng lên cả hai mặt miếng cá hồi rồi giũ nhẹ cho rơi hết phần bột thừa. Băm nhỏ tỏi khô, vắt nửa quả chanh tươi lấy nước cốt bỏ hạt và thái nhỏ hành lá để sẵn.', 'Lớp bột gạo cực mỏng giúp mặt cá lên màu vàng đẹp kiểu Meunière và giữ ẩm cho thớ thịt bên trong.', NULL),
('imp-38fb8569664d1f3b_v4_step_3', 'imp-38fb8569664d1f3b', 3, 'cook', 'Áp chảo mặt da cá hồi vàng giòn', 'Làm nóng chảo chống dính trên lửa vừa lớn với 10 ml dầu ăn trung tính tráng đều đáy chảo. Đặt miếng cá hồi úp mặt da xuống chảo, dùng xẻng ấn nhẹ khoảng 20 giây đầu để da phẳng tiếp xúc đều mặt chảo, sau đó để yên áp chảo khoảng 4 phút đến khi thấy phần da chuyển vàng giòn và thịt cá chín trắng lên khoảng 2/3 chiều dày miếng cá.', 'Không di chuyển hoặc lật cá sớm trong 4 phút đầu để lớp da giòn bám chắc và tách mặt chảo tự nhiên.', 4),
('imp-38fb8569664d1f3b_v4_step_4', 'imp-38fb8569664d1f3b', 4, 'cook', 'Áp chín mặt còn lại và cho cá ra đĩa', 'Lật nhẹ miếng cá hồi sang mặt thịt, hạ xuống lửa vừa và áp thêm khoảng 2 phút cho cá vừa chín tới (phần lõi giữa còn mềm ẩm, không bị khô bở) rồi gắp cá ra đĩa giữ ấm.', NULL, 2),
('imp-38fb8569664d1f3b_v4_step_5', 'imp-38fb8569664d1f3b', 5, 'sauce', 'Phi tỏi và nấu sốt bơ chanh xì dầu', 'Hạ lửa thật nhỏ trên cùng chiếc chảo đó, cho tỏi băm vào phi khoảng 30 giây đến khi dậy mùi thơm dịu mà không bị cháy vàng. Rót 5 ml xì dầu Nhật, 5 ml rượu Mirin và nước cốt chanh tươi vào khuấy đều cho sôi lăn tăn nhẹ.', 'Giữ lửa nhỏ khi phi tỏi để tỏi thơm dịu; nếu chảo quá nóng có thể nhấc chảo khỏi bếp vài giây.', NULL),
('imp-38fb8569664d1f3b_v4_step_6', 'imp-38fb8569664d1f3b', 6, 'finish', 'Đánh tan bơ lạt và rưới sốt lên cá hồi', 'Nhấc chảo khỏi bếp, thả 20 g bơ lạt lạnh vào và xoay nhẹ chảo cho bơ tan chảy từ từ quyện với nước cốt chanh tạo thành sốt sánh bóng mịn màng. Rưới đều sốt bơ chanh lên 2 miếng cá hồi, rắc hành lá thái nhỏ rồi dùng nóng ngay.', NULL, NULL),
('imp-eae128801c2c7f96_v4_step_1', 'imp-eae128801c2c7f96', 1, 'prep', 'Sơ chế rau bina và chuẩn bị nước chần', 'Nhặt sạch 300 g rau bina, rửa kỹ từng kẽ gốc dưới vòi nước lạnh cho sạch cát rồi để nguyên cọng. Đun sôi 1000 ml nước lọc trong nồi lớn trên lửa lớn, đồng thời chuẩn bị sẵn một tô lớn nước lọc lạnh có thả vài viên đá.', 'Giữ nguyên cọng rau khi chần giúp dễ cầm nhúng phần cuống trước và vắt ráo nước sạch hơn sau khi luộc.', NULL),
('imp-eae128801c2c7f96_v4_step_2', 'imp-eae128801c2c7f96', 2, 'sauce', 'Rang thơm và giã dập hạt mè trắng', 'Cho 35 g hạt mè trắng vào chảo khô trên lửa vừa, đảo và lắc chảo liên tục khoảng 2–3 phút đến khi hạt mè nở phồng, chuyển màu vàng nhạt và tỏa mùi thơm béo thì trút ngay ra bát cho nguội bớt. Chừa lại 1 muỗng cà phê hạt mè nguyên để trang trí, phần còn lại cho vào cối giã dập khoảng 70% để tiết dầu thơm.', 'Giã mè khi còn hơi ấm giúp dầu mè tiết ra thơm hơn nhiều, không giã nát nhuyễn hết mà để lẫn ít hạt dập tạo độ bùi.', 3),
('imp-eae128801c2c7f96_v4_step_3', 'imp-eae128801c2c7f96', 3, 'sauce', 'Pha sốt mè xì dầu ngọt mặn cân bằng', 'Cho 15 ml xì dầu Nhật, 12 g đường cát trắng, 5 ml rượu Mirin và 8 ml dầu mè thơm vào bát mè vừa giã, khuấy đều tay đến khi đường tan hết và hỗn hợp sánh thơm đồng nhất.', 'Nêm sốt hơi đậm nhẹ một chút vì khi trộn vào rau bina vẫn còn độ ẩm tự nhiên sẽ vừa miệng.', NULL),
('imp-eae128801c2c7f96_v4_step_4', 'imp-eae128801c2c7f96', 4, 'cook', 'Chần nhanh rau bina giữ màu xanh mướt', 'Khi nồi nước sôi bùng, thả 5 g muối ăn vào khuấy tan. Cầm phần ngọn lá, nhúng phần cuống rau bina vào nước sôi trước trong 15 giây cho cuống mềm bớt, sau đó nhấn chìm toàn bộ lá rau xuống nước sôi chần tiếp 35 giây rồi vớt ra ngay.', 'Chần phần cuống cứng trước phần lá giúp cả cọng rau chín đồng đều mà lá không bị nhũn nát.', 1),
('imp-eae128801c2c7f96_v4_step_5', 'imp-eae128801c2c7f96', 5, 'prep', 'Ngâm lạnh, vắt kiệt nước và cắt khúc rau', 'Thả ngay rau bina vừa chần vào tô nước lạnh khoảng 1 phút để hãm nhiệt và giữ màu xanh tươi, sau đó vớt ra nắm chặt tay vắt thật kiệt nước. Đặt bó rau lên thớt, cắt thành từng khúc dài khoảng 3 cm rồi tơi nhẹ các cọng rau.', 'Vắt thật ráo nước là bước quyết định món Goma-ae ngon chuẩn vị, không bị đọng nước làm loãng sốt mè.', 1),
('imp-eae128801c2c7f96_v4_step_6', 'imp-eae128801c2c7f96', 6, 'finish', 'Trộn rau bina với sốt mè và trình bày', 'Cho rau bina đã cắt khúc vào tô sốt mè, dùng đũa hoặc tay đeo găng đảo nhẹ nhàng để từng cọng rau áo đều lớp sốt mè sánh thơm. Bày ra đĩa nhỏ, rắc phần hạt mè rang nguyên hạt chừa lại lên trên rồi thưởng thức.', NULL, NULL),
('imp-56ec9eae817af509_v4_step_1', 'imp-56ec9eae817af509', 1, 'prep', 'Thái sợi mảnh bắp cải và cà rốt', 'Tách bỏ lá già ngoài cùng và lõi cứng của 480 g bắp cải xanh, rửa sạch rồi thái sợi mỏng đều tay. Cà rốt gọt vỏ, thái sợi mảnh có kích cỡ tương đương sợi bắp cải để khi hấp chín đồng đều và đẹp mắt.', 'Thái sợi bắp cải và cà rốt đều nhau giúp rau chín cùng lúc, không bị sợi nhũn sợi sống.', NULL),
('imp-56ec9eae817af509_v4_step_2', 'imp-56ec9eae817af509', 2, 'cook', 'Hấp nhanh bắp cải và cà rốt bằng ít nước', 'Cho toàn bộ bắp cải và cà rốt thái sợi vào nồi, đổ 60 ml nước lọc vào rồi đậy kín nắp, đun trên lửa vừa khoảng 4–5 phút đến khi rau vừa chín tới, xẹp xuống nhưng vẫn giữ độ giòn ngọt tự nhiên. Tắt bếp, trút rau ra rổ cho nguội nhanh.', 'Chỉ dùng 60 ml nước và đậy nắp kín giúp rau chín bằng hơi nước, giữ lại tối đa vị ngọt và vitamin.', 5),
('imp-56ec9eae817af509_v4_step_3', 'imp-56ec9eae817af509', 3, 'prep', 'Vắt ráo kiệt nước phần rau đã hấp', 'Khi bắp cải và cà rốt đã nguội hẳn, dùng tay sạch bóp nhẹ hoặc vắt kỹ cho ra hết nước thừa đọng trong rau rồi tơi nhẹ ra tô lớn.', 'Vắt thật ráo nước trước khi trộn giúp sốt mè bám chặt vào từng sợi bắp cải, món ăn đậm vị mà không bị chảy nước.', NULL),
('imp-56ec9eae817af509_v4_step_4', 'imp-56ec9eae817af509', 4, 'sauce', 'Rang vàng và giã dập hạt mè trắng', 'Cho 35 g hạt mè trắng vào chảo khô trên lửa vừa nhỏ, đảo đều tay khoảng 3 phút cho mè vàng thơm lừng rồi trút ra. Giữ lại 1 muỗng cà phê hạt nguyên, phần còn lại cho vào cối giã dập đến khi hơi sánh thơm.', NULL, 3),
('imp-56ec9eae817af509_v4_step_5', 'imp-56ec9eae817af509', 5, 'sauce', 'Pha sốt mè xì dầu giấm gạo', 'Trộn đều phần mè giã dập với 18 ml xì dầu Nhật, 12 g đường cát trắng, 10 ml giấm gạo và 10 ml dầu mè thơm đến khi đường tan hết thành hỗn hợp sốt sệt mịn.', 'Thêm chút giấm gạo vào sốt mè kiểu Nhật giúp vị béo bùi trở nên thanh nhẹ, rất hợp ăn lạnh vào ngày nóng.', NULL),
('imp-56ec9eae817af509_v4_step_6', 'imp-56ec9eae817af509', 6, 'finish', 'Trộn đều, ủ lạnh và hoàn thiện món ăn', 'Rưới sốt mè lên tô bắp cải và cà rốt đã vắt ráo, trộn đều tay cho từng sợi rau áo đều sốt. Đậy kín tô rau, cho vào ngăn mát tủ lạnh khoảng 20–30 phút cho thấm vị và mát lạnh rồi bày ra đĩa, rắc hành lá thái nhỏ và hạt mè nguyên lên trên.', NULL, 20),
('imp-44b1338a7a49098d_v4_step_1', 'imp-44b1338a7a49098d', 1, 'prep', 'Sơ chế kim chi, thịt ba chỉ và đậu phụ', 'Cắt 420 g kim chi cải thảo ủ chua thành khúc dài 3–4 cm và giữ lại khoảng 60 ml nước kim chi. Thái miếng thịt ba chỉ heo dày 0,5 cm, thái lát hành tây, thái lát đậu phụ trắng dày 1,5 cm và thái vát hành lá tươi.', NULL, NULL),
('imp-44b1338a7a49098d_v4_step_2', 'imp-44b1338a7a49098d', 2, 'cook', 'Xào thịt ba chỉ và kim chi dậy mùi thơm', 'Làm nóng nồi sâu lòng trên lửa vừa với 15 ml dầu thực vật, cho thịt ba chỉ heo vào đảo 3 phút đến khi thịt săn mặt và hơi xém cạnh. Thêm tỏi khô băm nhuyễn và kim chi cải thảo vào xào chung 4 phút để kim chi mềm lại và quyện vị béo từ thịt.', 'Xào kim chi khoảng 4 phút trước khi cho nước dùng giúp hương vị canh đậm sâu và thơm hơn hẳn.', 7),
('imp-44b1338a7a49098d_v4_step_3', 'imp-44b1338a7a49098d', 3, 'cook', 'Hòa gia vị và đổ nước dùng cá cơm tảo bẹ', 'Rắc 5 g ớt bột Hàn Quốc (Gochugaru), 18 g tương ớt Hàn Quốc (Gochujang), 8 g đường cát trắng và phần nước kim chi vào nồi đảo đều 30 giây. Rót 500 ml nước dùng cá cơm tảo bẹ vào, khuấy nhẹ cho tan gia vị rồi đun sôi trên lửa lớn.', NULL, NULL),
('imp-44b1338a7a49098d_v4_step_4', 'imp-44b1338a7a49098d', 4, 'cook', 'Hầm canh cùng hành tây cho ngọt nước', 'Khi nồi canh sôi bùng, thả hành tây thái lát vào, hớt bọt nổi và hạ xuống lửa vừa-nhỏ, đậy nắp hầm 12 phút để thịt ba chỉ chín mềm hoàn toàn và hành tây tiết vị ngọt thanh. Nêm thêm 4 g muối ăn cho vừa khẩu vị.', 'Nêm muối sau khi đã hầm khoảng 10 phút giúp bạn kiểm soát độ mặn chính xác vì kim chi đã có sẵn vị mặn.', 12),
('imp-44b1338a7a49098d_v4_step_5', 'imp-44b1338a7a49098d', 5, 'cook', 'Thả đậu phụ trắng vào nồi canh', 'Xếp nhẹ từng lát đậu phụ trắng lên mặt nồi canh, dùng muỗng múc nước canh rưới lên mặt đậu và nấu tiếp 4 phút trên lửa vừa cho đậu nóng thấm vị mà vẫn giữ nguyên miếng.', NULL, 4),
('imp-44b1338a7a49098d_v4_step_6', 'imp-44b1338a7a49098d', 6, 'finish', 'Rắc hành lá, rưới dầu mè và dọn nóng', 'Rắc hành lá tươi thái vát lên mặt nồi canh, tắt bếp rồi rưới 5 ml dầu mè rang quanh nồi cho thơm lừng và dọn nóng dùng ngay với cơm trắng.', 'Dọn canh trực tiếp bằng nồi giữ nhiệt sẽ giúp đậu phụ và nước canh ấm nóng đến cuối bữa.', NULL),
('imp-a24a701c584d3ef3_v4_step_1', 'imp-a24a701c584d3ef3', 1, 'marinate', 'Ướp thịt bò và pha sốt Bibimbap', 'Ướp 240 g thịt bò thăn thái sợi với 25 ml nước tương, 6 g đường cát trắng, 10 ml rượu ngọt Mirin, 1/3 lượng tỏi khô băm nhuyễn, 1/2 lượng hành lá thái nhỏ và 8 ml dầu mè rang trong 15 phút. Ở chén nhỏ, trộn đều 75 g tương ớt Hàn Quốc (Gochujang), 10 ml nước tương, 10 g đường cát trắng, 6 ml dầu mè rang, 3 g hạt mè trắng rang và chút tỏi băm thành sốt trộn.', 'Nếu sốt Gochujang hơi đặc, có thể hòa thêm 1–2 muỗng canh nước ấm để dễ rưới và trộn đều cơm.', 15),
('imp-a24a701c584d3ef3_v4_step_2', 'imp-a24a701c584d3ef3', 2, 'prep', 'Chần giá đỗ, rau chân vịt và ướp dưa leo', 'Bóp nhẹ dưa leo thái sợi với 1,5 g muối ăn để 10 phút rồi vắt ráo cho giòn. Đun sôi 1,2 lít nước lọc, chần giá đỗ tươi 2 phút rồi vớt ra để ráo, trộn với 1,5 g muối ăn, 1/3 tỏi băm, 6 ml dầu mè rang và 4 g hạt mè trắng rang. Tiếp tục tận dụng nước sôi chần rau chân vịt 45 giây, xả nước lạnh, vắt kiệt và trộn với 1 g muối ăn, 5 ml dầu mè rang, chút tỏi băm và 4 g hạt mè trắng rang.', NULL, 5);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-a24a701c584d3ef3_v4_step_3', 'imp-a24a701c584d3ef3', 3, 'cook', 'Xào riêng cà rốt, bí ngòi và nấm đùi gà', 'Dùng chảo sạch trên lửa vừa, lần lượt cho mỗi lần 4 ml dầu thực vật để xào riêng từng loại rau khoảng 2 phút mỗi loại: cà rốt thái sợi nêm 1 g muối ăn; bí ngòi xanh nêm 1 g muối ăn cùng chút tỏi băm; nấm đùi gà tươi xào với 10 ml nước tương còn lại cho thơm đậm rồi trút riêng ra khay.', 'Xào riêng từng loại rau giúp giữ nguyên màu sắc tươi tắn, mùi vị đặc trưng và độ giòn của từng nguyên liệu.', 6),
('imp-a24a701c584d3ef3_v4_step_4', 'imp-a24a701c584d3ef3', 4, 'cook', 'Xào chín thịt bò thăn trên lửa lớn', 'Làm nóng chảo với 5 ml dầu thực vật trên lửa lớn, cho toàn bộ thịt bò thăn đã ướp vào đảo nhanh tay 3–4 phút cho đến khi thịt chín săn đều và hơi xém cạnh thơm phức rồi trút ra đĩa.', NULL, 4),
('imp-a24a701c584d3ef3_v4_step_5', 'imp-a24a701c584d3ef3', 5, 'cook', 'Chiên 4 trứng ốp la lòng đào', 'Đun nóng chảo chống dính với 8 ml dầu thực vật còn lại trên lửa vừa, đập 4 quả trứng gà tươi vào chiên khoảng 3 phút cho lòng trắng chín hoàn toàn còn lòng đỏ vẫn sánh mềm lòng đào.', NULL, 3),
('imp-a24a701c584d3ef3_v4_step_6', 'imp-a24a701c584d3ef3', 6, 'finish', 'Xếp tô cơm trộn Bibimbap và hoàn thiện', 'Xới 720 g cơm trắng dẻo nóng chia đều vào 4 tô lớn. Xếp các loại giá đỗ, rau chân vịt, cà rốt, bí ngòi, dưa leo, nấm đùi gà và thịt bò theo hình quạt quanh thành tô. Đặt trứng ốp la vào chính giữa, rưới 5 ml dầu mè rang còn lại, rắc nốt phần hạt mè trắng rang cùng hành lá rồi dọn kèm sốt Gochujang để trộn đều khi ăn.', 'Làm ấm tô đựng cơm trước khi xếp nguyên liệu giúp Bibimbap giữ nóng lâu và dậy mùi dầu mè hơn khi trộn.', NULL),
('imp-52b5963c6cecfb96_v4_step_1', 'imp-52b5963c6cecfb96', 1, 'prep', 'Thái mỏng thịt bò và chuẩn bị hành tây, cà rốt', 'Thái 480 g thịt bò thăn ngoại thành lát mỏng 2–3 mm ngang thớ. Bào nhuyễn một nửa củ hành tây lấy cả nước lẫn xác để ướp mềm thịt, nửa củ còn lại thái lát mỏng. Thái lát mỏng cà rốt và cắt khúc 4 cm hành lá tươi.', 'Nước hành tây bào chứa enzyme tự nhiên giúp sợi cơ thịt bò mềm ra mà không bị bở.', NULL),
('imp-52b5963c6cecfb96_v4_step_2', 'imp-52b5963c6cecfb96', 2, 'marinate', 'Ướp thịt bò Bulgogi với mật ong và xì dầu', 'Khuấy tan 50 ml nước tương, 24 g đường nâu, 15 ml mật ong nguyên chất, 15 ml rượu ngọt Mirin, 10 ml dầu mè rang, tỏi khô băm nhuyễn, gừng tươi băm nhuyễn, phần hành tây bào nhuyễn và 1 g tiêu đen xay. Cho thịt bò thái lát, hành tây thái lát và cà rốt vào trộn đều, bọc kín ướp 30 phút trong ngăn mát.', 'Nếu có thời gian, ướp thịt qua đêm trong tủ lạnh sẽ giúp từng lát bò thấm đẫm hương vị hơn.', 30),
('imp-52b5963c6cecfb96_v4_step_3', 'imp-52b5963c6cecfb96', 3, 'cook', 'Làm nóng chảo gang và nướng mẻ thịt đầu tiên', 'Làm nóng chảo gang hoặc chảo đáy dày trên lửa lớn với 8 ml dầu thực vật đến khi chảo thật nóng. Gắp một nửa lượng thịt bò cùng rau củ trải thành một lớp mỏng đều, áp chảo mỗi mặt khoảng 2 phút cho đến khi thịt chín và cháy xém nhẹ ở rìa.', NULL, 4),
('imp-52b5963c6cecfb96_v4_step_4', 'imp-52b5963c6cecfb96', 4, 'cook', 'Nướng nốt mẻ thịt bò Bulgogi thứ hai', 'Trút mẻ đầu ra đĩa, thêm 7 ml dầu thực vật còn lại vào chảo, dàn nốt phần thịt bò và rau củ còn lại nướng trên lửa lớn thêm 4 phút đến khi thịt chín đều, phần sốt ướp hơi keo lại bám bóng lên từng lát thịt.', 'Chia làm 2 mẻ nướng giúp nhiệt độ chảo không bị tụt, thịt nướng cháy cạnh thơm chứ không bị luộc trong nước.', 4),
('imp-52b5963c6cecfb96_v4_step_5', 'imp-52b5963c6cecfb96', 5, 'cook', 'Đảo nhanh hành lá trên chảo nóng', 'Cho lại mẻ thịt đầu vào chảo cùng hành lá tươi cắt khúc, đảo nhanh tay 30–45 giây trên lửa lớn cho hành vừa chín tái dậy mùi thơm và thịt nóng đều.', NULL, NULL),
('imp-52b5963c6cecfb96_v4_step_6', 'imp-52b5963c6cecfb96', 6, 'finish', 'Rưới dầu mè, rắc mè rang và thưởng thức', 'Tắt bếp, rưới 5 ml dầu mè rang còn lại lên mặt thịt, bày ra đĩa lớn và rắc 5 g hạt mè trắng rang lên trên; dọn nóng ăn kèm cơm trắng hoặc cuốn rau sống.', NULL, NULL),
('imp-51b6559bf09bc980_v4_step_1', 'imp-51b6559bf09bc980', 1, 'prep', 'Sơ chế bí đỏ, rau thơm và làm sạch tôm', 'Gọt sạch vỏ 0,625 quả bí đỏ, bỏ hết phần ruột và hạt, rửa sạch rồi thái miếng vuông cạnh 2–3 cm. Lột vỏ 300 g tôm tươi, bỏ đầu, rạch nhẹ lưng rút sạch chỉ đen, rửa qua nước lạnh rồi thấm ráo. Băm nhỏ 12,5 g tỏi khô, thái sợi mảnh 8 g gừng tươi, thái nhỏ hành lá và ngò rí.', 'Chọn miếng bí đỏ có vỏ sẫm màu và ruột vàng cam rực sẽ cho thành phẩm dẻo bùi và ngọt nước hơn.', NULL),
('imp-51b6559bf09bc980_v4_step_2', 'imp-51b6559bf09bc980', 2, 'marinate', 'Ướp tôm tươi cho săn chắc đậm đà', 'Cho thịt tôm đã làm sạch vào tô, ướp cùng 4 g hạt nêm, 3 g muối ăn và 1 g tiêu đen xay. Trộn đều rồi để nghỉ khoảng 12 phút cho thịt tôm săn nhẹ và thấm đều gia vị.', NULL, 12),
('imp-51b6559bf09bc980_v4_step_3', 'imp-51b6559bf09bc980', 3, 'cook', 'Phi thơm tỏi gừng và xào săn tôm tươi', 'Làm nóng nồi đáy dày với 15 ml dầu ăn trên lửa vừa, cho tỏi băm và gừng thái sợi vào phi thơm dậy mùi. Trút tôm đã ướp vào đảo nhanh tay 2 phút đến khi tôm vừa săn lại và chuyển màu hồng cam thì tắt nhẹ lửa, gắp tôm ra chén riêng.', 'Gắp tôm ra riêng sau khi xào săn để tránh tôm bị ninh chung 15 phút với bí đỏ sẽ mất độ giòn ngọt.', 2),
('imp-51b6559bf09bc980_v4_step_4', 'imp-51b6559bf09bc980', 4, 'cook', 'Ninh bí đỏ chín bở dẻo trên lửa nhỏ', 'Đổ 1,2 lít nước lọc vào nồi vừa xào tôm, bật lửa lớn đun sôi bùng và hớt sạch bọt nếu có. Thả toàn bộ bí đỏ cắt miếng vào, hạ xuống lửa nhỏ và ninh khoảng 15 phút đến khi dùng đũa xiên thử thấy bí chín mềm bở dẻo.', 'Hầm bí đỏ trên lửa nhỏ giúp miếng bí chín bở dẻo từ từ và tiết vị ngọt sánh tự nhiên mà không bị đục nước.', 15),
('imp-51b6559bf09bc980_v4_step_5', 'imp-51b6559bf09bc980', 5, 'cook', 'Cho tôm trở lại và nêm nếm vị ngọt thanh', 'Trút phần tôm đã xào vào nồi bí đỏ, nêm 3 g muối còn lại, 4 g hạt nêm, 5 g đường cát trắng và 10 ml nước mắm ngon. Khuấy nhẹ cho gia vị hòa tan rồi đun sôi lăn tăn thêm 2 phút cho tôm chín kỹ hoàn toàn và hòa quyện với nước bí.', NULL, 2),
('imp-51b6559bf09bc980_v4_step_6', 'imp-51b6559bf09bc980', 6, 'finish', 'Rắc hành ngò, tiêu xay và dùng nóng', 'Nếm lại cho vừa khẩu vị rồi tắt bếp, rắc hành lá, ngò rí thái nhỏ và 1 g tiêu đen xay còn lại lên mặt nồi. Múc canh ra tô dùng nóng với cơm trắng.', NULL, NULL),
('imp-81a203668e5e4c1a_v4_step_1', 'imp-81a203668e5e4c1a', 1, 'prep', 'Làm sạch nấm kim châm, cà chua và đánh trứng', 'Cắt bỏ phần gốc rễ của 200 g nấm kim châm, tách tơi từng cụm nhỏ rồi rửa sạch và ngâm nước pha 2 g muối ăn khoảng 5 phút cho hết mùi hăng, vớt ra rổ để thật ráo. Bổ múi cau 2 quả cà chua; băm nhỏ 20 g hành tím và 10 g tỏi khô; thái nhỏ hành lá. Đập 3 quả trứng gà vào tô cùng 3 ml nước mắm rồi đánh tan đều.', 'Chỉ ngâm rửa nấm kim châm khi sắp nấu và để thật ráo để nấm không bị nhũn hay mất vị ngọt tự nhiên.', 5),
('imp-81a203668e5e4c1a_v4_step_2', 'imp-81a203668e5e4c1a', 2, 'cook', 'Phi thơm hành tỏi và xào cà chua tạo màu nền', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa, cho hành tím băm và tỏi băm vào phi thơm vàng nhạt. Thả cà chua bổ múi cau vào đảo đều khoảng 3 phút cho cà chua mềm nhẹ và tiết màu đỏ tự nhiên.', NULL, 3),
('imp-81a203668e5e4c1a_v4_step_3', 'imp-81a203668e5e4c1a', 3, 'cook', 'Đun sôi nước dùng và nấu chín nấm kim châm', 'Đổ 1,1 lít nước lọc vào nồi cà chua, đun lửa lớn đến khi sôi bùng rồi thả toàn bộ nấm kim châm vào nấu trên lửa vừa đúng 3–4 phút cho nấm vừa chín tới, vẫn giữ được độ giòn sần sật và tiết vị ngọt vào nước canh.', 'Không nấu nấm kim châm quá 5 phút để sợi nấm không bị dai nhũn và giữ trọn vị ngọt thanh.', 4),
('imp-81a203668e5e4c1a_v4_step_4', 'imp-81a203668e5e4c1a', 4, 'cook', 'Rưới trứng gà tạo vân mịn bồng bềnh', 'Hạ xuống lửa nhỏ để nước canh chỉ sôi lăn tăn nhẹ, rồi rót từ từ chén trứng đã đánh tan theo vòng tròn quanh nồi, đồng thời dùng đũa khuấy nhẹ nhàng theo một chiều để trứng tạo thành các sợi vân vàng mỏng mịn và không bị vón cục.', 'Rót trứng chậm theo dòng mảnh khi lửa nhỏ và khuấy nhẹ một chiều sẽ tạo vân trứng tơi mềm như mây.', 2),
('imp-81a203668e5e4c1a_v4_step_5', 'imp-81a203668e5e4c1a', 5, 'cook', 'Nêm gia vị và nấu chín kỹ trứng gà', 'Nêm 3 g muối ăn còn lại, 6 g hạt nêm và 12 ml nước mắm còn lại vào nồi, khuấy nhẹ tay và giữ lửa nhỏ đun thêm 1–2 phút cho các dải trứng chín hoàn toàn mà vẫn mềm mịn.', NULL, 2),
('imp-81a203668e5e4c1a_v4_step_6', 'imp-81a203668e5e4c1a', 6, 'finish', 'Rắc hành lá, tiêu xay và dùng nóng', 'Nếm lại nước canh lần cuối cho vừa miệng rồi tắt bếp ngay để vân trứng giữ độ mềm béo. Múc canh ra tô lớn, rắc hành lá thái nhỏ và 1 g tiêu đen xay lên trên, thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-6c20dba60d77bdfd_v4_step_1', 'imp-6c20dba60d77bdfd', 1, 'prep', 'Chần sạch sườn non khử mùi hôi', 'Rửa sạch 500 g sườn non đã chặt khúc dài 3–4 cm. Đun sôi một nồi nước riêng pha 3 g muối ăn, thả sườn vào chần khoảng 3 phút trên lửa lớn cho ra hết bọt bẩn và tạp chất, sau đó vớt ra xả sạch lại dưới vòi nước lạnh, để ráo.', 'Chần sơ sườn với chút muối rồi rửa sạch lại là bí quyết giúp nước canh sau khi ninh trong veo và thơm ngọt.', 3),
('imp-6c20dba60d77bdfd_v4_step_2', 'imp-6c20dba60d77bdfd', 2, 'cook', 'Ninh sườn non cùng hành khô cho mềm ngọt', 'Cho sườn non đã chần vào nồi cùng 1,4 lít nước lọc và 20 g hành tím khô đập dập. Đun sôi trên lửa lớn, hớt sạch lớp bọt nổi trên mặt rồi hạ xuống lửa nhỏ liu riu, mở hé nắp và hầm trong 32–35 phút cho đến khi thịt sườn mềm róc xương và nước dùng ngọt đậm; dùng vá vớt bỏ xác hành tím khô.', 'Hầm sườn ở lửa nhỏ liu riu và không nêm mắm muối quá sớm giúp thịt sườn mềm tơi và nước hầm thật trong.', 35),
('imp-6c20dba60d77bdfd_v4_step_3', 'imp-6c20dba60d77bdfd', 3, 'prep', 'Sơ chế su su non, cà rốt và rau thơm', 'Trong lúc hầm sườn, gọt vỏ 3 quả su su non dưới vòi nước chảy nhẹ cho trôi sạch nhựa mủ không dính tay, bổ miếng cau vừa ăn rồi ngâm ngay vào chậu nước pha 2 g muối ăn khoảng 5 phút cho su su trắng giòn, sau đó vớt ra để ráo. Gọt vỏ 0,75 củ cà rốt thái miếng dày 1 cm; rửa sạch hành lá và ngò rí rồi thái nhỏ.', NULL, NULL),
('imp-6c20dba60d77bdfd_v4_step_4', 'imp-6c20dba60d77bdfd', 4, 'cook', 'Nấu chín cà rốt và su su non giòn ngọt', 'Vặn lửa vừa cho nồi nước hầm sườn sôi lại, thả cà rốt vào nấu trước 3 phút. Tiếp theo thả toàn bộ su su non vào nồi và nấu thêm 5 phút đến khi su su và cà rốt vừa chín tới, xiên nhẹ thấy mềm nhưng miếng su su vẫn giữ nguyên dáng và độ giòn ngọt.', 'Không nấu su su quá lâu kẻo rau bị nhũn nát và mất đi vị thanh mát tự nhiên.', 8),
('imp-6c20dba60d77bdfd_v4_step_5', 'imp-6c20dba60d77bdfd', 5, 'cook', 'Nêm gia vị và nước mắm sau cùng', 'Nêm 3 g muối ăn còn lại và 10 g hạt nêm vào nồi canh, khuấy nhẹ cho tan đều rồi nếm thử lại cho vừa miệng. Cuối cùng rưới 15 ml nước mắm ngon vào khuấy nhẹ một lượt cho dậy mùi thơm rồi tắt bếp.', NULL, NULL),
('imp-6c20dba60d77bdfd_v4_step_6', 'imp-6c20dba60d77bdfd', 6, 'finish', 'Rắc hành ngò, tiêu xay và dọn nóng', 'Thả hành lá và ngò rí thái nhỏ vào nồi canh đang nóng, múc ra tô lớn, rắc 2 g tiêu đen xay lên mặt và thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-734cc9acf8620c69_v4_step_1', 'imp-734cc9acf8620c69', 1, 'prep', 'Sơ chế đậu phụ non, cà chua và rau thơm', 'Nhẹ nhàng lấy 300 g đậu phụ non ra khỏi hộp, tráng qua nước lọc cho ráo rồi cắt khối vuông cạnh khoảng 2 cm. Rửa sạch 2 quả cà chua chín đỏ, bỏ cuống, cắt múi cau (giữ 1 quả thái miếng vừa ăn, 1 quả cắt hạt lựu nhỏ để xào nhanh tạo màu). Bóc vỏ và băm nhỏ 20 g hành tím; rửa sạch 1/2 bó hành lá và 10 g ngò rí rồi thái nhỏ.', 'Đậu phụ non rất mềm và dễ vỡ, nên đặt trên thớt phẳng dùng dao sắc cắt dứt khoát và giữ nguyên trên thớt hoặc đĩa đến khi cho vào nồi.', NULL),
('imp-734cc9acf8620c69_v4_step_2', 'imp-734cc9acf8620c69', 2, 'prep', 'Đánh tan trứng gà với chút tiêu', 'Đập 2 quả trứng gà ta vào bát sạch, thêm khoảng 0,5 g tiêu đen xay rồi dùng đũa đánh đều tay khoảng 30 giây cho lòng đỏ và lòng trắng hòa quyện hoàn toàn, không còn vón sợi đặc.', NULL, NULL),
('imp-734cc9acf8620c69_v4_step_3', 'imp-734cc9acf8620c69', 3, 'cook', 'Phi thơm hành tím và xào cà chua tạo màu', 'Đặt nồi lên bếp ở lửa vừa, cho 15 ml dầu ăn vào làm nóng rồi thả hành tím băm và phần đầu hành lá vào phi khoảng 1 phút đến khi dậy mùi thơm vàng nhẹ. Cho phần cà chua cắt hạt lựu cùng 3 g muối ăn vào xào đều tay 3 phút đến khi cà chua nhuyễn mềm, tiết nước sốt đỏ cam óng ả.', 'Thêm muối khi xào giúp cà chua nhanh ra nước và lên màu đỏ đẹp hơn mà không bị khô cháy.', 3),
('imp-734cc9acf8620c69_v4_step_4', 'imp-734cc9acf8620c69', 4, 'cook', 'Đun sôi nước dùng và nêm gia vị', 'Đổ 1200 ml nước lọc vào nồi cà chua xào, tăng lên lửa lớn đun sôi bùng khoảng 4 phút rồi dùng muỗng hớt sạch bọt nổi để nước canh trong. Cho phần cà chua bổ múi cau còn lại vào, nêm 5 g hạt nêm, 3 g đường cát trắng và 15 ml nước mắm ngon, khuấy nhẹ cho gia vị tan đều.', NULL, 4),
('imp-734cc9acf8620c69_v4_step_5', 'imp-734cc9acf8620c69', 5, 'cook', 'Thả đậu phụ non và rưới trứng tạo vân hoa', 'Hạ xuống lửa nhỏ để nước chỉ sôi lăn tăn, trượt nhẹ từng miếng đậu phụ non vào nồi nấu 3 phút cho đậu nóng đều và thấm vị. Giữ nước sôi nhẹ, khuấy nước canh theo một chiều tạo xoáy nhẹ rồi từ từ rót bát trứng gà đã đánh tan qua đầu đũa theo vòng tròn, đợi 1 phút cho sợi trứng chín nổi bồng bềnh thành vân hoa vàng.', 'Rót trứng từ từ theo dòng nhỏ trong khi nước đang sôi lăn tăn và khuấy nhẹ một chiều sẽ tạo sợi vân trứng tơ mịn, không bị vón cục hay đục nước.', 3),
('imp-734cc9acf8620c69_v4_step_6', 'imp-734cc9acf8620c69', 6, 'finish', 'Thêm hành ngò và hoàn thiện món canh', 'Kiểm tra trứng gà và đậu phụ đã chín nóng hoàn toàn thì tắt bếp ngay, rắc phần hành lá thái nhỏ và ngò rí vào nồi rồi lắc nhẹ nồi thay vì khuấy mạnh. Múc canh ra tô lớn, rắc thêm 1 g tiêu đen xay còn lại lên mặt để dậy hương thơm trước khi dọn cơm.', NULL, NULL),
('imp-095cff5e61d32fd9_v4_step_1', 'imp-095cff5e61d32fd9', 1, 'prep', 'Thái mỏng và ướp thịt bò thăn', 'Thấm thật khô 350 g thịt bò thăn, thái lát mỏng ngang thớ để khi nấu thịt mềm không bị dai. Cho thịt bò vào tô, ướp với một nửa lượng hành tím băm (12 g), 5 ml nước tương, 5 ml dầu hào, 2,5 g hạt nêm, 2 g muối ăn và 1 g tiêu đen xay, trộn đều rồi để nghỉ 15 phút cho thấm vị.', 'Có thể đặt miếng thịt bò vào ngăn đá khoảng 20–30 phút cho bề mặt hơi se cứng trước khi thái sẽ dễ cắt được lát mỏng đều đẹp.', 15),
('imp-095cff5e61d32fd9_v4_step_2', 'imp-095cff5e61d32fd9', 2, 'prep', 'Sơ chế cà chua và các loại rau thơm', 'Rửa sạch 4 quả cà chua chín đỏ, bỏ cuống, bổ múi cau (riêng 1 quả thái hạt lựu để xào tạo màu, 3 quả giữ nguyên múi). Rửa sạch 3/4 bó hành lá, 20 g rau răm và 10 g ngò gai; đầu hành băm nhỏ, lá hành cắt khúc 1,5 cm, rau răm và ngò gai thái rối.', NULL, NULL),
('imp-095cff5e61d32fd9_v4_step_3', 'imp-095cff5e61d32fd9', 3, 'cook', 'Phi thơm hành tím và xào cà chua ra màu', 'Làm nóng nồi trên lửa vừa với 15 ml dầu ăn, cho phần hành tím băm còn lại cùng đầu hành lá vào phi khoảng 1 phút cho vàng thơm. Trút phần cà chua thái hạt lựu vào xào đều 3 phút đến khi cà chua mềm nhuyễn, ra màu đỏ cam tự nhiên.', 'Không để hành tím cháy sậm vì sẽ làm nước canh bị ngả màu tối và có vị đắng nhẹ.', 3),
('imp-095cff5e61d32fd9_v4_step_4', 'imp-095cff5e61d32fd9', 4, 'cook', 'Nấu nước dùng cà chua chua ngọt', 'Đổ 1500 ml nước lọc vào nồi, bật lửa lớn đun sôi khoảng 5 phút rồi hớt sạch bọt nổi. Thả 3 quả cà chua bổ múi cau vào nấu thêm 2 phút trên lửa vừa, nêm 3 g muối ăn, 2,5 g hạt nêm còn lại và 4 g đường cát trắng sao cho nước dùng có vị chua dịu ngọt thanh hài hòa.', NULL, 5),
('imp-095cff5e61d32fd9_v4_step_5', 'imp-095cff5e61d32fd9', 5, 'cook', 'Trụng chín nhanh thịt bò trong nước sôi', 'Đẩy nhẹ lửa lên mức lớn cho nước canh sôi bùng, thả từng phần thịt bò đã ướp vào nồi và dùng đũa đảo tơi ngay để thịt không dính cục. Nấu nhanh khoảng 40–60 giây đến khi miếng thịt bò vừa chuyển màu chín đều, hết sắc đỏ sống nhưng vẫn mềm mọng thì tắt bếp lập tức.', 'Thịt bò thăn chín rất nhanh; nấu quá 2 phút thịt sẽ bị ra nước, co cứng và dai, làm mất độ ngọt tự nhiên.', NULL),
('imp-095cff5e61d32fd9_v4_step_6', 'imp-095cff5e61d32fd9', 6, 'finish', 'Hoàn thiện với rau răm, ngò gai và tiêu', 'Cho hành lá cắt khúc, rau răm và ngò gai vào nồi canh nóng, đảo nhẹ một lượt cho rau thơm vừa chín tái dậy mùi đặc trưng. Múc canh ra tô lớn, rắc 0,5 g tiêu đen xay còn lại lên trên và dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-a4822c0a1187e4d7_v4_step_1', 'imp-a4822c0a1187e4d7', 1, 'prep', 'Làm sạch, chần sơ và khía nhẹ sườn non', 'Rửa sạch 800 g sườn non với 4 g muối hạt, chặt khúc vừa ăn cỡ 4–5 cm rồi chần qua nồi nước sôi pha 4 g muối trong 3 phút để khử mùi hôi và làm sạch bọt bẩn. Vớt sườn ra rửa lại nước lạnh, thấm thật khô và khía nhẹ vài đường trên mặt thịt để nhanh thấm gia vị.', 'Chần sơ sườn giúp loại bỏ tạp chất và giữ phần thịt bên trong mềm ẩm hơn khi nướng ở nhiệt độ cao.', 3),
('imp-a4822c0a1187e4d7_v4_step_2', 'imp-a4822c0a1187e4d7', 2, 'marinate', 'Giã muối ớt và ướp sườn thấm vị', 'Giã nhuyễn 4 g muối hạt còn lại cùng 3 quả ớt hiểm, tỏi khô và hành tím băm nhỏ. Trộn hỗn hợp muối ớt này với 20 ml nước mắm, 15 g đường cát trắng, 2 g tiêu đen xay và 15 ml dầu ăn cho tan đều, xoa khắp từng khúc sườn, bọc kín ướp ít nhất 40 phút.', 'Ướp thêm 15 ml dầu ăn trực tiếp vào sườn giúp bề mặt thịt giữ ẩm, không bị khô cứng khi nướng.', 40),
('imp-a4822c0a1187e4d7_v4_step_3', 'imp-a4822c0a1187e4d7', 3, 'sauce', 'Pha nước chấm chanh ớt tiêu ăn kèm', 'Trong lúc chờ sườn ngấm, khuấy tan 20 g đường cát trắng với 30 ml nước lọc ấm và nước cốt của 1 quả chanh tươi (chừa lại một ít để vắt lên sườn nếu thích). Cho tiếp 15 ml nước mắm ngon, 1 quả ớt hiểm băm nhỏ và 1 g tiêu đen xay vào khuấy đều.', NULL, NULL),
('imp-a4822c0a1187e4d7_v4_step_4', 'imp-a4822c0a1187e4d7', 4, 'cook', 'Làm nóng lò và nướng sườn mặt thứ nhất', 'Làm nóng lò nướng hoặc nồi chiên không dầu ở 200°C trước 10 phút. Xếp sườn lên vỉ nướng có lót giấy bạc hứng mỡ bên dưới, phết nhẹ một lớp dầu ăn trong phần 10 ml dầu còn lại và nướng 15 phút.', NULL, 15),
('imp-a4822c0a1187e4d7_v4_step_5', 'imp-a4822c0a1187e4d7', 5, 'cook', 'Lật mặt, phết sốt và nướng vàng cháy cạnh', 'Mở lò lật mặt sườn, phết phần dầu ăn còn lại cùng lớp nước ướp sườn mỏng lên bề mặt rồi nướng tiếp 12–15 phút ở 200°C cho đến khi hai mặt sườn vàng ruộm, xém cạnh thơm lừng và phần thịt sát xương chín hoàn toàn không còn đỏ.', 'Canh kỹ 5 phút cuối và trở đều mặt giúp lớp gia vị muối ớt bám thơm mà không bị cháy đen đắng.', 15),
('imp-a4822c0a1187e4d7_v4_step_6', 'imp-a4822c0a1187e4d7', 6, 'finish', 'Để sườn nghỉ giữ ngọt và dọn thưởng thức', 'Lấy sườn nướng ra khỏi lò, để nghỉ 5 phút trên đĩa cho nước thịt ổn định lại bên trong trước khi xếp ra bàn. Dọn sườn nướng muối ớt dùng nóng kèm chén nước chấm chua cay vừa pha và cơm trắng.', NULL, NULL),
('imp-04514fa34052d242_v4_step_1', 'imp-04514fa34052d242', 1, 'prep', 'Ngâm nấm hương khô và sơ chế gà, nấm đùi gà', 'Ngâm 30 g nấm hương khô vào 100 ml nước lọc ấm trong 25 phút cho nở mềm, vớt ra cắt bỏ chân cứng rồi thái đôi và giữ lại phần nước ngâm sạch cặn. Chà xát 700 g đùi gà với 5 g muối hạt, rửa sạch để ráo rồi chặt miếng vừa ăn. Nấm đùi gà thái lát dày 0,8 cm; tỏi băm nhỏ, gừng thái lát; hành lá và cần tây cắt khúc 3 cm, ớt sừng thái lát.', 'Giữ lại phần nước ngâm nấm hương đã lắng cặn để chế vào nồi kho giúp món ăn thơm ngọt tự nhiên gấp bội.', 25),
('imp-04514fa34052d242_v4_step_2', 'imp-04514fa34052d242', 2, 'marinate', 'Ướp đùi gà với nước tương và nước mắm', 'Cho thịt gà vào tô, ướp cùng 15 ml nước tương, 5 ml xì dầu đặc và 10 ml nước mắm ngon. Trộn đều rồi ướp trong 25 phút cho miếng thịt ngấm gia vị và lên màu nhạt.', 'Khứa nhẹ vài đường trên mặt thịt đùi gà trước khi ướp giúp nước tương thấm sâu vào bên trong thớ thịt.', 25),
('imp-04514fa34052d242_v4_step_3', 'imp-04514fa34052d242', 3, 'cook', 'Áp chảo xém vàng hai mặt thịt gà', 'Làm nóng chảo đáy rộng với 15 ml dầu ăn trên lửa vừa lớn, xếp các miếng gà đã ướp vào áp chảo khoảng 4 phút mỗi mặt đến khi da gà vàng giòn và thịt săn lại rồi gắp ra đĩa riêng.', 'Áp chảo xém mặt giúp khóa chặt nước ngọt bên trong miếng gà và làm phần mỡ dưới da tiết bớt, món kho không bị ngấy.', 5),
('imp-04514fa34052d242_v4_step_4', 'imp-04514fa34052d242', 4, 'cook', 'Phi thơm gừng tỏi bằng dầu mè và đảo nấm', 'Chắt bớt dầu thừa trong chảo, cho 20 ml dầu mè vào đun nóng trên lửa vừa rồi phi thơm gừng thái lát và tỏi băm trong 1 phút. Thả nấm đùi gà và nấm hương đã ngâm vào đảo đều 3 phút cho nấm thấm dầu mè thơm bóng.', NULL, 4),
('imp-04514fa34052d242_v4_step_5', 'imp-04514fa34052d242', 5, 'cook', 'Kho nhỏ lửa cho gà và nấm thấm sốt sánh', 'Trút phần gà đã áp chảo trở lại chảo nấm, nêm 15 ml nước tương còn lại, 10 ml xì dầu đặc, 20 ml dầu hào, 12 g đường phèn và rưới phần nước ngâm nấm cùng 80 ml nước lọc vào xâm xấp. Đậy nắp kho lửa nhỏ trong 12 phút đến khi đường phèn tan hết, thịt gà chín kỹ và nước kho sánh đậm.', NULL, 12),
('imp-04514fa34052d242_v4_step_6', 'imp-04514fa34052d242', 6, 'finish', 'Thêm cần tây, hành lá và ớt hoàn thiện', 'Mở nắp, nêm lại vừa khẩu vị rồi thả cần tây, hành lá cắt khúc và ớt sừng thái lát vào đảo nhanh 30 giây trên lửa vừa đến khi rau vừa chín tái giữ màu xanh mướt. Tắt bếp và dọn nóng cùng cơm trắng.', NULL, NULL),
('imp-695f59248dbf4895_v4_step_1', 'imp-695f59248dbf4895', 1, 'prep', 'Làm sạch nhớt và ướp muối cho cá săn chắc', 'Đánh vảy, bỏ ruột và màng đen trong bụng 750 g cá lóc, chà xát đều với 4 g muối hạt rồi rửa sạch nước lạnh và thấm khô, cắt khoanh dày 2–2,5 cm. Xóc nhẹ cá với 3 g muối hạt còn lại và ướp trong 25 phút cho thớ thịt cá săn chắc.', 'Ướp trước với chút muối giúp thịt cá cứng cáp khi chiên và thấm vị mặn đậm đà từ bên trong.', 25),
('imp-695f59248dbf4895_v4_step_2', 'imp-695f59248dbf4895', 2, 'prep', 'Giã gừng, băm sả, hành tím và ớt', 'Giã nhuyễn 50 g gừng tươi trong cối để tinh dầu gừng tiết ra tối đa. Băm thật nhuyễn 3 cây sả cùng 1 quả ớt hiểm; hành tím băm nhỏ; 2 quả ớt còn lại cắt khoanh xéo và hành lá thái nhỏ.', NULL, NULL),
('imp-695f59248dbf4895_v4_step_3', 'imp-695f59248dbf4895', 3, 'cook', 'Chiên sơ hai mặt khứa cá lóc cho săn vàng', 'Làm nóng chảo với 25 ml dầu ăn trên lửa vừa, thả từng khoanh cá vào chiên sơ khoảng 2 phút mỗi mặt cho bề mặt cá se vàng nhẹ rồi gắp ra đĩa có lót giấy thấm dầu.', 'Chiên sơ giúp khóa lớp thịt cá bên ngoài để khi kho lâu với nước sôi miếng cá vẫn giữ nguyên khoanh đẹp mắt.', 4),
('imp-695f59248dbf4895_v4_step_4', 'imp-695f59248dbf4895', 4, 'cook', 'Phi thơm hành tím, gừng sả và ớt bột', 'Dùng nồi đất hoặc nồi đáy dày, đun nóng 15 ml dầu ăn còn lại và 15 g đường cát trắng trên lửa nhỏ đến khi đường chuyển màu nâu cánh gián. Cho hành tím băm, gừng giã nhuyễn, sả băm và 2 g ớt bột khô vào xào đều trong 3 phút cho dậy mùi thơm nồng.', NULL, 3),
('imp-695f59248dbf4895_v4_step_5', 'imp-695f59248dbf4895', 5, 'cook', 'Xếp cá vào nồi và kho liu riu với nước sôi', 'Xếp từng khoanh cá đã chiên sơ lên lớp sả gừng thơm, rưới 45 ml nước mắm ngon và 10 g đường cát trắng còn lại lên mặt cá rồi đậy kín nắp 2 phút cho thấm hương. Chế 250 ml nước lọc sôi vào xâm xấp mặt cá, đun sôi lại rồi hạ lửa nhỏ kho liu riu trong 22 phút, thỉnh thoảng nghiêng nhẹ nồi cho nước kho áo đều.', 'Luôn dùng nước đang sôi chế vào nồi cá kho để cá không bị tanh và nước kho giữ được độ nóng ổn định.', 22),
('imp-695f59248dbf4895_v4_step_6', 'imp-695f59248dbf4895', 6, 'finish', 'Thả ớt khoanh, nêm lại và rắc hành lá', 'Khi nước kho rút còn khoảng một nửa và hơi sánh sệt, thả ớt cắt khoanh vào kho mở nắp thêm 3 phút cho nước keo đẹp, nêm lại vừa ăn rồi tắt bếp. Múc cá kho gừng sả ra đĩa và rắc hành lá thái nhỏ lên trên.', NULL, NULL),
('imp-208386f834b8da43_v4_step_1', 'imp-208386f834b8da43', 1, 'prep', 'Luộc trứng với giấm muối và bóc vỏ', 'Cho 8 quả trứng gà vào nồi nước lạnh ngập mặt cùng 5 g muối ăn và 15 ml giấm gạo, bật lửa vừa đến khi nước sôi thì hạ lửa nhỏ luộc thêm 7 phút cho trứng chín hoàn toàn. Vớt trứng ngâm ngay vào tô nước lạnh 3 phút rồi bóc sạch vỏ và dùng tăm xăm nhẹ vài lỗ quanh lòng trắng.', 'Thêm chút muối và giấm vào nồi nước lạnh khi luộc giúp vỏ trứng không bị nứt và tách khỏi màng lụa cực kỳ dễ dàng.', 7),
('imp-208386f834b8da43_v4_step_2', 'imp-208386f834b8da43', 2, 'prep', 'Sơ chế hành tỏi, rau thơm và pha chén sốt kho', 'Thái lát mỏng hành tím, tỏi khô và ớt tươi; cắt khúc phần đầu hành lá, thái nhỏ lá hành và ngò rí. Trong chén riêng, khuấy tan 55 ml nước tương, 15 ml xì dầu đặc, 10 ml tương ớt, 12 g đường cát trắng, 1 g bột ngũ vị hương và 100 ml nước lọc.', NULL, NULL),
('imp-208386f834b8da43_v4_step_3', 'imp-208386f834b8da43', 3, 'cook', 'Chiên sơ trứng cho vàng săn lớp vỏ ngoài', 'Thấm thật khô bề mặt trứng đã bóc vỏ. Làm nóng chảo chống dính với 15 ml dầu ăn trên lửa vừa, thả trứng vào lăn nhẹ đều tay trong 3 phút cho lớp lòng trắng bên ngoài se vàng nhẹ rồi vớt ra đĩa.', 'Thấm khô trứng trước khi chiên và đảo nhẹ liên tục giúp trứng không bị bắn dầu và có lớp vỏ dai ngon khi kho.', 3),
('imp-208386f834b8da43_v4_step_4', 'imp-208386f834b8da43', 4, 'cook', 'Phi thơm đầu hành, hành tím, tỏi và ớt', 'Chắt bớt dầu nếu còn nhiều, thêm 10 ml dầu ăn vào chảo trên lửa vừa nhỏ, phi thơm đầu hành lá, hành tím, tỏi và ớt thái lát trong 1 phút cho đến khi vừa dậy mùi và ngả vàng nhẹ thì tạm nhấc khỏi bếp để không cháy.', NULL, NULL),
('imp-208386f834b8da43_v4_step_5', 'imp-208386f834b8da43', 5, 'cook', 'Kho liu riu cho trứng áo màu nâu bóng', 'Đổ chén hỗn hợp sốt nước tương đã pha vào chảo, đặt lại lên bếp đun sôi nhẹ rồi thả toàn bộ trứng gà vào. Kho liu riu ở lửa vừa nhỏ trong 8–10 phút, thỉnh thoảng nghiêng chảo hoặc múc sốt rưới đều lên trứng cho đến khi nước kho sánh keo bóng đẹp.', 'Kho lửa nhỏ và đảo nhẹ tay giúp màu nâu của xì dầu đặc áo đều quanh từng quả trứng mà không làm nát lòng trắng.', 9),
('imp-208386f834b8da43_v4_step_6', 'imp-208386f834b8da43', 6, 'finish', 'Rắc hành lá, ngò rí và tiêu đen thưởng thức', 'Khi nước sốt đã keo sánh và trứng lên màu nâu óng ả, tắt bếp, gắp trứng ra đĩa sâu lòng và rưới phần sốt keo còn lại lên trên. Rắc hành lá, ngò rí thái nhỏ và 1,5 g tiêu đen xay rồi dùng nóng với cơm trắng.', NULL, NULL),
('imp-d1f8ab89051a6336_v4_step_1', 'imp-d1f8ab89051a6336', 1, 'marinate', 'Sơ chế và ướp tôm tươi', 'Tôm tươi bóc vỏ, bỏ đầu, rạch lưng rút bỏ chỉ đen rồi rửa sạch và thấm ráo. Cho tôm vào tô ướp với 3 g hạt nêm trong 10 phút để tôm thấm vị đậm nhẹ.', NULL, 10),
('imp-d1f8ab89051a6336_v4_step_2', 'imp-d1f8ab89051a6336', 2, 'prep', 'Chần sơ bông cải xanh, cà rốt và ngâm nước lạnh', 'Tách bông cải xanh thành nhánh vừa ăn; cà rốt gọt vỏ thái lát mỏng; hành tây thái múi cau; tỏi khô băm nhỏ. Đun sôi nồi nước với 6 g muối ăn, thả cà rốt vào chần 40 giây rồi cho bông cải xanh vào chần chung thêm 1 phút, vớt ngay ra tô nước đá lạnh ngâm 3 phút rồi vớt ra để thật ráo. Hòa tan 4 g bột bắp với 30 ml nước lọc.', 'Ngâm nước đá ngay sau khi chần giúp bông cải xanh và cà rốt giữ sắc màu rực rỡ cùng độ giòn sần sật.', 3),
('imp-d1f8ab89051a6336_v4_step_3', 'imp-d1f8ab89051a6336', 3, 'cook', 'Xào săn tôm tươi trên lửa lớn', 'Đặt chảo lên bếp lửa lớn, đun nóng 15 ml dầu ăn rồi trút tôm đã ướp vào đảo nhanh tay 1,5 phút cho đến khi tôm săn lại, chuyển màu đỏ cam đều và chín hoàn toàn thì gắp ra đĩa riêng.', 'Đảo tôm trên lửa lớn thật nhanh giúp tôm xém nhẹ thơm ngon mà không bị ra nước hay khô thịt.', 2),
('imp-d1f8ab89051a6336_v4_step_4', 'imp-d1f8ab89051a6336', 4, 'cook', 'Xào bông cải xanh và cà rốt với tỏi hành tây', 'Dùng lại chảo, thêm 10 ml dầu ăn vào đun nóng ở lửa vừa rồi phi thơm tỏi băm và hành tây trong 30 giây. Tăng lên lửa lớn, cho bông cải xanh và cà rốt đã ráo nước vào đảo đều, nêm 5 g hạt nêm còn lại và 2 g muối ăn trong khoảng 2 phút.', NULL, NULL),
('imp-d1f8ab89051a6336_v4_step_5', 'imp-d1f8ab89051a6336', 5, 'cook', 'Rưới nước bột bắp và đảo đều cùng tôm', 'Trút tôm đã xào trở lại chảo rau củ. Khuấy đều chén nước bột bắp rồi rưới từ từ vào chảo, đảo đều tay khoảng 1 phút cho lớp sốt sánh bóng áo đều quanh tôm và bông cải, thêm 5 ml nước mắm ngon nếu thích đậm vị hơn.', 'Rưới từ từ nước bột bắp và đảo liên tục để sốt sánh mịn đều, không bị vón cục.', NULL),
('imp-d1f8ab89051a6336_v4_step_6', 'imp-d1f8ab89051a6336', 6, 'finish', 'Rưới dầu mè và rắc mè trắng rang hoàn thiện', 'Rưới 3 ml dầu mè thơm vào đảo nhanh một lượt rồi tắt bếp. Bày bông cải xào tôm tươi ra đĩa, rắc tiêu đen xay và mè trắng rang lên trên, dùng nóng với cơm trắng.', NULL, NULL),
('imp-03c5e6e31e01088d_v4_step_1', 'imp-03c5e6e31e01088d', 1, 'prep', 'Cắt đậu phụ và băm nhỏ sả, tỏi, ớt', 'Đậu phụ rửa nhẹ, dùng khăn giấy thấm thật khô bề mặt rồi cắt thành từng miếng vuông dày khoảng 1,5 cm. Sả tươi bóc bỏ vỏ già, đập dập rồi băm nhuyễn phần củ non; tỏi khô băm nhuyễn; ớt chia một quả băm nhỏ và một quả thái lát xéo.', 'Băm sả thật nhuyễn giúp sả dậy mùi thơm nồng nhanh chóng và dễ bám đều lên từng miếng đậu phụ.', NULL),
('imp-03c5e6e31e01088d_v4_step_2', 'imp-03c5e6e31e01088d', 2, 'sauce', 'Pha chén sốt nước tương dầu hào chay sả ớt', 'Cho vào chén 15 ml nước tương (xì dầu), 15 ml dầu hào chay nấm đông cô, 15 ml tương ớt, 5 g đường cát trắng và 30 ml nước lọc, khuấy thật đều cho đường tan hoàn toàn.', NULL, NULL),
('imp-03c5e6e31e01088d_v4_step_3', 'imp-03c5e6e31e01088d', 3, 'cook', 'Chiên vàng giòn các mặt đậu phụ', 'Đun nóng 70 ml dầu ăn trên lửa vừa, thả nhẹ từng miếng đậu phụ vào chiên khoảng 4–5 phút mỗi mặt đến khi vỏ đậu vàng đều, hơi giòn cạnh thì vớt ra đĩa có lót giấy thấm dầu.', 'Không lật trở đậu quá sớm khi mặt dưới chưa se vàng để giữ từng miếng đậu vuông vắn đẹp mắt.', 5),
('imp-03c5e6e31e01088d_v4_step_4', 'imp-03c5e6e31e01088d', 4, 'cook', 'Phi thơm sả băm, tỏi và ớt', 'Chắt bớt dầu thừa ra ngoài, chỉ giữ lại khoảng 15 ml dầu ăn trong chảo. Hạ lửa vừa, cho sả băm, tỏi băm và ớt băm vào đảo đều tay khoảng 2 phút đến khi sả chuyển màu vàng thơm lừng.', NULL, 2),
('imp-03c5e6e31e01088d_v4_step_5', 'imp-03c5e6e31e01088d', 5, 'cook', 'Đun sánh sốt và đảo quyện đậu phụ', 'Khuấy lại chén sốt rồi rót vào chảo sả ớt, đun sôi lăn tăn khoảng 1 phút cho sốt hơi sánh lại. Trút toàn bộ đậu phụ đã chiên vào chảo, hạ lửa nhỏ và đảo nhẹ tay khoảng 4 phút để sốt sả ớt áo bám đều quanh từng miếng đậu.', 'Rim đậu phụ trên lửa nhỏ giúp lớp vỏ đậu thấm sâu nước sốt mà vẫn giữ độ dai giòn nhẹ bên ngoài.', 4),
('imp-03c5e6e31e01088d_v4_step_6', 'imp-03c5e6e31e01088d', 6, 'finish', 'Hoàn thiện với ớt lát và tiêu đen xay', 'Nêm nếm lại cho vừa khẩu vị, thả vài lát ớt thái xéo và rắc 1,5 g tiêu đen xay vào đảo nhẹ rồi tắt bếp. Bày đậu phụ xào sả ớt ra đĩa, dùng nóng cùng cơm trắng.', NULL, NULL),
('imp-2862e7aa0ae0d8fe_v4_step_1', 'imp-2862e7aa0ae0d8fe', 1, 'marinate', 'Thái lát và ướp thịt bò đậm đà', 'Thấm thật khô thịt thăn bò rồi thái lát mỏng ngang thớ. Cho thịt vào tô ướp cùng một nửa lượng tỏi băm, 12 ml nước mắm ngon, 15 ml dầu hào, 10 g đường cát trắng, 5 g hạt nêm, 3 g muối ăn, 1 g tiêu đen xay và 5 ml dầu ăn; trộn đều và để ngấm 15 phút.', 'Không ướp chung thịt bò với dứa sống trước khi xào vì enzyme trong dứa sẽ làm thịt bò bị bở nát.', 15),
('imp-2862e7aa0ae0d8fe_v4_step_2', 'imp-2862e7aa0ae0d8fe', 2, 'prep', 'Sơ chế dứa chín, hành tây và hành lá', 'Dứa chín gọt sạch vỏ và mắt, bổ dọc bỏ phần lõi cứng ở giữa rồi thái lát dày khoảng 0,5 cm vừa ăn. Hành tây bóc vỏ bổ múi cau; hành lá rửa sạch cắt khúc 3 cm; phần tỏi còn lại băm nhỏ.', 'Bỏ sạch phần lõi cứng của quả dứa giúp món xào ngọt thơm mà không bị rát lưỡi khi ăn.', NULL),
('imp-2862e7aa0ae0d8fe_v4_step_3', 'imp-2862e7aa0ae0d8fe', 3, 'cook', 'Xào tái thịt bò trên lửa lớn', 'Làm nóng 15 ml dầu ăn trong chảo trên lửa lớn, cho một nửa phần tỏi băm còn lại vào phi thơm. Trút thịt bò đã ướp vào đảo nhanh tay liên tục khoảng 1,5–2 phút đến khi thịt vừa chín tái 80% thì trút ngay ra đĩa riêng.', NULL, 2),
('imp-2862e7aa0ae0d8fe_v4_step_4', 'imp-2862e7aa0ae0d8fe', 4, 'cook', 'Xào dứa chín và hành tây dậy mùi chua ngọt', 'Dùng lại chảo vừa xào bò, thêm 10 ml dầu ăn đun nóng rồi phi thơm nốt phần tỏi băm. Cho dứa và hành tây vào xào trên lửa lớn khoảng 2 phút, rưới thêm 8 ml nước mắm ngon còn lại để dứa tiết vị chua ngọt đậm đà và hành tây vừa chín trong.', 'Xào dứa trên lửa lớn giúp dứa se mặt thơm lừng mà không bị tiết quá nhiều nước.', 2),
('imp-2862e7aa0ae0d8fe_v4_step_5', 'imp-2862e7aa0ae0d8fe', 5, 'cook', 'Đảo chung thịt bò quyện sốt dứa', 'Trút đĩa thịt bò cùng nước thịt tiết ra trở lại chảo dứa hành tây, bật lửa lớn và đảo nhanh tay khoảng 1 phút cho thịt bò chín hoàn toàn và thấm đều sốt chua ngọt.', NULL, NULL),
('imp-2862e7aa0ae0d8fe_v4_step_6', 'imp-2862e7aa0ae0d8fe', 6, 'finish', 'Thêm hành lá và dọn đĩa ăn nóng', 'Thả hành lá cắt khúc vào đảo nhanh 15 giây rồi tắt bếp. Bày bò xào dứa chua ngọt ra đĩa, rắc 1 g tiêu đen xay còn lại lên trên và thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-aa94e2f8bdf3985f_v4_step_1', 'imp-aa94e2f8bdf3985f', 1, 'prep', 'Làm sạch tôm sú và sơ chế sả, gừng, lá chanh', 'Cắt gọn râu và chân tôm sú, dùng kéo nhọn rạch nhẹ dọc sống lưng rút sạch chỉ đen rồi rửa lại bằng nước sạch, để thật ráo. Bóc bẹ già 3 cây sả: đập dập cắt khúc 2 cây và thái lát mỏng 1 cây; gừng cạo vỏ thái lát mỏng; lá chanh rửa sạch giữ một nửa nguyên lá và thái chỉ phần còn lại; 1 quả ớt hiểm thái lát, 1 quả băm nhỏ.', 'Chọn tôm sú còn sống nhảy khỏe, vỏ bóng chắc và đầu dính chặt vào thân để món hấp giữ được độ giòn ngọt tự nhiên nhất.', NULL),
('imp-aa94e2f8bdf3985f_v4_step_2', 'imp-aa94e2f8bdf3985f', 2, 'marinate', 'Ướp tôm sú cho thịt săn và đậm vị', 'Cho tôm vào tô lớn cùng 4 g muối hạt, 4 g hạt nêm và 1 g tiêu đen xay, xóc nhẹ đều tay để gia vị bám quanh vỏ và khe lưng tôm rồi ướp 15 phút.', NULL, 15),
('imp-aa94e2f8bdf3985f_v4_step_3', 'imp-aa94e2f8bdf3985f', 3, 'cook', 'Xếp xửng và hấp tôm với rượu trắng trên lửa lớn', 'Đổ 500 ml nước lọc vào đáy nồi hấp. Lót sả đập dập, gừng thái lát và lá chanh nguyên xuống mặt xửng hoặc đĩa chịu nhiệt, xếp tôm đều lên trên rồi rắc nốt sả thái lát và lá chanh thái chỉ phủ mặt. Rưới đều 45 ml rượu trắng nấu ăn lên tôm, đậy kín nắp và hấp lửa lớn 7 phút đến khi vỏ tôm đỏ au, thân cong chắc là chín tới.', 'Rưới rượu trắng ngay trước khi đậy nắp hấp trên lửa lớn giúp hơi cồn bốc qua thân tôm, khử hoàn toàn mùi tanh mà thịt tôm vẫn giữ trọn độ ngọt.', 7),
('imp-aa94e2f8bdf3985f_v4_step_4', 'imp-aa94e2f8bdf3985f', 4, 'sauce', 'Phi tỏi vàng giòn thơm lừng', 'Trong lúc chờ tôm chín, làm nóng 15 ml dầu ăn trên chảo nhỏ ở lửa vừa, cho tỏi băm nhuyễn vào đảo đều tay khoảng 2 phút đến khi tỏi vừa chuyển màu vàng nhạt thơm nức thì tắt bếp ngay, giữ cả dầu lẫn tỏi phi sang chén nhỏ.', 'Tắt bếp ngay khi tỏi vừa ngả vàng sáng để lượng dầu nóng còn lại tự làm tỏi giòn đều mà không bị đắng khét.', 2),
('imp-aa94e2f8bdf3985f_v4_step_5', 'imp-aa94e2f8bdf3985f', 5, 'sauce', 'Pha muối tiêu chanh ớt chấm tôm', 'Cho 8 g muối hạt còn lại, 1 g tiêu đen xay và 1 quả ớt hiểm băm nhỏ vào chén sạch, vắt nước cốt 1 quả chanh tươi vào rồi dùng thìa dằm nhẹ cho muối tan bớt.', NULL, NULL),
('imp-aa94e2f8bdf3985f_v4_step_6', 'imp-aa94e2f8bdf3985f', 6, 'finish', 'Rưới tỏi phi và thưởng thức tôm hấp nóng', 'Gắp tôm hấp xếp đều ra đĩa lớn, rưới phần dầu tỏi phi vàng giòn lên dọc thân từng con tôm, điểm thêm vài lát ớt hiểm và cọng sả cho bắt mắt rồi ăn nóng ngay cùng chén muối tiêu chanh ớt.', NULL, NULL),
('imp-b55451e6e46a4c13_v4_step_1', 'imp-b55451e6e46a4c13', 1, 'prep', 'Ngâm mộc nhĩ và sơ chế cà rốt, tỏi, hành lá', 'Ngâm 15 g mộc nhĩ khô trong nước ấm khoảng 15 phút cho nở mềm, cắt bỏ chân cứng, rửa sạch rồi băm nhỏ. Gọt vỏ 1/2 củ cà rốt băm hạt lựu thật nhỏ; bóc vỏ tỏi băm nhuyễn. Rửa sạch hành lá, chọn riêng 10–12 cọng lá xanh dài để buộc cuộn, phần đầu và lá còn lại thái nhỏ.', NULL, 15),
('imp-b55451e6e46a4c13_v4_step_2', 'imp-b55451e6e46a4c13', 2, 'marinate', 'Trộn và ướp dẻo nhân thịt heo xay', 'Cho 300 g thịt heo xay vào tô lớn cùng mộc nhĩ băm, cà rốt băm nhỏ, tỏi băm và phần hành lá thái nhỏ. Nêm 15 ml nước mắm, 4 g hạt nêm và 1,5 g tiêu đen xay, trộn quết đều tay 2 phút cho hỗn hợp dẻo quyện rồi để ướp 15 phút.', 'Quết nhân thịt kỹ một chiều khoảng 2 phút giúp thịt kết dính dẻo dai, không bị rời rạc hay chảy nhiều nước khi hấp.', 15),
('imp-b55451e6e46a4c13_v4_step_3', 'imp-b55451e6e46a4c13', 3, 'prep', 'Chần mềm lá bắp cải và cọng hành buộc', 'Tách nhẹ 10–12 lá bắp cải nguyên vẹn, rửa sạch rồi dùng dao lạng mỏng bớt phần sống gân trắng cứng ở gốc lá. Đun sôi 800 ml nước lọc với 4 g muối ăn, thả từng lá bắp cải vào chần nhanh 1 phút cho vừa mềm dẻo rồi vớt ngay ra thau nước mát để giữ màu xanh; tiếp tục chần cọng hành lá khoảng 20 giây rồi vớt ra để ráo.', 'Lạng mỏng phần sống gân dày và nhúng ngay lá qua nước lạnh sau khi chần giúp lá bắp cải dẻo dai, dễ cuộn chặt mà không bị rách hay ngả màu.', 2),
('imp-b55451e6e46a4c13_v4_step_4', 'imp-b55451e6e46a4c13', 4, 'prep', 'Gói cuộn bắp cải nhân thịt chắc tay', 'Trải phẳng từng lá bắp cải lên thớt sạch, đặt khoảng 1 muỗng canh đầy nhân thịt vào phần đầu lá gần gốc. Gấp hai mép lá hai bên vào trong rồi cuộn tròn đều tay như cuốn nem, dùng một cọng hành lá đã chần buộc nhẹ quanh thân cuộn để cố định.', NULL, NULL),
('imp-b55451e6e46a4c13_v4_step_5', 'imp-b55451e6e46a4c13', 5, 'cook', 'Hấp cách thủy bắp cải cuộn thịt chín đều', 'Đổ 600 ml nước lọc vào đáy nồi hấp, đun sôi mạnh. Xếp các cuộn bắp cải ngay ngắn vào đĩa sâu lòng hoặc trực tiếp lên xửng hấp sao cho không chồng đè quá dày, đậy kín nắp và hấp trên lửa vừa khoảng 20 phút đến khi lá bắp cải chín mềm và nhân thịt bên trong chín hẳn, không còn màu hồng.', 'Xếp cuộn bắp cải với mép gấp úp xuống dưới giúp các cuộn giữ dáng tròn đẹp mà không bị bung khi gặp hơi nóng.', 20),
('imp-b55451e6e46a4c13_v4_step_6', 'imp-b55451e6e46a4c13', 6, 'finish', 'Trình bày và dọn ăn nóng với nước chấm', 'Gắp các cuộn bắp cải hấp ra đĩa lớn, rưới thêm vài muỗng nước ngọt thanh tiết ra trong đĩa hấp lên trên và rắc 0,5 g tiêu đen xay còn lại; dọn dùng nóng kèm cơm trắng và chén nước tương ớt hoặc nước mắm chanh tỏi ớt.', NULL, NULL),
('imp-500644420438efd3_v4_step_1', 'imp-500644420438efd3', 1, 'prep', 'Sơ chế đậu phụ trắng, sả, hành lá và ớt', 'Rửa nhẹ 3 bìa đậu phụ dưới vòi nước mát, để thật ráo rồi cắt thành từng miếng vuông dày khoảng 1,5 cm. Bóc vỏ già 3 cây sả: băm nhuyễn 2 cây, đập dập cắt khúc 4 cm với 1 cây còn lại. Rửa sạch hành lá thái nhỏ và thái lát mỏng 2 quả ớt tươi.', 'Chọn bìa đậu phụ mới làm có mùi thơm nhẹ, cầm mềm mại và đàn hồi để khi hấp đậu giữ được vị béo mịn tự nhiên.', NULL),
('imp-500644420438efd3_v4_step_2', 'imp-500644420438efd3', 2, 'marinate', 'Ướp đậu phụ với xì dầu, đường và hạt nêm chay', 'Xếp các miếng đậu phụ vào đĩa sâu lòng chịu nhiệt (lót sả đập dập bên dưới). Hòa tan 25 ml xì dầu, 6 g hạt nêm chay nấm hương và 3 g đường cát trắng rồi rưới đều lên mặt các miếng đậu, để nghỉ 10 phút cho gia vị thấm nhẹ vào thớ đậu.', NULL, 10),
('imp-500644420438efd3_v4_step_3', 'imp-500644420438efd3', 3, 'cook', 'Xào sả băm dậy mùi thơm vàng nhẹ', 'Làm nóng 15 ml dầu ăn trên chảo nhỏ ở lửa vừa, cho phần sả băm nhuyễn vào đảo đều tay khoảng 2 phút đến khi sả săn lại, ngả vàng nhẹ và dậy mùi thơm nồng thì tắt bếp.', 'Xào chín thơm sả băm trước khi hấp giúp tinh dầu sả tiết ra quyện vào nước xì dầu, khử bớt vị hăng sống của sả.', 2),
('imp-500644420438efd3_v4_step_4', 'imp-500644420438efd3', 4, 'cook', 'Hấp cách thủy đậu phụ thấm hương sả ớt', 'Rải đều phần sả băm đã xào thơm cùng ớt tươi thái lát lên mặt từng miếng đậu phụ. Đun sôi 500 ml nước lọc trong nồi hấp, đặt đĩa đậu vào xửng, đậy kín nắp và hấp ở lửa vừa trong 12 phút cho đậu nóng mềm và thấm đẫm hương sả.', 'Không hấp đậu phụ ở lửa quá lớn quá lâu vì hơi nước sôi mạnh dễ làm mặt đậu bị rỗ bọt khí.', 12),
('imp-500644420438efd3_v4_step_5', 'imp-500644420438efd3', 5, 'cook', 'Rắc hành lá giữ sắc xanh tươi', 'Mở nắp nồi hấp, rắc đều phần hành lá thái nhỏ lên trên mặt các miếng đậu phụ rồi đậy nắp hấp thêm khoảng 30 giây cho hành vừa chín tái xanh mướt, sau đó tắt bếp.', NULL, NULL),
('imp-500644420438efd3_v4_step_6', 'imp-500644420438efd3', 6, 'finish', 'Rưới dầu mè thơm và dọn dùng nóng', 'Nhấc đĩa đậu phụ ra khỏi xửng hấp cẩn thận, rưới đều 5 ml dầu mè thơm lên trên mặt đĩa cho dậy mùi và bóng đẹp, dọn ăn nóng ngay cùng cơm trắng.', NULL, NULL),
('imp-47cbfe72125b811d_v4_step_1', 'imp-47cbfe72125b811d', 1, 'marinate', 'Thái mỏng và ướp thấm thịt bò thăn', 'Thái thịt bò thăn thành lát thật mỏng ngang thớ. Cho thịt bò vào tô, ướp với 5 g hạt nêm, 1 g muối ăn, 2 g tiêu đen xay, 5 ml dầu ăn và một ít tỏi băm trong 20 phút cho thấm đều và mềm thịt.', 'Thái thịt bò ngang thớ khi thịt còn hơi se lạnh giúp lát bò mỏng đều và không bị dai khi xào.', 20),
('imp-47cbfe72125b811d_v4_step_2', 'imp-47cbfe72125b811d', 2, 'prep', 'Sơ chế dưa leo, cà rốt và ngâm giòn hành tây', 'Rửa sạch dưa leo, chà nhẹ hai đầu khử nhựa, bỏ ruột và thái lát xéo mỏng. Cà rốt gọt vỏ bào sợi, trộn 4 g đường cát trắng để 10 phút rồi vắt ráo. Hành tây thái lát mỏng, ngâm nước lạnh 10 phút rồi trộn 3 g muối ăn, 4 g đường cát trắng và 10 ml giấm gạo trong 10 phút nữa trước khi vắt ráo.', 'Bỏ ruột dưa leo và vắt ráo cà rốt, hành tây giúp đĩa gỏi khô ráo, giữ độ giòn lâu.', 10),
('imp-47cbfe72125b811d_v4_step_3', 'imp-47cbfe72125b811d', 3, 'prep', 'Rang giã đậu phộng và cắt nhỏ rau thơm', 'Rang chín vàng đậu phộng trên lửa nhỏ, xát sạch vỏ lụa và giã dập vừa. Nhặt rửa sạch ngò rí, rau húng bạc hà và hành lá rồi cắt nhỏ. Chuẩn bị phần tỏi băm còn lại và ớt hiểm thái lát, băm nhuyễn.', NULL, NULL),
('imp-47cbfe72125b811d_v4_step_4', 'imp-47cbfe72125b811d', 4, 'cook', 'Xào nhanh thịt bò trên lửa lớn', 'Đun nóng chảo trên lửa lớn với 20 ml dầu ăn, cho nửa phần tỏi băm vào phi thơm. Trút thịt bò đã ướp vào đảo thật nhanh tay khoảng 2 phút đến khi thịt bò vừa chín đều mềm mọng, không còn màu đỏ sống và không tiết nước thì trút ngay ra đĩa.', 'Xào bò ở lửa lớn trong thời gian ngắn giúp thịt chín mềm ngọt mà không bị ra nước hay dai cứng.', 2),
('imp-47cbfe72125b811d_v4_step_5', 'imp-47cbfe72125b811d', 5, 'sauce', 'Pha nước trộn gỏi mắm chanh chua ngọt', 'Khuấy tan 45 ml nước mắm ngon với 30 g đường cát trắng, nước cốt 2 quả chanh tươi và 5 ml giấm gạo còn lại, thêm phần tỏi băm và 1 quả ớt hiểm băm nhuyễn vào đảo đều đến khi sánh thơm.', NULL, NULL),
('imp-47cbfe72125b811d_v4_step_6', 'imp-47cbfe72125b811d', 6, 'finish', 'Trộn gỏi bò thấm vị và trình bày ra đĩa', 'Cho thịt bò xào, dưa leo, cà rốt và hành tây đã vắt ráo vào âu lớn, rưới đều nước trộn vào đảo nhẹ tay và để 5 phút cho ngấm vị. Tiếp tục trộn ngò rí, rau húng bạc hà, hành lá và một nửa lượng đậu phộng rang giã dập. Bày gỏi ra đĩa, rắc phần đậu phộng còn lại cùng vài lát ớt hiểm lên trên.', NULL, NULL),
('imp-403a1693ea9b3cf8_v4_step_1', 'imp-403a1693ea9b3cf8', 1, 'prep', 'Chần và hầm xương ống heo lấy nước dùng', 'Rửa sạch xương ống heo, chần qua 400 ml nước sôi với 4 g muối ăn trong 5 phút rồi xả sạch dưới vòi nước lạnh. Cho xương vào nồi với 1,9 lít nước lọc, đun sôi rồi hạ lửa nhỏ hầm khoảng 45 phút, thường xuyên hớt bọt rồi lọc bỏ xương giữ phần nước dùng trong.', NULL, 45),
('imp-403a1693ea9b3cf8_v4_step_2', 'imp-403a1693ea9b3cf8', 2, 'prep', 'Sơ chế tôm tươi, rau muống chẻ và lọc me', 'Tôm tươi bóc vỏ, giữ lại phần đầu tôm riêng và rút sạch chỉ đen thân tôm; ướp thân tôm với 2 g hạt nêm và 1 g tiêu đen xay trong 10 phút. Ngâm 40 g me chín với 100 ml nước ấm trong 5 phút rồi dằm lọc bỏ hạt lấy nước cốt. Chẻ sợi rau muống ngâm nước cho giòn; thái lát cà chua, dứa, đập dập sả cây và băm hành tím, tỏi khô.', 'Giữ lại đầu tôm để phi xào trước khi nấu giúp nước dùng có vị ngọt đậm và màu gạch tôm tự nhiên.', 10),
('imp-403a1693ea9b3cf8_v4_step_3', 'imp-403a1693ea9b3cf8', 3, 'cook', 'Phi hành giòn và xào đầu tôm cùng cà chua dứa', 'Đun nóng 30 ml dầu ăn trên chảo lửa vừa, phi vàng giòn 15 g hành tím thái lát rồi vớt ra giấy thấm dầu. Dùng phần dầu còn lại phi thơm 30 g hành tím băm và tỏi băm, cho đầu tôm vào đảo nhanh 2 phút cho dậy mùi gạch đỏ rồi gắp bỏ đầu tôm. Tiếp tục cho cà chua, dứa và sả đập dập vào xào 4 phút với 10 ml nước mắm và 10 g đường cát trắng.', 'Phi hành trước rồi tận dụng dầu thơm để xào đầu tôm và cà chua giúp nước dùng không bị ngấy dầu mà cực kỳ dậy mùi.', 6),
('imp-403a1693ea9b3cf8_v4_step_4', 'imp-403a1693ea9b3cf8', 4, 'cook', 'Nấu nước dùng chua cay và luộc chín tôm', 'Trút phần cà chua, dứa và sả đã xào vào nồi nước dùng xương, đổ nước cốt me vào đun sôi. Nêm 40 ml nước mắm ngon, 25 g đường cát trắng, 6 g muối ăn còn lại, 4 g hạt nêm, 20 ml sa tế ớt, 2 quả ớt đập dập và 10 ml dầu màu điều cho vị chua cay mặn ngọt hài hòa. Khi nước sôi bùng, thả thân tôm đã ướp vào nấu khoảng 3 phút đến khi tôm chuyển màu hồng cam uốn cong chín kỹ thì vớt ra ngay.', 'Vớt tôm ngay sau 3 phút nấu chín tới giúp thịt tôm giòn ngọt, không bị bở hoặc teo nhỏ.', 5),
('imp-403a1693ea9b3cf8_v4_step_5', 'imp-403a1693ea9b3cf8', 5, 'prep', 'Trụng bún tươi và xếp rau muống ra tô', 'Đun sôi một nồi nước khác, trụng nhanh bún gạo tươi khoảng 1 phút cho sợi bún nóng tơi rồi vớt ra để ráo. Chia đều bún vào 4 tô lớn, xếp phần rau muống chẻ giòn và tôm tươi đã nấu chín lên trên mặt bún.', NULL, NULL),
('imp-403a1693ea9b3cf8_v4_step_6', 'imp-403a1693ea9b3cf8', 6, 'finish', 'Chan nước dùng nóng và thưởng thức', 'Chan nước dùng bún tôm chua cay đang sôi sùng sục ngập mặt bún, rắc hành lá, ngò rí, hành phi và 1 g tiêu đen xay còn lại lên trên. Dọn nóng ngay kèm chanh tươi cắt múi và ớt tươi thái lát để điều chỉnh vị chua cay.', NULL, NULL),
('imp-c039dac37b31acdb_v4_step_1', 'imp-c039dac37b31acdb', 1, 'marinate', 'Sơ chế và ướp thịt gà ta với nghệ', 'Chà xát gà ta với 5 g muối ăn rồi rửa sạch, thấm khô. Lọc lấy phần thịt gà chặt miếng vừa ăn; giữ riêng xương, cổ và cánh gà để ninh nước dùng. Ướp thịt gà với 30 g hành tím giã nhỏ, 10 g tỏi khô băm, 1 quả ớt tươi băm, 5 g bột nghệ, 20 ml nước mắm ngon, 5 g muối ăn, 10 g đường cát trắng, 10 g hạt nêm và 2 g tiêu đen xay trong 20 phút cho ngấm sâu.', 'Tách riêng phần thịt và xương gà giúp thịt gà xào chín mềm ngọt mà vẫn có nồi nước dùng xương đậm đà.', 20),
('imp-c039dac37b31acdb_v4_step_2', 'imp-c039dac37b31acdb', 2, 'cook', 'Hầm xương gà lấy nước dùng trong', 'Cho phần xương, cổ và cánh gà vào nồi với 1,2 lít nước lọc, đun sôi trên lửa lớn, hớt sạch bọt rồi hạ lửa nhỏ ninh khoảng 35 phút cho ngọt nước; vớt bỏ xác xương để thu khoảng 900 ml nước dùng gà.', NULL, 35),
('imp-c039dac37b31acdb_v4_step_3', 'imp-c039dac37b31acdb', 3, 'cook', 'Phi thơm gia vị và nấu nước nhân gà ta', 'Đun nóng 25 ml dầu ăn trong nồi rộng ở lửa vừa, cho 3 g ớt bột màu vào đảo nhanh 10 giây rồi phi thơm 30 g hành tím băm còn lại và sả cây băm. Trút thịt gà đã ướp vào xào săn đều các mặt trong 4 phút, sau đó chế 900 ml nước dùng gà vào đun sôi và hạ lửa nhỏ rim 18 phút đến khi gà chín mềm thấm đẫm gia vị. Nêm thêm 15 ml nước mắm ngon và 15 ml dầu màu điều, thả đầu hành lá vào rồi tắt bếp.', 'Nước nhân Mì Quảng chuẩn vị cần đậm đà hơn nước phở bún thông thường vì khi chan chỉ ngập xâm xấp mặt mì.', 22),
('imp-c039dac37b31acdb_v4_step_4', 'imp-c039dac37b31acdb', 4, 'prep', 'Sơ chế rau sống, đậu phộng và pha nước chấm', 'Rửa sạch xà lách, giá đỗ, rau húng lủi; ngâm bắp chuối bào với nước có vắt ít nước cốt chanh tươi để giữ màu trắng giòn. Giã dập đậu phộng rang và thái nhỏ hành lá. Giã nhuyễn 5 g tỏi khô, 1 quả ớt tươi và 10 g đường cát trắng rồi khuấy đều với 15 ml nước mắm ngon và nước cốt 1/2 quả chanh thành chén nước mắm chấm.', NULL, NULL),
('imp-c039dac37b31acdb_v4_step_5', 'imp-c039dac37b31acdb', 5, 'prep', 'Trụng sợi mì Quảng tươi', 'Đun sôi một nồi nước khác, trụng sợi mì Quảng tươi khoảng 1 phút cho sợi mềm dẻo nóng đều rồi vớt ra rổ để thật ráo nước.', NULL, NULL),
('imp-c039dac37b31acdb_v4_step_6', 'imp-c039dac37b31acdb', 6, 'finish', 'Xếp tô Mì Quảng gà ta và thưởng thức', 'Lót hỗn hợp rau sống xà lách, giá đỗ, húng lủi và bắp chuối bào dưới đáy 4 tô, xếp sợi mì Quảng lên trên, gắp các miếng thịt gà ta vàng ươm và chan nước nhân nóng vừa xâm xấp mặt mì. Rắc hành lá, đậu phộng rang giã dập lên trên và dọn kèm bánh đa nướng bẻ miếng cùng chén nước mắm ớt chanh.', 'Chan nước nhân vừa xâm xấp đáy tô chứ không chan đầy ngập để giữ đúng tinh thần Mì Quảng đậm vị.', NULL),
('imp-875e99916a13d031_v4_step_1', 'imp-875e99916a13d031', 1, 'prep', 'Sơ chế rau củ và nướng hành tây, gừng', 'Gọt vỏ cà rốt và củ cải trắng rồi cắt khúc dày 3 cm. Bổ đôi hành tây, cắt lát dày gừng tươi rồi nướng trực tiếp trên chảo khô hoặc bếp đến khi mặt ngoài cháy xém thơm lừng, cạo sạch lớp cháy đen.', NULL, 8),
('imp-875e99916a13d031_v4_step_2', 'imp-875e99916a13d031', 2, 'cook', 'Ninh nước dùng rau củ và rang thảo mộc phở', 'Cho 2,8 lít nước lọc vào nồi cùng cà rốt, củ cải trắng, hành tây nướng và gừng nướng, đun sôi rồi hạ lửa nhỏ ninh 40 phút để rau củ tiết hết vị ngọt tự nhiên. Rang hoa hồi khô, quế thanh khô và thảo quả khô trên chảo khô ở lửa nhỏ 2–3 phút đến khi dậy hương thì cho vào túi lọc, thả vào nồi nước dùng ninh thêm 10 phút cuối rồi vớt bỏ toàn bộ xác rau củ và túi gia vị.', 'Chỉ thả túi hoa hồi, quế, thảo quả vào 10 phút cuối để nước phở dậy hương thơm dịu mà không bị nồng gắt hoặc sậm màu.', 50),
('imp-875e99916a13d031_v4_step_3', 'imp-875e99916a13d031', 3, 'cook', 'Chiên vàng đậu phụ và xào nấm đùi gà đậm đà', 'Thấm khô đậu phụ trắng rồi chiên áp chảo với 20 ml dầu ăn trên lửa vừa khoảng 6 phút cho vàng giòn các mặt, gắp ra giấy thấm dầu. Dùng chảo đó đun nóng 10 ml dầu ăn còn lại, phi thơm đầu hành lá băm rồi cho nấm đùi gà thái lát vào xào 3 phút trên lửa lớn. Trút đậu phụ chiên vào đảo cùng 15 ml xì dầu, 2 g muối ăn, 3 g hạt nêm chay nấm hương, 2 g bột ngũ vị hương và 1 g tiêu đen xay thêm 4 phút cho thấm vị.', 'Xào nấm đùi gà trên lửa lớn trước giúp nấm săn giòn, không bị ra nước trước khi đảo chung với đậu phụ.', 10),
('imp-875e99916a13d031_v4_step_4', 'imp-875e99916a13d031', 4, 'cook', 'Nêm nước dùng phở chay thanh ngọt', 'Nêm vào nồi nước dùng trong 10 g muối ăn còn lại, 20 g đường phèn và 7 g hạt nêm chay nấm hương, khuấy tan và đun sôi trở lại cho vị thanh ngọt hài hòa rồi giữ nóng trên bếp.', 'Dùng đường phèn kết hợp cùng hạt nêm chay nấm hương giúp vị ngọt nước dùng thanh nhẹ và sâu hậu hơn đường cát.', NULL),
('imp-875e99916a13d031_v4_step_5', 'imp-875e99916a13d031', 5, 'prep', 'Trụng bánh phở, giá đỗ và chuẩn bị rau thơm', 'Trụng nhanh bánh phở tươi qua nước sôi cho mềm tơi rồi vẩy thật ráo; trụng sơ giá đỗ qua nước sôi khoảng 30 giây. Thái nhỏ phần lá hành lá và ngò gai; rửa sạch húng quế và cắt múi chanh tươi.', NULL, NULL),
('imp-875e99916a13d031_v4_step_6', 'imp-875e99916a13d031', 6, 'finish', 'Xếp tô phở chay nấm đậu và thưởng thức', 'Chia bánh phở vào 4 tô, xếp giá đỗ trụng, nấm đùi gà và đậu phụ chiên xào lên trên, rắc hành lá và ngò gai. Chan ngập nước dùng chay đang sôi nóng vào tô và dọn ăn ngay kèm húng quế, chanh tươi cùng tương đen.', NULL, NULL);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-389f525ea854b373_v4_step_1', 'imp-389f525ea854b373', 1, 'prep', 'Lọc nước cốt me và sơ chế rau củ, đậu phụ', 'Ngâm 45 g me chín với 100 ml nước ấm trong 5 phút rồi dằm nhuyễn, lọc qua rây lấy phần nước cốt sánh bỏ hạt. Đậu phụ trắng cắt miếng vuông cạnh 2,5 cm; dứa gọt vỏ, bỏ mắt, thái lát xéo 0,5 cm; cà chua bổ múi cau; đậu bắp thái lát xéo; giá đỗ rửa ráo. Tước vỏ dọc mùng, thái lát xéo, bóp nhẹ với 2 g muối ăn rồi xả thật sạch, vắt ráo; hành boa-rô băm nhỏ; ngò gai và rau ngổ cắt khúc.', 'Bóp dọc mùng với chút muối rồi xả sạch nhiều lần giúp loại bỏ nhựa gây ngứa họng mà vẫn giữ độ giòn.', 5),
('imp-389f525ea854b373_v4_step_2', 'imp-389f525ea854b373', 2, 'cook', 'Phi thơm hành boa-rô và xào sơ cà chua, dứa', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa, phi thơm hành boa-rô băm khoảng 30 giây. Cho một nửa lượng cà chua và toàn bộ dứa thái lát vào xào đều 2 phút cho cà chua tiết màu đỏ cam tự nhiên và dứa dậy hương chua ngọt.', 'Xào sơ cà chua và dứa với chút dầu trước khi đổ nước giúp mặt canh có màu đỏ vàng bắt mắt mà không cần phẩm màu.', 2),
('imp-389f525ea854b373_v4_step_3', 'imp-389f525ea854b373', 3, 'cook', 'Đun nước dùng và nêm vị chua ngọt', 'Đổ 1300 ml nước lọc còn lại vào nồi, bật lửa lớn đun sôi bùng rồi hạ lửa vừa. Rót từ từ nước cốt me đã lọc vào nồi, nêm 20 g đường cát trắng, 4 g muối ăn và 8 g hạt nêm chay, khuấy đều đến khi gia vị tan và đạt độ chua mặn ngọt hài hòa.', NULL, 5),
('imp-389f525ea854b373_v4_step_4', 'imp-389f525ea854b373', 4, 'cook', 'Nấu chín đậu bắp và thả đậu phụ', 'Cho đậu bắp và phần cà chua múi cau còn lại vào nấu trên lửa vừa khoảng 3 phút cho đậu bắp chuyển màu xanh tươi. Hạ xuống lửa nhỏ rồi nhẹ nhàng thả đậu phụ trắng vào nấu thêm 3 phút để đậu nóng đều và thấm nước canh mà không bị nát.', 'Thả đậu phụ sau khi hạ nhỏ lửa và tránh khuấy mạnh tay để từng miếng đậu giữ nguyên vuông vức.', 6),
('imp-389f525ea854b373_v4_step_5', 'imp-389f525ea854b373', 5, 'cook', 'Chần chín tới dọc mùng và giá đỗ', 'Đưa dọc mùng đã vắt ráo vào nồi nấu sôi nhẹ khoảng 1 phút cho vừa chín giòn. Cuối cùng thả giá đỗ vào đảo thật nhẹ rồi tắt bếp ngay để giá không bị nhũn.', NULL, NULL),
('imp-389f525ea854b373_v4_step_6', 'imp-389f525ea854b373', 6, 'finish', 'Rắc rau thơm và dọn canh chua chay nóng', 'Múc canh chua chay dứa đậu phụ ra tô lớn, rắc đều ngò gai và rau ngổ thái khúc lên mặt để dậy hương thơm đặc trưng Nam Bộ. Dùng nóng cùng cơm trắng hoặc bún tươi.', NULL, NULL),
('imp-8301ed8c884fb619_v4_step_1', 'imp-8301ed8c884fb619', 1, 'prep', 'Sơ chế bắp cải, nấm đùi gà, lá hẹ và gia vị', 'Tách từng lá bắp cải, cắt bỏ lõi cứng rồi thái miếng vuông vừa ăn, rửa sạch và để ráo. Nấm đùi gà cắt bỏ gốc, rửa nhanh rồi thái lát chéo mỏng khoảng 0,5 cm. Hẹ lá rửa sạch cắt khúc 2–3 cm; tỏi khô băm nhuyễn; ớt hiểm thái lát mỏng.', 'Thái nấm đùi gà thành lát chéo mỏng giúp nấm nhanh chín đều, thấm gia vị và giữ được độ giòn sần sật.', NULL),
('imp-8301ed8c884fb619_v4_step_2', 'imp-8301ed8c884fb619', 2, 'cook', 'Chần sơ bắp cải trong nước sôi muối', 'Đun sôi nồi nước vừa đủ ngập rau cùng 3 g muối ăn, thả bắp cải vào chần nhanh trong 2 phút rồi vớt ngay ra rổ để thật ráo nước.', 'Chần sơ bắp cải giúp lá cải giữ được độ giòn ngọt, màu sắc tươi sáng và không bị ra nhiều nước khi xào.', 2),
('imp-8301ed8c884fb619_v4_step_3', 'imp-8301ed8c884fb619', 3, 'cook', 'Phi thơm tỏi và xào săn nấm đùi gà', 'Làm nóng chảo với 25 ml dầu ăn trên lửa vừa, thả tỏi băm vào phi khoảng 20 giây đến khi thơm nhẹ. Trút nấm đùi gà vào xào trên lửa lớn khoảng 3 phút cho đến khi lát nấm săn lại, rưới 15 ml rượu gạo nấu ăn dọc thành chảo để dậy hương.', NULL, 3),
('imp-8301ed8c884fb619_v4_step_4', 'imp-8301ed8c884fb619', 4, 'cook', 'Xào nhanh bắp cải trên lửa lớn', 'Cho bắp cải đã ráo nước vào chảo nấm, duy trì lửa lớn và đảo nhanh tay đều liên tục trong 3 phút để bắp cải nóng đều, quyện mùi thơm mà vẫn giữ trọn độ giòn ngọt.', 'Xào nhanh tay trên lửa lớn là bí quyết giúp bắp cải chín tới giòn ngon thay vì bị mềm nhũn.', 3),
('imp-8301ed8c884fb619_v4_step_5', 'imp-8301ed8c884fb619', 5, 'cook', 'Nêm gia vị xì dầu, hạt nêm chay và đảo hẹ', 'Nêm vào chảo 20 ml nước tương, 3 g muối ăn còn lại, 5 g hạt nêm chay và 5 g đường cát trắng, đảo đều 1 phút cho gia vị thấm phủ khắp rau nấm. Thả hẹ lá cắt khúc và ớt hiểm thái lát vào đảo thêm 30 giây rồi tắt bếp ngay.', NULL, NULL),
('imp-8301ed8c884fb619_v4_step_6', 'imp-8301ed8c884fb619', 6, 'finish', 'Hoàn thiện đĩa bắp cải xào nấm nóng', 'Rắc 1,5 g tiêu đen xay vào đảo nhẹ thêm một lượt rồi trút ra đĩa lớn, dùng nóng ngay với cơm trắng hoặc chấm thêm chút nước tương ớt.', NULL, NULL),
('imp-327ffa644fbe1a7d_v4_step_1', 'imp-327ffa644fbe1a7d', 1, 'prep', 'Rang thơm gạo tẻ và gạo nếp', 'Vo sạch 150 g gạo tẻ và 25 g gạo nếp qua 2 nước, chắt thật ráo. Làm nóng nồi đáy dày không dầu trên lửa nhỏ, cho hỗn hợp gạo vào rang đều tay khoảng 6 phút đến khi hạt gạo khô ráo, chuyển màu trắng đục và thoảng mùi thơm nhẹ.', 'Rang gạo trước khi nấu giúp hạt gạo săn nở đều, tạo độ sánh tự nhiên mà không bị vữa nước.', 6),
('imp-327ffa644fbe1a7d_v4_step_2', 'imp-327ffa644fbe1a7d', 2, 'cook', 'Ninh cháo nở bung sánh mịn', 'Đổ 1,5 lít nước lọc sôi vào nồi gạo vừa rang, khuấy đều đáy nồi rồi đậy hé nắp. Đun sôi bùng sau đó hạ lửa nhỏ ninh khoảng 22 phút, thỉnh thoảng khuấy sát đáy nồi để cháo sánh mịn không bị bén khét.', NULL, 22),
('imp-327ffa644fbe1a7d_v4_step_3', 'imp-327ffa644fbe1a7d', 3, 'marinate', 'Sơ chế, ướp tôm tươi và thái nấm đùi gà', 'Trong lúc ninh cháo, bóc vỏ 220 g tôm tươi, rút sạch chỉ lưng rồi cắt miếng nhỏ vừa ăn; ướp tôm với một nửa lượng hành tím băm, 5 ml nước mắm ngon và một nửa lượng tiêu đen xay trong 10 phút. Nấm đùi gà làm sạch, thái hạt lựu vừa; gừng tươi thái sợi chỉ; hành lá và ngò rí thái nhỏ.', 'Thái tôm và nấm đùi gà kích thước nhỏ tương đương nhau giúp từng muỗng cháo đều có đủ cả tôm ngọt và nấm giòn.', NULL),
('imp-327ffa644fbe1a7d_v4_step_4', 'imp-327ffa644fbe1a7d', 4, 'cook', 'Phi thơm hành tím và xào chín tôm nấm', 'Làm nóng 15 ml dầu ăn trong chảo trên lửa vừa, phi thơm phần hành tím băm còn lại. Cho tôm vào xào nhanh 2 phút đến khi tôm chuyển màu đỏ hồng săn chắc thì trút nấm đùi gà cùng 2 g hạt nêm vào đảo chung thêm 2 phút trên lửa lớn cho nấm chín ngọt mà không ra nhiều nước.', 'Xào nấm trên lửa lớn trong thời gian ngắn giúp nấm đùi gà giữ độ giòn sần sật và không tiết nhiều nước loãng.', 4),
('imp-327ffa644fbe1a7d_v4_step_5', 'imp-327ffa644fbe1a7d', 5, 'cook', 'Nêm gia vị và hòa quyện tôm nấm vào nồi cháo', 'Nêm 10 ml nước mắm ngon còn lại, 3 g hạt nêm và 3 g muối ăn vào nồi cháo đã nhừ, khuấy đều. Trút khoảng 2/3 phần tôm nấm xào và một nửa lượng gừng thái chỉ vào nồi cháo, đun sôi lăn tăn thêm 2 phút cho vị ngọt tiết ra quyện đều rồi tắt bếp.', NULL, NULL),
('imp-327ffa644fbe1a7d_v4_step_6', 'imp-327ffa644fbe1a7d', 6, 'finish', 'Múc cháo ra tô và trang trí nóng', 'Múc cháo tôm nấm nóng hổi ra 4 tô, xếp phần tôm nấm xào còn lại lên mặt cùng hành lá, ngò rí, phần gừng tươi thái chỉ còn lại và tiêu đen xay. Thưởng thức ngay khi còn nóng.', NULL, NULL),
('imp-9aed26098f07c061_v4_step_1', 'imp-9aed26098f07c061', 1, 'marinate', 'Sơ chế hành lá, hành tím và ướp thịt heo xay', 'Băm nhuyễn 20 g hành tím khô; rửa sạch hành lá rồi thái thật nhỏ. Cho 200 g thịt heo nạc vai xay vào tô, ướp với một nửa lượng hành tím băm, 5 ml nước mắm ngon, 2 g hạt nêm và 1 g tiêu đen xay, trộn đều và để nghỉ 10 phút cho thịt ngấm vị.', NULL, 10),
('imp-9aed26098f07c061_v4_step_2', 'imp-9aed26098f07c061', 2, 'cook', 'Xào chín tơi thịt heo xay với hành tím', 'Làm nóng 10 ml dầu ăn trong chảo chống dính trên lửa vừa, cho phần hành tím băm còn lại vào phi thơm. Trút toàn bộ thịt heo xay đã ướp vào đảo tơi đều tay khoảng 4 phút đến khi thịt săn chín hoàn toàn và tơi rời không vón cục, tắt bếp để nguội bớt rồi chắt bỏ nước mỡ thừa nếu có.', 'Xào chín thịt băm trước khi trộn với trứng giúp nhân thịt chín kỹ 100%, thơm hơn và không bị ra nước làm nhão khối trứng khi chiên.', 4),
('imp-9aed26098f07c061_v4_step_3', 'imp-9aed26098f07c061', 3, 'prep', 'Đánh tan trứng gà và trộn đều nhân thịt hành lá', 'Đập 6 quả trứng gà vào tô lớn, thêm 10 ml nước mắm ngon còn lại, 2 g hạt nêm, 2 g muối ăn và 0,5 g tiêu đen xay, dùng phới hoặc đũa đánh tan nhẹ nhàng cho hòa quyện. Trút phần thịt xay đã nguội bớt và toàn bộ hành lá thái nhỏ vào tô trứng, khuấy đều.', 'Để thịt xào nguội bớt trước khi cho vào tô trứng để tránh làm trứng bị chín lợn cợn ngay trong tô.', NULL),
('imp-9aed26098f07c061_v4_step_4', 'imp-9aed26098f07c061', 4, 'cook', 'Chiên đúc mặt dưới ở lửa nhỏ có nắp đậy', 'Bắc chảo chống dính đáy dày (đường kính khoảng 20–22 cm) lên bếp với 15 ml dầu ăn còn lại, láng đều mặt chảo trên lửa vừa rồi hạ xuống lửa nhỏ nhất. Đổ toàn bộ hỗn hợp trứng thịt vào chảo, dàn đều nhân thịt, đậy kín nắp và chiên liu riu khoảng 6 phút cho mặt dưới vàng thơm và phần mặt trên gần đông đặc.', 'Giữ lửa thật nhỏ và đậy kín nắp giúp khối trứng dày chín đều từ dưới lên trên mà mặt đáy không bị cháy sém.', 6),
('imp-9aed26098f07c061_v4_step_5', 'imp-9aed26098f07c061', 5, 'cook', 'Úp lật và chiên vàng mặt còn lại', 'Khi mặt trên trứng đã se đặc, đặt một chiếc đĩa phẳng to hơn miệng chảo lên trên, dứt khoát lật ngược chảo để trút miếng trứng ra đĩa rồi nhẹ nhàng trượt mặt còn lại xuống chảo. Chiên tiếp không đậy nắp trên lửa nhỏ thêm 3 phút cho mặt kia vàng đều và chín chắc hoàn toàn.', NULL, 3),
('imp-9aed26098f07c061_v4_step_6', 'imp-9aed26098f07c061', 6, 'finish', 'Cắt miếng vừa ăn và thưởng thức nóng', 'Trút miếng trứng đúc thịt ra thớt hoặc đĩa lớn, rắc nốt 0,5 g tiêu đen xay còn lại lên mặt rồi dùng dao sắc cắt thành 8 miếng tam giác hoặc miếng vuông gọn đẹp. Dọn ăn ngay khi còn nóng.', NULL, NULL),
('imp-24e75cbb2ba569f4_v4_step_1', 'imp-24e75cbb2ba569f4', 1, 'prep', 'Cắt sợi bánh tráng và bào mỏng bắp cải, cà rốt', 'Dùng kéo cắt 100 g bánh tráng gạo thành những sợi dài rộng khoảng 1–1,5 cm rồi tách nhẹ cho rời nhau. Bào sợi thật mỏng 160 g bắp cải trắng và 110 g cà rốt đã rửa sạch để thật ráo nước. Rau răm thái rối, ớt hiểm thái lát mỏng và giã dập 35 g đậu phộng rang.', 'Rau củ và rau răm phải vẩy thật ráo nước trước khi trộn để bánh tráng không bị ướt nhũn nhanh.', NULL),
('imp-24e75cbb2ba569f4_v4_step_2', 'imp-24e75cbb2ba569f4', 2, 'cook', 'Làm mỡ hành thơm béo chống dính bánh tráng', 'Cho hành lá thái nhuyễn cùng 1 g muối ăn vào chén chịu nhiệt. Đun nóng 15 ml dầu ăn trong chảo nhỏ khoảng 1 phút đến khi thấy hơi gợn sóng nóng thì đổ trực tiếp vào chén hành, trộn đều cho hành chín xanh thơm dậy mùi.', 'Thêm một chút mỡ hành vào bánh tráng giúp các sợi bánh tách rời nhau, mềm bóng mà không bị vón cục.', 1),
('imp-24e75cbb2ba569f4_v4_step_3', 'imp-24e75cbb2ba569f4', 3, 'sauce', 'Pha nước sốt xì dầu chanh chua ngọt', 'Vắt 1,5 quả chanh tươi lấy nước cốt bỏ hạt. Cho 10 ml xì dầu, 10 g đường cát trắng, 1 g muối ăn còn lại, 15 ml nước lọc và một nửa lượng nước cốt chanh vào chén, khuấy đều tay đến khi đường tan hoàn toàn.', NULL, NULL),
('imp-24e75cbb2ba569f4_v4_step_4', 'imp-24e75cbb2ba569f4', 4, 'cook', 'Áo mỡ hành cho bánh tráng trước khi trộn rau', 'Cho toàn bộ bánh tráng cắt sợi vào thau lớn, rưới đều chén mỡ hành vào và dùng tay sạch (đeo găng) xóc nhẹ 1 phút cho từng sợi bánh tráng áo lớp dầu hành mỏng thơm đều.', NULL, 1),
('imp-24e75cbb2ba569f4_v4_step_5', 'imp-24e75cbb2ba569f4', 5, 'cook', 'Trộn đều bánh tráng với rau củ và nước sốt', 'Cho bắp cải, cà rốt bào sợi, rau răm thái rối, ớt hiểm thái lát và một nửa lượng đậu phộng rang vào thau bánh tráng. Rưới đều nước sốt xì dầu đã pha và phần nước cốt chanh còn lại lên trên, trộn nhẹ tay đều từ dưới lên trong 1 phút cho nguyên liệu thấm đều vị chua cay mặn ngọt.', 'Không bóp quá mạnh tay khi trộn để sợi bánh tráng giữ độ dai dẻo và bắp cải vẫn giòn ngon.', NULL),
('imp-24e75cbb2ba569f4_v4_step_6', 'imp-24e75cbb2ba569f4', 6, 'finish', 'Bày đĩa, rắc đậu phộng rang và thưởng thức ngay', 'Chia bánh tráng trộn rau củ ra đĩa, rắc nốt phần đậu phộng rang giã dập lên mặt và thưởng thức ngay lúc bánh tráng còn dai giòn.', NULL, NULL),
('imp-0bd4954058454e92_v4_step_1', 'imp-0bd4954058454e92', 1, 'prep', 'Làm sạch khử mùi và ướp thịt đùi gà', 'Chà xát 800 g đùi gà ta với 3 g muối hạt và 10 g gừng tươi đập dập trong 2 phút để hết mùi hôi, rửa sạch để ráo rồi chặt miếng 3,5 cm. Ướp thịt gà với 10 ml nước mắm ngon, 4 g hạt nêm, 1 g tiêu đen xay, một nửa tỏi băm và đầu hành lá băm trong 15 phút.', NULL, 15),
('imp-0bd4954058454e92_v4_step_2', 'imp-0bd4954058454e92', 2, 'prep', 'Sơ chế nấm hương, nấm đùi gà và rau nhúng', 'Gọt sạch gốc 150 g nấm hương tươi và 200 g nấm đùi gà tươi, rửa sạch nhẹ tay để ráo; khía chữ thập trên mũ nấm hương và thái lát xéo nấm đùi gà. Rửa sạch bắp cải trắng cắt miếng 4 cm, rau muống cắt khúc; bổ múi cau 1 quả cà chua; thái sợi 15 g gừng tươi còn lại, đập dập 2 cây sả và băm nhỏ hành tím.', 'Khía nhẹ chữ thập lên mũ nấm hương tươi không chỉ giúp tô lẩu đẹp mắt hơn mà còn giúp nấm nhanh thấm vị ngọt của nước dùng.', NULL),
('imp-0bd4954058454e92_v4_step_3', 'imp-0bd4954058454e92', 3, 'cook', 'Phi thơm gừng hành tỏi và xào săn đùi gà', 'Làm nóng nồi đáy dày trên lửa vừa với 15 ml dầu ăn, cho hành tím băm, tỏi băm còn lại, gừng thái sợi và sả đập dập vào phi thơm 1 phút. Trút thịt gà đã ướp vào đảo săn khoảng 4 phút đến khi da gà căng bóng và thịt hơi ngả màu vàng nhẹ.', NULL, 5),
('imp-0bd4954058454e92_v4_step_4', 'imp-0bd4954058454e92', 4, 'cook', 'Ninh gà cùng nấm hương tươi và cà chua', 'Đổ 2000 ml nước lọc vào nồi, bật lửa lớn đun sôi bùng rồi hớt thật sạch lớp bọt nổi. Hạ lửa vừa nhỏ, thả nấm hương tươi, cà chua bổ múi cau và 1 quả ớt đập dập vào ninh thêm 18 phút đến khi thịt gà chín mềm hoàn toàn không còn sắc đỏ bên trong xương và nước lẩu vàng óng ngọt thơm.', 'Hớt bọt kỹ ngay khi nước mới sôi bùng và ninh lửa vừa nhỏ sẽ giữ nước lẩu gà trong veo, thơm dịu mùi gừng sả.', 18),
('imp-0bd4954058454e92_v4_step_5', 'imp-0bd4954058454e92', 5, 'cook', 'Nêm gia vị thanh đậm hài hòa', 'Nêm 15 ml nước mắm ngon, 4 g hạt nêm, 3 g muối hạt còn lại và 8 g đường cát trắng vào nồi lẩu, khuấy nhẹ và đun thêm 2 phút cho gia vị thấm đều vào từng miếng gà và nấm hương.', 'Vào ngày thời tiết se lạnh, bạn có thể tăng nhẹ lượng gừng thái sợi hoặc tiêu xay để tăng cảm giác ấm bụng khi thưởng thức.', NULL),
('imp-0bd4954058454e92_v4_step_6', 'imp-0bd4954058454e92', 6, 'finish', 'Dọn nồi lẩu ra bàn và nhúng nấm, rau dùng với bún', 'Chuyển nồi lẩu ra bếp giữa bàn giữ sôi lăn tăn, thả nấm đùi gà và hành lá cắt khúc vào nấu 3 phút cho nấm chín giòn ngọt rồi rắc 0,5 g tiêu đen xay lên mặt. Lần lượt nhúng bắp cải và rau muống ăn nóng kèm bún tươi cùng 1 quả ớt thái lát chấm nước mắm.', NULL, NULL),
('imp-7fa36d5f0187a86e_v4_step_1', 'imp-7fa36d5f0187a86e', 1, 'prep', 'Thái hạt lự thịt ba chỉ và làm tơi cơm nguội', 'Thấm thật khô 200 g thịt ba chỉ heo rồi thái hạt lự nhỏ đều cạnh 0,8 cm. Băm nhỏ 1 củ tỏi khô; rửa sạch hành lá, tách riêng đầu hành trắng băm nhỏ và lá xanh thái nhuyễn. Đánh tơi 540 g cơm nguội với 2 g muối ăn trong tô lớn.', 'Cắt thịt ba chỉ hạt lự đều nhau giúp thịt nhanh ra mỡ và cháy cạnh giòn đều khắp từng miếng.', NULL),
('imp-7fa36d5f0187a86e_v4_step_2', 'imp-7fa36d5f0187a86e', 2, 'cook', 'Áp chảo thịt ba chỉ ra mỡ vàng giòn cạnh', 'Tráng 10 ml dầu ăn vào chảo lớn trên lửa vừa, cho thịt ba chỉ cắt hạt lự vào đảo đều khoảng 5 phút đến khi thịt tiết ra mỡ béo và các cạnh xém vàng giòn nhẹ. Rưới 5 ml xì dầu lên thịt đảo nhanh 20 giây cho thơm rồi vớt phần thịt ra chén riêng, giữ lại khoảng 2 muỗng canh mỡ thơm trong chảo.', 'Vớt thịt ba chỉ ra trước rồi mới rang cơm giúp thịt giữ được độ giòn cạnh mà không bị dai cứng.', 5),
('imp-7fa36d5f0187a86e_v4_step_3', 'imp-7fa36d5f0187a86e', 3, 'cook', 'Phi thơm tỏi và đầu hành trắng với mỡ ba chỉ', 'Làm nóng phần mỡ ba chỉ vừa giữ lại trên lửa vừa, cho tỏi băm và đầu hành trắng băm nhỏ vào phi nhanh khoảng 30 giây đến khi dậy mùi thơm nức và hơi ngả vàng.', NULL, NULL),
('imp-7fa36d5f0187a86e_v4_step_4', 'imp-7fa36d5f0187a86e', 4, 'cook', 'Rang cơm lửa lớn cho săn hạt thấm mỡ thơm', 'Trút toàn bộ cơm nguội vào chảo, tăng lên lửa lớn và đảo liên tục trong 4 phút để từng hạt cơm áo đều lớp mỡ ba chỉ thơm tỏi, trở nên săn chắc, tơi rời và nhảy nhẹ trên mặt chảo.', NULL, 4),
('imp-7fa36d5f0187a86e_v4_step_5', 'imp-7fa36d5f0187a86e', 5, 'cook', 'Nêm xì dầu quanh chảo và trộn ba chỉ giòn', 'Rưới 15 ml xì dầu còn lại dọc quanh thành chảo nóng, thêm 4 g hạt nêm và 3 g đường cát trắng vào đảo đều tay 1 phút cho dậy hương thơm đặc trưng và hạt cơm lên màu nâu vàng đẹp mắt. Trút đĩa thịt ba chỉ cháy cạnh vào đảo đều thêm 1 phút.', 'Rưới xì dầu vào mép chảo nóng giúp nước tương bốc hương thơm nồng mà không làm ướt nhão hạt cơm.', NULL),
('imp-7fa36d5f0187a86e_v4_step_6', 'imp-7fa36d5f0187a86e', 6, 'finish', 'Rắc nhiều hành lá xanh, tiêu xay và dọn nóng', 'Tắt bếp, rắc toàn bộ phần lá hành xanh thái nhuyễn và 1,5 g tiêu đen xay vào chảo cơm, đảo nhẹ 2–3 lượt cho hành vừa chín tái xanh mướt. Múc cơm chiên ba chỉ hành ra đĩa và thưởng thức nóng ngay.', NULL, NULL),
('imp-fcf23c737f51ef13_v4_step_1', 'imp-fcf23c737f51ef13', 1, 'prep', 'Tơi cơm nguội và chuẩn bị trứng, cà chua', 'Dùng tay sạch bóp nhẹ 700 g cơm nguội để lạnh sao cho từng hạt cơm tách rời hoàn toàn, không còn vón cục. Đập 6 quả trứng gà vào tô đánh tan đều. Cà chua chín bỏ bớt phần hạt nước rồi cắt hạt lựu nhỏ; tỏi băm nhuyễn; hành lá thái nhỏ tách riêng đầu trắng và lá xanh.', 'Dùng cơm nguội để lạnh qua đêm và bỏ bớt nước hạt cà chua là hai bí quyết giúp hạt cơm chiên săn tơi, không bị nhão dính.', NULL),
('imp-fcf23c737f51ef13_v4_step_2', 'imp-fcf23c737f51ef13', 2, 'cook', 'Chiên trứng bác mềm ẩm rồi trút ra riêng', 'Làm nóng chảo sâu lòng với 15 ml dầu ăn trên lửa vừa-lớn. Đổ trứng gà đã đánh vào, đảo nhẹ tay theo vòng tròn khoảng 1–2 phút cho đến khi trứng vừa đông thành từng mảng bông mềm, bề mặt còn hơi ẩm bóng thì lập tức múc ra đĩa để riêng.', 'Không chiên trứng quá khô ở bước này vì trứng sẽ chín tiếp khi trộn chung với cơm nóng ở cuối.', 2),
('imp-fcf23c737f51ef13_v4_step_3', 'imp-fcf23c737f51ef13', 3, 'cook', 'Phi thơm hành tỏi và xào cạn nước cà chua', 'Cho 30 ml dầu ăn còn lại vào chảo trên lửa vừa, cho đầu hành trắng vào phi thơm 15 giây rồi thả tỏi băm và cà chua hạt lựu vào. Đảo đều khoảng 3 phút cho đến khi cà chua mềm nhừ và phần nước tiết ra bay hơi gần hết, tạo thành lớp nền sệt.', 'Phải đợi nước cà chua rút cạn gần hết mới cho cơm vào để cơm giữ được độ tơi ráo hoàn hảo.', 3),
('imp-fcf23c737f51ef13_v4_step_4', 'imp-fcf23c737f51ef13', 4, 'cook', 'Chiên tơi cơm nguội trên lửa vừa-lớn', 'Trút toàn bộ cơm nguội đã tơi vào chảo, tăng lửa vừa-lớn và đảo đều tay liên tục khoảng 3 phút cho hạt cơm nóng đều, săn lại và quyện lớp xốt cà chua đỏ cam.', NULL, 3),
('imp-fcf23c737f51ef13_v4_step_5', 'imp-fcf23c737f51ef13', 5, 'sauce', 'Rưới tương cà, dầu hào, xì dầu đặc áo đều hạt cơm', 'Rưới 45 ml tương cà, 22 ml dầu hào và 22 ml xì dầu đặc quanh mặt cơm, tiếp tục đảo nhanh tay thêm 2 phút trên lửa lớn cho đến khi từng hạt cơm đều lên màu nâu đỏ bóng bẩy, không còn đọng sốt ở đáy chảo.', NULL, 2),
('imp-fcf23c737f51ef13_v4_step_6', 'imp-fcf23c737f51ef13', 6, 'finish', 'Trộn trứng bác, rưới dầu mè và hoàn thiện', 'Cho trứng gà bác trở lại chảo, rưới 7,5 ml dầu mè thơm và dùng xẻng nhẹ nhàng đảo tơi cùng cơm trong 1 phút cho trứng chín hẳn và hòa quyện. Nếm thử và điều chỉnh thêm 3 g đường cát trắng, 3 g muối ăn hoặc 1 g tiêu trắng xay nếu thích, rắc phần lá xanh hành lá lên trên rồi dọn nóng ngay.', NULL, NULL),
('imp-a5148e527a9ce9cf_v4_step_1', 'imp-a5148e527a9ce9cf', 1, 'prep', 'Sơ chế thịt gà, hành tây và gia vị thơm', 'Thấm thật khô đùi gà rút xương không da rồi cắt miếng vuông cỡ 3–4 cm. Hành tây bổ múi cau, tách nhẹ các lớp; hành lá cắt khúc 3 cm, tách riêng phần đầu trắng và phần lá xanh; tỏi khô băm nhỏ; gừng non chia 10 g nạo nhuyễn và 5 g thái lát mỏng.', 'Chọn đùi gà rút xương thay vì ức gà giúp từng miếng thịt sau khi xào và om sốt vẫn mềm mọng, không bị khô xơ.', NULL),
('imp-a5148e527a9ce9cf_v4_step_2', 'imp-a5148e527a9ce9cf', 2, 'sauce', 'Pha sẵn nước sốt gừng và hỗn hợp bột bắp', 'Trong tô vừa, khuấy đều 200 ml nước lọc với 10 g gừng nạo, 15 ml dầu hào, 30 ml xì dầu nhạt, 7,5 ml xì dầu đặc, 3 g đường cát trắng, 0,5 g tiêu trắng xay và 15 ml rượu Thiệu Hưng (nếu dùng) cho tan hết gia vị. Ở chén khác, hòa tan 4 g bột bắp với 30 ml nước lọc.', NULL, NULL),
('imp-a5148e527a9ce9cf_v4_step_3', 'imp-a5148e527a9ce9cf', 3, 'cook', 'Phi thơm gừng lát, tỏi và hành tây trên lửa lớn', 'Đun nóng 15 ml dầu ăn trong chảo sâu lòng trên lửa lớn đến khi dầu nóng già. Cho 5 g gừng thái lát vào phi thơm 15 giây, tiếp tục thả tỏi băm, đầu hành trắng và hành tây múi cau vào đảo nhanh tay khoảng 30 giây cho dậy hương thơm nồng.', NULL, NULL),
('imp-a5148e527a9ce9cf_v4_step_4', 'imp-a5148e527a9ce9cf', 4, 'cook', 'Xào săn vàng các mặt thịt đùi gà', 'Trút thịt đùi gà vào chảo, dàn đều một lớp và xào nhanh tay trên lửa lớn khoảng 4–5 phút đến khi thịt săn chắc, mặt ngoài hơi xém vàng và không còn màu hồng sống.', 'Giữ lửa lớn khi áp chảo gà để bề mặt thịt nhanh se lại, khóa nước ngọt bên trong và không bị ra nước lênh láng.', 5),
('imp-a5148e527a9ce9cf_v4_step_5', 'imp-a5148e527a9ce9cf', 5, 'cook', 'Om thịt gà thấm sốt gừng và hành lá', 'Đổ toàn bộ tô nước sốt gừng đã pha vào chảo, đảo đều và đun sôi trở lại. Thả phần lá xanh hành lá vào, hạ xuống lửa vừa nấu thêm 3 phút cho thịt gà chín kỹ hoàn toàn bên trong, thấm đẫm sốt thơm và hành lá vừa chín tới.', NULL, 3),
('imp-a5148e527a9ce9cf_v4_step_6', 'imp-a5148e527a9ce9cf', 6, 'finish', 'Làm sánh nước sốt và dọn nóng', 'Khuấy đều lại chén bột bắp pha nước rồi rưới từ từ vào chảo, vừa rưới vừa đảo đều khoảng 30 giây cho nước sốt sánh bóng bám đều lên từng miếng thịt gà và hành tây. Nếm lại cho vừa miệng, tắt bếp và dọn nóng ra đĩa dùng ngay với cơm trắng.', 'Rưới nước bột bắp từng chút một để kiểm soát độ sánh vừa phải, tránh làm sốt đặc quánh quá mức.', NULL),
('imp-b3d9ecb751b0a043_v4_step_1', 'imp-b3d9ecb751b0a043', 1, 'prep', 'Làm sạch, thấm khô và thái mỏng thịt bò ngang thớ', 'Rửa nhanh thịt bò thăn qua nước pha 2 g muối ăn để khử mùi rồi thấm thật khô bằng khăn giấy. Dùng dao sắc thái thịt thành từng lát mỏng ngang thớ để khi xào thịt nhanh chín và không bị dai.', 'Thấm thật khô miếng thịt trước khi ướp và xào giúp thịt áp chảo săn mặt thơm ngon thay vì bị ra nhiều nước.', NULL),
('imp-b3d9ecb751b0a043_v4_step_2', 'imp-b3d9ecb751b0a043', 2, 'marinate', 'Ướp thịt bò thấm gia vị và khóa ẩm bằng dầu ăn', 'Cho thịt bò vào tô cùng 15 ml xì dầu, 15 ml dầu hào, 2 g đường cát trắng, 1 g muối ăn, một nửa lượng tiêu đen xay và 5 ml dầu ăn. Trộn đều tay rồi ướp khoảng 15–20 phút cho thịt ngấm gia vị và mềm mượt.', 'Cho một chút dầu ăn vào ướp cùng giúp bao bọc bề mặt lát bò, giữ độ ẩm và giúp thịt tách rời dễ dàng khi cho vào chảo nóng.', 15),
('imp-b3d9ecb751b0a043_v4_step_3', 'imp-b3d9ecb751b0a043', 3, 'prep', 'Sơ chế hành tây, tỏi, ớt hiểm và gừng tươi', 'Hành tây bóc vỏ, bổ múi cau vừa ăn rồi tách nhẹ các cánh hành. Tỏi khô băm nhỏ; ớt hiểm đỏ thái lát vát xéo; nếu dùng gừng tươi thì cạo sạch vỏ rồi thái sợi thật mảnh hoặc băm nhỏ.', NULL, NULL),
('imp-b3d9ecb751b0a043_v4_step_4', 'imp-b3d9ecb751b0a043', 4, 'cook', 'Phi thơm tỏi, ớt hiểm và gừng tươi', 'Làm nóng chảo trên lửa vừa với 25 ml dầu ăn còn lại, cho tỏi băm vào phi 20 giây cho dậy mùi thơm vàng nhẹ rồi thả ớt hiểm (và gừng tươi nếu dùng) vào đảo chung thêm 20 giây.', NULL, NULL),
('imp-b3d9ecb751b0a043_v4_step_5', 'imp-b3d9ecb751b0a043', 5, 'cook', 'Xào hành tây giữ độ giòn ngọt', 'Tăng lên lửa lớn, cho hành tây múi cau vào đảo nhanh tay khoảng 1–2 phút đến khi hành tây hơi trong ở viền cánh nhưng vẫn giữ nguyên độ giòn ngọt tự nhiên.', NULL, 2),
('imp-b3d9ecb751b0a043_v4_step_6', 'imp-b3d9ecb751b0a043', 6, 'finish', 'Xào nhanh thịt bò chín tới và dọn nóng', 'Trút toàn bộ thịt bò đã ướp vào chảo hành tây, giữ lửa lớn nhất đảo thật nhanh tay khoảng 1–2 phút đến khi thịt bò vừa chuyển màu chín tới và nước sốt áo bóng quanh từng lát thịt. Nêm thêm 4 g hạt nêm cho vừa miệng, tắt bếp, rắc phần tiêu đen xay còn lại lên trên và dọn nóng với cơm trắng.', 'Không xào thịt bò quá 2–3 phút vì thịt thăn thái mỏng chín rất nhanh; xào quá lửa thịt sẽ bị khô và dai.', 2),
('imp-835a527c81a79e9c_v4_step_1', 'imp-835a527c81a79e9c', 1, 'prep', 'Sơ chế cải thảo, cà rốt, gừng và hành lá', 'Tách từng lá cải thảo rửa sạch, để ráo rồi cắt khúc dài 3–4 cm, tách riêng phần cọng trắng cứng và phần lá xanh mềm ra hai rổ. Gọt vỏ cà rốt thái lát mỏng (nếu dùng). Gừng tươi chia một nửa băm nhỏ, một nửa thái lát mỏng; hành lá thái nhỏ tách riêng đầu trắng và lá xanh.', 'Tách riêng cọng trắng và lá xanh cải thảo vì phần cọng cần nấu lâu hơn, giúp cả hai phần chín đồng đều mà lá không bị nhũn.', NULL),
('imp-835a527c81a79e9c_v4_step_2', 'imp-835a527c81a79e9c', 2, 'marinate', 'Ướp và quết dẻo thịt heo xay', 'Cho 250 g thịt heo xay vào tô cùng gừng băm, 5 ml xì dầu nhạt, 2 g muối ăn, 0,6 g tiêu trắng xay, 3 g bột bắp, 15 ml rượu Thiệu Hưng và 15 ml nước lọc. Dùng đũa khuấy đều theo một chiều khoảng 1 phút cho thịt ngấm nước và dẻo mịn, để nghỉ 10 phút.', 'Quết thịt heo xay theo một chiều với chút nước lọc và bột bắp giúp thịt mềm ẩm, không bị khô xác khi nấu canh.', 10),
('imp-835a527c81a79e9c_v4_step_3', 'imp-835a527c81a79e9c', 3, 'cook', 'Phi thơm gừng hành và xào săn thịt bằm', 'Đặt nồi lên bếp lửa vừa, làm nóng 15 ml dầu ăn rồi cho gừng thái lát và đầu hành trắng vào phi thơm 30 giây. Trút thịt heo xay đã ướp vào, dùng đũa đảo tơi liên tục khoảng 3–4 phút đến khi thịt săn rời hoàn toàn và không còn màu hồng sống.', 'Xào săn thịt trước giúp nước canh thơm đậm đà và giữ được độ trong, ít bọt hơn so với thả thịt sống vào nước.', 4),
('imp-835a527c81a79e9c_v4_step_4', 'imp-835a527c81a79e9c', 4, 'cook', 'Nấu sôi nước dùng gà và hầm phần cọng cải thảo', 'Đổ 500 ml nước dùng gà và 500 ml nước lọc còn lại vào nồi thịt, bật lửa lớn đun sôi rồi hớt sạch bọt nổi. Thả phần cọng trắng cải thảo (và cà rốt thái lát nếu dùng) vào, hạ lửa vừa nấu khoảng 5 phút cho cọng cải vừa mềm ngọt.', NULL, 5),
('imp-835a527c81a79e9c_v4_step_5', 'imp-835a527c81a79e9c', 5, 'cook', 'Nấu phần lá cải thảo và nêm gia vị', 'Cho phần lá xanh cải thảo vào nồi, nấu thêm 3 phút trên lửa vừa đến khi lá vừa chín tới và giữ được màu xanh tươi. Nêm 15 ml xì dầu nhạt còn lại và 4 g muối ăn vào khuấy đều, nếm thử và điều chỉnh cho vừa khẩu vị.', NULL, 3),
('imp-835a527c81a79e9c_v4_step_6', 'imp-835a527c81a79e9c', 6, 'finish', 'Rưới dầu mè, rắc hành lá và dọn nóng', 'Tắt bếp ngay để lá cải thảo không bị quá mềm. Nhỏ 5 ml dầu mè thơm (nếu dùng) và rắc phần lá xanh hành lá lên mặt nồi canh, múc ra tô lớn và thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-1dc0835c31b06d5e_v4_step_1', 'imp-1dc0835c31b06d5e', 1, 'marinate', 'Thấm khô và ướp tôm với gia vị', 'Thấm thật khô tôm tươi bằng khăn giấy. Cho tôm vào tô cùng 2 g muối ăn, 3 g ớt bột Paprika ngọt, 1,2 g tiêu đen xay và 15 ml dầu ăn, trộn đều tay rồi để nghỉ 10 phút cho tôm thấm vị.', 'Thấm khô tôm trước khi ướp giúp tôm nhanh săn và không tiết nước làm loãng sốt khi xào lửa lớn.', 10),
('imp-1dc0835c31b06d5e_v4_step_2', 'imp-1dc0835c31b06d5e', 2, 'prep', 'Sơ chế bông cải xanh và băm tỏi gừng', 'Cắt tách bông cải xanh thành từng nhánh nhỏ vừa ăn, rửa sạch và để ráo nước. Tỏi khô và gừng tươi băm nhỏ; ớt hiểm đỏ cắt khúc ngắn nếu dùng.', NULL, NULL),
('imp-1dc0835c31b06d5e_v4_step_3', 'imp-1dc0835c31b06d5e', 3, 'sauce', 'Pha sẵn hỗn hợp nước sốt dầu hào Hoisin', 'Trong tô vừa, khuấy đều 180 ml nước lọc, 3 g đường cát trắng, 22 ml dầu hào, 22 ml xì dầu nhạt, 7,5 ml xì dầu đặc, 10 ml tương đen Hoisin và 8 g bột bắp cho đến khi bột bắp và đường tan hoàn toàn.', 'Khuấy đều lại chén sốt ngay trước khi đổ vào chảo vì bột bắp rất nhanh lắng xuống đáy.', NULL),
('imp-1dc0835c31b06d5e_v4_step_4', 'imp-1dc0835c31b06d5e', 4, 'cook', 'Áp chảo nhanh tôm trên lửa lớn', 'Làm nóng chảo sâu lòng trên lửa lớn đến khi hơi bốc khói, đổ 35 ml dầu ăn còn lại vào láng đều đáy chảo. Thả tôm vào đảo nhanh tay khoảng 2 phút đến khi vỏ ngoài chuyển màu cam hồng và thịt tôm vừa săn tái thì vớt tôm ra đĩa, giữ lại toàn bộ phần dầu thơm trong chảo.', 'Không xào tôm chín kỹ ở bước này vì tôm sẽ tiếp tục chín hoàn toàn khi đảo lại với nước sốt ở cuối.', 2),
('imp-1dc0835c31b06d5e_v4_step_5', 'imp-1dc0835c31b06d5e', 5, 'cook', 'Xào thơm tỏi gừng và ủ hơi bông cải xanh', 'Hạ xuống lửa vừa, cho tỏi băm, gừng băm, ớt hiểm (nếu dùng) và bông cải xanh vào chảo dầu đảo đều 1–2 phút. Rưới 45 ml nước lọc quanh thành chảo rồi đậy kín nắp lại, ủ hơi khoảng 2 phút cho bông cải xanh chín tới giòn mướt.', 'Kỹ thuật ủ hơi nhanh bằng nắp vung giúp bông cải giữ trọn màu xanh tươi và độ ngọt tự nhiên tốt hơn so với chần nước.', 3),
('imp-1dc0835c31b06d5e_v4_step_6', 'imp-1dc0835c31b06d5e', 6, 'finish', 'Đảo quyện tôm với sốt sánh bóng và dọn nóng', 'Mở nắp, khuấy đều chén sốt rồi đổ vào chảo, trút tôm trở lại và đảo đều trên lửa lớn khoảng 1–2 phút đến khi thịt tôm chín đục hoàn toàn và nước sốt sánh bóng bám đều từng nhánh bông cải. Tắt bếp, trút ra đĩa và dùng nóng với cơm trắng.', NULL, 2),
('imp-57b4406be05661c7_v4_step_1', 'imp-57b4406be05661c7', 1, 'marinate', 'Thái dải và ướp thịt ba chỉ thấm gia vị', 'Thái thịt ba chỉ heo thành các dải dày khoảng 5 mm. Cho thịt vào tô ướp cùng 22 ml rượu Thiệu Hưng, 0,8 g tiêu trắng xay, 10 ml xì dầu nhạt và 5 ml xì dầu đặc; trộn đều rồi để thấm khoảng 10–15 phút trong lúc sơ chế rau củ.', NULL, 15),
('imp-57b4406be05661c7_v4_step_2', 'imp-57b4406be05661c7', 2, 'prep', 'Sơ chế rau củ và băm nhỏ tương đậu', 'Ớt chuông đỏ cắt sợi dày, hành tây thái lát dày, tỏi khô băm nhỏ, hành lá cắt khúc tách riêng đầu trắng và lá xanh, gừng thái sợi và ớt hiểm thái lát nếu dùng. Băm nhỏ 30 g tương ớt đậu bản Doubanjiang cùng 13 g đậu tương đen lên men Douchi trên thớt.', 'Băm nhỏ hai loại tương đậu giúp gia vị tan đều trong dầu nóng và không bị cắn trúng miếng tương mặn gắt.', NULL),
('imp-57b4406be05661c7_v4_step_3', 'imp-57b4406be05661c7', 3, 'cook', 'Áp chảo vàng giòn hai mặt thịt ba chỉ', 'Làm nóng chảo sâu lòng lớn trên lửa vừa-lớn, tráng đều 10 ml dầu ăn. Xếp các dải thịt ba chỉ thành một lớp phẳng không chồng lên nhau, áp chảo mỗi mặt khoảng 2–3 phút cho thịt tiết bớt mỡ, xém vàng cạnh và chín kỹ hoàn toàn bên trong. Gắp thịt ra thớt cắt miếng dài 4–5 cm vừa ăn; chắt bỏ bớt phần mỡ thừa tiết ra trong chảo, chỉ chừa lại khoảng 1 muỗng canh mỡ thơm để phi tương đậu.', NULL, 6),
('imp-57b4406be05661c7_v4_step_4', 'imp-57b4406be05661c7', 4, 'cook', 'Xào thơm tương đậu trên lửa nhỏ tạo dầu đỏ', 'Hạ bếp xuống lửa nhỏ, cho tương ớt đậu bản và đậu tương đen băm vào phần mỡ thịt trong chảo, đảo đều tay khoảng 1 phút cho đến khi hỗn hợp dậy mùi thơm nồng và phần dầu chuyển màu đỏ cam óng ánh.', 'Luôn xào tương đậu trên lửa nhỏ để tương ra màu đỏ đẹp mà không bị cháy khét gây đắng.', 1),
('imp-57b4406be05661c7_v4_step_5', 'imp-57b4406be05661c7', 5, 'cook', 'Xào tỏi, hành và rau củ giữ độ giòn', 'Cho tỏi băm và phần đầu hành trắng (thêm gừng sợi, ớt hiểm nếu dùng) vào đảo 1 phút cho thơm. Tăng lên lửa lớn, thả hành tây và ớt chuông đỏ vào xào nhanh tay khoảng 30–45 giây cho rau vừa chín tái vẫn giữ độ giòn ngọt.', NULL, 1),
('imp-57b4406be05661c7_v4_step_6', 'imp-57b4406be05661c7', 6, 'finish', 'Đảo quyện thịt ba chỉ, rưới rượu và hoàn thiện', 'Trút thịt ba chỉ đã cắt miếng trở lại chảo, đảo đều 30 giây trên lửa lớn. Rưới 8 ml rượu Thiệu Hưng còn lại cùng 5 ml xì dầu nhạt quanh thành chảo nóng, rắc 6 g đường cát trắng và phần lá xanh hành lá vào đảo nhanh một lượt rồi tắt bếp ngay. Dọn nóng dùng kèm cơm trắng.', 'Không cần nêm thêm muối rời vì tương đậu bản, đậu đen muối và xì dầu đã đủ độ mặn đậm đà.', NULL),
('imp-3774a1f0fda5cce1_v4_step_1', 'imp-3774a1f0fda5cce1', 1, 'marinate', 'Cắt khối và ướp giữ ẩm thịt ức gà', 'Cắt ức gà lọc xương không da thành miếng vuông đều cỡ 2,5 cm. Trộn gà trong tô cùng 30 ml nước lọc, 1 g bột tỏi, 4 ml dầu mè thơm, 0,6 g tiêu trắng xay và 3 g muối ăn; đảo đều cho thịt hút hết nước gia vị rồi ướp 10 phút.', 'Ướp thêm chút nước giúp miếng ức gà giữ độ ẩm mọng bên trong khi chiên ngập dầu mà không bị khô.', 10),
('imp-3774a1f0fda5cce1_v4_step_2', 'imp-3774a1f0fda5cce1', 2, 'prep', 'Pha bột chiên giòn và sơ chế rau củ, dứa chín', 'Trộn đều 120 g bột mì đa dụng, 10 g bột bắp và 2 g baking soda trong tô. Rót 200 ml nước lọc thật lạnh vào khuấy thành hỗn hợp bột sánh mịn rồi thêm 15 ml dầu ăn khuấy đều. Cắt miếng vuông 2,5 cm hành tây tím và ớt chuông; thái miếng vừa ăn dứa chín; băm nhỏ tỏi khô.', 'Dùng nước thật lạnh pha bột giúp hạn chế tạo gluten, làm lớp vỏ chiên nhẹ và giòn xốp lâu hơn.', NULL),
('imp-3774a1f0fda5cce1_v4_step_3', 'imp-3774a1f0fda5cce1', 3, 'sauce', 'Pha sẵn nước sốt chua ngọt và hỗn hợp bột bắp', 'Hòa tan 180 ml nước lọc ấm với 2 g muối ăn còn lại, 36 g đường cát trắng và 25 ml tương cà cho tan hết đường muối, sau đó khuấy đều thêm 60 ml giấm gạo. Ở chén khác, hòa tan 16 g bột bắp còn lại với 30 ml nước lọc.', NULL, NULL),
('imp-3774a1f0fda5cce1_v4_step_4', 'imp-3774a1f0fda5cce1', 4, 'cook', 'Chiên gà lần một cho chín đều và định hình vỏ', 'Đun nóng 500 ml dầu ăn trong nồi sâu lòng đến khoảng 170°C. Nhúng từng mẻ 5–6 miếng gà vào tô bột, thả chậm từng miếng vào dầu nóng để bột không dính đáy. Chiên mỗi mẻ khoảng 3 phút cho vỏ vàng nhạt và thịt gà chín kỹ bên trong rồi vớt ra rổ thưa cho ráo dầu.', 'Chia nhỏ từng mẻ chiên để nhiệt độ dầu không bị giảm đột ngột, giúp lớp bột se giòn mà không ngấm dầu.', 6),
('imp-3774a1f0fda5cce1_v4_step_5', 'imp-3774a1f0fda5cce1', 5, 'cook', 'Xào rau củ, nấu sánh sốt chua ngọt và chiên lại gà lần hai', 'Đun nóng 15 ml dầu ăn trong chảo lớn trên lửa vừa-lớn, cho tỏi băm, hành tây tím và ớt chuông vào xào nhanh 30 giây. Đổ tô nước sốt chua ngọt vào đun sôi rồi hạ lửa vừa, vừa khuấy vừa rưới từ từ hỗn hợp bột bắp pha nước đến khi sốt sánh bóng bám thìa, thả dứa chín vào đảo nóng. Song song đó, đun nóng lại nồi dầu chiên lên 175°C rồi thả toàn bộ gà vào chiên nhanh thêm 45 giây cho vỏ vàng giòn rụm, vớt ra để ráo.', 'Chiên lại lần hai ngay trước khi trộn sốt là bí quyết giúp miếng gà giòn tan và giữ được độ giòn khi áo sốt.', 3),
('imp-3774a1f0fda5cce1_v4_step_6', 'imp-3774a1f0fda5cce1', 6, 'finish', 'Xóc nhanh gà với sốt chua ngọt và dọn nóng', 'Cho toàn bộ gà chiên giòn vào chảo sốt chua ngọt, dùng xẻng đảo nhẹ và nhanh tay khoảng 3–4 lượt cho từng miếng gà áo đều lớp sốt đỏ óng cùng dứa và ớt chuông. Trút ngay ra đĩa và thưởng thức nóng khi lớp vỏ còn giòn rụm.', NULL, NULL),
('imp-49ca1819d60ffec8_v4_step_1', 'imp-49ca1819d60ffec8', 1, 'prep', 'Làm khô và cắt khúc dài hành lá', 'Rửa sạch hành lá tươi, dùng khăn giấy thấm thật khô từng cọng hành để khi phi không bị bắn dầu. Cắt bỏ rễ, cắt hành thành từng khúc dài khoảng 5 cm và chẻ đôi phần gốc trắng theo chiều dọc.', 'Không nên thái hành quá nhỏ và phải thấm thật khô để hành không bị cháy nhanh trước khi kịp tiết hết tinh dầu thơm.', NULL),
('imp-49ca1819d60ffec8_v4_step_2', 'imp-49ca1819d60ffec8', 2, 'cook', 'Phi chậm hành lá từ dầu nguội cho vàng thơm', 'Cho 30 ml dầu ăn và toàn bộ hành lá vào chảo từ lúc dầu còn nguội, sau đó mới bật lửa nhỏ. Đảo nhẹ và đều tay khoảng 6 phút đến khi phần gốc hành chuyển màu vàng nâu đẹp mắt, giòn thơm thì vớt hết xác hành ra đĩa để riêng, giữ lại toàn bộ phần dầu hành trong chảo.', 'Bắt đầu phi từ dầu nguội giúp tinh dầu hành chiết xuất chậm và sâu hơn, đồng thời kiểm soát nhiệt độ tránh làm hành bị cháy đắng.', 6),
('imp-49ca1819d60ffec8_v4_step_3', 'imp-49ca1819d60ffec8', 3, 'sauce', 'Nấu hòa tan hỗn hợp sốt xì dầu dầu hành', 'Tắt bếp, chờ dầu hành nguội bớt khoảng 1 phút rồi đổ 15 ml xì dầu nhạt, 15 ml xì dầu đặc và 4 g đường cát trắng vào chảo. Khuấy đều đến khi hỗn hợp sủi lăn tăn nhẹ từ nhiệt dư và đường tan hoàn toàn; nếu dầu nguội quá, bật lại lửa nhỏ khoảng 20 giây cho sốt hòa quyện.', NULL, NULL),
('imp-49ca1819d60ffec8_v4_step_4', 'imp-49ca1819d60ffec8', 4, 'cook', 'Đun sôi nước và luộc chín sợi mì trứng', 'Đun sôi 1 lít nước lọc trong nồi lớn cùng 6 g muối ăn. Thả 200 g mì trứng sợi khô vào luộc theo hướng dẫn trên bao bì khoảng 4–5 phút đến khi sợi mì chín mềm nhưng vẫn giữ được độ dai nhẹ ở lõi.', 'Có thể luộc mì song song trong lúc phi hành để hoàn thành món ăn chỉ trong vòng 10–12 phút.', 5),
('imp-49ca1819d60ffec8_v4_step_5', 'imp-49ca1819d60ffec8', 5, 'cook', 'Vớt ráo mì và trộn đều cùng sốt dầu hành ấm', 'Vớt mì ra rổ, xóc thật kỹ cho ráo hết nước rồi trút ngay vào chảo sốt dầu hành còn ấm. Dùng đũa trộn đều nhẹ tay khoảng 1 phút cho từng sợi mì áo đều lớp sốt nâu bóng thơm lừng.', 'Mì phải thật ráo nước để lớp sốt dầu hành bám chặt quanh sợi mì mà không bị loãng nhạt.', NULL),
('imp-49ca1819d60ffec8_v4_step_6', 'imp-49ca1819d60ffec8', 6, 'finish', 'Trình bày tô mì, rắc hành phi giòn và thưởng thức', 'Gắp mì ra hai tô vừa, rưới thêm phần sốt còn đọng dưới chảo lên trên. Xếp phần hành lá phi vàng giòn lên mặt, rắc thêm 5 g hạt mè trắng rang (nếu dùng) và thưởng thức nóng ngay.', NULL, NULL),
('imp-2b5b79ba1b622db1_v4_step_1', 'imp-2b5b79ba1b622db1', 1, 'prep', 'Ngâm mềm tôm khô và sơ chế cải thảo, gừng hành', 'Rửa sạch 45 g tôm khô qua nước lạnh rồi ngâm trong nước ấm khoảng 15 phút cho tôm nở mềm, vớt ra để ráo. Cải thảo tách từng bẹ, rửa sạch, cắt khúc dài 5–6 cm và để riêng phần bẹ trắng cứng với phần lá xanh mềm. Gừng tươi thái lát mỏng; hành lá thái nhỏ.', 'Ngâm tôm khô trước giúp tôm nhanh tiết vị ngọt umami vào nước dùng và thịt tôm mềm ngọt dễ ăn hơn.', 15),
('imp-2b5b79ba1b622db1_v4_step_2', 'imp-2b5b79ba1b622db1', 2, 'cook', 'Xào thơm gừng và tôm khô làm nền nước canh', 'Đặt nồi lên bếp lửa vừa, làm nóng 10 ml dầu ăn rồi cho gừng tươi thái lát và tôm khô đã ngâm vào đảo đều khoảng 1 phút cho dậy mùi thơm đặc trưng.', NULL, NULL),
('imp-2b5b79ba1b622db1_v4_step_3', 'imp-2b5b79ba1b622db1', 3, 'cook', 'Ninh ngọt nước dùng gà với tôm khô', 'Đổ 500 ml nước dùng gà và 500 ml nước lọc vào nồi tôm khô, bật lửa lớn đun sôi rồi hớt sạch bọt nổi. Hạ xuống lửa vừa, đậy hé nắp và nấu liu riu khoảng 8–10 phút cho tôm khô tiết trọn vị ngọt tự nhiên.', NULL, 10),
('imp-2b5b79ba1b622db1_v4_step_4', 'imp-2b5b79ba1b622db1', 4, 'cook', 'Nấu mềm phần bẹ trắng cải thảo', 'Thả phần bẹ trắng cải thảo vào nồi nước dùng đang sôi, nấu trên lửa vừa khoảng 5 phút cho bẹ cải vừa chín mềm trong nhẹ.', 'Cho phần bẹ trắng vào nấu trước 5 phút giúp bẹ và lá chín đồng đều, không bị tình trạng lá nhũn nát mà bẹ vẫn sượng.', 5),
('imp-2b5b79ba1b622db1_v4_step_5', 'imp-2b5b79ba1b622db1', 5, 'cook', 'Nấu chín phần lá xanh và nêm gia vị vừa miệng', 'Tiếp tục cho phần lá xanh cải thảo vào nồi, nấu thêm 2–3 phút đến khi lá vừa chín mềm vẫn giữ màu xanh tươi. Nêm 4 g muối ăn và 1 g tiêu trắng xay vào khuấy nhẹ cho tan đều rồi nếm thử điều chỉnh.', 'Luôn nêm muối ở bước cuối để dễ kiểm soát độ mặn vì tôm khô đã có sẵn vị mặn tự nhiên.', 3),
('imp-2b5b79ba1b622db1_v4_step_6', 'imp-2b5b79ba1b622db1', 6, 'finish', 'Rưới dầu mè, rắc hành lá và dọn nóng', 'Tắt bếp ngay sau khi nêm vừa miệng, rưới 5 ml dầu mè thơm và rắc hành lá thái nhỏ lên mặt nồi canh. Múc canh ra tô lớn và thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-ee5bc076d722f397_v4_step_1', 'imp-ee5bc076d722f397', 1, 'prep', 'Ngâm nở và sơ chế nấm hương khô', 'Rửa sạch bụi trên 30 g nấm hương khô rồi ngâm trong nước ấm khoảng 30 phút (hoặc ngâm nước lạnh vài giờ) cho nấm nở mềm hoàn toàn. Vớt nấm ra, vắt nhẹ bớt nước, dùng kéo cắt bỏ phần chân nấm dai cứng rồi bổ đôi các tai nấm to.', 'Nên dùng nấm hương khô ngâm nở thay cho nấm tươi vì nấm khô giữ được hương thơm umami đậm đà đặc trưng khi hấp cùng gà.', 30),
('imp-ee5bc076d722f397_v4_step_2', 'imp-ee5bc076d722f397', 2, 'marinate', 'Thái miếng và ướp gà với gia vị giữ ẩm', 'Cắt đùi gà rút xương không da thành miếng vừa ăn cỡ 3–4 cm, cho vào tô lớn. Thêm 40 g gừng tươi thái lát, 5 ml xì dầu nhạt, 3 ml xì dầu đặc, 8 ml dầu hào, 5 ml rượu Thiệu Hưng, 2 ml dầu mè thơm, 0,5 g tiêu trắng xay và 3 g bột bắp. Trộn thật đều tay rồi ướp khoảng 10–15 phút cho thịt ngấm vị.', NULL, 10),
('imp-ee5bc076d722f397_v4_step_3', 'imp-ee5bc076d722f397', 3, 'prep', 'Trộn gà với nấm đông cô và chuẩn bị ớt, hành lá', 'Cho toàn bộ nấm hương khô đã ngâm mềm vào tô thịt gà ướp cùng ớt hiểm đỏ băm nhỏ (nếu dùng), trộn đều lại một lượt. Hành lá rửa sạch thái nhỏ; kỷ tử khô (nếu dùng) rửa nhanh qua nước sạch rồi để ráo.', NULL, NULL),
('imp-ee5bc076d722f397_v4_step_4', 'imp-ee5bc076d722f397', 4, 'prep', 'Dàn đều gà và nấm lên đĩa sâu lòng', 'Chuyển toàn bộ hỗn hợp gà, gừng và nấm sang một chiếc đĩa sứ sâu lòng chịu nhiệt, dàn đều thành một lớp phẳng không chồng chất quá dày, rải kỷ tử khô (nếu dùng) lên trên.', 'Chọn đĩa sâu lòng thay vì tô sâu giúp thịt gà tiếp xúc đều với hơi nóng để chín nhanh, đồng thời hứng trọn được phần nước ngọt tiết ra.', NULL),
('imp-ee5bc076d722f397_v4_step_5', 'imp-ee5bc076d722f397', 5, 'cook', 'Hấp cách thủy lửa vừa đến khi gà chín hoàn toàn', 'Đun sôi mạnh nước trong nồi xửng lớn, đặt đĩa gà lên giá hấp, đậy kín nắp và hấp trên lửa vừa khoảng 20 phút tính từ lúc nước sôi mạnh. Kiểm tra phần thịt gà dày nhất không còn màu hồng đỏ và nước thịt tiết ra trong hoàn toàn là đạt.', 'Chỉ đặt đĩa gà vào xửng khi nước đã sôi mạnh để hơi nóng bao bọc đều ngay từ đầu, giúp thịt gà giữ trọn nước ngọt.', 20),
('imp-ee5bc076d722f397_v4_step_6', 'imp-ee5bc076d722f397', 6, 'finish', 'Rắc hành lá và dọn nóng cùng nước hấp ngọt', 'Cẩn thận nhấc đĩa gà ra khỏi xửng hấp, rắc hành lá thái nhỏ lên mặt khi đĩa gà còn bốc khói nghi ngút. Dọn nóng ngay và thưởng thức cùng cơm trắng.', NULL, NULL),
('imp-aac2c265c3845ec4_v4_step_1', 'imp-aac2c265c3845ec4', 1, 'prep', 'Làm sạch và ướp nhẹ tôm sú khử mùi tanh', 'Cắt râu và phần gai nhọn trên đầu tôm sú tươi, dùng tăm khéo léo rút bỏ chỉ đen dọc sống lưng rồi rửa sạch, để ráo. Cho tôm vào tô cùng 5 ml rượu Thiệu Hưng và một nửa lượng tiêu trắng xay (0,25 g), trộn nhẹ và ướp 10 phút cho tôm thơm.', 'Giữ nguyên vỏ khi hấp giúp khóa ẩm tự nhiên, làm thịt tôm sau khi chín vẫn giòn ngọt và mọng nước.', 10),
('imp-aac2c265c3845ec4_v4_step_2', 'imp-aac2c265c3845ec4', 2, 'prep', 'Thái sợi gừng tươi và chuẩn bị hành lá', 'Gừng tươi gọt vỏ, thái lát mỏng rồi cắt thành sợi thật mảnh. Hành lá tách 1/3 cắt khúc dài 5 cm để lót đĩa hấp, phần 2/3 còn lại thái khoanh mỏng để rắc sau khi hấp xong.', NULL, NULL),
('imp-aac2c265c3845ec4_v4_step_3', 'imp-aac2c265c3845ec4', 3, 'sauce', 'Pha sẵn nước sốt xì dầu gừng hành', 'Trong một chén nhỏ, trộn đều 25 ml xì dầu nhạt, 10 ml rượu Thiệu Hưng còn lại, 20 ml nước lọc, 4 g đường cát trắng, 2 ml dầu mè thơm, 0,25 g tiêu trắng xay còn lại và 10 ml dầu ăn thực vật. Khuấy kỹ đến khi đường tan hoàn toàn.', 'Pha thêm nước lọc vào xì dầu giúp vị sốt dịu thanh, tôn lên độ ngọt biển tự nhiên của tôm tươi.', NULL),
('imp-aac2c265c3845ec4_v4_step_4', 'imp-aac2c265c3845ec4', 4, 'cook', 'Xếp tôm thành một lớp trên đĩa lót hành và gừng', 'Đun sôi mạnh nước trong nồi xửng hấp. Lót các khúc hành lá 5 cm dưới đáy đĩa chịu nhiệt, xếp tôm sú thành một lớp phẳng không chồng lên nhau và rải một nửa lượng gừng sợi lên mặt tôm.', NULL, NULL),
('imp-aac2c265c3845ec4_v4_step_5', 'imp-aac2c265c3845ec4', 5, 'cook', 'Hấp tôm lửa lớn vừa chín hồng tới', 'Khi nước trong nồi đã sôi bùng nhiều hơi, đặt đĩa tôm vào xửng, đậy kín nắp và hấp trên lửa lớn khoảng 5–6 phút đến khi vỏ tôm chuyển đỏ cam đồng đều, thân tôm uốn cong và thịt tôm chuyển trắng đục hoàn toàn.', 'Không hấp tôm quá 6 phút vì tôm chín quá lửa sẽ bị khô cứng và teo nhỏ.', 6),
('imp-aac2c265c3845ec4_v4_step_6', 'imp-aac2c265c3845ec4', 6, 'finish', 'Chắt bỏ nước hấp đục, rưới sốt và dọn nóng', 'Nhấc đĩa tôm ra khỏi nồi, nhẹ nhàng nghiêng đĩa chắt bỏ hết phần nước hấp đục tiết ra. Rưới đều chén nước sốt xì dầu lên khắp mình tôm, rắc phần gừng sợi còn lại và hành lá thái khoanh lên trên rồi thưởng thức nóng ngay.', 'Chắt bỏ phần nước đọng sau khi hấp giúp nước sốt xì dầu giữ nguyên độ đậm đà thanh sạch.', NULL),
('imp-55201e4225342ca3_v4_step_1', 'imp-55201e4225342ca3', 1, 'marinate', 'Thấm khô, ướp cá phi lê với lòng trắng trứng và áo bột bắp', 'Thấm thật khô 700 g phi lê cá thịt trắng rồi cắt miếng vuông cỡ 3–4 cm. Ướp cá với 5 g muối ăn, 0,6 g tiêu trắng xay và lòng trắng của 1 quả trứng gà, trộn đều để nghỉ 15 phút. Trước khi chiên, rắc đều 30 g bột bắp vào xóc nhẹ cho bột phủ kín mỏng từng miếng cá.', 'Thấm thật khô cá trước khi ướp giúp lớp bột bắp bám chắc và lên vỏ giòn rụm, không bị nhão khi thả vào dầu nóng.', 15),
('imp-55201e4225342ca3_v4_step_2', 'imp-55201e4225342ca3', 2, 'sauce', 'Pha sẵn nước sốt chua ngọt và sơ chế rau củ', 'Hòa tan 70 ml tương cà, 30 ml giấm gạo, 25 g đường cát trắng, 15 ml xì dầu nhạt và 100 ml nước lọc trong bát cho tan hết đường. Hòa tan riêng 12 g bột bắp còn lại với 45 ml nước lọc. Thái vuông 2 cm hành tây và ớt chuông; bổ múi cau cà chua; cắt miếng vừa ăn dứa chín; băm nhỏ tỏi, thái lát gừng và cắt khúc 3 cm hành lá.', NULL, NULL),
('imp-55201e4225342ca3_v4_step_3', 'imp-55201e4225342ca3', 3, 'cook', 'Chiên ngập dầu từng mẻ cá phi lê vàng giòn', 'Đun nóng 500 ml dầu ăn trong chảo sâu lòng đến khoảng 180–190°C. Thả từng miếng cá đã áo bột vào chiên thành nhiều mẻ vừa phải, không nhồi chảo; chiên mỗi mẻ 3–4 phút đến khi lớp vỏ vàng giòn và thịt cá chín trắng hoàn toàn bên trong thì vớt ra giấy thấm dầu.', 'Chiên từng mẻ nhỏ giữ nhiệt dầu ổn định để cá giòn rụm; nếu cá hơi mềm trước khi trộn sốt, có thể chiên lại nhanh 30 giây trong dầu nóng già.', 4),
('imp-55201e4225342ca3_v4_step_4', 'imp-55201e4225342ca3', 4, 'cook', 'Phi thơm tỏi gừng và xào dậy màu tương cà cùng rau củ', 'Chắt bớt dầu chiên ra hũ riêng, giữ lại khoảng 15 ml dầu ăn trong chảo trên lửa vừa. Cho tỏi băm và gừng thái lát (nếu dùng) vào phi thơm 30 giây, cho hành tây, ớt chuông, cà chua và dứa chín vào đảo nhanh tay khoảng 1 phút cho rau củ vừa chín giòn.', NULL, 1),
('imp-55201e4225342ca3_v4_step_5', 'imp-55201e4225342ca3', 5, 'sauce', 'Nấu sôi và làm sánh nước sốt chua ngọt', 'Đổ chén nước sốt chua ngọt đã pha vào chảo rau củ, đun sôi nhẹ trên lửa vừa khoảng 2 phút cho các vị hòa quyện. Khuấy đều lại chén bột bắp pha nước rồi rưới từ từ vào chảo, vừa rưới vừa khuấy đều tay đến khi nước sốt sánh bóng vừa đủ bám mặt muỗng.', NULL, 2),
('imp-55201e4225342ca3_v4_step_6', 'imp-55201e4225342ca3', 6, 'finish', 'Xóc nhanh cá chiên với sốt nóng và dọn ngay', 'Trút toàn bộ cá phi lê chiên giòn và hành lá cắt khúc vào chảo sốt, dùng xẻng nhẹ nhàng xúc gập 3–4 lượt cho sốt chua ngọt áo đều từng miếng cá mà không làm nát thịt cá. Tắt bếp và dọn nóng ngay ra đĩa dùng kèm cơm trắng.', 'Chỉ đảo nhanh vài lượt rồi dọn ngay để lớp vỏ cá giữ được độ giòn ngon khi thưởng thức.', NULL),
('imp-6771c725aa163703_v4_step_1', 'imp-6771c725aa163703', 1, 'prep', 'Thấm ráo đậu phụ non', 'Nhẹ tay mở hộp và lấy 450 g đậu phụ non ra ngoài, đặt lên đĩa có lót hai lớp khăn giấy sạch trong 10 phút để hút bớt nước dư, giúp đậu giữ được kết cấu mịn mà không bị loãng sốt.', 'Đậu phụ non rất dễ vỡ, hãy úp nhẹ hộp ra đĩa phẳng thay vì dùng dao nạy từng miếng.', 10),
('imp-6771c725aa163703_v4_step_2', 'imp-6771c725aa163703', 2, 'prep', 'Sơ chế hành lá, tỏi và ớt', 'Rửa sạch hành lá, tách riêng phần đầu hành trắng thái nhỏ và phần lá xanh thái khoanh mỏng (giữ lại một phần nhỏ lá xanh để rắc mặt). Bóc vỏ tỏi rồi băm nhuyễn; ớt hiểm bỏ cuống, bỏ bớt hạt và băm nhỏ.', NULL, NULL),
('imp-6771c725aa163703_v4_step_3', 'imp-6771c725aa163703', 3, 'sauce', 'Trộn nền sốt xì dầu giấm gạo', 'Cho vào chảo nhỏ lúc bếp còn nguội gồm phần đầu hành trắng thái nhỏ, tỏi băm, ớt hiểm băm, 45 ml xì dầu nhạt, 15 ml giấm gạo, 8 g đường nâu và một nửa lượng hạt mè trắng rang, khuấy đều cho đường hòa quyện.', 'Cho toàn bộ nguyên liệu sốt vào chảo nguội ngay từ đầu giúp tỏi và hành tiết hương từ từ mà không bị cháy xém.', NULL),
('imp-6771c725aa163703_v4_step_4', 'imp-6771c725aa163703', 4, 'cook', 'Đun sánh nước sốt thơm nồng', 'Bật bếp lửa vừa, vừa đun vừa khuấy nhẹ đến khi hỗn hợp sôi lăn tăn thì hạ lửa nhỏ, đun liu riu 2 phút cho đường tan hoàn toàn, sốt hơi sánh lại và bay bớt mùi hăng của tỏi sống.', 'Không đun sốt quá lâu khiến nước bốc hơi nhiều làm sốt bị mặn gắt.', 2),
('imp-6771c725aa163703_v4_step_5', 'imp-6771c725aa163703', 5, 'cook', 'Thêm lá hành và dầu mè thơm', 'Cho phần lớn lá hành xanh thái khoanh vào chảo sốt, đảo nhanh tay 30 giây rồi tắt bếp ngay để hành giữ màu xanh mướt. Rưới 10 ml dầu mè thơm vào chảo, khuấy đều khi sốt còn ấm.', NULL, NULL),
('imp-6771c725aa163703_v4_step_6', 'imp-6771c725aa163703', 6, 'finish', 'Cắt đậu, rưới sốt và làm mát', 'Cắt đậu phụ non thành từng khối vuông vừa ăn khoảng 2,5 cm hoặc khía nhẹ thành lát đều trên đĩa sâu lòng. Chan đều nước sốt ấm lên mặt đậu, rắc phần lá hành xanh để riêng cùng số hạt mè trắng rang còn lại, ủ ngăn mát 15 phút trước khi dọn lạnh.', NULL, 15),
('imp-5eb2769876646aae_v4_step_1', 'imp-5eb2769876646aae', 1, 'prep', 'Ép ráo nước và áo bột đậu phụ', 'Bọc 3 bìa đậu phụ cứng trong khăn bếp sạch, đặt vật nặng lên trên ép 20 phút cho ra bớt nước để khi chiên không bị bắn dầu. Cắt đậu thành khối vuông 2 cm, cho vào tô rắc đều 10 g bột bắp cùng 2 g ngũ vị hương rồi xóc nhẹ cho bột phủ thành lớp mỏng.', 'Đậu phụ càng ráo nước thì lớp áo bột bắp càng bám chặt và giữ độ giòn lâu sau khi chiên.', 20),
('imp-5eb2769876646aae_v4_step_2', 'imp-5eb2769876646aae', 2, 'cook', 'Chiên vàng giòn các khối đậu phụ', 'Đun nóng khoảng 135 ml dầu ăn trong chảo sâu lòng trên lửa vừa lớn đến khi đầu đũa sủi tăm. Xếp từng khối đậu phụ thành một lớp không chồng lấn, chiên 8 phút và trở đều các mặt đến khi vỏ ngoài vàng giòn rụm thì vớt ra giá thưa cho ráo dầu.', 'Tuyệt đối không trộn đậu phụ vào mì quá sớm vì hơi ẩm từ sốt sẽ làm lớp vỏ giòn bị ỉu nhanh.', 8),
('imp-5eb2769876646aae_v4_step_3', 'imp-5eb2769876646aae', 3, 'prep', 'Băm tỏi, ớt và pha bát sốt cay', 'Băm nhuyễn tỏi và ớt hiểm; hành lá tách riêng đầu trắng thái nhỏ và lá xanh thái khoanh để riêng. Chắt bớt dầu trong chảo chỉ chừa lại 15 ml, phi thơm đầu hành trắng, tỏi băm và ớt hiểm trong 30 giây trên lửa vừa, rồi trút toàn bộ vào âu lớn cùng 40 ml xì dầu nhạt, 20 ml xì dầu đặc, 20 ml dầu ớt Tứ Xuyên, 8 g đường cát trắng, 10 ml giấm gạo và 5 ml dầu mè thơm, khuấy tan đường.', NULL, NULL),
('imp-5eb2769876646aae_v4_step_4', 'imp-5eb2769876646aae', 4, 'cook', 'Luộc chín tới và giữ nước luộc mì', 'Đun sôi nồi nước lớn với 6 g muối ăn, thả 400 g mì sợi vào luộc 3 phút trên lửa lớn đến khi sợi mì chín tới vẫn còn độ dai nhẹ. Trước khi vớt mì, múc giữ lại 120 ml nước luộc mì nóng, rồi vớt mì ra rổ xả nhanh nước lạnh hoặc xóc ráo cho sợi tơi.', NULL, 3),
('imp-5eb2769876646aae_v4_step_5', 'imp-5eb2769876646aae', 5, 'sauce', 'Trộn mì nóng thấm đều sốt cay', 'Cho mì vừa ráo nước vào âu sốt cay khi mì còn ấm, dùng đũa trộn nhanh tay để từng sợi mì áo đều màu nâu đỏ bóng mượt. Rót từ từ từng muỗng nước luộc mì nóng vào trộn cùng cho đến khi sốt sánh mượt bám sợi.', NULL, NULL);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-5eb2769876646aae_v4_step_6', 'imp-5eb2769876646aae', 6, 'finish', 'Trình bày và thưởng thức giòn ngon', 'Chia mì trộn sốt ra 3 tô, xếp đậu phụ chiên giòn lên trên bề mặt, rắc phần lá hành xanh thái nhỏ và thêm chút dầu ớt nếu thích cay hơn. Dùng nóng hoặc nguội mát đều rất ngon miệng.', 'Giữ phần đậu phụ nằm riêng trên mặt tô giúp người ăn cảm nhận rõ sự tương phản giữa mì mềm đậm đà và đậu giòn rụm.', NULL),
('imp-87adca15ad4c1369_v4_step_1', 'imp-87adca15ad4c1369', 1, 'prep', 'Sơ chế khoai tây, cà rốt, hành tây và đùi gà', 'Khoai tây gọt vỏ, cắt khối cỡ 3–4 cm và tỉa sơ cạnh sắc rồi ngâm ngay vào thau nước lạnh 10 phút cho ra bớt tinh bột, sau đó vớt ráo. Cà rốt cắt vát xoay thành miếng vừa ăn; hành tây bổ múi cau; đùi gà lọc xương còn da cắt miếng cỡ 3–4 cm và hành lá thái nhỏ.', 'Gọt sơ các cạnh sắc của khoai tây (kỹ thuật Mentori) giúp khoai không bị vỡ nát cạnh trong quá trình ninh hầm.', 10),
('imp-87adca15ad4c1369_v4_step_2', 'imp-87adca15ad4c1369', 2, 'cook', 'Xào sơ thịt gà với dầu ăn cho săn thơm', 'Làm nóng nồi rộng đáy dày trên lửa vừa với 10 ml dầu ăn thực vật, cho 350 g đùi gà vào xào khoảng 3 phút đến khi mặt da hơi xém vàng nhẹ và thịt gà săn bên ngoài thì gắp tạm ra đĩa.', 'Xào áp mặt da gà trước giúp tiết bớt mỡ thơm và giữ thịt gà không bị nát khi hầm chung rau củ.', 3),
('imp-87adca15ad4c1369_v4_step_3', 'imp-87adca15ad4c1369', 3, 'cook', 'Xếp rau củ và đun sôi nước hầm Dashi gia vị', 'Xếp hành tây xuống đáy nồi, tiếp đến là cà rốt và cuối cùng đặt khoai tây lên trên cùng. Đổ 500 ml nước dùng Dashi vào nồi cùng 60 ml xì dầu Nhật, 30 ml rượu Mirin, 30 ml rượu Sake nấu ăn và 12 g đường cát trắng, bật lửa lớn đun đến khi nước sôi bùng.', 'Xếp hành tây và cà rốt ở dưới, khoai tây ở lớp trên giúp khoai ít bị va đập và giữ nguyên hình dáng đẹp mắt.', NULL),
('imp-87adca15ad4c1369_v4_step_4', 'imp-87adca15ad4c1369', 4, 'cook', 'Hầm rau củ mềm thấm bằng nắp thả', 'Khi nước dùng sôi, hớt sạch bọt nổi, hạ lửa xuống mức vừa nhỏ, đặt một tờ giấy bạc chọc vài lỗ nhỏ lên sát mặt nguyên liệu (làm nắp thả Otoshibuta) rồi đậy hờ nắp nồi, hầm liu riu 15 phút cho khoai tây và cà rốt gần chín mềm.', 'Nắp thả giúp nước hầm sôi tuần hoàn phủ đều lên bề mặt khoai tây dù lượng nước không quá ngập.', 15),
('imp-87adca15ad4c1369_v4_step_5', 'imp-87adca15ad4c1369', 5, 'cook', 'Cho gà vào hầm chín kỹ và ủ thấm vị', 'Nhấc nắp thả ra, xếp phần đùi gà đã xào sơ vào nồi, rưới nước hầm lên trên và tiếp tục đun liu riu thêm 6–8 phút đến khi thịt gà chín hoàn toàn (không còn màu hồng bên trong) và xiên đũa xuyên qua khoai tây dễ dàng. Tắt bếp, đậy nắp để nồi nghỉ 15 phút cho khoai và thịt thấm sâu gia vị.', 'Để nồi Nikujaga nghỉ nguội bớt 15–20 phút sau khi tắt bếp là bí quyết giúp khoai tây hút trọn vị ngọt mặn từ nước hầm.', 20),
('imp-87adca15ad4c1369_v4_step_6', 'imp-87adca15ad4c1369', 6, 'finish', 'Trình bày bát Nikujaga gà nóng cùng cơm trắng', 'Múc gà hầm cùng khoai tây, cà rốt, hành tây và một ít nước hầm sánh ngọt ra bát sâu lòng, rắc hành lá thái nhỏ lên trên rồi dùng nóng với cơm trắng.', NULL, NULL),
('imp-62d95da722597187_v4_step_1', 'imp-62d95da722597187', 1, 'sauce', 'Pha sốt xì dầu dầu mè giấm gạo và rang mè', 'Cho 60 ml xì dầu Nhật, 25 ml dầu mè rang, 20 ml giấm gạo, 8 g đường cát trắng, 8 g gừng tươi mài nhuyễn và 1 g tiêu đen xay vào bát, khuấy tan đều đường. Đồng thời cho 20 g hạt mè trắng vào chảo khô rang trên lửa vừa khoảng 2 phút đến khi vàng thơm rồi trút ra chén riêng.', 'Khuấy sốt cho tan đường trước khi nấu giúp các gia vị quyện đều ngay khi tiếp xúc với mì nóng.', 2),
('imp-62d95da722597187_v4_step_2', 'imp-62d95da722597187', 2, 'cook', 'Luộc và xả lạnh sợi mì Soba giữ độ dai', 'Đun sôi 1500 ml nước lọc trên lửa lớn, thả 210 g mì Soba kiều mạch vào luộc khoảng 4–5 phút, đảo nhẹ bằng đũa cho sợi mì không dính chùm. Khi mì vừa chín tới (còn hơi dai ở lõi), vớt ngay ra rổ xả dưới vòi nước lạnh kết hợp chà nhẹ cho sạch nhớt bột rồi xóc thật ráo nước.', 'Không luộc mì Soba quá lâu kẻo sợi bị bở đứt; xả nước lạnh ngay giúp mì săn dai.', 5),
('imp-62d95da722597187_v4_step_3', 'imp-62d95da722597187', 3, 'prep', 'Sơ chế nấm đùi gà, hành tím và hành lá', 'Cắt bỏ phần gốc cứng của 350 g nấm đùi gà tươi, dùng khăn ẩm lau sạch bụi bẩn mà không ngâm nước, thái lát dày khoảng 5 mm. Hành tím bóc vỏ băm nhỏ; hành lá thái lát xéo mỏng và chia làm 2 phần.', 'Lau nấm bằng khăn ẩm thay vì rửa ngập nước giúp nấm không bị sũng nước khi áp chảo, lên màu vàng ngon hơn.', NULL),
('imp-62d95da722597187_v4_step_4', 'imp-62d95da722597187', 4, 'cook', 'Áp chảo xào thơm nấm đùi gà cùng hành tím', 'Làm nóng chảo lớn trên lửa vừa lớn với 10 ml dầu ăn thực vật, cho hành tím băm vào phi khoảng 45 giây cho dậy mùi thơm rồi thả nấm đùi gà cùng 1/2 lượng hành lá vào đảo nhanh tay 3–4 phút đến khi nấm xém cạnh vàng nhẹ và chín mềm.', 'Xào nấm trên lửa lớn giúp bề mặt nấm săn vàng và giữ độ giòn ngọt thay vì bị ra nhiều nước.', 4),
('imp-62d95da722597187_v4_step_5', 'imp-62d95da722597187', 5, 'cook', 'Rim nhẹ nước sốt cùng nấm và đảo đều với mì Soba', 'Rót toàn bộ bát sốt đã pha vào chảo nấm, đảo đều khoảng 30 giây cho sốt sôi lăn tăn và áo quanh từng lát nấm. Cho mì Soba đã ráo nước vào chảo, đảo đều nhẹ tay trên lửa nhỏ khoảng 1 phút để sợi mì hút trọn hương vị sốt nấm, thêm 1/2 lượng hạt mè rang và phần hành lá còn lại vào đảo lần cuối rồi tắt bếp.', NULL, NULL),
('imp-62d95da722597187_v4_step_6', 'imp-62d95da722597187', 6, 'finish', 'Trình bày đĩa mì Soba trộn nấm mè', 'Gắp mì Soba trộn nấm ra 3 đĩa hoặc bát nông, rắc nốt phần hạt mè rang còn lại lên trên mặt và thưởng thức ngay khi mì còn ấm thơm hoặc để nguội mát như món mì trộn lạnh.', NULL, NULL),
('imp-d2ab8a9e07388289_v4_step_1', 'imp-d2ab8a9e07388289', 1, 'prep', 'Làm sạch, chần nhanh và khứa vằn thân mực ống', 'Rút bỏ phần nội tạng, túi mực, xương sống trong suốt, bỏ mắt và răng cứng rồi lột sạch lớp màng mỏng bên ngoài 650 g mực ống tươi, giữ nguyên thân và phần râu rồi rửa sạch. Đun sôi nồi nước lọc khoảng 470 ml trên lửa lớn, thả mực vào chần nhanh đúng 15 giây cho thân mực vừa co săn lại thì vớt ngay ra thấm thật khô nước. Dùng dao sắc khứa ngang thân mực các đường cách nhau 1,5 cm sâu khoảng nửa thân mà không cắt đứt rời.', 'Chần nhanh mực trước khi ướp giúp mực không bị chảy nước khi nướng và giữ trọn lớp gừng tỏi ướp ngay trên bề mặt.', NULL),
('imp-d2ab8a9e07388289_v4_step_2', 'imp-d2ab8a9e07388289', 2, 'marinate', 'Ướp gừng tỏi nhẹ lên mực đã chần ráo', 'Trộn đều phần thân và râu mực đã thấm khô với 10 g gừng tươi bào nhuyễn, tỏi băm nhuyễn và 1 g muối ăn, ướp khoảng 10 phút cho mực dậy mùi thơm khử tanh mà không bị mặn gắt trước khi phết sốt Teriyaki.', 'Không ướp quá nhiều muối vì lớp sốt Teriyaki nấu từ xì dầu đã đậm đà sẵn.', 10),
('imp-d2ab8a9e07388289_v4_step_3', 'imp-d2ab8a9e07388289', 3, 'sauce', 'Nấu sốt Teriyaki sánh bóng', 'Cho 60 ml xì dầu Nhật, 60 ml rượu Sake nấu ăn, 40 ml rượu Mirin và 20 g đường nâu vào nồi nhỏ, đun lửa nhỏ và khuấy đều cho đường tan hoàn toàn. Hòa tan 4 g bột bắp với 30 ml nước lọc rồi rót từ từ vào nồi, vừa rót vừa khuấy đều đến khi sốt sôi nhẹ và sánh bóng như lớp siro mỏng thì tắt bếp.', NULL, 5),
('imp-d2ab8a9e07388289_v4_step_4', 'imp-d2ab8a9e07388289', 4, 'cook', 'Làm nóng lò nướng và nướng lượt đầu với sốt', 'Làm nóng trước lò nướng hoặc bếp nướng ở mức 180°C trong 10 phút, lót giấy bạc lên khay nướng rồi phết đều 15 ml dầu ăn thực vật chống dính. Phết một nửa lượng sốt Teriyaki phủ đều lên thân và râu mực, xếp lên khay và nướng trong 5 phút.', 'Phết dầu lên giấy bạc hoặc vỉ nướng giúp lớp sốt đường trên mực không bị dính cháy vào khay.', 5),
('imp-d2ab8a9e07388289_v4_step_5', 'imp-d2ab8a9e07388289', 5, 'cook', 'Phết thêm sốt và nướng xém cạnh hoàn chỉnh', 'Kéo khay mực ra, lật mặt và phết thêm một lớp sốt Teriyaki nữa phủ đều thân mực rồi nướng tiếp 4–5 phút đến khi thịt mực chuyển trắng đục hoàn toàn, mặt ngoài bóng sốt và hơi xém cạnh thơm lừng.', 'Không nướng mực quá 10 phút tổng thời gian vì mực chín quá lửa sẽ bị khô cứng và dai.', 5),
('imp-d2ab8a9e07388289_v4_step_6', 'imp-d2ab8a9e07388289', 6, 'finish', 'Thái khoanh mực nướng và dọn nóng', 'Đặt mực nướng Teriyaki ra thớt cắt thân mực thành từng khoanh tròn dày 1,5 cm, xếp ra đĩa cùng râu mực, rưới phần sốt Teriyaki còn lại lên trên và rắc hành lá thái nhỏ rồi dùng nóng ngay.', NULL, NULL),
('imp-81ff926a5557c059_v4_step_1', 'imp-81ff926a5557c059', 1, 'prep', 'Sơ chế và chia phần cá hồi phi lê', 'Dùng tay miết dọc thớ thịt 510 g cá hồi phi lê để tìm xương dăm và nhổ sạch bằng nhíp, cạo sạch vảy còn sót trên mặt da rồi rửa nhanh và thấm thật khô. Chia cá thành 3 miếng đều nhau khoảng 170 g/miếng để cá chín đồng đều.', 'Giữ nguyên lớp da cá giúp miếng cá giữ dáng đẹp khi nướng và phần thịt sát da thêm béo mềm.', NULL),
('imp-81ff926a5557c059_v4_step_2', 'imp-81ff926a5557c059', 2, 'sauce', 'Trộn hỗn hợp sốt ướp tương Miso trắng', 'Cho 50 g tương Miso trắng Nhật, 25 ml rượu Sake nấu ăn, 25 ml rượu Mirin, 20 ml xì dầu Nhật và 5 ml dầu mè rang vào tô nông, khuấy thật đều tay đến khi tương Miso tan mịn hoàn toàn thành hỗn hợp sốt sệt đồng nhất.', NULL, NULL),
('imp-81ff926a5557c059_v4_step_3', 'imp-81ff926a5557c059', 3, 'marinate', 'Phết sốt Miso và ướp lạnh cá hồi', 'Đặt 3 miếng cá hồi vào khay nông, phết đều hỗn hợp sốt Miso phủ kín cả mặt thịt, hai bên cạnh và mặt da cá. Bọc kín khay bằng màng bọc thực phẩm và ướp trong ngăn mát tủ lạnh từ 1 đến 2 giờ cho thịt cá thấm vị dịu nhẹ.', 'Không nên ướp cá hồi với Miso quá 3 giờ hoặc qua đêm vì độ mặn của tương Miso sẽ làm thịt cá bị gắt và ra nước.', 90),
('imp-81ff926a5557c059_v4_step_4', 'imp-81ff926a5557c059', 4, 'prep', 'Làm nóng lò nướng và gạt sạch sốt Miso thừa', 'Bật lò nướng chế độ lửa trên ở mức 220°C (hoặc làm nóng nồi chiên không dầu 200°C) trước 5 phút, lót giấy bạc lên khay và phết đều 5 ml dầu ăn thực vật chống dính. Lấy cá hồi ra khỏi tủ lạnh, dùng phới dẹt gạt sạch toàn bộ lớp sốt Miso bám trên mặt cá chỉ giữ lại hương vị đã thấm.', 'Gạt sạch sốt Miso thừa trước khi nướng là bước then chốt giúp mặt cá vàng xém hấp dẫn mà không bị cháy đen đắng.', 5),
('imp-81ff926a5557c059_v4_step_5', 'imp-81ff926a5557c059', 5, 'cook', 'Nướng cá hồi vàng xém cạnh và chín mọng', 'Xếp cá hồi lên khay nướng với mặt da úp xuống dưới, đặt khay ở rãnh giữa lò và nướng khoảng 10–12 phút (không cần lật mặt) đến khi thịt cá chuyển màu hồng đục hoàn toàn, mặt trên vàng xém nhẹ và dùng nĩa tách thớ dễ dàng.', 'Cá hồi chín tới sẽ giữ được độ béo mọng bên trong; tránh nướng quá lâu làm thớ cá bị khô xác.', 11),
('imp-81ff926a5557c059_v4_step_6', 'imp-81ff926a5557c059', 6, 'finish', 'Trình bày cá hồi nướng Miso cùng mè rang và hành lá', 'Dùng xẻng nhẹ nhàng gắp cá hồi ra đĩa, rắc hạt mè trắng rang và hành lá thái lát xéo mỏng lên trên, thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-8c6abf9194ba8c45_v4_step_1', 'imp-8c6abf9194ba8c45', 1, 'prep', 'Sơ chế đùi gà, giá đỗ và tỏi băm', 'Thấm thật khô 450 g đùi gà lọc xương còn da, cắt miếng vuông cỡ 3 cm rồi xóc đều với 1 g muối ăn. Giá đỗ tươi rửa sạch, vớt ra rổ xóc kỹ cho thật ráo nước; tỏi khô mài nhuyễn hoặc băm mịn và hành lá thái nhỏ để riêng.', 'Giá đỗ phải để thật ráo nước trước khi cho vào chảo để tránh tiết nước làm món xào bị ướt nhũn.', NULL),
('imp-8c6abf9194ba8c45_v4_step_2', 'imp-8c6abf9194ba8c45', 2, 'cook', 'Áp chảo mặt da đùi gà chín vàng giòn', 'Làm nóng chảo rộng trên lửa vừa với 10 ml dầu mè thơm, xếp các miếng đùi gà úp mặt da xuống chảo không chồng lên nhau, đậy nắp áp chảo khoảng 3 phút cho mặt da vàng giòn và tiết mỡ thơm.', 'Đậy nắp khi áp mặt da giúp hơi nóng làm thịt gà chín đều bên trong mà phần da vẫn giòn đẹp.', 3),
('imp-8c6abf9194ba8c45_v4_step_3', 'imp-8c6abf9194ba8c45', 3, 'cook', 'Lật mặt áp chín gà hoàn toàn', 'Mở nắp, lật mặt thịt gà xuống và áp thêm khoảng 3 phút đến khi gà chín hoàn toàn bên trong, mặt ngoài vàng đều không còn nước đỏ thì gắp gà ra tô riêng, giữ nguyên phần mỡ gà thơm trong chảo.', NULL, 3),
('imp-8c6abf9194ba8c45_v4_step_4', 'imp-8c6abf9194ba8c45', 4, 'marinate', 'Trộn thịt gà nóng với sốt xì dầu và tỏi mài', 'Cho 35 ml xì dầu Nhật và tỏi băm nhuyễn vào tô thịt gà đang còn nóng, đảo trộn đều tay và để yên 2 phút cho từng miếng thịt gà hút đậm hương vị tỏi xì dầu.', 'Trộn sốt xì dầu tỏi vào gà ngay khi gà còn nóng giúp thịt thấm vị sâu mà không làm cháy tỏi trong chảo.', 2),
('imp-8c6abf9194ba8c45_v4_step_5', 'imp-8c6abf9194ba8c45', 5, 'cook', 'Xào nhanh giá đỗ trên lửa lớn giữ độ giòn', 'Bật lửa lớn làm nóng lại phần mỡ gà trong chảo, trút toàn bộ 300 g giá đỗ vào cùng 4 g hạt nêm gà, đảo nhanh tay khoảng 1–2 phút đến khi giá vừa hơi trong nhẹ mà vẫn giữ nguyên độ giòn sần sật.', 'Chỉ xào giá đỗ trên lửa lớn trong thời gian ngắn; xào quá 2 phút giá sẽ mềm nhũn và ra nước.', NULL),
('imp-8c6abf9194ba8c45_v4_step_6', 'imp-8c6abf9194ba8c45', 6, 'finish', 'Đảo quyện gà với giá đỗ và dọn nóng', 'Trút thịt gà cùng toàn bộ nước sốt tỏi xì dầu trở lại chảo giá đỗ, đảo nhanh tay 30 giây cho sốt áo đều gà và giá rồi tắt bếp ngay. Múc ra đĩa, rắc hành lá thái nhỏ cùng tiêu đen xay lên trên và thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-b33750551f6ea7fe_v4_step_1', 'imp-b33750551f6ea7fe', 1, 'prep', 'Lau sạch và thái khoanh khía caro nấm đùi gà', 'Cắt bỏ phần gốc cứng của 300 g nấm đùi gà tươi, dùng khăn ẩm lau sạch bụi đất mà không ngâm nước. Thái thân nấm thành từng khoanh tròn dày khoảng 1,5–2 cm, dùng mũi dao khía nhẹ hình mắt lưới caro lên một mặt khoanh nấm và thái nhỏ hành lá để riêng.', 'Thái nấm thành khoanh dày và không rửa ngập nước giúp nấm giữ được độ giòn sần sật như sò điệp áp chảo.', NULL),
('imp-b33750551f6ea7fe_v4_step_2', 'imp-b33750551f6ea7fe', 2, 'cook', 'Làm tan chảy bơ với dầu ăn trên chảo nóng', 'Làm nóng chảo rộng trên lửa vừa, cho 8 ml dầu ăn thực vật và 25 g bơ lạt vào, lắc nhẹ chảo đến khi bơ tan chảy hoàn toàn và bắt đầu sủi bọt lăn tăn thơm béo.', 'Pha thêm một chút dầu ăn cùng bơ lạt giúp nâng điểm khói, tránh làm bơ chuyển màu cháy đen khi áp chảo.', NULL),
('imp-b33750551f6ea7fe_v4_step_3', 'imp-b33750551f6ea7fe', 3, 'cook', 'Áp chảo mặt khía caro của nấm vàng nâu', 'Xếp các khoanh nấm thành một lớp đều trên chảo (mặt khía caro úp xuống), không xếp chồng lên nhau, chiên yên trên lửa vừa khoảng 3 phút đến khi mặt nấm chuyển màu vàng nâu đẹp mắt và hơi xém cạnh.', 'Không đảo nấm liên tục và không xếp chồng để nấm được áp chảo trực tiếp thay vì bị hấp hơi chảy nước.', 3),
('imp-b33750551f6ea7fe_v4_step_4', 'imp-b33750551f6ea7fe', 4, 'cook', 'Lật mặt nấm áp vàng và nêm muối tiêu', 'Lật ngược các khoanh nấm sang mặt còn lại, áp chảo thêm khoảng 2–3 phút đến khi hai mặt đều vàng nâu hấp dẫn rồi rắc đều 1,5 g muối ăn và 1 g tiêu đen xay lên mặt nấm.', NULL, 3),
('imp-b33750551f6ea7fe_v4_step_5', 'imp-b33750551f6ea7fe', 5, 'sauce', 'Rưới xì dầu quanh mép chảo tạo hương Shoyu thơm lừng', 'Rưới 10 ml xì dầu Nhật chạy dọc theo thành chảo nóng để xì dầu bốc hơi thơm nức, lập tức nghiêng và lắc nhẹ chảo trong 15 giây cho phần sốt bơ xì dầu áo bóng đều quanh từng khoanh nấm.', 'Rưới xì dầu vào mép chảo nóng thay vì đổ thẳng lên nấm giúp bốc mùi thơm cháy cạnh đặc trưng của món Nhật.', NULL),
('imp-b33750551f6ea7fe_v4_step_6', 'imp-b33750551f6ea7fe', 6, 'finish', 'Trộn hành lá và dọn đĩa nấm nướng bơ Shoyu nóng', 'Cho hành lá thái nhỏ vào đảo nhanh 5 giây rồi tắt bếp ngay. Gắp nấm ra đĩa ấm, rưới hết phần bơ xì dầu trong chảo lên trên và thưởng thức nóng kèm cơm trắng hoặc làm món khai vị.', NULL, NULL),
('imp-e9562581c7d79169_v4_step_1', 'imp-e9562581c7d79169', 1, 'prep', 'Vo gạo và pha nước gia vị nấu cơm Nhật', 'Vo nhẹ 300 g gạo hạt ngắn Nhật 2–3 lần nước cho sạch rồi để ráo, cho vào lòng nồi cơm điện. Đổ 360 ml nước lọc cùng 18 ml xì dầu Nhật, 15 ml rượu Sake nấu ăn và 5 g hạt nêm gà vào khuấy nhẹ cho gia vị tan đều, ngâm 15 phút.', 'Bớt nhẹ một chút nước lọc so với nấu cơm trắng thông thường vì đã có thêm xì dầu và rượu Sake, giúp hạt cơm chín tơi ráo.', 15),
('imp-e9562581c7d79169_v4_step_2', 'imp-e9562581c7d79169', 2, 'cook', 'Bật nấu cơm chín dẻo thơm vị nước dùng', 'Đậy nắp nồi cơm điện, bật chế độ nấu cơm tiêu chuẩn và nấu khoảng 30–35 phút cho đến khi nồi chuyển sang chế độ giữ ấm.', NULL, 35),
('imp-e9562581c7d79169_v4_step_3', 'imp-e9562581c7d79169', 3, 'prep', 'Xé tơi thịt cua, thái hành lá và đánh trứng Mayonnaise', 'Trong lúc chờ cơm chín, kiểm tra nhặt sạch mảnh vỏ cứng còn sót trong 200 g thịt cua tươi và xé tơi nhẹ dọc thớ thịt, rửa sạch và thái nhỏ hành lá. Đập 2 quả trứng gà ra bát, cho 8 g sốt Mayonnaise vào đánh tan đều cho đến khi hòa quyện mịn.', 'Trộn thêm chút sốt Mayonnaise vào trứng giúp trứng khi hấp trên cơm nóng sẽ bông xốp và giữ độ mềm ẩm rất ngon.', NULL),
('imp-e9562581c7d79169_v4_step_4', 'imp-e9562581c7d79169', 4, 'cook', 'Trộn thịt cua, hành lá và dầu mè vào cơm nóng', 'Ngay khi cơm vừa chín tới còn đang bốc hơi nóng, mở nắp nồi và rải toàn bộ thịt cua tươi, 2/3 lượng hành lá thái nhỏ cùng 12 ml dầu mè thơm vào, dùng muôi xới nhẹ từ dưới lên cho đều.', 'Thực hiện thao tác nhanh tay để giữ nhiệt độ nóng hổi trong nồi cho bước hấp chín hoàn toàn thịt cua và trứng tiếp theo.', NULL),
('imp-e9562581c7d79169_v4_step_5', 'imp-e9562581c7d79169', 5, 'cook', 'Hấp chín kỹ thịt cua và hỗn hợp trứng gà', 'Rưới đều bát trứng gà đánh Mayonnaise phủ khắp bề mặt cơm và cua đang nóng, lập tức đậy kín nắp nồi và bật lại chế độ nấu thêm 3 phút rồi để ủ kín thêm 4–5 phút cho đến khi thịt cua chín thơm nóng đều và trứng chín hẳn, đông tơi mềm mịn.', 'Đảm bảo thịt cua và trứng gà được hấp chín kỹ hoàn toàn bằng hơi nóng trước khi mở nắp trộn cơm.', 8),
('imp-e9562581c7d79169_v4_step_6', 'imp-e9562581c7d79169', 6, 'finish', 'Nêm muối tiêu, xới tơi và dọn cơm cua Kanimeshi', 'Mở nắp nồi, rắc 2 g muối ăn và 0,5 g tiêu đen xay vào rồi xới tơi nhẹ nhàng cho cơm, thịt cua và trứng chín quyện đều. Múc ra 3 bát, rắc nốt phần hành lá thái nhỏ còn lại lên trên và dùng nóng ngay.', NULL, NULL),
('imp-ee7ca138c67f4f24_v4_step_1', 'imp-ee7ca138c67f4f24', 1, 'marinate', 'Sơ chế và ướp thịt bò áo tinh bột khoai tây', 'Cắt 250 g thịt bò thái lát mỏng thành miếng vừa ăn khoảng 4 cm. Cho thịt bò vào tô cùng 15 ml rượu Sake nấu ăn, 1 g muối ăn, 1 g tiêu đen xay và 4 g tinh bột khoai tây, dùng tay bóp trộn nhẹ cho gia vị và lớp tinh bột áo đều quanh từng lát thịt, để thấm 10 phút.', 'Lớp tinh bột khoai tây mỏng giúp khóa độ ẩm bên trong thớ thịt bò, đồng thời làm nước sốt tự nhiên sánh nhẹ khi xào.', 10),
('imp-ee7ca138c67f4f24_v4_step_2', 'imp-ee7ca138c67f4f24', 2, 'prep', 'Chuẩn bị hành tây, gừng tươi hai kiểu và hành lá', 'Hành tây bóc vỏ, bổ múi cau dày 1,5 cm. Gừng tươi cạo thật mỏng lớp vỏ ngoài; chia 30 g gừng làm hai phần, một nửa thái sợi mảnh và một nửa mài nhuyễn; hành lá rửa sạch thái nhỏ để riêng.', 'Gọt vỏ gừng thật mỏng giúp giữ lại phần tinh dầu thơm nhất nằm ngay dưới lớp vỏ.', NULL),
('imp-ee7ca138c67f4f24_v4_step_3', 'imp-ee7ca138c67f4f24', 3, 'sauce', 'Pha bát nước sốt Sake Mirin xì dầu cân bằng', 'Cho 30 ml xì dầu Nhật, 30 ml rượu Mirin, 30 ml rượu Sake nấu ăn còn lại và 4 g đường cát trắng vào chén, khuấy đều đến khi đường tan hoàn toàn.', 'Pha sẵn nước sốt trước khi bật bếp giúp thao tác xào diễn ra liên tục nhanh gọn, thịt bò không bị quá lửa.', NULL),
('imp-ee7ca138c67f4f24_v4_step_4', 'imp-ee7ca138c67f4f24', 4, 'cook', 'Xào nhanh thịt bò với dầu mè rồi hấp mềm hành tây', 'Làm nóng chảo trên lửa vừa với 10 ml dầu mè thơm, cho thịt bò đã ướp vào đảo nhanh khoảng 1–2 phút đến khi thịt vừa đổi màu hết đỏ tái. Lập tức thả hành tây bổ múi cau vào đảo đều, đậy nắp chảo và hạ lửa nhỏ hấp-xào khoảng 3 phút cho hành tây mềm dịu và tiết vị ngọt.', 'Đậy nắp hạ lửa nhỏ giúp hành tây chín mềm ngọt nhanh mà không làm thịt bò bị khô xơ.', 3),
('imp-ee7ca138c67f4f24_v4_step_5', 'imp-ee7ca138c67f4f24', 5, 'cook', 'Đảo quyện nước sốt gừng sánh bóng', 'Mở nắp chảo, vặn lên lửa vừa lớn, rót toàn bộ bát nước sốt đã pha cùng cả phần gừng thái sợi và gừng mài nhuyễn vào chảo. Đảo nhanh tay khoảng 1–2 phút đến khi nước sốt sôi sệt lại, bám bóng đều quanh thịt bò và hành tây thì tắt bếp.', NULL, 2),
('imp-ee7ca138c67f4f24_v4_step_6', 'imp-ee7ca138c67f4f24', 6, 'finish', 'Trình bày đĩa bò xào gừng Itame dùng nóng', 'Múc bò xào gừng hành tây ra đĩa nóng, rắc hành lá thái nhỏ lên trên rồi dùng ngay với cơm trắng nóng hổi.', NULL, NULL),
('imp-57a8ece15d731efb_v4_step_1', 'imp-57a8ece15d731efb', 1, 'prep', 'Sơ chế bắp cải, nấm đùi gà và ngâm rong biển Wakame', 'Rửa sạch 240 g bắp cải xanh, bỏ phần lõi cứng và cắt thành miếng vuông cỡ 2 cm (để riêng phần cọng dày nếu có). Nấm đùi gà lau sạch, cắt lát dày 5 mm; rong biển Wakame khô ngâm nước lạnh 5 phút cho nở mềm rồi vắt ráo; hành lá thái lát xéo mỏng.', 'Tách riêng phần cọng bắp cải dày để cho vào nồi trước giúp cả cọng và lá chín mềm đồng đều.', 5),
('imp-57a8ece15d731efb_v4_step_2', 'imp-57a8ece15d731efb', 2, 'cook', 'Đun sôi nước dùng Dashi và nấu mềm bắp cải cùng nấm', 'Đổ 650 ml nước dùng Dashi vào nồi vừa, đậy nắp đun sôi trên lửa vừa. Khi nước vừa sôi lăn tăn, hạ lửa vừa nhỏ rồi thả bắp cải (cho phần cọng vào trước 1 phút) và nấm đùi gà vào nồi, đậy nắp nấu liu riu khoảng 4–5 phút cho đến khi bắp cải chín mềm ngọt và nấm chín đều.', 'Nấu bắp cải và nấm ở mức sôi liu riu giữ cho nước dùng trong veo và rau củ giữ trọn vị ngọt tự nhiên.', 5),
('imp-57a8ece15d731efb_v4_step_3', 'imp-57a8ece15d731efb', 3, 'cook', 'Thả rong biển Wakame vào nồi canh', 'Mở nắp nồi, thả phần rong biển Wakame đã ngâm nở vào khuấy nhẹ khoảng 30 giây cho rong biển nóng đều rồi tắt bếp ngay.', 'Không đun rong biển Wakame quá lâu trên lửa để tránh rong biển bị nhũn và mất màu xanh đẹp.', NULL),
('imp-57a8ece15d731efb_v4_step_4', 'imp-57a8ece15d731efb', 4, 'sauce', 'Hòa tan tương Miso sau khi tắt bếp', 'Đặt rây lọc nhỏ (hoặc vá múc canh) chạm mặt nước dùng đang nóng trong nồi, cho 55 g tương Miso Nhật vào và dùng đũa hoặc thìa tán nhẹ cho tương Miso tan mịn hoàn toàn vào nước canh mà không bị vón cục.', 'Luôn tắt bếp trước khi hòa tương Miso và không đun sôi lại nồi súp để giữ nguyên lợi khuẩn và hương thơm tinh tế của Miso.', NULL),
('imp-57a8ece15d731efb_v4_step_5', 'imp-57a8ece15d731efb', 5, 'sauce', 'Nếm chỉnh vị canh với xì dầu Nhật', 'Khuấy nhẹ nồi súp Miso rồi nếm thử; nếu thích vị đậm đà hơn có thể thêm 5 ml xì dầu Nhật (tránh nêm mặn quá vì tương Miso vốn đã có vị mặn dịu).', NULL, NULL),
('imp-57a8ece15d731efb_v4_step_6', 'imp-57a8ece15d731efb', 6, 'finish', 'Múc súp Miso ra bát và hoàn thiện', 'Múc súp Miso bắp cải nấm ra 3 bát, rắc hành lá thái lát xéo lên trên và nhỏ nhẹ 5 ml dầu mè thơm chia đều vào các bát, dùng nóng ngay.', NULL, NULL),
('imp-23a82881883d70fb_v4_step_1', 'imp-23a82881883d70fb', 1, 'prep', 'Ngâm tảo bẹ Kombu và nấm hương khô lấy vị Dashi', 'Lau nhẹ 6 g tảo bẹ Kombu khô bằng khăn ẩm sạch, rửa nhanh 25 g nấm hương khô rồi cho cả hai vào nồi với 900 ml nước lọc lạnh, ngâm tối thiểu 30 phút để Kombu và nấm hương tiết ra vị ngọt umami tự nhiên.', 'Ngâm lạnh trước khi đun giúp tảo bẹ Kombu tiết tối đa vị ngọt thanh mà không cần nấu sôi lâu.', 30),
('imp-23a82881883d70fb_v4_step_2', 'imp-23a82881883d70fb', 2, 'cook', 'Nấu nước dùng Dashi chay và vớt tảo bẹ Kombu', 'Bắc nồi nước ngâm lên bếp lửa vừa, canh ngay khi mặt nước bắt đầu sủi tăm nhẹ chuẩn bị sôi thì vớt bỏ miếng tảo bẹ Kombu ra ngoài. Tiếp tục đun sôi liu riu trên lửa nhỏ 10 phút cho nấm hương mềm ngọt, sau đó vớt nấm hương ra thái lát mỏng để lại vào tô.', 'Vớt tảo bẹ Kombu trước khi nước sôi bùng giúp nước dùng Dashi trong veo và không bị nhớt hoặc đắng.', 10),
('imp-23a82881883d70fb_v4_step_3', 'imp-23a82881883d70fb', 3, 'prep', 'Sơ chế nấm đùi gà, đậu phụ chiên và hành lá', 'Trong lúc nấu nước dùng, lau sạch 200 g nấm đùi gà tươi rồi thái lát dày 5 mm. Đậu phụ chiên sẵn cắt miếng vuông vừa ăn dày 1,5 cm (có thể dội qua chút nước sôi cho bớt dầu); hành lá thái khoanh mỏng để riêng.', 'Thái lát nấm đùi gà dày 5 mm giúp nấm giữ được độ giòn ngọt sần sật khi nấu trong nước dùng.', NULL),
('imp-23a82881883d70fb_v4_step_4', 'imp-23a82881883d70fb', 4, 'cook', 'Nêm nước dùng Dashi chay và nấu nấm đùi gà, đậu phụ', 'Nêm vào nồi nước dùng 22 ml xì dầu Nhật, 22 ml rượu Mirin, 6 g đường cát trắng và 2 g muối ăn, khuấy tan rồi nếm lại vừa miệng. Thả nấm đùi gà và đậu phụ chiên vào nồi nước dùng sôi nhẹ, nấu lửa vừa 4 phút cho nấm chín mềm và đậu phụ thấm vị ngọt thanh.', NULL, 4),
('imp-23a82881883d70fb_v4_step_5', 'imp-23a82881883d70fb', 5, 'cook', 'Luộc riêng mì Udon trong nước sôi', 'Đun sôi 600 ml nước lọc còn lại trong một nồi riêng trên lửa lớn, thả 3 gói mì Udon vào luộc khoảng 2–3 phút, dùng đũa khuấy nhẹ cho sợi mì tơi rời, trong dai rồi vớt ra xả nhanh qua nước ấm và xóc thật ráo nước.', 'Luôn luộc mì Udon ở nồi riêng thay vì luộc thẳng vào nước dùng để nước Dashi chay giữ được độ trong thanh.', 3),
('imp-23a82881883d70fb_v4_step_6', 'imp-23a82881883d70fb', 6, 'finish', 'Trình bày tô mì Udon nấm đậu nóng hổi', 'Chia mì Udon đã ráo nước ra 3 tô lớn, xếp nấm hương thái lát, nấm đùi gà và đậu phụ chiên lên mặt mì, chan ngập nước dùng Dashi đang nóng sôi rồi rắc hành lá thái khoanh lên trên và dùng ngay.', NULL, NULL),
('imp-85a3d8b84fc0bc05_v4_step_1', 'imp-85a3d8b84fc0bc05', 1, 'prep', 'Sơ chế kim chi, hành tỏi và phô mai', 'Thái nhỏ 160 g kim chi cải thảo ủ chua và chắt riêng khoảng 50 ml nước kim chi. Thái lát hành tím khô, băm nhỏ tỏi khô, thái nhỏ hành lá tươi (tách riêng đầu trắng và lá xanh), chuẩn bị sẵn 50 g phô mai Cheddar bào sợi.', NULL, NULL),
('imp-85a3d8b84fc0bc05_v4_step_2', 'imp-85a3d8b84fc0bc05', 2, 'cook', 'Phi thơm hành tỏi và xào kim chi', 'Làm nóng nồi trên lửa vừa với 10 ml dầu thực vật và 10 ml dầu mè rang, cho hành tím khô thái lát, tỏi khô băm nhỏ và đầu hành trắng vào phi thơm 1 phút. Tiếp tục cho kim chi cải thảo cùng 3 g ớt bột Hàn Quốc (Gochugaru) vào đảo đều 2 phút cho kim chi dậy mùi thơm nồng.', 'Xào kim chi với chút dầu mè trước khi đổ nước giúp nước dùng mì có mùi thơm sâu và màu sắc hấp dẫn.', 3),
('imp-85a3d8b84fc0bc05_v4_step_3', 'imp-85a3d8b84fc0bc05', 3, 'cook', 'Nấu sôi nước dùng kim chi đậm vị', 'Rót 800 ml nước lọc cùng phần nước kim chi vào nồi, nêm 6 g hạt nêm vị gà và 3 g đường cát trắng, khuấy đều và đun trên lửa lớn khoảng 3–4 phút cho đến khi nước dùng sôi bùng.', NULL, 4),
('imp-85a3d8b84fc0bc05_v4_step_4', 'imp-85a3d8b84fc0bc05', 4, 'cook', 'Nấu mì ramen vừa chín dai', 'Thả 200 g mì ramen Hàn Quốc (2 vắt mì) vào nồi nước dùng đang sôi, nấu khoảng 2 phút trên lửa vừa đồng thời dùng đũa tách nhẹ cho sợi mì tơi ra nhưng vẫn giữ độ dai giòn.', 'Chỉ nấu mì khoảng 2 phút trước khi cho trứng để tổng thời gian nấu không làm mì bị nhũn nát.', 2),
('imp-85a3d8b84fc0bc05_v4_step_5', 'imp-85a3d8b84fc0bc05', 5, 'cook', 'Đập trứng gà và phủ phô mai Cheddar', 'Hạ lửa nhỏ, gạt nhẹ mì sang hai bên để tạo hai khoảng trống rồi đập 2 quả trứng gà tươi vào nồi, đậy nắp nấu thêm 2 phút cho lòng trắng chín đông còn lòng đỏ sánh lòng đào. Mở nắp, rải đều 50 g phô mai Cheddar bào sợi lên mặt mì rồi đậy nắp thêm 30 giây cho phô mai tan chảy.', 'Phủ phô mai ở bước cuối trên lửa thật nhỏ giúp phô mai tan mịn quyện vào sợi mì mà không bị tách dầu.', 2),
('imp-85a3d8b84fc0bc05_v4_step_6', 'imp-85a3d8b84fc0bc05', 6, 'finish', 'Rưới dầu mè, rắc hành lá và thưởng thức', 'Tắt bếp, rưới 5 ml dầu mè rang còn lại và rắc phần hành lá xanh thái khoanh lên mặt nồi mì; dùng nóng ngay để cảm nhận trọn vẹn vị cay ấm hòa cùng phô mai béo ngậy.', NULL, NULL),
('imp-9d28abab0b8e5619_v4_step_1', 'imp-9d28abab0b8e5619', 1, 'prep', 'Sơ chế đùi gà, kim chi và rau củ', 'Rửa sạch 750 g đùi gà có xương chặt miếng, để ráo và khứa nhẹ vài đường trên thịt để nhanh thấm sốt. Cắt đôi theo chiều dọc 500 g kim chi cải thảo ủ chua kỹ và chắt giữ khoảng 60 ml nước kim chi. Thái múi cau hành tây, cắt khúc 4 cm hành lá tươi.', 'Giữ nguyên bẹ kim chi dài hoặc chỉ cắt làm đôi giúp kim chi khi hầm 30 phút vẫn còn độ mềm dai chứ không bị vụn.', NULL),
('imp-9d28abab0b8e5619_v4_step_2', 'imp-9d28abab0b8e5619', 2, 'sauce', 'Pha hỗn hợp sốt om Gochujang đậm đà', 'Trong tô vừa, khuấy đều 36 g tương ớt Hàn Quốc (Gochujang), 7 g ớt bột Hàn Quốc (Gochugaru), 30 ml nước tương, 15 ml nước mắm cá cơm, 12 g đường cát trắng, 15 ml rượu nấu ăn, 1 g tiêu đen xay, tỏi khô băm nhuyễn và phần nước kim chi cho hòa quyện hoàn toàn.', NULL, NULL),
('imp-9d28abab0b8e5619_v4_step_3', 'imp-9d28abab0b8e5619', 3, 'cook', 'Xếp kim chi, thịt gà và đun sôi nồi hầm', 'Lót một lớp kim chi cải thảo xuống đáy nồi rộng, xếp các miếng đùi gà và hành tây lên trên rồi phủ phần kim chi còn lại xung quanh. Rưới đều tô sốt Gochujang và rót 450 ml nước lọc vào nồi, đậy nắp đun lửa lớn 5 phút đến khi sôi bùng.', 'Xếp kim chi lót đáy nồi vừa giúp thịt gà không bị bén đáy, vừa để kim chi thấm mỡ gà tiết ra rất ngọt.', 5),
('imp-9d28abab0b8e5619_v4_step_4', 'imp-9d28abab0b8e5619', 4, 'cook', 'Hầm liu riu cho đùi gà chín mềm thấm sốt', 'Hạ lửa vừa-nhỏ, đậy nắp hầm 25 phút cho đến khi thịt đùi gà chín mềm hoàn toàn sát xương (không còn nước hồng khi xăm đũa) và kim chi dịu vị chua. Trong quá trình hầm, thỉnh thoảng mở nắp múc nước sốt rưới đều lên mặt thịt gà.', NULL, 25),
('imp-9d28abab0b8e5619_v4_step_5', 'imp-9d28abab0b8e5619', 5, 'cook', 'Cô sánh nước sốt và thêm hành lá', 'Mở nắp nồi, tăng lên lửa vừa nấu thêm 5 phút để phần nước sốt rút bớt, sánh đỏ bóng mượt áo đều lên từng miếng gà và kim chi. Thả hành lá tươi cắt khúc vào đảo nhẹ cho vừa chín tới.', 'Canh độ sánh của sốt theo sở thích: nếu thích chan nhiều nước sốt ăn cơm thì có thể tắt bếp sớm hơn 2 phút.', 5),
('imp-9d28abab0b8e5619_v4_step_6', 'imp-9d28abab0b8e5619', 6, 'finish', 'Rưới dầu mè và dọn nóng', 'Tắt bếp, rưới 10 ml dầu mè rang lên khắp bề mặt nồi gà hầm kim chi, dọn nóng ngay ra bàn cùng cơm trắng nóng hổi.', NULL, NULL),
('imp-2842fe1b767de23d_v4_step_1', 'imp-2842fe1b767de23d', 1, 'prep', 'Băm nhuyễn cà rốt, hành lá và đánh mịn trứng', 'Thái hạt lựu thật nhỏ 27,5 g cà rốt (khoảng 2 mm) và thái nhuyễn 20 g hành lá tươi. Đập 4 quả trứng gà tươi vào tô, thêm 15 ml sữa tươi không đường, 2 g muối ăn và 0,5 g tiêu đen xay rồi đánh tan đều tay. Nên lọc hỗn hợp trứng qua rây rồi mới trộn cà rốt và hành lá vào.', 'Lọc trứng qua rây trước khi trộn rau giúp loại bỏ lợn cợn lòng trắng, bề mặt cuộn trứng láng mịn và dễ cuộn hơn.', NULL),
('imp-2842fe1b767de23d_v4_step_2', 'imp-2842fe1b767de23d', 2, 'cook', 'Đổ và cuộn lớp trứng đầu tiên', 'Làm nóng chảo chống dính đáy phẳng trên lửa nhỏ, dùng giấy thấm phết một lớp mỏng dầu thực vật (khoảng 3 ml). Khuấy đều tô trứng để cà rốt không lắng đáy, rót 1/3 lượng trứng láng kín mặt chảo. Đợi khoảng 1,5 phút khi mặt dưới chín vàng nhẹ còn mặt trên hơi ướt thì nhẹ nhàng cuộn tròn từ một mép chảo sang mép đối diện.', 'Luôn giữ lửa nhỏ trong suốt quá trình tráng để trứng chín từ từ mà không bị cháy sạm hay rỗ mặt.', 2),
('imp-2842fe1b767de23d_v4_step_3', 'imp-2842fe1b767de23d', 3, 'cook', 'Nối thêm lớp trứng thứ hai dày đều', 'Đẩy cuộn trứng về sát mép chảo, phết thêm 3 ml dầu thực vật lên phần mặt chảo trống. Rót tiếp 1/3 lượng trứng vào, nghiêng nhẹ chảo cho trứng chảy vào phần mép dưới cuộn đầu tiên để kết dính. Chờ 1,5 phút cho lớp mới chín tới rồi cuộn ngược lại ôm trọn lớp cũ.', NULL, 2),
('imp-2842fe1b767de23d_v4_step_4', 'imp-2842fe1b767de23d', 4, 'cook', 'Cuộn lớp trứng cuối và ép tạo dáng bầu dục', 'Phết nốt 4 ml dầu thực vật lên phần chảo trống, rót 1/3 lượng trứng còn lại vào nối mép và chiên 1,5 phút rồi cuộn tiếp thành khối trứng dày chắc. Ép nhẹ bốn mặt cuộn trứng vào thành chảo khoảng 30 giây mỗi mặt để định hình dáng chữ nhật hoặc bầu dục gọn đẹp và trứng chín hoàn toàn bên trong.', NULL, 2),
('imp-2842fe1b767de23d_v4_step_5', 'imp-2842fe1b767de23d', 5, 'prep', 'Ủ nguội nhẹ cho khối trứng định hình', 'Gắp cuộn trứng ra thớt hoặc mành tre, cuộn nhẹ giữ dáng trong 3 phút cho hơi nóng tản bớt và kết cấu trứng ổn định chắc chắn trước khi cắt.', 'Để trứng nghỉ 3 phút sau khi chiên giúp lát cắt sắc gọn, các lớp trứng không bị tách rời.', NULL),
('imp-2842fe1b767de23d_v4_step_6', 'imp-2842fe1b767de23d', 6, 'finish', 'Cắt khoanh vừa ăn và dọn kèm xì dầu', 'Dùng dao sắc cắt cuộn trứng Gyeran Mari thành từng khoanh dày khoảng 2 cm, xếp nghiêng đẹp mắt lên đĩa và dọn kèm chén nước tương chấm nhẹ hoặc ăn cùng cơm nóng.', NULL, NULL),
('imp-412960b58d00d211_v4_step_1', 'imp-412960b58d00d211', 1, 'prep', 'Sơ chế tôm tươi, nấm đùi gà và rau gia vị', 'Bóc vỏ, bỏ đầu và rút sạch chỉ đen lưng 350 g tôm tươi, rửa nhanh nước muối loãng rồi để ráo. Thái hạt lựu nhỏ hành tây, thái lát mỏng nấm đùi gà tươi, băm nhuyễn tỏi khô và đầu hành trắng; phần lá xanh hành lá tươi thái khoanh, ớt hiểm đỏ thái lát chéo.', NULL, NULL),
('imp-412960b58d00d211_v4_step_2', 'imp-412960b58d00d211', 2, 'cook', 'Chưng dầu ớt Gochugaru thơm không khét', 'Làm nóng nồi đất hoặc nồi đáy dày trên lửa nhỏ với 15 ml dầu thực vật và 15 ml dầu mè rang, cho đầu hành trắng, tỏi khô băm nhuyễn và hành tây vào đảo 2 phút cho thơm mềm. Tắt hoặc hạ lửa thật nhỏ, cho 24 g ớt bột Hàn Quốc (Gochugaru) vào đảo đều 1 phút thành hỗn hợp dầu ớt đỏ sẫm thơm lừng.', 'Chưng ớt bột Gochugaru ở lửa thật nhỏ để chiết xuất màu đỏ đẹp mà không bị cháy khét gây vị đắng.', 3),
('imp-412960b58d00d211_v4_step_3', 'imp-412960b58d00d211', 3, 'cook', 'Xào tôm và nấu nước dùng cá cơm tảo bẹ', 'Tăng lên lửa vừa, cho tôm tươi và nấm đùi gà tươi vào đảo nhanh 1–2 phút cho tôm vừa chuyển sắc hồng nhẹ, sau đó rót 700 ml nước dùng cá cơm tảo bẹ vào nồi. Nêm 30 ml nước mắm cá cơm và 1 g tiêu đen xay, đun sôi trên lửa lớn.', NULL, 4),
('imp-412960b58d00d211_v4_step_4', 'imp-412960b58d00d211', 4, 'cook', 'Thả đậu phụ non thành từng khối lớn', 'Khi nồi canh sôi bùng và tôm đã chín săn chuyển đỏ đều, nhẹ nhàng múc từng muỗng lớn 600 g đậu phụ non Hàn Quốc (Sundubu) thả vào nồi. Hạ lửa vừa-nhỏ, nấu liu riu khoảng 4 phút cho đậu phụ nóng xuyên tâm và ngấm nước dùng cay thơm.', 'Không khuấy mạnh sau khi cho đậu phụ non để giữ từng mảng đậu to mềm mượt, tan nhẹ khi múc.', 4),
('imp-412960b58d00d211_v4_step_5', 'imp-412960b58d00d211', 5, 'cook', 'Đập trứng gà tươi trực tiếp vào nồi canh', 'Đập nhẹ 3 quả trứng gà tươi vào các khoảng trống trên mặt nồi canh, đậy nắp nấu thêm 2 phút trên lửa nhỏ để lòng trắng chín đông còn lòng đỏ sánh lòng đào (hoặc nấu thêm 1 phút nếu muốn trứng chín kỹ hơn).', NULL, 2),
('imp-412960b58d00d211_v4_step_6', 'imp-412960b58d00d211', 6, 'finish', 'Rắc hành lá, ớt hiểm và thưởng thức nóng', 'Tắt bếp, rắc hành lá tươi thái khoanh cùng ớt hiểm đỏ thái lát lên mặt nồi canh Sundubu Jjigae đang sôi nhẹ; dọn nóng ngay ăn kèm cơm trắng.', 'Khi ăn có thể đánh tan lòng đỏ trứng hòa trực tiếp vào nước canh nóng để tăng độ béo mượt và dịu vị cay.', NULL),
('imp-80976e834de46c34_v4_step_1', 'imp-80976e834de46c34', 1, 'prep', 'Ngâm miến khoai lang, nấm hương và ướp thịt bò', 'Ngâm 15 g nấm hương khô trong 300 ml nước ấm 20 phút cho nở mềm rồi vắt ráo, bỏ chân và thái lát mỏng. Song song, ngâm 160 g miến khoai lang Hàn Quốc (Dangmyeon) trong nước ấm cho mềm dẻo. Ướp chung thịt bò thăn thái sợi và nấm hương với 15 ml nước tương, 6 g đường cát trắng, 2/3 lượng tỏi khô băm nhuyễn, 5 ml dầu mè rang và 1 g tiêu đen xay trong 15 phút.', NULL, 20),
('imp-80976e834de46c34_v4_step_2', 'imp-80976e834de46c34', 2, 'prep', 'Chần rau chân vịt và tráng trứng thái sợi', 'Đun sôi 1,2 lít nước lọc, chần 150 g rau chân vịt 45 giây rồi vớt ra xả nước lạnh, vắt kiệt và trộn với 1 g muối ăn, 1/3 lượng tỏi khô băm nhuyễn cùng 5 ml dầu mè rang. Trên chảo chống dính với 3 ml dầu thực vật ở lửa nhỏ, tráng mỏng 1 quả trứng gà tươi rồi để nguội, thái sợi dài.', 'Tận dụng ngay nồi nước sôi sau khi chần rau chân vịt để luộc miến giúp tiết kiệm thời gian và giữ màu xanh của rau.', NULL),
('imp-80976e834de46c34_v4_step_3', 'imp-80976e834de46c34', 3, 'cook', 'Xào riêng từng loại rau củ giữ màu và độ giòn', 'Làm nóng chảo trên lửa vừa với tổng cộng 15 ml dầu thực vật chia làm nhiều lần để xào riêng từng nguyên liệu trong 1,5–2 phút mỗi loại rồi trút vào tô lớn: hành tây với 0,5 g muối ăn; cà rốt và ớt chuông đỏ với 0,5 g muối ăn; nấm đùi gà tươi với 0,5 g muối ăn; hành lá tươi với 0,5 g muối ăn.', 'Xào riêng từ nguyên liệu nhạt màu trước sang đậm màu sau giúp giữ chảo sạch và rau củ luôn tươi giòn.', 6),
('imp-80976e834de46c34_v4_step_4', 'imp-80976e834de46c34', 4, 'cook', 'Xào chín thịt bò và nấm hương đã ướp', 'Cho 7 ml dầu thực vật còn lại vào chảo đun lửa lớn, trút thịt bò thăn và nấm hương đã ướp vào đảo nhanh tay 3 phút cho đến khi thịt bò chín săn đều, dậy mùi thơm lừng rồi trút chung vào tô rau củ.', NULL, 3),
('imp-80976e834de46c34_v4_step_5', 'imp-80976e834de46c34', 5, 'cook', 'Luộc chín và xào thấm sợi miến khoai lang', 'Luộc miến khoai lang trong nồi nước sôi khoảng 6 phút đến khi sợi miến trong suốt và mềm dai vừa tới (không nhũn), vớt ra xả nhanh nước lạnh, để ráo và cắt bớt cho vừa ăn. Cho miến vào chảo cùng 30 ml nước tương còn lại, 14 g đường cát trắng và 10 ml dầu mè rang, đảo đều trên lửa vừa 2 phút cho miến hút trọn gia vị bóng đẹp.', 'Xào sơ miến với nước tương, đường và dầu mè trước khi trộn rau giúp từng sợi miến thấm đậm vị và không bị dính chùm.', 8),
('imp-80976e834de46c34_v4_step_6', 'imp-80976e834de46c34', 6, 'finish', 'Trộn đều Japchae và trang trí trứng sợi', 'Trút phần miến còn ấm vào tô lớn đựng thịt bò và rau củ, rưới nốt 10 ml dầu mè rang còn lại, rắc 1 g tiêu đen xay và 9 g hạt mè trắng rang rồi dùng tay đeo găng trộn nhẹ nhàng cho tất cả hòa quyện. Bày ra đĩa, xếp trứng gà thái sợi lên trên và thưởng thức.', NULL, NULL),
('imp-8608afb7fee8ebc3_v4_step_1', 'imp-8608afb7fee8ebc3', 1, 'prep', 'Chuẩn bị rau cuốn, hành lá sợi và thịt ba chỉ', 'Rửa sạch xà lách tươi và lá tía tô tươi rồi vẩy thật ráo nước. Thái lát 1 củ tỏi khô để nướng, băm nhuyễn 0,5 củ tỏi khô còn lại để pha sốt, thái lát mỏng 3 quả ớt xanh sừng. Tước sợi dọc hành lá tươi ngâm nước lạnh 5 phút rồi vớt ráo, trộn với 5 ml dầu mè rang. Thấm thật khô các dải thịt ba chỉ heo cắt dày.', 'Thấm thật khô thịt ba chỉ trước khi đặt lên chảo gang giúp bề mặt thịt cháy cạnh vàng giòn nhanh và hạn chế bắn mỡ.', NULL),
('imp-8608afb7fee8ebc3_v4_step_2', 'imp-8608afb7fee8ebc3', 2, 'sauce', 'Pha sốt chấm Ssamjang và chén dầu mè muối tiêu', 'Trong chén thứ nhất, trộn đều 45 g tương đậu Hàn Quốc (Doenjang), 18 g tương ớt Hàn Quốc (Gochujang), 15 ml rượu ngọt Mirin, 5 g đường cát trắng, 15 ml dầu mè rang, tỏi khô băm nhuyễn và 5 g hạt mè trắng rang thành sốt Ssamjang sánh mịn. Ở chén thứ hai, khuấy 15 ml dầu mè rang còn lại với 4 g muối hạt mịn và 0,5 g tiêu đen xay.', 'Chuẩn bị đủ cả hai loại nước chấm Ssamjang và dầu mè muối tiêu giúp thực khách đổi vị linh hoạt theo kiểu ăn truyền thống Hàn Quốc.', NULL),
('imp-8608afb7fee8ebc3_v4_step_3', 'imp-8608afb7fee8ebc3', 3, 'cook', 'Nướng áp chảo ba chỉ heo vàng ruộm hai mặt', 'Làm nóng chảo gang hoặc vỉ nướng trên lửa vừa-lớn (không cần thêm dầu vì thịt ba chỉ sẽ tự tiết mỡ), đặt các dải thịt ba chỉ heo lên chảo, rắc nhẹ 2 g muối hạt mịn và 0,5 g tiêu đen xay. Áp chảo khoảng 4 phút mỗi mặt đến khi thịt chín vàng ruộm giòn cạnh.', NULL, 8),
('imp-8608afb7fee8ebc3_v4_step_4', 'imp-8608afb7fee8ebc3', 4, 'cook', 'Cắt miếng thịt và nướng kèm tỏi lát, kim chi', 'Dùng kéo bếp cắt thịt ba chỉ thành từng miếng dày vừa ăn khoảng 1,5 cm ngay trên chảo. Gạt thịt sang một bên chảo, tận dụng phần mỡ thịt nóng đặt tỏi khô thái lát và kim chi cải thảo vào áp chảo thêm 3–4 phút cho tỏi vàng thơm, kim chi xém cạnh và thịt chín hoàn toàn.', 'Nướng kim chi trực tiếp bằng mỡ tiết ra từ thịt ba chỉ giúp kim chi béo thơm dịu chua và làm phần thịt đỡ ngấy.', 4),
('imp-8608afb7fee8ebc3_v4_step_5', 'imp-8608afb7fee8ebc3', 5, 'cook', 'Giữ nóng thịt ở lửa thật nhỏ', 'Hạ bếp xuống lửa thật nhỏ để thịt ba chỉ, kim chi và tỏi nướng luôn ấm nóng, đồng thời thấm bớt lượng mỡ dư trên chảo bằng một miếng giấy thấm nếu cần.', NULL, NULL),
('imp-8608afb7fee8ebc3_v4_step_6', 'imp-8608afb7fee8ebc3', 6, 'finish', 'Cuốn rau Ssam cùng Ssamjang và thưởng thức', 'Bày đĩa thịt ba chỉ nướng Samgyeopsal cùng kim chi và tỏi nướng ra bàn kèm rổ xà lách tươi, lá tía tô tươi, hành lá sợi, ớt xanh sừng và hai chén nước chấm. Khi ăn chấm miếng thịt vào dầu mè muối tiêu, đặt lên lá xà lách và lá tía tô cùng kim chi, tỏi nướng, chút Ssamjang rồi gói gọn thưởng thức.', NULL, NULL),
('imp-97ba5787e2d4113b_v4_step_1', 'imp-97ba5787e2d4113b', 1, 'prep', 'Sơ chế rau chân vịt, nấm đùi gà và đậu phụ', 'Rửa sạch 150 g rau chân vịt rồi cắt khúc 4 cm. Thái lát vát nấm đùi gà tươi dày 0,5 cm, cắt vuông hành tây 1,5 cm, cắt khối vuông đậu phụ trắng mềm cỡ 2 cm, băm nhuyễn tỏi khô và thái khúc hành lá tươi.', NULL, NULL),
('imp-97ba5787e2d4113b_v4_step_2', 'imp-97ba5787e2d4113b', 2, 'cook', 'Đun sôi nước dùng và đánh tan tương đậu Doenjang', 'Đổ 800 ml nước dùng cá cơm tảo bẹ vào nồi đất hoặc nồi đáy dày, đun sôi trên lửa lớn. Đặt rây lọc lên miệng nồi, cho 36 g tương đậu Hàn Quốc (Doenjang) vào rây rồi dùng muỗng dằm nhẹ cho tương tan đều vào nước dùng đang sôi.', 'Đánh tan Doenjang qua rây giúp nước canh mượt mịn, giữ lại phần xác đậu thô nếu thích hoặc hòa tan hoàn toàn đều ngon.', 4),
('imp-97ba5787e2d4113b_v4_step_3', 'imp-97ba5787e2d4113b', 3, 'cook', 'Nấu hành tây và nấm đùi gà cho ngọt nước', 'Cho hành tây thái vuông, nấm đùi gà tươi và 2 g ớt bột Hàn Quốc (Gochugaru) vào nồi, hạ lửa vừa và nấu liu riu khoảng 5 phút cho hành tây chín trong và nấm tiết vị ngọt thanh.', NULL, 5),
('imp-97ba5787e2d4113b_v4_step_4', 'imp-97ba5787e2d4113b', 4, 'cook', 'Thả đậu phụ trắng và tỏi băm vào nồi canh', 'Nhẹ nhàng thả các khối đậu phụ trắng mềm cùng tỏi khô băm nhuyễn vào nồi canh, nấu thêm 3 phút trên lửa vừa để đậu phụ nóng thấm hương tương đậu lên men mà không bị nát.', 'Cho tỏi băm vào ở công đoạn sau giúp giữ mùi thơm đặc trưng rõ nét của món canh Doenjang.', 3),
('imp-97ba5787e2d4113b_v4_step_5', 'imp-97ba5787e2d4113b', 5, 'cook', 'Chần chín rau chân vịt trong nước canh nóng', 'Cho toàn bộ rau chân vịt cắt khúc vào nồi canh, nhấn nhẹ cho rau ngập nước và nấu thêm 1–2 phút đến khi rau vừa chín mềm vẫn giữ màu xanh mướt.', 'Không nấu rau chân vịt quá lâu để giữ trọn độ giòn ngọt và màu xanh tươi mắt.', NULL),
('imp-97ba5787e2d4113b_v4_step_6', 'imp-97ba5787e2d4113b', 6, 'finish', 'Rắc hành lá, ớt lát và dọn nóng', 'Rắc hành lá tươi và ớt hiểm đỏ thái lát lên mặt nồi canh, tắt bếp rồi dọn nóng ngay ra bàn cùng cơm trắng.', NULL, NULL),
('imp-96d226a7f4d12156_v4_step_1', 'imp-96d226a7f4d12156', 1, 'marinate', 'Ướp thịt ức gà và áo lớp bột bắp khô', 'Trộn đều 500 g ức gà phi lê cắt miếng với 2 g muối ăn, 1 g tiêu đen xay, 1/3 lượng tỏi khô băm nhuyễn, 1/3 lượng gừng tươi băm nhuyễn và 15 ml rượu ngọt Mirin, ướp 15 phút cho thấm vị. Trước khi chiên, cho từng miếng gà vào tô chứa 50 g bột bắp lăn áo thật đều và rũ nhẹ phần bột thừa.', 'Rũ bỏ bột bắp thừa trước khi thả vào chảo dầu giúp dầu chiên sạch, không bị cháy cặn và vỏ gà mỏng giòn.', 15),
('imp-96d226a7f4d12156_v4_step_2', 'imp-96d226a7f4d12156', 2, 'cook', 'Chiên gà lần một ở lửa vừa cho chín bên trong', 'Đun nóng 400 ml dầu thực vật trong nồi sâu lòng trên lửa vừa đến khi nhúng đầu đũa vào thấy sủi tăm đều (khoảng 170°C). Chia gà thành 2 mẻ chiên khoảng 4 phút mỗi mẻ cho đến khi thịt gà chín đều bên trong và lớp bột chuyển màu vàng nhạt, vớt ra giá lưới nghỉ 5 phút.', NULL, 8),
('imp-96d226a7f4d12156_v4_step_3', 'imp-96d226a7f4d12156', 3, 'cook', 'Chiên gà lần hai ở lửa lớn cho vỏ giòn rụm', 'Tăng lửa lớn đun dầu nóng già hơn (khoảng 190°C), thả toàn bộ gà đã chiên lần một vào chiên nhanh thêm 2 phút cho đến khi lớp vỏ phồng giòn rụm và có màu vàng nâu đẹp mắt rồi vớt ra giấy thấm dầu.', 'Kỹ thuật chiên hai lần giúp đẩy hết hơi ẩm ra khỏi lớp vỏ, giữ gà giòn tan ngay cả sau khi áo sốt.', 2),
('imp-96d226a7f4d12156_v4_step_4', 'imp-96d226a7f4d12156', 4, 'sauce', 'Nấu keo sốt cay ngọt mật ong Gochujang', 'Trong chảo rộng sạch trên lửa vừa, cho 20 g tương ớt Hàn Quốc (Gochujang), 50 ml mật ong nguyên chất, 25 g đường nâu, 20 ml nước tương, 20 ml rượu ngọt Mirin còn lại, 25 ml giấm gạo, 1 g tiêu đen xay cùng phần tỏi khô và gừng tươi băm nhuyễn còn lại vào khuấy tan. Đun sôi nhẹ khoảng 3 phút cho hỗn hợp nổi bọt li ti và hơi sánh keo, tắt bếp rồi khuấy thêm 10 ml dầu mè rang.', 'Không đun sốt quá cạn kiệt trên bếp vì mật ong và đường nâu sẽ tiếp tục đặc lại khi nguội bớt.', 3),
('imp-96d226a7f4d12156_v4_step_5', 'imp-96d226a7f4d12156', 5, 'cook', 'Xóc nhanh gà chiên với nước sốt cay ngọt', 'Trút toàn bộ gà chiên giòn vào chảo sốt còn ấm nóng, đảo và xóc nhanh tay trong 30–45 giây cho từng miếng gà áo đều một lớp sốt đỏ cam bóng mượt mà không bị ỉu vỏ.', NULL, NULL),
('imp-96d226a7f4d12156_v4_step_6', 'imp-96d226a7f4d12156', 6, 'finish', 'Rắc đậu phộng, mè rang và thưởng thức nóng', 'Bày gà chiên sốt Dakgangjeong ra đĩa, rắc 20 g đậu phộng rang giã dập, 5 g hạt mè trắng rang và hành lá tươi thái nhỏ lên trên rồi dùng nóng ngay.', NULL, NULL),
('imp-ba1871f088d9a522_v4_step_1', 'imp-ba1871f088d9a522', 1, 'marinate', 'Ướp thịt bò Bulgogi và ngâm miến khoai lang', 'Ngâm 85 g miến khoai lang Hàn Quốc (Dangmyeon) vào tô nước ấm khoảng 20 phút cho sợi mềm dẻo rồi vớt ra để ráo. Trộn 450 g thịt bò thăn thái lát mỏng với 40 ml nước tương, 12 g đường cát trắng, 15 ml mật ong nguyên chất, 15 ml rượu ngọt Mirin, 15 ml dầu mè rang, tỏi khô băm nhuyễn và 1 g tiêu đen xay, ướp 20 phút.', 'Thịt bò thái lát mỏng ngang thớ ướp cùng mật ong và dầu mè sẽ giữ được độ mềm ngọt ngay cả khi nấu trong nước lẩu.', 20),
('imp-ba1871f088d9a522_v4_step_2', 'imp-ba1871f088d9a522', 2, 'prep', 'Sơ chế rau cải thảo, nấm đùi gà và củ cải trắng', 'Cắt khúc 4 cm cải thảo tươi, thái lát dọc dày 0,5 cm nấm đùi gà tươi, thái múi cau hành tây, thái lát mỏng cà rốt và củ cải trắng, cắt khúc 5 cm hành lá tươi và thái lát ớt sừng đỏ.', NULL, NULL),
('imp-ba1871f088d9a522_v4_step_3', 'imp-ba1871f088d9a522', 3, 'cook', 'Nấu ngọt nền nước lẩu cùng củ cải trắng', 'Đổ 1,1 lít nước dùng cá cơm tảo bẹ và thả 90 g củ cải trắng thái lát vào nồi nấu lẩu, đun sôi trên lửa lớn rồi hạ lửa vừa ninh 8 phút cho củ cải tiết vị ngọt thanh. Nêm 15 ml nước tương còn lại và 10 ml nước mắm cá cơm, nếm thử và chỉ thêm tối đa 1 g muối ăn nếu cần cho vừa miệng.', NULL, 8),
('imp-ba1871f088d9a522_v4_step_4', 'imp-ba1871f088d9a522', 4, 'cook', 'Xếp rau nấm, miến và thịt bò vào nồi lẩu', 'Tắt tạm bếp hoặc xếp gọn gàng cải thảo tươi, nấm đùi gà tươi, hành tây, cà rốt và miến khoai lang thành từng cụm xung quanh lòng nồi lẩu nông đáy, đặt thịt bò thăn đã ướp vào phần giữa nồi rồi chan nước dùng nóng ngập khoảng 2/3 nguyên liệu.', 'Xếp từng loại nguyên liệu theo nhóm màu sắc xung quanh thành nồi tạo dáng trình bày đẹp mắt đúng chuẩn lẩu Jeongol.', NULL),
('imp-ba1871f088d9a522_v4_step_5', 'imp-ba1871f088d9a522', 5, 'cook', 'Đun sôi cho thịt bò và rau nấm vừa chín tới', 'Bật bếp vừa-lớn đun sôi lại nồi lẩu khoảng 5 phút, dùng đũa tách nhẹ phần thịt bò để thịt chín đều chuyển màu nâu nhạt, nấm chín giòn và miến trong dai quyện vị ngọt từ thịt.', 'Không đun sôi quá lâu sau khi thịt bò đã chín tới để thịt giữ độ mềm mọng và nước lẩu không bị đục.', 5),
('imp-ba1871f088d9a522_v4_step_6', 'imp-ba1871f088d9a522', 6, 'finish', 'Thêm hành lá, ớt lát và thưởng thức nóng tại bàn', 'Rắc hành lá tươi cắt khúc và ớt sừng đỏ thái lát lên mặt nồi lẩu, giữ bếp ở mức lửa liu riu để thưởng thức nóng hổi cùng cơm trắng hoặc kim chi.', NULL, NULL),
('imp-24fc3ac5cd3ff445_v4_step_1', 'imp-24fc3ac5cd3ff445', 1, 'prep', 'Sơ chế kim chi ủ chua và chuẩn bị cơm nguội', 'Vắt nhẹ 200 g kim chi cải thảo ủ chua kỹ để chắt lấy khoảng 60 ml nước kim chi vào chén, phần cái thái nhỏ cỡ 1 cm. Thái nhỏ hành lá tươi (để riêng đầu hành trắng và lá xanh). Bóp nhẹ hoặc dùng thìa dằm tơi 500 g cơm trắng nấu chín để nguội.', 'Kim chi càng ủ chua kỹ thì khi xào lên càng thơm nồng và không cần nêm thêm giấm hay đường.', NULL),
('imp-24fc3ac5cd3ff445_v4_step_2', 'imp-24fc3ac5cd3ff445', 2, 'sauce', 'Khuấy đều sốt Gochujang và nước kim chi', 'Cho 35 g tương ớt Hàn Quốc (Gochujang), 15 ml nước tương và 60 ml nước kim chi vừa chắt vào chén, khuấy tan đều thành hỗn hợp sốt đỏ sánh mượt để dễ áo đều lên cơm.', NULL, NULL),
('imp-24fc3ac5cd3ff445_v4_step_3', 'imp-24fc3ac5cd3ff445', 3, 'cook', 'Xào săn kim chi với đầu hành trắng', 'Làm nóng chảo rộng trên lửa vừa-lớn với 5 ml dầu thực vật, cho đầu hành trắng vào phi thơm 30 giây rồi trút kim chi cải thảo thái nhỏ vào xào đều tay 3 phút cho kim chi săn ráo bớt nước và dậy mùi thơm.', NULL, 3),
('imp-24fc3ac5cd3ff445_v4_step_4', 'imp-24fc3ac5cd3ff445', 4, 'cook', 'Rang cơm tơi và áo sốt Gochujang', 'Tăng lửa lớn, trút 500 g cơm trắng nguội vào chảo, đảo đều và dàn cơm ép nhẹ xuống mặt chảo khoảng 3 phút cho hạt cơm nóng ráo, săn lại. Rưới đều chén sốt Gochujang vào chảo, đảo nhanh tay thêm 2 phút đến khi cơm nhuộm màu đỏ cam đều đẹp và hơi cháy cạnh thơm lừng.', 'Giữ lửa lớn khi cho cơm và sốt giúp phần nước thừa bay hơi nhanh, hạt cơm tơi bóng mà không bị nhão.', 5),
('imp-24fc3ac5cd3ff445_v4_step_5', 'imp-24fc3ac5cd3ff445', 5, 'cook', 'Chiên 3 trứng gà ốp la lòng đào', 'Trong chảo chống dính nhỏ với 5 ml dầu thực vật còn lại trên lửa vừa, chiên 3 quả trứng gà tươi khoảng 3 phút cho lòng trắng đông chín hoàn toàn còn lòng đỏ sánh lòng đào.', 'Đậy nắp chảo 30 giây cuối nếu thích bề mặt lòng trắng se ráo nhanh mà vẫn giữ được lòng đỏ chảy dẻo.', 3),
('imp-24fc3ac5cd3ff445_v4_step_6', 'imp-24fc3ac5cd3ff445', 6, 'finish', 'Trộn dầu mè rang và bày đĩa cơm chiên', 'Tắt bếp chảo cơm, rưới 15 ml dầu mè rang, rắc phần hành lá xanh và một nửa lượng hạt mè trắng rang vào đảo đều. Xới cơm ra 3 đĩa, đặt trứng ốp la lên trên, rắc nốt phần hạt mè trắng rang cùng rong biển lá khô xé nhỏ rồi thưởng thức ngay khi nóng.', NULL, NULL),
('imp-46962ad0d6f6e63b_v4_step_1', 'imp-46962ad0d6f6e63b', 1, 'prep', 'Băm gà, sơ chế rau thơm và pha sẵn nước sốt', 'Băm nhỏ 450 g ức gà phi lê bằng dao để giữ thớ thịt mềm ngọt. Băm nhỏ 3/4 củ tỏi cùng 3 quả ớt hiểm, thái lát 1 quả ớt sừng đỏ, thái nhỏ 50 g đậu que, cắt khúc 1/2 bó hành lá và nhặt rửa ráo 30 g lá húng quế Thái. Khuấy đều trong chén gồm 22 ml dầu hào, 15 ml xì dầu nhạt, 5 ml xì dầu đen đặc Thái, 15 ml nước mắm ngon và 8 g đường cát trắng.', 'Tự băm thịt ức gà bằng dao thay vì xay nhuyễn giúp món gà xào có độ sần giòn tự nhiên và không bị bở.', NULL),
('imp-46962ad0d6f6e63b_v4_step_2', 'imp-46962ad0d6f6e63b', 2, 'cook', 'Phi thơm tỏi ớt và xào chín tơi thịt gà băm', 'Làm nóng chảo sâu lòng trên lửa vừa lớn với 20 ml dầu ăn, cho tỏi và ớt hiểm băm vào đảo nhanh 20 giây đến khi dậy mùi thơm. Trút toàn bộ ức gà băm vào chảo, dùng xẻng dằm tơi đều tay và xào liên tục 4 phút trên lửa lớn cho đến khi thịt gà chuyển trắng hoàn toàn và săn rời.', 'Xào tơi trên lửa lớn giúp thịt ức gà băm ráo nước nhanh, giữ được độ ngọt mọng bên trong mà không bị khô bã.', 4),
('imp-46962ad0d6f6e63b_v4_step_3', 'imp-46962ad0d6f6e63b', 3, 'cook', 'Xào đậu que và áo sốt đậm đà', 'Thêm đậu que cắt nhỏ và ớt sừng đỏ thái lát vào đảo 1 phút. Rưới hết chén sốt đã pha vào chảo, đảo đều trên lửa lớn thêm 2 phút để sốt sôi quyện bóng đều vào thịt gà và đậu que vừa chín giòn.', 'Để đậu que vào gần cuối giúp đậu giữ màu xanh mướt và độ giòn nhẹ khi ăn cùng cơm nóng.', 3);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-46962ad0d6f6e63b_v4_step_4', 'imp-46962ad0d6f6e63b', 4, 'finish', 'Tắt bếp đảo lá húng quế và hành lá', 'Nhấc chảo khỏi bếp, cho toàn bộ 30 g lá húng quế Thái và hành lá cắt khúc vào đảo nhanh 15 giây cho lá vừa héo thơm nức rồi trút ra đĩa.', 'Đảo húng quế ngay khi tắt bếp giúp lá giữ màu xanh đẹp mà không bị thâm đen hay bay mất tinh dầu.', NULL),
('imp-46962ad0d6f6e63b_v4_step_5', 'imp-46962ad0d6f6e63b', 5, 'cook', 'Chiên 3 quả trứng gà ốp la viền giòn', 'Đun nóng 25 ml dầu ăn còn lại trong chảo nhỏ trên lửa vừa lớn đến khi dầu thật nóng già, đập lần lượt 3 quả trứng gà vào chiên khoảng 2 phút cho viền lòng trắng phồng giòn vàng rụm và lòng đỏ còn sánh dẻo, vớt ra đĩa lót giấy thấm dầu.', NULL, 2),
('imp-46962ad0d6f6e63b_v4_step_6', 'imp-46962ad0d6f6e63b', 6, 'finish', 'Trình bày 3 phần cơm gà Pad Krapow', 'Chia 450 g cơm trắng nóng ra 3 đĩa, múc thịt gà băm xào húng quế vào bên cạnh cơm rồi đặt lên trên mỗi đĩa 1 quả trứng ốp la nóng giòn và thưởng thức ngay.', NULL, NULL),
('imp-f8fc539b7aa359ac_v4_step_1', 'imp-f8fc539b7aa359ac', 1, 'prep', 'Chuẩn bị cơm nguội, tôm, dứa và cà chua', 'Đánh tơi 500 g cơm trắng nguội để hạt cơm rời hẳn không vón cục. Thấm thật khô 250 g tôm tươi đã bóc vỏ rút chỉ lưng. Thái vuông 1/2 quả dứa chín và để ráo nước trên rây; thái hạt lựu 3/4 củ hành tây và 1,5 quả cà chua bỏ ruột; thái nhỏ 1 bó hành lá.', 'Dùng cơm nấu ráo để nguội qua đêm giúp hạt cơm săn chắc, không bị nhão nát khi đảo với dứa tươi.', NULL),
('imp-f8fc539b7aa359ac_v4_step_2', 'imp-f8fc539b7aa359ac', 2, 'sauce', 'Trộn sẵn gia vị khô cà ri và gia vị ướt', 'Trộn đều trong chén gia vị khô gồm 5 g bột cà ri vàng, 8 g đường cát trắng, 2 g muối ăn và 2 g tiêu trắng xay để bột cà ri tơi không vón cục. Pha riêng chén gia vị ướt gồm 15 ml xì dầu và 15 ml nước mắm ngon đặt sẵn cạnh bếp.', 'Pha tách biệt gia vị khô và ướt giúp bạn rắc tơi bột cà ri đều từng hạt cơm rồi mới rưới nước mắm tạo hương thơm bùng vị.', NULL),
('imp-f8fc539b7aa359ac_v4_step_3', 'imp-f8fc539b7aa359ac', 3, 'cook', 'Áp chảo tôm vàng thơm và giữ riêng', 'Làm nóng chảo sâu lòng trên lửa lớn với 15 ml dầu ăn, xếp tôm tươi vào áp chảo mỗi mặt khoảng 1 phút đến khi tôm chuyển màu hồng cam, cạnh hơi xém thơm và chín hoàn toàn bên trong thì gắp ra đĩa riêng, giữ lại dầu thơm trong chảo.', NULL, 2),
('imp-f8fc539b7aa359ac_v4_step_4', 'imp-f8fc539b7aa359ac', 4, 'cook', 'Chiên trứng tơi và đảo cơm cùng hành tây', 'Thêm 25 ml dầu ăn vào chảo trên lửa vừa lớn, đổ 3 quả trứng gà vào đảo nhanh tay đến khi trứng vừa se chín 90% thành từng mảng nhỏ thì trút ngay cơm nguội và hành tây thái hạt lựu vào đảo đều 3 phút cho hạt cơm nóng tơi và áo trứng vàng đều.', NULL, 3),
('imp-f8fc539b7aa359ac_v4_step_5', 'imp-f8fc539b7aa359ac', 5, 'cook', 'Nêm gia vị cà ri và rang cháy cạnh với dứa', 'Rắc toàn bộ chén gia vị khô chứa bột cà ri và rưới đều chén xì dầu nước mắm quanh thành chảo, đảo liên tục 2 phút trên lửa lớn cho hạt cơm thấm vàng óng đều màu. Cho dứa chín vào đảo cùng 2 phút cho dứa nóng thơm, thỉnh thoảng dàn phẳng cơm nghỉ 15 giây rồi đảo tiếp để hạt cơm săn ráo và thơm nhẹ mùi chảo.', 'Rưới nước mắm và xì dầu dọc thành chảo đang nóng sẽ tạo hương thơm dậy mùi mà không làm cơm bị ướt.', 4),
('imp-f8fc539b7aa359ac_v4_step_6', 'imp-f8fc539b7aa359ac', 6, 'finish', 'Trộn tôm, hạt điều, cà chua và hành lá', 'Trút tôm áp chảo vào đảo đều 30 giây rồi tắt bếp. Thêm ngay 75 g hạt điều rang, cà chua thái hạt lựu và hành lá thái nhỏ vào trộn nhanh tay cho giữ trọn độ giòn bùi của hạt điều và màu tươi của rau củ, múc ra đĩa dùng nóng.', NULL, NULL),
('imp-e28e249efceacac7_v4_step_1', 'imp-e28e249efceacac7', 1, 'prep', 'Sơ chế rau thơm, hành tím và rau ăn kèm', 'Thái lát mỏng 40 g hành tím tươi, thái chỉ thật mảnh 3 g lá chanh Thái bỏ gân, nhặt rửa ráo 15 g lá húng lủi, thái khúc 15 g ngò rí và thái nhỏ 1/2 bó hành lá. Tách lá 1/4 bắp cải trắng và thái lát 1 quả dưa leo xếp sẵn ra đĩa. Vắt 2 quả chanh tươi lọc bỏ hạt.', 'Ngâm bắp cải và dưa leo trong nước lạnh vài phút rồi vẩy ráo giúp rau sống giòn ngọt khi ăn kèm thịt bằm chua cay.', NULL),
('imp-e28e249efceacac7_v4_step_2', 'imp-e28e249efceacac7', 2, 'marinate', 'Đánh tơi thịt heo xay với nước mắm', 'Cho 320 g thịt heo xay vào tô, rưới 10 ml nước mắm ngon rồi dùng nĩa trộn bóp nhẹ để các thớ thịt tơi rời hẳn, không bị dính thành mảng dài khi nấu.', NULL, NULL),
('imp-e28e249efceacac7_v4_step_3', 'imp-e28e249efceacac7', 3, 'cook', 'Xào chín mềm thịt heo bằm không dầu mỡ', 'Đun sôi lăn tăn 40 ml nước lọc trong nồi hoặc chảo sâu lòng trên lửa vừa, trút toàn bộ thịt heo xay vào đảo và dằm liên tục khoảng 4 phút đến khi thịt chín trắng hoàn toàn, không còn màu hồng và nước trong thịt tiết ra vừa cạn sánh thì tắt bếp.', 'Nấu chín thịt heo với chút nước lọc thay vì xào dầu giúp món Larb giữ độ ẩm ngọt thanh nhẹ và đậm nước thịt tự nhiên.', 4),
('imp-e28e249efceacac7_v4_step_4', 'imp-e28e249efceacac7', 4, 'sauce', 'Trộn hành tím và lá chanh khi thịt còn ấm', 'Ngay khi vừa tắt bếp lúc thịt còn ấm nóng, cho toàn bộ hành tím thái lát và lá chanh Thái thái chỉ vào đảo đều 1 phút để hơi nóng làm hành tím dịu vị hăng và tỏa hương thơm dịu.', NULL, 1),
('imp-e28e249efceacac7_v4_step_5', 'imp-e28e249efceacac7', 5, 'sauce', 'Nêm nước cốt chanh, ớt bột và thính gạo rang', 'Chờ thêm 2 phút cho thịt nguội bớt không còn bốc hơi nóng gắt rồi rưới 20 ml nước mắm còn lại, nước cốt 2 quả chanh, 3 g đường cát trắng, 3 g ớt bột và 20 g thính gạo rang vào trộn đều tay cho gia vị quyện sánh.', 'Cho nước cốt chanh và thính gạo vào lúc thịt chỉ còn ấm vừa giúp thính không bị vón nhão và giữ vị chua sáng tươi.', 2),
('imp-e28e249efceacac7_v4_step_6', 'imp-e28e249efceacac7', 6, 'finish', 'Trộn rau thơm và dọn kèm rau sống giòn', 'Nếm lại cho vừa vị chua cay mặn ngọt hài hòa rồi thả lá húng lủi, ngò rí và hành lá vào trộn nhẹ tay cho rau không bị dập. Múc gỏi thịt heo bằm ra đĩa, ăn kèm bắp cải tách lá và dưa leo thái lát.', NULL, NULL),
('imp-90fc2e140739a7d7_v4_step_1', 'imp-90fc2e140739a7d7', 1, 'prep', 'Sơ chế phi lê cá và thảo mộc Thái', 'Cắt 500 g phi lê cá thịt trắng thành miếng vuông 3–4 cm để ráo. Thái lát 200 g nấm đùi gà, bổ múi cau 1 quả cà chua. Đập dập và cắt khúc 5 cm phần 2,5 cây sả, thái lát mỏng 30 g củ riềng, xé bỏ gân 5 g lá chanh Thái, đập dập 4 quả ớt hiểm, bổ đôi 30 g hành tím. Cắt khúc 1/2 bó hành lá và thái nhỏ 15 g ngò rí.', 'Cắt phi lê cá thành miếng vuông dày vừa phải giúp cá không bị vỡ vụn khi nấu trong nước dùng nóng.', NULL),
('imp-90fc2e140739a7d7_v4_step_2', 'imp-90fc2e140739a7d7', 2, 'cook', 'Nấu nước dùng thảo mộc thơm nồng', 'Đun sôi 900 ml nước lọc trong nồi trên lửa lớn, thả toàn bộ sả, riềng, lá chanh Thái, hành tím và ớt hiểm vào rồi hạ lửa vừa, nấu liu riu 5 phút cho các loại thảo mộc tiết hết tinh dầu thơm vào nước dùng.', 'Có thể vớt bớt xác sả và riềng ra sau khi nấu thơm nếu muốn tô canh gọn gàng dễ múc.', 5),
('imp-90fc2e140739a7d7_v4_step_3', 'imp-90fc2e140739a7d7', 3, 'cook', 'Nêm vị nền và nấu nấm, cà chua', 'Nêm 45 ml nước mắm ngon cùng 12 g đường thốt nốt vào nồi khuấy tan. Cho 200 g nấm đùi gà và cà chua bổ múi cau vào nấu sôi vừa khoảng 3 phút cho nấm chín mềm ngọt và cà chua tiết màu nhẹ.', NULL, 3),
('imp-90fc2e140739a7d7_v4_step_4', 'imp-90fc2e140739a7d7', 4, 'cook', 'Thả phi lê cá nấu chín nhẹ nhàng', 'Hạ lửa xuống mức vừa để mặt nước chỉ sôi lăn tăn, thả nhẹ từng miếng phi lê cá vào nồi và nấu khoảng 3 phút đến khi thịt cá chuyển trắng đục, săn chắc chín hoàn toàn mà không đảo mạnh tay làm nát miếng cá.', 'Giữ nước sôi lăn tăn và không khuấy đảo sau khi thả cá là bí quyết giữ từng miếng cá nguyên vẹn và nước canh trong veo.', 3),
('imp-90fc2e140739a7d7_v4_step_5', 'imp-90fc2e140739a7d7', 5, 'finish', 'Tắt bếp vắt nước cốt chanh cân vị', 'Tắt bếp chờ nước canh ngừng sôi hẳn mới rưới nước cốt từ 2 quả chanh tươi vào khuấy thật nhẹ tay để giữ trọn hương thơm tươi mát và vị chua thanh mà không bị đắng.', NULL, NULL),
('imp-90fc2e140739a7d7_v4_step_6', 'imp-90fc2e140739a7d7', 6, 'finish', 'Thêm hành ngò và dọn canh Tom Yum nóng', 'Nếm lại cho đạt vị chua cay mặn ngọt cân bằng, thả hành lá cắt khúc vào nồi đảo nhẹ rồi múc canh ra tô, rắc ngò rí thái nhỏ lên trên và dùng nóng ngay.', NULL, NULL);
